-- mysql_tl_tssh_汇总.sql
-- 汇总 mysql_tl_tssh 目录的 146 个函数/存储过程脚本，按原文件名排序。
-- 执行前请选择目标数据库，并在同一数据库中依次安装共享对象：
-- bjts/mysql_added/mysql_extra.sql
-- bjts/mysql_added/mysql_extra_seq_nextval_fix.sql
-- 使用支持 DELIMITER 的客户端一次执行整个文件。
-- 各段保留原脚本的 DROP/CREATE、注释及 DELIMITER 语句。
-- 单独脚本更新后，应重新生成本汇总文件。

-- ======================================================================
-- [001/146] BEGIN SOURCE: F_JKGL_JKM_PD.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS F_JKGL_JKM_PD$$

CREATE PROCEDURE F_JKGL_JKM_PD(p_djxh VARCHAR(4000), p_yxq DATETIME, OUT P_RESULT integer)
routine_body: BEGIN
/*
 * 单户企业健康码结果计算（仅评定，不更新）
 */
  DECLARE v_swjg   VARCHAR(11);
  DECLARE v_tsjsfs char(1);

  -- 定义变量
  -- 指标分转健康码分的折算比例
  DECLARE zsblv1 DECIMAL(18,2);
  DECLARE zsblv2 DECIMAL(18,2);
  DECLARE zsblv3 DECIMAL(18,2);
  DECLARE zsblv4 DECIMAL(18,2);
  DECLARE zsblv5 DECIMAL(18,2);
  DECLARE zsblv6 DECIMAL(18,2);

  -- 六个分类的红线
  DECLARE lineRed1 int;
  DECLARE lineRed2 int;
  DECLARE lineRed3 int;
  DECLARE lineRed4 int;
  DECLARE lineRed5 int;
  DECLARE lineRed6 int;
  -- 六个分类的黄线
  DECLARE lineYellow1 int;
  DECLARE lineYellow2 int;
  DECLARE lineYellow3 int;
  DECLARE lineYellow4 int;
  DECLARE lineYellow5 int;
  DECLARE lineYellow6 int;

  DECLARE lineRed_Zh integer;          -- 综合红线
  DECLARE lineYellow_Zh integer;       -- 综合黄线

  -- 实际指标赋分
  DECLARE zb_SCORE1 int;
  DECLARE zb_SCORE2 int;
  DECLARE zb_SCORE3 int;
  DECLARE zb_SCORE4 int;
  DECLARE zb_SCORE5 int;
  DECLARE zb_SCORE6 int;

  -- 折算后的分数
  DECLARE jk_SCORE1 int;
  DECLARE jk_SCORE2 int;
  DECLARE jk_SCORE3 int;
  DECLARE jk_SCORE4 int;
  DECLARE jk_SCORE5 int;
  DECLARE jk_SCORE6 int;
  DECLARE jk_SCORE_ZH integer;          -- -折算后健康码综合赋分

  -- 健康码结果  1绿  2黄 3红
  DECLARE V_level char(1);

  SET V_level ='0';

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';


  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      DO ORA_CONCAT('【健康码】等级评定：', BJTS_SQLERRM_001);
      ROLLBACK;
      CALL ORA_RAISE_APPLICATION_ERROR(-20001,ORA_CONCAT('【健康码】等级评定：', P_djxh));

  END;
select swjgdm,(CASE jsmode WHEN '1' THEN '1' ELSE '2' END) into v_swjg,v_tsjsfs from GLXT_BB_SHXT_DJXX d where d.cpcode=p_djxh;
    -- 从健康码配置表，计算折算比率
    /*
    select
      sum(decode (ywfl_dm,'10',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'20',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'30',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'40',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'50',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'60',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'10',line_red,0)),
      sum(decode (ywfl_dm,'20',line_red,0)),
      sum(decode (ywfl_dm,'30',line_red,0)),
      sum(decode (ywfl_dm,'40',line_red,0)),
      sum(decode (ywfl_dm,'50',line_red,0)),
      sum(decode (ywfl_dm,'60',line_red,0)),
      sum(decode (ywfl_dm,'ZH',line_red,0)),
      sum(decode (ywfl_dm,'10',line_yellow,0)),
      sum(decode (ywfl_dm,'20',line_yellow,0)),
      sum(decode (ywfl_dm,'30',line_yellow,0)),
      sum(decode (ywfl_dm,'40',line_yellow,0)),
      sum(decode (ywfl_dm,'50',line_yellow,0)),
      sum(decode (ywfl_dm,'60',line_yellow,0)),
      sum(decode (ywfl_dm,'ZH',line_yellow,0))
    into zsblv1,zsblv2,zsblv3,zsblv4,zsblv5,zsblv6,
         lineRed1,lineRed2,lineRed3,lineRed4,lineRed5,lineRed6,lineRed_Zh,
         lineYellow1,lineYellow2,lineYellow3,lineYellow4,lineYellow5,lineYellow6,lineYellow_Zh
    from tl_tssh.JKGL_PZ_JKM t
    where t.tsjsfs=v_tsjsfs ;
    */
    with TT as (
    select zb.ywfl_dm, sum(score) as zbScore
    from
      JKGL_PZ_ZB zb left join
      (
      select t.zb_id,max(IFNULL(s.score, t.score)) as score
      from
      JKGL_PZ_ZB_YCFF t
      left join JKGL_PZ_ZB_YCFF_SWJG s
           on s.swjg_dm =v_swjg
           and s.zb_id=t.zb_id and s.xh=t.xh and s.yxbz='Y'
      where t.yxbz='Y'
      group by t.zb_id
      ) pt on pt.zb_id=zb.zb_id
    where
      zb.yxbz='Y' and
      zb.apply_qy=v_tsjsfs
      group by zb.ywfl_dm
    )
    select
     sum((CASE jkm.ywfl_dm WHEN '10' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '20' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '30' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '40' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '50' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '60' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '10' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '20' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '30' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '40' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '50' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '60' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN 'ZH' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '10' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '20' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '30' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '40' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '50' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '60' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN 'ZH' THEN line_yellow ELSE 0 END))
    into zsblv1,zsblv2,zsblv3,zsblv4,zsblv5,zsblv6,
         lineRed1,lineRed2,lineRed3,lineRed4,lineRed5,lineRed6,lineRed_Zh,
         lineYellow1,lineYellow2,lineYellow3,lineYellow4,lineYellow5,lineYellow6,lineYellow_Zh
    from JKGL_PZ_JKM jkm
    left join TT on TT.ywfl_dm=jkm.ywfl_dm
    where jkm.tsjsfs=v_tsjsfs ;



    -- 获取该纳税人的指标赋分
    select
        IFNULL(sum((CASE ywfl_dm WHEN '10' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '20' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '30' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '40' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '50' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '60' THEN score ELSE 0 END)), 0)
    into zb_SCORE1,zb_SCORE2,zb_SCORE3,zb_SCORE4,zb_SCORE5,zb_SCORE6
    from (
    select s.ywfl_dm,
      --   sum(t.score) as score
        sum(case when (p_yxq is null OR p_yxq>=DATE(CURRENT_TIMESTAMP)) and IFNULL(t.hcjg, '2')='1' then 0 else t.score end) as score
        from
 --       tl_tssh.JKGL_DATA_QYJKM_JGB k
 --       inner join tl_tssh.JKGL_DATA_ZB_JGB t on t.djxh=k.djxh
        JKGL_DATA_ZB_JGB t
        inner join JKGL_PZ_ZB s on t.zb_id=s.zb_id and s.yxbz='Y'
        where t.djxh=p_djxh
        group by s.ywfl_dm
    ) AS BJTS_DERIVED_001;

    -- 计算健康码折算赋分
    SET jk_SCORE1 = zb_SCORE1 * zsblv1;
    SET jk_SCORE2 = zb_SCORE2 * zsblv2;
    SET jk_SCORE3 = zb_SCORE3 * zsblv3;
    SET jk_SCORE4 = zb_SCORE4 * zsblv4;
    SET jk_SCORE5 = zb_SCORE5 * zsblv5;
    SET jk_SCORE6 = zb_SCORE6 * zsblv6;
    SET jk_SCORE_ZH = jk_SCORE1+jk_SCORE2+jk_SCORE3+jk_SCORE4+jk_SCORE5+jk_SCORE6;

    if (lineRed_Zh<>0 and jk_SCORE_ZH >= lineRed_Zh)
      OR (lineRed1<>0 and jk_SCORE1 >= lineRed1)
      OR (lineRed2<>0 and jk_SCORE2 >= lineRed2)
      OR (lineRed3<>0 and jk_SCORE3 >= lineRed3)
      OR (lineRed4<>0 and jk_SCORE4 >= lineRed4)
      OR (lineRed5<>0 and jk_SCORE5 >= lineRed5)
      OR (lineRed6<>0 and jk_SCORE6 >= lineRed6)
    then
      SET V_level = '3';
    else
      if (lineYellow_Zh<>0 and jk_SCORE_ZH >= lineYellow_Zh)
        OR (lineYellow1<>0 and jk_SCORE1 >= lineYellow1)
        OR (lineYellow2<>0 and jk_SCORE2 >= lineYellow2)
        OR (lineYellow3<>0 and jk_SCORE3 >= lineYellow3)
        OR (lineYellow4<>0 and jk_SCORE4 >= lineYellow4)
        OR (lineYellow5<>0 and jk_SCORE5 >= lineYellow5)
        OR (lineYellow6<>0 and jk_SCORE6 >= lineYellow6)
      then
        SET V_level = '2';
      else
        SET V_level ='1';
      end if;
    end if;

  END;

  SET P_RESULT = (V_level); LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: F_JKGL_JKM_PD.sql

-- ======================================================================
-- [002/146] BEGIN SOURCE: F_MY_STDAVG_TMPTB.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS F_MY_STDAVG_TMPTB$$

CREATE PROCEDURE F_MY_STDAVG_TMPTB(p_datasql VARCHAR(4000), OUT P_RESULT DECIMAL(38,10))
routine_body: BEGIN
-- 计算一组数据的标准值
-- 区别于算数平均值，是一组数中剔除和标准差偏离较大的坏点后，再取平均值
-- 输入数据组的脚本示例如下，对象必须别名为obj
-- 示例：select zb_total as obj from JKGL_PZ_JKM
-- 示例：select to_number(zb_val) as obj from tl_tssh.JKGL_DATA_ZB_JGB where zb_val is not null and zb_val<>0
-- select zb_val as obj from JKGL_DATA_TJ_ZB t where zb_id='W50202' and t.bgqid in (select bgqid from JKGL_DATA_BGQ b,GLXT_BB_SHXT_DJXX d where b.djxh=d.djxh_js and d.jsmode='2' and b.bgq_q=date'2019-01-01')
  DECLARE v_tmpSql VARCHAR(2000);
  DECLARE v_stddev DECIMAL(18,2);
  DECLARE v_avg DECIMAL(18,2);
  DECLARE v_deeps integer;-- 嵌套计算深度
  DECLARE v_id integer;
  DECLARE v_tablecnt integer;
  DECLARE BJTS_DYNAMIC_ROWCOUNT_001 BIGINT DEFAULT 0;

  -- 创建临时表
  SET v_tmpSql ='SELECT 1';
  SET @BJTS_DYNAMIC_OUT_001_001 = NULL;
SET @BJTS_DYNAMIC_SQL_001 = CONCAT(TRIM(TRAILING ';' FROM v_tmpSql), ' INTO @BJTS_DYNAMIC_OUT_001_001');
PREPARE BJTS_DYNAMIC_STMT_001 FROM @BJTS_DYNAMIC_SQL_001;
EXECUTE BJTS_DYNAMIC_STMT_001;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_001;
SET v_tablecnt = @BJTS_DYNAMIC_OUT_001_001;
  if v_tablecnt>0 then
    SET v_tmpSql ='DROP TEMPORARY TABLE IF EXISTS TMP_STDDEV';
    SET @BJTS_DYNAMIC_SQL_002 = v_tmpSql;
PREPARE BJTS_DYNAMIC_STMT_002 FROM @BJTS_DYNAMIC_SQL_002;
EXECUTE BJTS_DYNAMIC_STMT_002;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_002;
  end if;

  SET v_tmpSql ='CREATE TEMPORARY TABLE TMP_STDDEV (id INTEGER,val DECIMAL(18,2),ybbz CHAR(1))';
  SET @BJTS_DYNAMIC_SQL_003 = v_tmpSql;
PREPARE BJTS_DYNAMIC_STMT_003 FROM @BJTS_DYNAMIC_SQL_003;
EXECUTE BJTS_DYNAMIC_STMT_003;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_003;

--  v_tmpSql:='select nvl(max(id),0) from TMP_STDDEV';
--  EXECUTE IMMEDIATE v_tmpSql into v_id ;
--  v_id := v_id + 1;
  SET v_id =1;
  SET v_deeps =0;


  -- 首先，将数组写入临时表
  SET v_tmpSql = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('insert into TMP_STDDEV(id,val,ybbz) ', ' select '), v_id), ',obj,''1'' from ('), p_datasql), ') AS BJTS_DERIVED_001') ;
  SET @BJTS_DYNAMIC_SQL_004 = v_tmpSql;
PREPARE BJTS_DYNAMIC_STMT_004 FROM @BJTS_DYNAMIC_SQL_004;
EXECUTE BJTS_DYNAMIC_STMT_004;
SET BJTS_DYNAMIC_ROWCOUNT_001 = ROW_COUNT();
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_004;

  IF BJTS_DYNAMIC_ROWCOUNT_001 = 0 THEN
    SET v_avg =null;
  ELSE
    BJTS_LOOP_001: LOOP IF (v_deeps>3) THEN LEAVE BJTS_LOOP_001; END IF;
      SET v_deeps =v_deeps+1;
      -- 计算标准差
      SET v_tmpSql =ORA_CONCAT(ORA_CONCAT('select stddev(val) from TMP_STDDEV where id=', v_id), ' and ybbz=''1''');
      SET @BJTS_DYNAMIC_OUT_005_001 = NULL;
SET @BJTS_DYNAMIC_SQL_005 = CONCAT(TRIM(TRAILING ';' FROM v_tmpSql), ' INTO @BJTS_DYNAMIC_OUT_005_001');
PREPARE BJTS_DYNAMIC_STMT_005 FROM @BJTS_DYNAMIC_SQL_005;
EXECUTE BJTS_DYNAMIC_STMT_005;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_005;
SET v_stddev = @BJTS_DYNAMIC_OUT_005_001;
      -- 计算平均值
      SET v_tmpSql =ORA_CONCAT(ORA_CONCAT('select avg(val) from TMP_STDDEV where id=', v_id), ' and ybbz=''1''');
      SET @BJTS_DYNAMIC_OUT_006_001 = NULL;
SET @BJTS_DYNAMIC_SQL_006 = CONCAT(TRIM(TRAILING ';' FROM v_tmpSql), ' INTO @BJTS_DYNAMIC_OUT_006_001');
PREPARE BJTS_DYNAMIC_STMT_006 FROM @BJTS_DYNAMIC_SQL_006;
EXECUTE BJTS_DYNAMIC_STMT_006;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_006;
SET v_avg = @BJTS_DYNAMIC_OUT_006_001;

      if IFNULL(v_stddev, 0) = 0 OR IFNULL(v_avg, 0)=0 then
        LEAVE BJTS_LOOP_001;
      end if;

      -- 和平均值的偏差 和标准差相比，偏差在一倍以上的剔除掉。
      SET v_tmpSql =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('update TMP_STDDEV t set ybbz=''0'' where id=', v_id), ' and '), ' abs(t.val - '), v_avg), ')/'), v_stddev), ' > 2 and ybbz=''1''') ;
      SET @BJTS_DYNAMIC_SQL_007 = v_tmpSql;
PREPARE BJTS_DYNAMIC_STMT_007 FROM @BJTS_DYNAMIC_SQL_007;
EXECUTE BJTS_DYNAMIC_STMT_007;
SET BJTS_DYNAMIC_ROWCOUNT_001 = ROW_COUNT();
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_007;
      if (BJTS_DYNAMIC_ROWCOUNT_001 = 0) then
        LEAVE BJTS_LOOP_001;
      end if;
    END LOOP BJTS_LOOP_001;

    SET v_tmpSql =ORA_CONCAT(ORA_CONCAT('select avg(val) from TMP_STDDEV where id=', v_id), ' and ybbz=''1''');
    SET @BJTS_DYNAMIC_OUT_008_001 = NULL;
SET @BJTS_DYNAMIC_SQL_008 = CONCAT(TRIM(TRAILING ';' FROM v_tmpSql), ' INTO @BJTS_DYNAMIC_OUT_008_001');
PREPARE BJTS_DYNAMIC_STMT_008 FROM @BJTS_DYNAMIC_SQL_008;
EXECUTE BJTS_DYNAMIC_STMT_008;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_008;
SET v_avg = @BJTS_DYNAMIC_OUT_008_001;
  END IF;

--  delete from TMP_STDDEV where id=v_id;
  SET v_tmpSql ='DROP TEMPORARY TABLE IF EXISTS TMP_STDDEV';
  SET @BJTS_DYNAMIC_SQL_009 = v_tmpSql;
PREPARE BJTS_DYNAMIC_STMT_009 FROM @BJTS_DYNAMIC_SQL_009;
EXECUTE BJTS_DYNAMIC_STMT_009;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_009;

  SET P_RESULT = (v_avg); LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: F_MY_STDAVG_TMPTB.sql

-- ======================================================================
-- [003/146] BEGIN SOURCE: F_WLGL_EXTRACT_DATE.sql
-- ======================================================================
DELIMITER $$

DROP FUNCTION IF EXISTS F_WLGL_EXTRACT_DATE$$

CREATE FUNCTION F_WLGL_EXTRACT_DATE
-- ============================================
-- 函数：提取并标准化起运日
-- ============================================
(
  p_text VARCHAR(4000),
  p_date DATETIME
)
RETURNS DATETIME
NOT DETERMINISTIC
READS SQL DATA
BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';
  DECLARE v_date_ck     VARCHAR(100);
  DECLARE v_text_nock   VARCHAR(2000);
  DECLARE v_pattern     VARCHAR(200);
  DECLARE v_date_str    VARCHAR(30);
  DECLARE v_result      DATETIME;


  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
  RETURN NULL; -- 日期解析失败返回空

  END;
IF p_text IS NULL THEN
    RETURN NULL;
  END IF;

  -- 为防止出口日期干扰，将出口日期相关信息先置换掉
  SET v_pattern = '(出口日期)[:：[:space:]]*(\\d{8}|\\d{4}[-/\\.,]\\d{1,2}[-/\\.,]\\d{1,2}|\\d{4}年\\d{1,2}月\\d{1,2}日)';
  SET v_date_ck = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  SET v_text_nock = REGEXP_REPLACE(p_text, v_date_ck, '');

  -- 1、有日期格式(Mon-dd-yyyy OR YYYY-Mon-DD)
  SET v_pattern = ORA_CONCAT('((Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Mon|Nov|Dec)[-/\\.,]\\d{1,2}[-/\\.,]\\d{4}|', '\\d{4}[-/\\.,](Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Mon|Nov|Dec)[-/\\.,]\\d{1,2})');
  SET v_date_str = UPPER(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'));
  IF v_date_str IS NULL THEN
    -- 2、有日期格式(Y.M.D OR Y年M月D日(号) OR M月D日(号))
    SET v_pattern = '(\\d{2,4}[-/\\.]\\d{1,2}[-/\\.]\\d{1,2}|\\d{2,4}年\\d{1,2}月\\d{1,2}(日|号)|\\d{1,2}月\\d{1,2}(日|号))';
    SET v_date_str = REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'号','日');
  END IF;
  IF v_date_str IS NULL THEN
    -- 3、纯8位数字YYYYMMDD，为了准确分割，要求提取的8位数据前后均为非数字，然后将前后的非数字替换掉
    SET v_pattern = '[^0-9]\\d{8}([^0-9]|$)';
    SET v_date_str = REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'[^0-9]+','');
  END IF;
  IF v_date_str IS NULL THEN
    -- 4、带前缀日期标识的6位YYMMDD、4位MMDD，为了准确分割，要求提取的数据后面为非数字
    SET v_pattern = '(起运|启运|出运|起始|起送|始运|发车|发货|装货|送货|拉货|装运|装柜|装箱)(日|日期|时间)[:：[:space:]]*(\\d{6}|\\d{4})([^0-9]|$)';
    SET v_date_str = REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'[^0-9]+','');
  END IF;
  IF v_date_str IS NULL THEN
    -- 5、带前缀日期标识的 MM.DD，为了准确分割，要求提取的数据后面为非数字
    SET v_pattern = '(起运|启运|出运|起始|起送|始运|发车|发货|装货|送货|拉货|装运|装柜|装箱)(日|日期|时间)[:：[:space:]]*\\d{1,2}[-/\\.]\\d{1,2}([^0-9]|$)';
    SET v_date_str = REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'[^0-9/\\.-]+','');
  END IF;

  -- 统一标准化为 YYYY-MM-DD
  -- 情况1.1: APR.13.2026
  IF REGEXP_LIKE(v_date_str, '^(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|MON|NOV|DEC)[-/\\.,]\\d{1,2}[-/\\.,]\\d{4}$') THEN
    SELECT STR_TO_DATE(REGEXP_REPLACE(v_date_str, '[-/\\.,]', '-'), '%b-%d-%Y')
      INTO v_result
;
  -- 情况1.2: 2026.APR.13
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{4}[-/\\.,](JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|MON|NOV|DEC)[-/\\.,]\\d{1,2}$') THEN
    SELECT STR_TO_DATE(REGEXP_REPLACE(v_date_str, '[-/\\.]', '-'), '%Y-%b-%d')
      INTO v_result
;
  -- 情况2.1: 2023-01-15 / 2023/01/15 / 2023.01.15
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{4}[-/\\.]\\d{1,2}[-/\\.]\\d{1,2}$') THEN
    SELECT STR_TO_DATE(REGEXP_REPLACE(v_date_str, '[-/\\.]', '-'), '%Y-%m-%d')
      INTO v_result
;
  -- 情况2.2: 23-01-15 / 23/01/15 / 23.01.15
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{2}[-/\\.]\\d{1,2}[-/\\.]\\d{1,2}$') THEN
    SELECT STR_TO_DATE(REGEXP_REPLACE(ORA_CONCAT('20', v_date_str), '[-/\\.]', '-'), '%Y-%m-%d')
      INTO v_result
;
  -- 情况2.3: 2023年1月15日
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{4}年\\d{1,2}月\\d{1,2}日$') THEN
    SELECT STR_TO_DATE(v_date_str, '%Y年%m月%d日')
      INTO v_result
;
  -- 情况2.4: 23年1月15日
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{2}年\\d{1,2}月\\d{1,2}日$') THEN
    SELECT STR_TO_DATE(ORA_CONCAT('20', v_date_str), '%Y年%m月%d日')
      INTO v_result
;
  -- 情况2.5: 1月15日
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{1,2}月\\d{1,2}日$') THEN
    SELECT STR_TO_DATE(ORA_CONCAT(ORA_CONCAT(DATE_FORMAT(p_date, '%Y'), '年'), v_date_str), '%Y年%m月%d日')
      INTO v_result
;
  -- 情况3: 纯8位数字 20230115
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{8}$') THEN
    SELECT STR_TO_DATE(v_date_str, '%Y%m%d')
      INTO v_result
;
  -- 情况4.1: 纯6位数字 230115
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{6}$') THEN
    SELECT STR_TO_DATE(ORA_CONCAT('20', v_date_str), '%Y%m%d')
      INTO v_result
;
  -- 情况4.2: 纯4位数字 0115
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{4}$') THEN
    SELECT STR_TO_DATE(ORA_CONCAT(DATE_FORMAT(p_date, '%Y'), v_date_str), '%Y%m%d')
      INTO v_result
;
  -- 情况5: 01-15 / 01/15 / 01.15
  ELSEIF REGEXP_LIKE(v_date_str, '^\\d{1,2}[-/\\.]\\d{1,2}$') THEN
    SELECT STR_TO_DATE(ORA_CONCAT(ORA_CONCAT(DATE_FORMAT(p_date, '%Y'), '-'), REGEXP_REPLACE(v_date_str, '[-/\\.]', '-')), '%Y-%m-%d')
      INTO v_result
;
  END IF;

  RETURN v_result;

END$$

DELIMITER ;

-- END SOURCE: F_WLGL_EXTRACT_DATE.sql

-- ======================================================================
-- [004/146] BEGIN SOURCE: F_WLGL_EXTRACT_FROM.sql
-- ======================================================================
DELIMITER $$

DROP FUNCTION IF EXISTS F_WLGL_EXTRACT_FROM$$

CREATE FUNCTION F_WLGL_EXTRACT_FROM
-- ============================================
-- 函数：提取起运地
-- ============================================
(
  p_text VARCHAR(4000)
)
RETURNS VARCHAR(4000)
NOT DETERMINISTIC
READS SQL DATA
BEGIN
  DECLARE v_pattern   VARCHAR(200);
  DECLARE v_result    VARCHAR(500) DEFAULT '';
  DECLARE v_end       BIGINT;

  IF p_text IS NULL THEN
    RETURN NULL;
  END IF;

  -- 方式1: 匹配关键词前缀，取到下一个分隔符(逗号/分号/空白字符)为止
  SET v_pattern = '(起至运|起运|启运|起始|起送|始发|始运|出发|出运|发货|出货|发车|装货|装运|装车|装柜|装箱|托运)(地点|地址|地区|地|点)[:：;；[:space:]]*\\s*([^A-Z0-9,，;；：.．。、/[:space:]]+)';
  SET v_result = ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 3);
  IF v_result IS NULL OR LENGTH(v_result)<2 THEN
    SET v_pattern = '(货源地|产地)[:：;；[:space:]]*\\s*([^A-Z0-9,，;；：.．。、/[:space:]]+)';
    SET v_result = ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 2);
  END IF;
  -- 起运地后无分隔，直接跟其他汉字，根据目前备注的标签截取
  SET v_end = REGEXP_INSTR(v_result,'起运|启运|起始|起送|始发|始运|出发|出运|发货|出货|发车|装货|装运|装车|币种|车牌|快递|报关',1);
  IF v_end>1 THEN
    SET v_result = SUBSTR(v_result,1,v_end-1);
  END IF;

  -- 方式2.1: 匹配"从XX出发/起运"
  IF v_result IS NULL OR LENGTH(v_result)<2 THEN
    SET v_pattern = '(从|在)([^A-Z0-9,，;；.．。[:space:]]+)(到|至|出发|起运|发运|发货|发车|装车|发往)';
    SET v_result = ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 2);
  END IF;

  -- 方式2.2: 匹配"从XX出发/起运"
  IF v_result IS NULL OR LENGTH(v_result)<2 THEN
    SET v_pattern = '([^A-Z0-9,，;；.．。[:space:]]+)(到|至|出发|起运|发运|发货|发车|装车|发往)';
    SET v_result = ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 1);
  END IF;

  -- 方式3: 兜底 - 匹配常见省/市后缀地名（可按需扩展字典）
  IF v_result IS NULL OR LENGTH(v_result)<2 THEN
    SET v_pattern = '[^A-Z0-9,，;；:：.．。[:space:]]*(省|市|自治区|州|县|区)';
    SET v_result = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  END IF;

  -- 方式4: 兜底 - 省内地市、绍兴区县
  IF v_result IS NULL OR LENGTH(v_result)<2 THEN
    SET v_pattern = '(浙江|杭州|宁波|温州|嘉兴|湖州|绍兴|金华|衢州|舟山|台州|丽水|越城|柯桥|上虞|新昌|诸暨|上虞|嵊州)($|[^A-Z0-9,，;；：.．。、[:space:]]*)';
    SET v_result = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  END IF;

  RETURN v_result;

END$$

DELIMITER ;

-- END SOURCE: F_WLGL_EXTRACT_FROM.sql

-- ======================================================================
-- [005/146] BEGIN SOURCE: F_WLGL_EXTRACT_PARCEL.sql
-- ======================================================================
DELIMITER $$

DROP FUNCTION IF EXISTS F_WLGL_EXTRACT_PARCEL$$

CREATE FUNCTION F_WLGL_EXTRACT_PARCEL
-- ============================================
-- 函数：物流、快递单号（仅取第一个）
-- ============================================
(
  p_text VARCHAR(4000)
)
RETURNS VARCHAR(4000)
NOT DETERMINISTIC
READS SQL DATA
BEGIN
  DECLARE v_pattern   VARCHAR(200);
  DECLARE v_result    VARCHAR(500) DEFAULT '';

  IF p_text IS NULL THEN
    RETURN NULL;
  END IF;

  -- 1.1、UPS(1Z+16位编码）
  SET v_pattern = '(1Z|IZ)[[:space:]]?[A-Z0-9]{3}[[:space:]]?[A-Z0-9]{3}[[:space:]]?[A-Z0-9]{2}[[:space:]]?[A-Z0-9]{4}[[:space:]]?[A-Z0-9]{4}';
  SET v_result = REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i'),'[[:space:]]',''),'IZ','1Z');
  IF v_result IS NOT NULL THEN
    RETURN UPPER(v_result);
  END IF;

  -- 1.2、DHL(10位数字)
  IF REGEXP_INSTR(UPPER(p_text),'DHL|WAYBILL') > 0 THEN
    SET v_pattern = '(DHL|DHL NO.|WAYBILL|快递|快递号|快递单|快递单号|国际快件|提单|[^(报关|报关单|报送|报送单)]单号)[#:：_[:space:]-]{0,3}(\\d{2}[[:space:]]?\\d{4}[[:space:]]?\\d{4})';
    SET v_result = REGEXP_REPLACE(ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 2),'[[:space:]]','');
  END IF;
  IF v_result IS NOT NULL THEN
    RETURN ORA_CONCAT('DHL', UPPER(v_result));
  END IF;

  -- 1.3、FEDEX(10-12位数字)
  IF REGEXP_INSTR(UPPER(p_text),'联邦|FEDEX|TRK') > 0 THEN
    SET v_pattern = '(FEDEX|FEDEX NO.|联邦|TRK|快递|快递号|快递单|快递单号|国际快件|提单|[^(报关|报关单|报送|报送单)]单号)[#:：_[:space:]-]{0,3}(\\d{4}[[:space:]]?\\d{4}[[:space:]]?\\d{2,4})';
    SET v_result = REGEXP_REPLACE(ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 2),'[[:space:]]','');
  END IF;
  IF v_result IS NOT NULL THEN
    RETURN ORA_CONCAT('FEDEX', UPPER(v_result));
  END IF;

  -- 1.4、顺丰(SF+12,13位数字）
  IF REGEXP_INSTR(UPPER(p_text),'顺丰|SF') > 0 THEN
    SET v_pattern = '(顺丰|SF|快递|快递号|快递单|快递单号|国际快件|提单|[^(报关|报关单|报送|报送单)]单号)[#:：_[:space:]-]{0,3}(\\d{3}[[:space:]]?\\d{3}[[:space:]]?\\d{3}[[:space:]]?\\d{3,4})';
    SET v_result = REGEXP_REPLACE(ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 2),'[[:space:]]','');
  END IF;
  IF v_result IS NOT NULL THEN
    RETURN ORA_CONCAT('SF', UPPER(v_result));
  END IF;

  -- 1.5、德邦(DPK|DPL+12位数字）
  SET v_pattern = '(DPK|DPL)\\d{12}';
  SET v_result = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  IF v_result IS NOT NULL THEN
    RETURN UPPER(v_result);
  END IF;

  -- 1.6、跨越(KY+13位数字 or KYE+12位数字）
  SET v_pattern = '(KY)(\\d{13}|E\\d{12})';
  SET v_result = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  IF v_result IS NOT NULL THEN
    RETURN UPPER(v_result);
  END IF;

  -- 1.7、中通快运（ZY+12位数字）
  SET v_pattern = '(ZY)\\d{12}';
  SET v_result = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  IF v_result IS NOT NULL THEN
    RETURN UPPER(v_result);
  END IF;

  -- 1.8、京东(JD+13-18位字符）
  SET v_pattern = '(JD)[A-Z0-9]{13,18}';
  SET v_result = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  IF v_result IS NOT NULL THEN
    RETURN UPPER(v_result);
  END IF;

  -- 1.9、安能|中通|申通|百世|韵达
  SET v_pattern = '(安能|中通|申通|百世|韵达)[物流快速运递单号#:：;；_[:space:]-]*([0-9]{6,20})';
  SET v_result = REGEXP_REPLACE(REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i'),'[物流快速运递单号#:：;；_[:space:]-]','');
  IF v_result IS NOT NULL THEN
    RETURN UPPER(v_result);
  END IF;

  -- 1.10、速腾|速通|汇森速运|嘉里大通|顺心捷达|融辉
  SET v_pattern = '(速腾|速通|汇森速运|嘉里大通|顺心捷达|融辉)[物流快递单号#:：;；_[:space:]-]*([A-Z0-9]{6,20})';
  SET v_result = REGEXP_REPLACE(REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i'),'[物流快递单号#:：;；_[:space:]-]','');
  IF v_result IS NOT NULL THEN
    RETURN UPPER(v_result);
  END IF;

  -- 2.1、其他快递
  SET v_pattern = '(快递|快递单|快递号|快递单号|快递运单|快递运单号)[:：[:space:]]{0,3}([A-Z0-9]{6,20}|\\d{2,4}[[:space:]-]?\\d{3,4}[[:space:]]?\\d{4}|\\d{2}[[:space:]-]?\\d{3}[[:space:]-]?\\d{3}[[:space:]-]?\\d{3})';
  SET v_result = UPPER(REGEXP_REPLACE(ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 2),'[[:space:]-]',''));
  IF v_result IS NOT NULL THEN
    RETURN ORA_CONCAT('(快递)', UPPER(v_result));
  END IF;

  -- 2.2、其他物流
  SET v_pattern = '(物流|物流单|物流号|物流单号)[:：[:space:]]{0,3}([A-Z0-9]{6,20}|\\d{2,4}[[:space:]-]?\\d{3,4}[[:space:]]?\\d{4}|\\d{2}[[:space:]-]?\\d{3}[[:space:]-]?\\d{3}[[:space:]-]?\\d{3})';
  SET v_result = UPPER(REGEXP_REPLACE(ORA_REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i', 2),'[[:space:]-]',''));
  IF v_result IS NOT NULL THEN
    RETURN ORA_CONCAT('(物流)', UPPER(v_result));
  END IF;

  RETURN UPPER(v_result);

END$$

DELIMITER ;

-- END SOURCE: F_WLGL_EXTRACT_PARCEL.sql

-- ======================================================================
-- [006/146] BEGIN SOURCE: F_WLGL_EXTRACT_PLATE.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS F_WLGL_EXTRACT_PLATE$$

CREATE PROCEDURE F_WLGL_EXTRACT_PLATE
-- ============================================
-- 函数：提取车牌号、物流单号（仅取第一个）
-- ============================================
(
  IN p_text VARCHAR(4000),
  OUT p_addr DECIMAL(38,10)
, OUT P_RESULT VARCHAR(4000))
routine_body: BEGIN
  DECLARE v_pattern   VARCHAR(200);
  DECLARE v_result    VARCHAR(500) DEFAULT '';

  IF p_text IS NULL THEN
    SET P_RESULT = NULL; LEAVE routine_body;
  END IF;

  -- 匹配车牌号
  -- 省份简称 + 字母 + 5或6位字母数字，包括 7 位燃油车 / 8 位新能源
  -- 允许省份与字母智检有一个空格、允许首字母与后续号码之间有。.·空格等
  -- 自动屏蔽 I、O 易混淆字母，不匹配军牌、警牌、使领馆黑牌、挂车
  -- v_pattern := '([京津冀晋蒙辽吉黑沪苏浙皖闽赣鲁豫鄂湘粤桂琼渝川贵云藏陕甘青宁新][.·[:space:]-]{0,1}[A-HJ-NP-Z][。？.·[:space:]-]{0,1}([0-9A-HJ-NP-Z]{5,6}))';

  -- 将I转换为1，O转换为0，不匹配军牌、警牌、使领馆黑牌、挂车
  SET v_pattern = '([京津冀晋蒙辽吉黑沪苏浙皖闽赣鲁豫鄂湘粤桂琼渝川贵云藏陕甘青宁新][.·[:space:]-]{0,1}[A-Z][。？.·[:space:]-]{0,1}([0-9A-Z]{5,6}))';
  SET v_result = REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  SET p_addr = REGEXP_INSTR(p_text,v_result,1);
  SET v_result = UPPER(REGEXP_REPLACE(v_result,'[。？.·[:space:]-]',''));
  SET v_result = REGEXP_REPLACE(v_result,'I','1');
  SET v_result = REGEXP_REPLACE(v_result,'O','0');

  SET P_RESULT = UPPER(v_result); LEAVE routine_body;

END$$

DELIMITER ;

-- END SOURCE: F_WLGL_EXTRACT_PLATE.sql

-- ======================================================================
-- [007/146] BEGIN SOURCE: ORIGINAL_JKGL_DATA_TJ_ZBU.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS ORIGINAL_JKGL_DATA_TJ_ZBU$$

CREATE PROCEDURE ORIGINAL_JKGL_DATA_TJ_ZBU()
/*
 * 指标元刷新口径
 * 金三、电子抵账部分数据的统计，通过ETL实现。
 */
routine_body: BEGIN
  DECLARE V_CK_BGDSL        BIGINT; --  出口_报关单数量
  DECLARE V_CK_CKEUSD       DECIMAL(18,2); --  出口_出口额USD
  DECLARE V_CK_CKERMB       DECIMAL(18,2); --  出口_出口额
  DECLARE V_CK_SBDW_SL      BIGINT; --  出口_申报单位数量
  DECLARE V_CK_GB_SL        BIGINT; --  出口_目的国数量
  DECLARE V_CK_BGDSL_DE     BIGINT; --  出口_大额报关单数量
  DECLARE V_CK_CKEUSD_DE    DECIMAL(18,2); --  出口_大额报关单出口额USD
  DECLARE V_CK_BGDSL_ST     BIGINT; --  出口_四同报关单数量
  DECLARE V_CK_PXBGDSL      BIGINT; --  出口_拼箱报关单数量
  DECLARE V_CK_ZXBGDSL      DECIMAL(18,2); --  出口_整箱报关单数量
  DECLARE V_CK_PJDBHGZ      DECIMAL(18,2); --  出口_平均单笔货柜值
  DECLARE V_CK_CKEUSD_LASTYEAR	DECIMAL(18,2); --	出口_最近12个月出口额USD
  DECLARE V_ZZS_XSE_QB      DECIMAL(18,2); --  增值税_全部销售
  DECLARE V_ZZS_XSE_MDT     DECIMAL(18,2); --  增值税_免抵退出口销售
  DECLARE V_ZZS_XSE_MS      DECIMAL(18,2); --  增值税_免税销售
  DECLARE V_ZZS_XXSE        DECIMAL(18,2); --  增值税_销项税额
  DECLARE V_ZZS_JXSE        DECIMAL(18,2); --  增值税_进项税额
  DECLARE V_ZZS_JXSEZC      DECIMAL(18,2); --  增值税_进项税额转出
  DECLARE V_ZZS_MDTBDDKJXSE DECIMAL(18,2); --  增值税_免抵退不得抵扣进项税额
  DECLARE V_ZZS_YNSE        DECIMAL(18,2); --  增值税_应纳税额
  DECLARE V_DZ_XXFS_QB      BIGINT; --  底账_销项份数_全部
  DECLARE V_DZ_XXJE_QB      DECIMAL(18,2); --  底账_销项金额_全部
  DECLARE V_DZ_XXSE_QB      DECIMAL(18,2); --  底账_销项税额_全部
  DECLARE V_DZ_XXFS_ZY      BIGINT; --  底账_销项份数_专票
  DECLARE V_DZ_XXJE_ZY      DECIMAL(18,2); --  底账_销项金额_专票
  DECLARE V_DZ_XXSE_ZY      DECIMAL(18,2); --  底账_销项税额_专票
  DECLARE V_DZ_XXFS_PT      BIGINT; --  底账_销项份数_普票
  DECLARE V_DZ_XXJE_PT      DECIMAL(18,2); --  底账_销项金额_普票
  DECLARE V_DZ_XXSE_PT      DECIMAL(18,2); --  底账_销项税额_普票
  DECLARE V_DZ_XXFS_CK      BIGINT; --  底账_销项份数_出口
  DECLARE V_DZ_XXJE_CK      DECIMAL(18,2); --  底账_销项金额_出口
  DECLARE V_DZ_JXFS_QB      BIGINT; --  底账_全部进项份数
  DECLARE V_DZ_JXJE_QB      DECIMAL(18,2); --  底账_全部进项金额
  DECLARE V_DZ_JXSE_QB      DECIMAL(18,2); --  底账_全部进项税额
  DECLARE V_DZ_JXFS_ZY      BIGINT; --  底账_进项份数_专票
  DECLARE V_DZ_JXJE_ZY      DECIMAL(18,2); --  底账_进项金额_专票
  DECLARE V_DZ_JXSE_ZY      DECIMAL(18,2); --  底账_进项税额_专票
  DECLARE V_DZ_JXFS_PT      BIGINT; --  底账_进项份数_普票
  DECLARE V_DZ_JXJE_PT      DECIMAL(18,2); --  底账_进项金额_普票
  DECLARE V_DZ_JXSE_PT      DECIMAL(18,2); --  底账_进项税额_普票
  DECLARE V_DZ_JXFS_DGKJ    BIGINT; --  底账_进项份数_专票顶格开具
  DECLARE V_DZ_JXJE_DGKJ    DECIMAL(18,2); --  底账_进项金额_专票顶格开具
  DECLARE V_DZ_JXSE_DGKJ    DECIMAL(18,2); --  底账_进项税额_专票顶格开具
  DECLARE V_DZ_JXSE_JKS     DECIMAL(18,2); --  底账_进项税额_缴款书
  DECLARE V_DZ_JXJE_NCP     DECIMAL(18,2); --  底账_进项金额_农产品
  DECLARE V_DZ_JXSE_NCP     DECIMAL(18,2); --  底账_进项税额_农产品
  DECLARE V_DZ_DFJE_SR      DECIMAL(18,2); --  底账_电费收入（销项）
  DECLARE V_DZ_DFJE_ZC      DECIMAL(18,2); --  底账_电费支出（进项）
  DECLARE V_DZ_WTJG         DECIMAL(18,2); --  底账_委托加工费支出
  DECLARE V_DZ_YFJE         DECIMAL(18,2); --  底账_运费支出
  DECLARE V_DZ_JXJE_SN      DECIMAL(18,2); --  底账_进项金额_省内
  DECLARE V_DZ_JXJE_SW      DECIMAL(18,2); --  底账_进项金额_省外
  DECLARE V_TS_BGDSL        BIGINT; --  退税_报关单数量
  DECLARE V_TS_CKEUSD       DECIMAL(18,2); --  退税_出口额USD
  DECLARE V_TS_CKERMB       DECIMAL(18,2); --  退税_出口额RMB
  DECLARE V_TS_JSJE         DECIMAL(18,2); --  退税_计税金额（免退税）
  DECLARE V_TS_HHCB         DECIMAL(18,2); --  退税_换汇成本（免退税）
  DECLARE V_TS_BGDSL_CQ     BIGINT; --  退税_报关单数量_超期申报
  DECLARE V_TS_CKEUSD_CQ    DECIMAL(18,2); --  退税_出口额USD_超期申报
  DECLARE V_TS_TSE_SB       DECIMAL(18,2); --  退税_退税额_申报
  DECLARE V_TS_MDE_SB       DECIMAL(18,2); --  退税_免抵额_申报
  DECLARE V_TS_TSE_HZ       DECIMAL(18,2); --  退税_退税_核准
  DECLARE V_TS_MDE_HZ       DECIMAL(18,2); --  退税_免抵_核准
  DECLARE V_TS_TSE_BL       DECIMAL(18,2); --  退税_退税_办理
  DECLARE V_TS_MDE_BL       DECIMAL(18,2); --  退税_免抵_办理
  DECLARE V_TS_CKERMB_STZC  DECIMAL(18,2); --  退税_视同自产出口额
  DECLARE V_TS_JHFP_JE_DG   DECIMAL(18,2); --  退税_顶格开票金额
  DECLARE V_TS_JHFP_FS_DG   BIGINT; --  退税_顶格开票份数
  DECLARE V_TS_JHFP_JE      DECIMAL(18,2); --  退税_发票总金额
  DECLARE V_TS_JHFP_FS      BIGINT; --  退税_发票总份数
  DECLARE V_TS_JHFP_JE_CQ1  DECIMAL(18,2); --  退税_超期1发票金额
  DECLARE V_TS_JHFP_FS_CQ1  BIGINT; --  退税_超期1发票份数
  DECLARE V_TS_JHFP_JE_CQ2  DECIMAL(18,2); --  退税_超期2发票金额
  DECLARE V_TS_JHFP_FS_CQ2  BIGINT; --  退税_超期2发票份数
  DECLARE V_TS_GHS_NUM      BIGINT; --  退税_供货商个数
  DECLARE V_ZC_YSZK_QC      DECIMAL(18,2); --  资产_应收账款_期初
  DECLARE V_ZC_YSZK_QM      DECIMAL(18,2); --  资产_应收账款_期末
  DECLARE V_ZC_YFZK_QC      DECIMAL(18,2); --  资产_应付账款_期初
  DECLARE V_ZC_YFZK_QM      DECIMAL(18,2); --  资产_应付账款_期末
  DECLARE V_ZC_GDZC_QC      DECIMAL(18,2); --  资产_固定资产_期初
  DECLARE V_ZC_GDZC_QM      DECIMAL(18,2); --  资产_固定资产_期末
  DECLARE V_ZC_CH_QC        DECIMAL(18,2); --  资产_存货_期初
  DECLARE V_ZC_CH_QM        DECIMAL(18,2); --  资产_存货_期末
  DECLARE V_ZC_ZCZE_QC      DECIMAL(18,2); --  资产_资产总额_期初
  DECLARE V_ZC_ZCZE_QM      DECIMAL(18,2); --  资产_资产总额_期末
  DECLARE V_ZC_FZZE_QC      DECIMAL(18,2); --  资产_负债总额_期初
  DECLARE V_ZC_FZZE_QM      DECIMAL(18,2); --  资产_负债总额_期末
  DECLARE V_ZC_SYZQY_QC     DECIMAL(18,2); --  资产_所有者权益_期初
  DECLARE V_ZC_SYZQY_QM     DECIMAL(18,2); --  资产_所有者权益_期末
  DECLARE V_ZC_SSGDQY_QC    DECIMAL(18,2); --  资产_少数股东权益_期初
  DECLARE V_ZC_SSGDQY_QM    DECIMAL(18,2); --  资产_少数股东权益_期末
  DECLARE V_ZC_LDZC_QC      DECIMAL(18,2); --  资产_流动资产_期初
  DECLARE V_ZC_LDZC_QM      DECIMAL(18,2); --  资产_流动资产_期末
  DECLARE V_ZC_YUSZK_QC     DECIMAL(18,2); --  资产_预收账款_期初
  DECLARE V_ZC_YUSZK_QM     DECIMAL(18,2); --  资产_预收账款_期末
  DECLARE V_ZC_YUFZK_QC     DECIMAL(18,2); --  资产_预付账款_期初
  DECLARE V_ZC_YUFZK_QM     DECIMAL(18,2); --  资产_预付账款_期末
  DECLARE V_ZC_LDFZZE_QC    DECIMAL(18,2); --  资产_流动负债总额_期初
  DECLARE V_ZC_LDFZZE_QM    DECIMAL(18,2); --  资产_流动负债总额_期末

  DECLARE V_LR_YYSR         DECIMAL(18,2); --  利润_营业收入
  DECLARE V_LR_YYCB         DECIMAL(18,2); --  利润_营业成本
  DECLARE V_LR_XSFY         DECIMAL(18,2); --  利润_销售费用
  DECLARE V_LR_GLFY         DECIMAL(18,2); --  利润_管理费用
  DECLARE V_LR_YYLR         DECIMAL(18,2); --  利润_营业利润
  DECLARE V_LR_LRZE         DECIMAL(18,2); --  利润_利润总额
  DECLARE V_LR_QTSR         DECIMAL(18,2); --  利润_其它收入
  DECLARE V_LR_SJJFJ        DECIMAL(18,2); --  利润_税金及附加
  DECLARE V_LR_CWFY         DECIMAL(18,2); --  利润_财务费用
  DECLARE V_LR_JLR          DECIMAL(18,2); --  利润_净利润
  DECLARE V_LR_SDS          DECIMAL(18,2); --  利润_所得税
  DECLARE V_LR_LXZC         DECIMAL(18,2); --  利润_利息支出

  DECLARE V_CW_MLL          DECIMAL(8,2); --  财务_毛利率
  DECLARE V_CW_HYSFL        DECIMAL(8,2); --  财务_还原税负率

  DECLARE V_ROWS            BIGINT;  -- 待更新表中是否存在目标记录
  DECLARE V_CK_BGDSL_SN     BIGINT;  -- 出口_上年报关单数量，用于确定大额报关单阈值
  DECLARE V_CK_CKEUSD_SN    DECIMAL(18,2); -- 出口_上年报关单出口额USD，用于确定大额报关单阈值
  DECLARE V_CK_DEBGD_YZ     DECIMAL(18,2); -- 出口_大额报关单阈值
  DECLARE V_SDS_YYSR        DECIMAL(18,2); --     所得税_营业收入
  DECLARE V_SDS_YNSSDE      DECIMAL(18,2); --     所得税_应纳税所得额

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGQ_BGQID_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_NSRDJNO_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_SHXYNO_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_ZQLX_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Q_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Z_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_YF_Q_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_YF_Z_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.BGQID, T.DJXH, S.NSRDJNO, S.SHXYNO, T.ZQLX,
                         T.BGQ_Q, T.BGQ_Z, DATE_FORMAT(T.BGQ_Q, '%Y%m') AS YF_Q, DATE_FORMAT(T.BGQ_Z, '%Y%m') AS YF_Z
                    FROM JKGL_DATA_BGQ T
                   INNER JOIN GLXT_BB_SHXT_DJXX S ON S.DJXH_JS=T.DJXH
                   WHERE T.SXZT='0' AND T.TQBZ IS NULL AND T.BGQ_Z<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_BGQ_BGQID_001, BJTS_CUR_BGQ_DJXH_001, BJTS_CUR_BGQ_NSRDJNO_001, BJTS_CUR_BGQ_SHXYNO_001, BJTS_CUR_BGQ_ZQLX_001, BJTS_CUR_BGQ_BGQ_Q_001, BJTS_CUR_BGQ_BGQ_Z_001, BJTS_CUR_BGQ_YF_Q_001, BJTS_CUR_BGQ_YF_Z_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    -- 锁定正在处理的报告期
    UPDATE JKGL_DATA_BGQ AS T
       SET TQBZ=REPLACE(UUID(), '-', ''),
    TQSJ=CURRENT_TIMESTAMP,
    SXZT='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU.BGQID
    SELECT LEAST(COUNT(1), 1)
      INTO V_ROWS
      FROM JKGL_DATA_TJ_ZBU T
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001 AND 1=1;
    IF V_ROWS=0 THEN
      INSERT INTO JKGL_DATA_TJ_ZBU(BGQID) VALUES (BJTS_CUR_BGQ_BGQID_001);
      COMMIT;
    END IF;

    --  V_CK_
    BEGIN
      --  V_CK_BGDSL  NUMBER(10)  出口_报关单数量
      --  V_CK_CKEUSD NUMBER(18,2)  出口_出口额USD
      --  V_CK_CKERMB NUMBER(18,2)  出口_出口额
      --  V_CK_SBDW_SL  NUMBER(10)  出口_申报单位数量
      --  V_CK_GB_SL  NUMBER(10)  出口_目的国数量
      SELECT COUNT(DISTINCT SUBSTR(T.CKBGDH,1,18)), IFNULL(SUM(T.MYLAJ), 0), IFNULL(SUM(T.RMBLAJ), 0),
             COUNT(DISTINCT T.SBDWDM), COUNT(DISTINCT T.MYGDQSZ_DM)
        INTO V_CK_BGDSL, V_CK_CKEUSD, V_CK_CKERMB, V_CK_SBDW_SL, V_CK_GB_SL
        FROM CKTS_WBSJ_HG_BGD T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND T.JGFS_DM<>'1039';

      --  V_CK_BGDSL_DE NUMBER(10)  出口_大额报关单数量
      --  V_CK_CKEUSD_DE  NUMBER(18,2)  出口_大额报关单出口额USD
      --  每单超10W美金算大额报关单
      SELECT COUNT(1), IFNULL(SUM(MYLAJ18), 0)
        INTO V_CK_BGDSL_DE, V_CK_CKEUSD_DE
        FROM (SELECT SUBSTR(T.CKBGDH,1,18) AS BGD18, SUM(T.MYLAJ) AS MYLAJ18
                FROM CKTS_WBSJ_HG_BGD T
               WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                 AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                 AND T.JGFS_DM<>'1039'
               GROUP BY SUBSTR(T.CKBGDH,1,18)
              HAVING SUM(T.MYLAJ)>100000) T2;

      --  V_CK_BGDSL_ST NUMBER(10)  出口_四同报关单数量
      SELECT COUNT(1)
        INTO V_CK_BGDSL_ST
        FROM (SELECT T.CKRQ_1,T.HGGQKA_DM,T.CKSP_DM,T.MYGDQSZ_DM, COUNT(DISTINCT SUBSTR(T.CKBGDH,1,18)) AS STNUM
                FROM CKTS_WBSJ_HG_BGD T
               WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                 AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                 AND T.JGFS_DM<>'1039'
               GROUP BY T.CKRQ_1,T.HGGQKA_DM,T.CKSP_DM,T.MYGDQSZ_DM) AS BJTS_DERIVED_001
       WHERE STNUM>=3;

      --  V_CK_PXBGDSL  NUMBER(10)  出口_拼箱报关单数量
      SELECT COUNT(DISTINCT T.BGDHGBH)
        INTO V_CK_PXBGDSL
        FROM CKTS_WBSJ_HG_BGD204 T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND EXISTS (SELECT 1
                       FROM CKTS_WBSJ_HG_BGD204 S
                      WHERE S.JZXH=T.JZXH AND S.CKRQ_1=T.CKRQ_1 AND S.DJXH<>T.DJXH);

      --  V_CK_ZXBGDSL  NUMBER(18,2)  出口_整箱报关单数量
      --  V_CK_PJDBHGZ  NUMBER(18,2)  出口_平均单笔货柜值
      WITH JZXHXX AS (SELECT T2.BGDHGBH, COUNT(DISTINCT T2.JZXH) AS JZXSL
                        FROM CKTS_WBSJ_HG_BGD204 T2
                       WHERE T2.DJXH=BJTS_CUR_BGQ_DJXH_001
                         AND T2.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T2.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                         AND NOT EXISTS (SELECT 1
                                           FROM CKTS_WBSJ_HG_BGD204 T3
                                          WHERE T3.JZXH=T2.JZXH AND T3.CKRQ_1=T2.CKRQ_1 AND T3.DJXH<>T2.DJXH)
                       GROUP BY T2.BGDHGBH),
           CKBGXX AS (SELECT SUBSTR(T.CKBGDH,1,18) AS BGDHGBH, SUM(T.MYLAJ) AS TOTALMY
                        FROM CKTS_WBSJ_HG_BGD T
                       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                         AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                         AND T.JGFS_DM<>'1039'
                       GROUP BY SUBSTR(T.CKBGDH,1,18))
      SELECT COUNT(DISTINCT JZXHXX.BGDHGBH),
             IFNULL((CASE WHEN SUM(JZXHXX.JZXSL)=0 THEN 0 ELSE SUM(CKBGXX.TOTALMY)/SUM(JZXHXX.JZXSL) END), 0)
        INTO V_CK_ZXBGDSL, V_CK_PJDBHGZ
        FROM JZXHXX
       INNER JOIN CKBGXX ON JZXHXX.BGDHGBH=CKBGXX.BGDHGBH;

      --  V_CK_CKEUSD_LASTYEAR	NUMBER(18,2); --	出口_最近12个月出口额USD
      IF BJTS_CUR_BGQ_BGQ_Q_001 = DATE_ADD(CAST(DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_001, '%Y-%m-01') AS DATETIME), INTERVAL -11 MONTH) THEN
        SET V_CK_CKEUSD_LASTYEAR =V_CK_CKEUSD;
      ELSE
        SELECT IFNULL(SUM(T.MYLAJ), 0)
          INTO V_CK_CKEUSD_LASTYEAR
          FROM CKTS_WBSJ_HG_BGD T
         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
           AND T.CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_001, '%Y-%m-01') AS DATETIME), INTERVAL -11 MONTH) AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
           AND T.JGFS_DM<>'1039';
      END IF;

      UPDATE JKGL_DATA_TJ_ZBU
         SET CK_BGDSL=V_CK_BGDSL,
    CK_CKEUSD=V_CK_CKEUSD,
    CK_CKERMB=V_CK_CKERMB,
    CK_SBDW_SL=V_CK_SBDW_SL,
    CK_GB_SL=V_CK_GB_SL,
    CK_BGDSL_DE=V_CK_BGDSL_DE,
    CK_CKEUSD_DE=V_CK_CKEUSD_DE,
    CK_BGDSL_ST=V_CK_BGDSL_ST,
    CK_PXBGDSL=V_CK_PXBGDSL,
    CK_ZXBGDSL=V_CK_ZXBGDSL,
    CK_PJDBHGZ=V_CK_PJDBHGZ,
    CK_CKEUSD_LASTYEAR=V_CK_CKEUSD_LASTYEAR
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;
    END;

    --  V_TS_
    BEGIN
      --  V_TS_BGDSL NUMBER(10) 退税_报关单数量
      --  V_TS_CKEUSD NUMBER(18,2)  退税_出口额USD
      --  V_TS_CKERMB NUMBER(18,2)  退税_出口额RMB
      --  V_TS_JSJE NUMBER(18,2)  退税_计税金额（免退税）
      --  V_TS_BGDSL_CQ NUMBER(10) 退税_报关单数量_超期申报
      --  V_TS_CKEUSD_CQ NUMBER(18,2)  退税_出口额USD_超期申报
      SELECT COUNT(DISTINCT SUBSTR(T.CKBGDH,1,18)), IFNULL(SUM(T.MYLAJ), 0), IFNULL(SUM(T.RMBLAJ), 0), IFNULL(SUM(T.JSJE), 0),
             COUNT(DISTINCT CASE WHEN T.SBRQ>STR_TO_DATE(ORA_CONCAT(DATE_FORMAT(DATE_ADD(T.CKRQ, INTERVAL 12 MONTH), '%Y'), '0420'), '%Y%m%d') AND T.MYLAJ>0 THEN SUBSTR(T.CKBGDH,1,18) ELSE NULL END),
             IFNULL(SUM(CASE WHEN T.SBRQ>STR_TO_DATE(ORA_CONCAT(DATE_FORMAT(DATE_ADD(T.CKRQ, INTERVAL 12 MONTH), '%Y'), '0420'), '%Y%m%d') AND T.MYLAJ>0 THEN T.MYLAJ ELSE NULL END), 0)
        INTO V_TS_BGDSL, V_TS_CKEUSD, V_TS_CKERMB, V_TS_JSJE, V_TS_BGDSL_CQ, V_TS_CKEUSD_CQ
        FROM JCFX_DATA_TSSBMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1);

      --  V_TS_HHCB NUMBER(18,2)  退税_换汇成本（免退税）
      SET V_TS_HHCB = CASE WHEN V_TS_CKERMB >0 AND V_TS_JSJE>0 THEN V_TS_JSJE / V_TS_CKERMB ELSE 0 END;

      --  V_TS_TSE_SB NUMBER(18,2)  退税_退税额_申报
      --  V_TS_MDE_SB NUMBER(18,2)  退税_免抵额_申报
      --  CKTS_LC_SBXX.SBRQ为便捷退税申报日期，部分数据没有，改用流程启动时间
      SELECT IFNULL(SUM(T.SB_ZZSTSE+T.SB_XFSTSE), 0), IFNULL(SUM(T.SB_MDSE), 0)
        INTO V_TS_TSE_SB, V_TS_MDE_SB
        FROM CKTS_LC_SBXX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.QDSJ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.QDSJ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND IFNULL(T.ZFBZ, 'N')='N';

      --  V_TS_TSE_HZ NUMBER(18,2)  退税_退税_核准
      --  V_TS_MDE_HZ NUMBER(18,2)  退税_免抵_核准
      SELECT IFNULL(SUM(S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE), 0), IFNULL(SUM(S.SEHZ_MDSE), 0)
        INTO V_TS_TSE_HZ, V_TS_MDE_HZ
        FROM CKTS_LC_SEHZXX S
       WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND S.SEHZRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.SEHZRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1);

      --  V_TS_TSE_BL NUMBER(18,2)  退税_退税_办理
      SELECT IFNULL(SUM(S.SE), 0)
        INTO V_TS_TSE_BL
        FROM CKTS_ZS_SRTHS S
       WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND S.THRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.THRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND S.TTSJLX_DM='01' AND S.TZLX_DM IN ('1','4');

      --  V_TS_MDE_BL NUMBER(18,2)  退税_免抵_办理
      SELECT IFNULL(SUM(S.JE), 0)
        INTO V_TS_MDE_BL
        FROM CKTS_ZS_TKGZ S
       WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND S.GKGZRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.GKGZRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND S.TZSLY='3' AND S.TZLX_DM='1' AND S.GZBZ='Y';

      --  V_TS_CKERMB_STZC  NUMBER(18,2)  退税_视同自产出口额
      SELECT IFNULL(SUM(MYLAJ), 0)
        INTO V_TS_CKERMB_STZC
        FROM CKTS_SB_MDT_CKMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND T.CKTMSYWLXDMJH LIKE '%STZC%';

      --  V_TS_JHFP_JE  NUMBER(18,2)  退税_发票总金额
      --  V_TS_JHFP_FS  NUMBER(10)  退税_发票总份数
      --  V_TS_GHS_NUM  NUMBER(10)  退税_供货商个数
      SELECT COUNT(DISTINCT T.JHPZH), IFNULL(SUM(T.JSJE), 0), COUNT(DISTINCT T.GHFNSRSBH_1)
        INTO V_TS_JHFP_FS, V_TS_JHFP_JE, V_TS_GHS_NUM
        FROM CKTS_SB_MTS_JHMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1);

      --  V_TS_JHFP_FS_CQ1  NUMBER(10)  退税_超期1发票份数
      --  V_TS_JHFP_JE_CQ1  NUMBER(18,2)  退税_超期1发票金额
      SELECT COUNT(DISTINCT T.JHPZH), IFNULL(SUM(T.JSJE), 0)
        INTO V_TS_JHFP_FS_CQ1, V_TS_JHFP_JE_CQ1
        FROM CKTS_SB_MTS_JHMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND ORA_DATE_DIFF(T.KPRQ, T.CKRQ_1) >= 30
         AND ORA_DATE_DIFF(T.KPRQ, T.CKRQ_1) < 60;

      --  V_TS_JHFP_FS_CQ2  NUMBER(10)  退税_超期2发票份数
      --  V_TS_JHFP_JE_CQ2  NUMBER(18,2)  退税_超期2发票金额
      SELECT COUNT(DISTINCT T.JHPZH), IFNULL(SUM(T.JSJE), 0)
        INTO V_TS_JHFP_FS_CQ2, V_TS_JHFP_JE_CQ2
        FROM CKTS_SB_MTS_JHMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND ORA_DATE_DIFF(T.KPRQ, T.CKRQ_1) >= 60;

      UPDATE JKGL_DATA_TJ_ZBU
         SET TS_BGDSL=V_TS_BGDSL,
    TS_CKEUSD=V_TS_CKEUSD,
    TS_CKERMB=V_TS_CKERMB,
    TS_JSJE=V_TS_JSJE,
    TS_HHCB=V_TS_HHCB,
    TS_BGDSL_CQ=V_TS_BGDSL_CQ,
    TS_CKEUSD_CQ=V_TS_CKEUSD_CQ,
    TS_TSE_SB=V_TS_TSE_SB,
    TS_MDE_SB=V_TS_MDE_SB,
    TS_TSE_HZ=V_TS_TSE_HZ,
    TS_MDE_HZ=V_TS_MDE_HZ,
    TS_TSE_BL=V_TS_TSE_BL,
    TS_MDE_BL=V_TS_MDE_BL,
    TS_CKERMB_STZC=V_TS_CKERMB_STZC,
    TS_JHFP_JE_DG=V_TS_JHFP_JE_DG,
    TS_JHFP_FS_DG=V_TS_JHFP_FS_DG,
    TS_JHFP_JE=V_TS_JHFP_JE,
    TS_JHFP_FS=V_TS_JHFP_FS,
    TS_GHS_NUM=V_TS_GHS_NUM,
    TS_JHFP_FS_CQ1=V_TS_JHFP_FS_CQ1,
    TS_JHFP_JE_CQ1=V_TS_JHFP_JE_CQ1,
    TS_JHFP_FS_CQ2=V_TS_JHFP_FS_CQ2,
    TS_JHFP_JE_CQ2=V_TS_JHFP_JE_CQ2
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;
    END;

    --  V_ZZS_
    BEGIN
      --  V_ZZS_XSE_QB  NUMBER(18,2)  增值税_全部销售
      --  V_ZZS_XSE_MDT NUMBER(18,2)  增值税_免抵退出口销售
      --  V_ZZS_XSE_MS  NUMBER(18,2)  增值税_免税销售
      --  V_ZZS_XXSE  NUMBER(18,2)  增值税_销项税额
      --  V_ZZS_JXSE  NUMBER(18,2)  增值税_进项税额
      --  V_ZZS_JXSEZC  NUMBER(18,2)  增值税_进项税额转出
      --  V_ZZS_YNSE  NUMBER(18,2)  增值税_应纳税额
      SELECT IFNULL(SUM(ASYSLJSXSE+AJYBFJSXSE+MDTBFCKXSE+MSXSE), 0), IFNULL(SUM(MDTBFCKXSE), 0), IFNULL(SUM(MSXSE), 0),
             IFNULL(SUM(XXSE), 0), IFNULL(SUM(JXSE), 0),  IFNULL(SUM(JXSEZC), 0), IFNULL(SUM(YNSE), 0)
        INTO V_ZZS_XSE_QB, V_ZZS_XSE_MDT, V_ZZS_XSE_MS, V_ZZS_XXSE, V_ZZS_JXSE, V_ZZS_JXSEZC, V_ZZS_YNSE
        FROM HX_SB.SB_ZZS_YBNSR
       WHERE SBUUID IN (SELECT DISTINCT SBUUID
                          FROM HX_SB.SB_SBXX
                         WHERE DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND SKSSQQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND SKSSQZ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND ZSXM_DM='10101'
                           AND YZPZZL_DM='BDA0610606'
                           AND GZLX_DM_1 IN ('1','5')
                           AND ZFBZ_1='N' )
         AND EWBLXH IN (1, 3);

      --  V_ZZS_MDTBDDKJXSE NUMBER(18,2)  增值税_免抵退不得抵扣进项税额
      --  V_DZ_JXJE_NCP NUMBER(18,2)  底账_进项金额_农产品
      --  V_DZ_JXSE_NCP NUMBER(18,2)  底账_进项税额_农产品
      SELECT IFNULL(SUM(CASE WHEN EWBHXH = 18 THEN SE ELSE 0 END), 0),
             IFNULL(SUM(CASE WHEN EWBHXH = 6 THEN JE ELSE 0 END), 0),
             IFNULL(SUM(CASE WHEN EWBHXH = 6 THEN SE ELSE 0 END), 0)
        INTO V_ZZS_MDTBDDKJXSE, V_DZ_JXJE_NCP, V_DZ_JXSE_NCP
        FROM HX_SB.SB_ZZS_YBNSR_FB2_BQJXSEMX
       WHERE SBUUID IN (SELECT DISTINCT SBUUID
                          FROM HX_SB.SB_SBXX
                         WHERE DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND SKSSQQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND SKSSQZ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND ZSXM_DM='10101'
                           AND YZPZZL_DM='BDA0610606'
                           AND GZLX_DM_1 IN ('1','5')
                           AND ZFBZ_1='N' );

      UPDATE JKGL_DATA_TJ_ZBU
         SET ZZS_XSE_QB=V_ZZS_XSE_QB,
    ZZS_XSE_MDT=V_ZZS_XSE_MDT,
    ZZS_XSE_MS=V_ZZS_XSE_MS,
    ZZS_XXSE=V_ZZS_XXSE,
    ZZS_JXSE=V_ZZS_JXSE,
    ZZS_JXSEZC=V_ZZS_JXSEZC,
    ZZS_YNSE=V_ZZS_YNSE,
    ZZS_MDTBDDKJXSE=V_ZZS_MDTBDDKJXSE,
    DZ_JXJE_NCP=V_DZ_JXJE_NCP,
    DZ_JXSE_NCP=V_DZ_JXSE_NCP
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;
    END;

    --  V_FP_1             (DZDZ_ZT)
    BEGIN
      --  V_DZ_XXFS_ZY  NUMBER(10)  底账_销项份数_专票
      --  V_DZ_XXJE_ZY  NUMBER(18,2)  底账_销项金额_专票
      --  V_DZ_XXSE_ZY  NUMBER(18,2)  底账_销项税额_专票
      SELECT COUNT(1), IFNULL(SUM(TT.JE), 0), IFNULL(SUM(TT.SE), 0)
        INTO V_DZ_XXFS_ZY, V_DZ_XXJE_ZY, V_DZ_XXSE_ZY
        FROM (SELECT T1.JE, T1.SE
                FROM DZDZ.DZDZ_FPXX_DZZP T1 -- 电子专票
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T1.XSFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T1.FPZTBZ IN ('0','1')
               UNION ALL
              SELECT T2.JE, T2.SE
                FROM DZDZ.DZDZ_FPXX_ZZSFP T2 -- 纸质专票
               WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T2.XFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T2.FPZT_BZ IN ('0','1')
             ) TT;

      --  V_DZ_XXFS_PT  NUMBER(10)  底账_销项份数_普票
      --  V_DZ_XXJE_PT  NUMBER(18,2)  底账_销项金额_普票
      --  V_DZ_XXSE_PT  NUMBER(18,2)  底账_销项税额_普票
      SELECT COUNT(1), IFNULL(SUM(TT.JE), 0), IFNULL(SUM(TT.SE), 0)
        INTO V_DZ_XXFS_PT, V_DZ_XXJE_PT, V_DZ_XXSE_PT
        FROM (SELECT T1.JE, T1.SE
                FROM DZDZ.DZDZ_FPXX_DZFP T1 -- 电子普票
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T1.XFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T1.FPZT_BZ IN ('0','1')
               UNION ALL
              SELECT T2.JE, T2.SE
                FROM DZDZ.DZDZ_FPXX_PTFP T2 -- 纸质普票
               WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T2.XFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T2.FPZT_BZ IN ('0','1')
             ) TT;

      --  V_DZ_XXFS_QB  NUMBER(10)  底账_销项份数_全部
      --  V_DZ_XXJE_QB  NUMBER(18,2)  底账_销项金额_全部
      --  V_DZ_XXSE_QB  NUMBER(18,2)  底账_销项税额_全部
      SET V_DZ_XXFS_QB = V_DZ_XXFS_ZY + V_DZ_XXFS_PT;
      SET V_DZ_XXJE_QB = V_DZ_XXJE_ZY + V_DZ_XXJE_PT;
      SET V_DZ_XXSE_QB = V_DZ_XXSE_ZY + V_DZ_XXSE_PT;

      --  V_DZ_XXFS_CK  NUMBER(10)  底账_销项份数_出口
      --  V_DZ_XXJE_CK  NUMBER(18,2)  底账_销项金额_出口
      SELECT COUNT(1),IFNULL(SUM(T.JE), 0)
        INTO V_DZ_XXFS_CK,V_DZ_XXJE_CK
        FROM DZDZ.DZDZ_FPXX_DZFP T
       WHERE T.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T.KPYF<=BJTS_CUR_BGQ_YF_Z_001
         AND T.XFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
         AND T.FPZT_BZ IN ('0','1')
         AND T.BZ LIKE '出口业务%';

      UPDATE JKGL_DATA_TJ_ZBU
         SET DZ_XXFS_ZY=V_DZ_XXFS_ZY,
    DZ_XXJE_ZY=V_DZ_XXJE_ZY,
    DZ_XXSE_ZY=V_DZ_XXSE_ZY,
    DZ_XXFS_PT=V_DZ_XXFS_PT,
    DZ_XXJE_PT=V_DZ_XXJE_PT,
    DZ_XXSE_PT=V_DZ_XXSE_PT,
    DZ_XXFS_QB=V_DZ_XXFS_QB,
    DZ_XXJE_QB=V_DZ_XXJE_QB,
    DZ_XXSE_QB=V_DZ_XXSE_QB,
    DZ_XXFS_CK=V_DZ_XXFS_CK,
    DZ_XXJE_CK=V_DZ_XXJE_CK
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;

      --  V_DZ_JXFS_ZY  NUMBER(10)  底账_进项份数_专票
      --  V_DZ_JXJE_ZY  NUMBER(18,2)  底账_进项金额_专票
      --  V_DZ_JXSE_ZY  NUMBER(18,2)  底账_进项税额_专票
      SELECT COUNT(1), IFNULL(SUM(TT.JE), 0), IFNULL(SUM(TT.SE), 0)
        INTO V_DZ_JXFS_ZY, V_DZ_JXJE_ZY, V_DZ_JXSE_ZY
        FROM (SELECT T1.JE, T1.SE
                FROM DZDZ.DZDZ_FPXX_DZZP T1  -- 电子专票
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T1.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T1.FPZTBZ IN ('0','1')
               UNION ALL
              SELECT T2.JE, T2.SE
                FROM DZDZ.DZDZ_FPXX_DZZP_YD T2
               WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T2.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T2.FPZTBZ IN ('0','1')
               UNION ALL
              SELECT T3.JE, T3.SE
                FROM DZDZ.DZDZ_FPXX_ZZSFP T3 -- 纸质专票
               WHERE T3.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T3.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T3.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T3.FPZT_BZ IN ('0','1')
               UNION ALL
              SELECT T4.JE, T4.SE
                FROM DZDZ.DZDZ_FPXX_ZZSFP_YD T4
               WHERE T4.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T4.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T4.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T4.FPZT_BZ IN ('0','1')
             ) TT;

      --  V_DZ_JXFS_PT  NUMBER(10)  底账_进项份数_普票
      --  V_DZ_JXJE_PT  NUMBER(18,2)  底账_进项金额_普票
      --  V_DZ_JXSE_PT  NUMBER(18,2)  底账_进项税额_普票
      SELECT COUNT(1), IFNULL(SUM(TT.JE), 0), IFNULL(SUM(TT.SE), 0)
        INTO V_DZ_JXFS_ZY, V_DZ_JXJE_ZY, V_DZ_JXSE_ZY
        FROM (SELECT T1.JE, T1.SE
                FROM DZDZ.DZDZ_FPXX_DZFP T1  -- 电子普票
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T1.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T1.FPZTBZ IN ('0','1')
               UNION ALL
              SELECT T2.JE, T2.SE
                FROM DZDZ.DZDZ_FPXX_DZFP_YD T2
               WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T2.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T2.FPZTBZ IN ('0','1')
               UNION ALL
              SELECT T3.JE, T3.SE
                FROM DZDZ.DZDZ_FPXX_PTFP T3 -- 纸质普票
               WHERE T3.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T3.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T3.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T3.FPZT_BZ IN ('0','1')
               UNION ALL
              SELECT T4.JE, T4.SE
                FROM DZDZ.DZDZ_FPXX_PTFP_YD T4
               WHERE T4.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T4.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T4.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T4.FPZT_BZ IN ('0','1')
             ) TT;

      --  V_DZ_JXFS_QB  NUMBER(10)  底账_全部进项份数
      --  V_DZ_JXJE_QB  NUMBER(18,2)  底账_全部进项金额
      --  V_DZ_JXSE_QB  NUMBER(18,2)  底账_全部进项税额
      SET V_DZ_JXFS_QB = V_DZ_JXFS_ZY + V_DZ_JXFS_PT;
      SET V_DZ_JXJE_QB = V_DZ_JXJE_ZY + V_DZ_JXJE_PT;
      SET V_DZ_JXSE_QB = V_DZ_JXSE_ZY + V_DZ_JXSE_PT;

      --  V_DZ_JXFS_DGKJ  NUMBER(10)  底账_进项份数_专票顶格开具
      --  V_DZ_JXJE_DGKJ  NUMBER(18,2)  底账_进项金额_专票顶格开具
      --  V_DZ_JXSE_DGKJ  NUMBER(18,2)  底账_进项税额_专票顶格开具
      SELECT COUNT(1), IFNULL(SUM(TT.JE), 0), IFNULL(SUM(TT.SE), 0)
        INTO V_DZ_JXFS_DGKJ, V_DZ_JXJE_DGKJ, V_DZ_JXSE_DGKJ
        FROM (SELECT T1.JE, T1.SE
                FROM DZDZ.DZDZ_FPXX_DZZP T1  -- 电子专票
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T1.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T1.FPZTBZ IN ('0','1')
                 AND SUBSTR(CAST(T1.JE AS CHAR),1,1)='9'
               UNION ALL
              SELECT T2.JE, T2.SE
                FROM DZDZ.DZDZ_FPXX_DZZP_YD T2
               WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T2.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T2.FPZTBZ IN ('0','1')
                 AND SUBSTR(CAST(T2.JE AS CHAR),1,1)='9'
               UNION ALL
              SELECT T3.JE, T3.SE
                FROM DZDZ.DZDZ_FPXX_ZZSFP T3 -- 纸质专票
               WHERE T3.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T3.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T3.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T3.FPZT_BZ IN ('0','1')
                 AND SUBSTR(CAST(T3.JE AS CHAR),1,1)='9'
               UNION ALL
              SELECT T4.JE, T4.SE
                FROM DZDZ.DZDZ_FPXX_ZZSFP_YD T4
               WHERE T4.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T4.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T4.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T4.FPZT_BZ IN ('0','1')
                 AND SUBSTR(CAST(T4.JE AS CHAR),1,1)='9'
             ) TT;

      --  V_DZ_JXSE_JKS NUMBER(18,2)  底账_进项税额_缴款书
      SELECT IFNULL(SUM(T.SJJE), 0)
        INTO V_DZ_JXSE_JKS
        FROM DZDZ.DZDZ_HGWS4 T
       WHERE T.JKDW_SH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
         AND T.JSRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.JSRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1);

      --  V_DZ_JXJE_SN  NUMBER(18,2)  底账_进项金额_省内
      SELECT IFNULL(SUM(TT.JE), 0)
        INTO V_DZ_JXJE_SN
        FROM (SELECT T1.JE
                FROM DZDZ.DZDZ_FPXX_DZZP T1  -- 电子专票
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T1.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T1.FPZTBZ IN ('0','1')
               UNION ALL
              SELECT T2.JE
                FROM DZDZ.DZDZ_FPXX_DZFP T2  -- 电子普票
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T1.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T1.FPZTBZ IN ('0','1')
               UNION ALL
              SELECT T3.JE
                FROM DZDZ.DZDZ_FPXX_ZZSFP T3 -- 纸质专票
               WHERE T3.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T3.KPYF<=BJTS_CUR_BGQ_YF_Z_001
