               WHERE T8.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T8.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T8.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T8.FPZT_BZ IN ('0','1')
                 AND S8.SPBM LIKE '110010102%'
             ) TT;

      --  V_DZ_WTJG NUMBER(18,2)  底账_委托加工费支出
      SELECT IFNULL(SUM(TT.JE), 0)
        INTO V_DZ_JXSE_NCP
        FROM (SELECT S1.JE
                FROM DZDZ.DZDZ_FPXX_DZZP T1  -- 电子专票
               INNER JOIN DZDZ.DZDZ_HWXX_DZZP S1 ON S1.FPDM=T1.FPDM AND S1.FPHM=T1.FPHM AND S1.KPYF=T1.KPYF
               WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
