               WHERE T6.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T6.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T6.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T6.FPZT_BZ IN ('0','1')
                 AND (S6.SPBM LIKE '301%' OR S6.SPBM LIKE '304080201%')
