                 AND T7.FPZT_BZ IN ('0','1')
                 AND (S7.SPBM LIKE '301%' OR S7.SPBM LIKE '304080201%')
               UNION ALL
              SELECT S8.JE
                FROM DZDZ.DZDZ_FPXX_PTFP_YD T8
               INNER JOIN DZDZ.DZDZ_HWXX_PTFP_YD S8 ON S8.FPDM=T8.FPDM AND S8.FPHM=T8.FPHM AND S8.KPYF=T8.KPYF
               WHERE T8.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T8.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                 AND T8.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                 AND T8.FPZT_BZ IN ('0','1')
                 AND (S8.SPBM LIKE '301%' OR S8.SPBM LIKE '304080201%')
             ) TT;

      UPDATE JKGL_DATA_TJ_ZBU
         SET DZ_DFJE_SR=V_DZ_DFJE_SR,
    DZ_DFJE_ZC=V_DZ_DFJE_ZC,
    DZ_WTJG=V_DZ_WTJG,
    DZ_YFJE=V_DZ_YFJE
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;
    END;

    --  V_ZC_
    BEGIN
      IF EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Q_001) IN (1,4,7,10) AND EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Z_001) IN (3,6,9,12) THEN
        --  V_ZC_YSZK_QC    资产_应收账款_期初
        --  V_ZC_YUFZK_QC   资产_预付账款_期初
        --  V_ZC_CH_QC      资产_存货_期初
        --  V_ZC_LDZC_QC    资产_流动资产_期初
        --  V_ZC_GDZC_QC    资产_固定资产_期初
        --  V_ZC_ZCZE_QC    资产_资产总额_期初
        --  V_ZC_YFZK_QC    资产_应付账款_期初
        --  V_ZC_YUSZK_QC   资产_预收账款_期初
        --  V_ZC_LDFZZE_QC  资产_流动负债总额_期初
        --  V_ZC_FZZE_QC    资产_负债总额_期初
        --  V_ZC_SYZQY_QC   资产_所有者权益_期初
        SELECT IFNULL(SUM(ZC_YSZK), 0), IFNULL(SUM(ZC_YUFZK), 0), IFNULL(SUM(ZC_CH), 0), IFNULL(SUM(ZC_LDZC), 0),
               IFNULL(SUM(ZC_GDZC), 0), IFNULL(SUM(ZC_ZCZE), 0), IFNULL(SUM(ZC_YFZK), 0), IFNULL(SUM(ZC_YUSZK), 0),
               IFNULL(SUM(ZC_LDFZZE), 0), IFNULL(SUM(ZC_FZZE), 0), IFNULL(SUM(ZC_SYZQY), 0)
          INTO V_ZC_YSZK_QC, V_ZC_YUFZK_QC, V_ZC_CH_QC, V_ZC_LDZC_QC, V_ZC_GDZC_QC, V_ZC_ZCZE_QC,
               V_ZC_YFZK_QC, V_ZC_YUSZK_QC, V_ZC_LDFZZE_QC, V_ZC_FZZE_QC, V_ZC_SYZQY_QC
          FROM (SELECT (CASE B.EWBHXH WHEN 4 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 9 THEN B.QMYE_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 12 THEN B.QMYE_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 19 THEN B.QMYE_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 32 THEN B.QMYE_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 4 THEN B.QMYE_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 13 THEN B.QMYE_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 23 THEN B.QMYE_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 30 THEN B.QMYE_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_ZCFZB B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 6 THEN B.QMS_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 8 THEN B.QMS_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 10 THEN B.QMS_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 14 THEN B.QMS_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 27 THEN B.QMS_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 36 THEN B.QMS_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 3 THEN B.QMS_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 4 THEN B.QMS_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 15 THEN B.QMS_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 25 THEN B.QMS_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 35 THEN B.QMS_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZ_ZCFZB B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 4 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 9 THEN B.QMYE_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 15 THEN B.QMYE_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 21 THEN B.QMYE_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 31 THEN B.QMYE_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 3 THEN B.QMYE_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 4 THEN B.QMYE_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 11 THEN B.QMYE_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 18 THEN B.QMYE_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 30 THEN B.QMYE_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_XQYKJZZ_ZCFZB B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 5 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 7 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 9 THEN B.QMYE_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 14 THEN B.QMYE_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 22 THEN B.QMYE_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 34 THEN B.QMYE_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 6 THEN B.QMYE_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 14 THEN B.QMYE_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 26 THEN B.QMYE_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 38 THEN B.QMYE_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_ZCFZBZX B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
               ) T;

        UPDATE JKGL_DATA_TJ_ZBU
           SET ZC_YSZK_QC=V_ZC_YSZK_QC,
    ZC_YUFZK_QC=V_ZC_YUFZK_QC,
    ZC_CH_QC=V_ZC_CH_QC,
    ZC_LDZC_QC=V_ZC_LDZC_QC,
    ZC_GDZC_QC=V_ZC_GDZC_QC,
    ZC_ZCZE_QC=V_ZC_ZCZE_QC,
    ZC_YFZK_QC=V_ZC_YFZK_QC,
    ZC_YUSZK_QC=V_ZC_YUSZK_QC,
    ZC_LDFZZE_QC=V_ZC_LDFZZE_QC,
    ZC_FZZE_QC=V_ZC_FZZE_QC,
    ZC_SYZQY_QC=V_ZC_SYZQY_QC,
    ZC_SSGDQY_QC=0
         WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
        COMMIT;

        --  V_ZC_YSZK_QM    资产_应收账款_期末
        --  V_ZC_YUFZK_QM   资产_预付账款_期末
        --  V_ZC_CH_QM      资产_存货_期末
        --  V_ZC_LDZC_QM    资产_流动资产_期末
        --  V_ZC_GDZC_QM    资产_固定资产_期末
        --  V_ZC_ZCZE_QM    资产_资产总额_期末
        --  V_ZC_YFZK_QM    资产_应付账款_期末
        --  V_ZC_YUSZK_QM   资产_预收账款_期末
        --  V_ZC_LDFZZE_QM  资产_流动负债总额_期末
        --  V_ZC_FZZE_QM    资产_负债总额_期末
        --  V_ZC_SYZQY_QM   资产_所有者权益_期末
        SELECT IFNULL(SUM(ZC_YSZK), 0), IFNULL(SUM(ZC_YUFZK), 0), IFNULL(SUM(ZC_CH), 0), IFNULL(SUM(ZC_LDZC), 0),
               IFNULL(SUM(ZC_GDZC), 0), IFNULL(SUM(ZC_ZCZE), 0), IFNULL(SUM(ZC_YFZK), 0), IFNULL(SUM(ZC_YUSZK), 0),
               IFNULL(SUM(ZC_LDFZZE), 0), IFNULL(SUM(ZC_FZZE), 0), IFNULL(SUM(ZC_SYZQY), 0)
          INTO V_ZC_YSZK_QM, V_ZC_YUFZK_QM, V_ZC_CH_QM, V_ZC_LDZC_QM, V_ZC_GDZC_QM, V_ZC_ZCZE_QM,
               V_ZC_YFZK_QM, V_ZC_YUSZK_QM, V_ZC_LDFZZE_QM, V_ZC_FZZE_QM, V_ZC_SYZQY_QM
          FROM (SELECT (CASE B.EWBHXH WHEN 4 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 9 THEN B.QMYE_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 12 THEN B.QMYE_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 19 THEN B.QMYE_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 32 THEN B.QMYE_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 4 THEN B.QMYE_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 13 THEN B.QMYE_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 23 THEN B.QMYE_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 30 THEN B.QMYE_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_ZCFZB B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -2 MONTH), '%Y-%m-01') AS DATETIME) AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 6 THEN B.QMS_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 8 THEN B.QMS_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 10 THEN B.QMS_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 14 THEN B.QMS_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 27 THEN B.QMS_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 36 THEN B.QMS_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 3 THEN B.QMS_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 4 THEN B.QMS_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 15 THEN B.QMS_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 25 THEN B.QMS_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 35 THEN B.QMS_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZ_ZCFZB B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -3 MONTH), '%Y-%m-01') AS DATETIME) AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 4 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 9 THEN B.QMYE_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 15 THEN B.QMYE_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 21 THEN B.QMYE_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 31 THEN B.QMYE_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 3 THEN B.QMYE_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 4 THEN B.QMYE_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 11 THEN B.QMYE_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 18 THEN B.QMYE_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 30 THEN B.QMYE_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_XQYKJZZ_ZCFZB B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -3 MONTH), '%Y-%m-01') AS DATETIME) AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 5 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YSZK,
                       (CASE B.EWBHXH WHEN 7 THEN B.QMYE_ZC ELSE 0 END) AS ZC_YUFZK,
                       (CASE B.EWBHXH WHEN 9 THEN B.QMYE_ZC ELSE 0 END) AS ZC_CH,
                       (CASE B.EWBHXH WHEN 14 THEN B.QMYE_ZC ELSE 0 END) AS ZC_LDZC,
                       (CASE B.EWBHXH WHEN 22 THEN B.QMYE_ZC ELSE 0 END) AS ZC_GDZC,
                       (CASE B.EWBHXH WHEN 34 THEN B.QMYE_ZC ELSE 0 END) AS ZC_ZCZE,
                       (CASE B.EWBHXH WHEN 5 THEN B.QMYE_QY ELSE 0 END) AS ZC_YFZK,
                       (CASE B.EWBHXH WHEN 6 THEN B.QMYE_QY ELSE 0 END) AS ZC_YUSZK,
                       (CASE B.EWBHXH WHEN 14 THEN B.QMYE_QY ELSE 0 END) AS ZC_LDFZZE,
                       (CASE B.EWBHXH WHEN 26 THEN B.QMYE_QY ELSE 0 END) AS ZC_FZZE,
                       (CASE B.EWBHXH WHEN 38 THEN B.QMYE_QY ELSE 0 END) AS ZC_SYZQY
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_ZCFZBZX B ON B.ZLBSCJUUID=A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -3 MONTH), '%Y-%m-01') AS DATETIME) AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
               ) T;

        UPDATE JKGL_DATA_TJ_ZBU
           SET ZC_YSZK_QM=V_ZC_YSZK_QM,
    ZC_YUFZK_QM=V_ZC_YUFZK_QM,
    ZC_CH_QM=V_ZC_CH_QM,
    ZC_LDZC_QM=V_ZC_LDZC_QM,
    ZC_GDZC_QM=V_ZC_GDZC_QM,
    ZC_ZCZE_QM=V_ZC_ZCZE_QM,
    ZC_YFZK_QM=V_ZC_YFZK_QM,
    ZC_YUSZK_QM=V_ZC_YUSZK_QM,
    ZC_LDFZZE_QM=V_ZC_LDFZZE_QM,
    ZC_FZZE_QM=V_ZC_FZZE_QM,
    ZC_SYZQY_QM=V_ZC_SYZQY_QM,
    ZC_SSGDQY_QM=0
         WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
        COMMIT;
      END IF;
    END;

    --  V_LR_
    BEGIN
      IF EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Q_001) IN (1,4,7,10) AND EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Z_001) IN (3,6,9,12) THEN
        --  V_LR_YYSR NUMBER(18,2)  利润_营业收入
        --  V_LR_YYCB NUMBER(18,2)  利润_营业成本
        --  V_LR_SJJFJ  NUMBER(18,2)  利润_税金及附加
        --  V_LR_XSFY NUMBER(18,2)  利润_销售费用
        --  V_LR_GLFY NUMBER(18,2)  利润_管理费用
        --  V_LR_CWFY NUMBER(18,2)  利润_财务费用
        --  V_LR_LXZC NUMBER(18,2)  利润_利息支出
        --  V_LR_YYLR NUMBER(18,2)  利润_营业利润
        --  V_LR_QTSR NUMBER(18,2)  利润_其它收入
        --  V_LR_LRZE NUMBER(18,2)  利润_利润总额
        --  V_LR_SDS  NUMBER(18,2)  利润_所得税
        --  V_LR_JLR  NUMBER(18,2)  利润_净利润
        SELECT IFNULL(SUM(LR_YYSR), 0), IFNULL(SUM(LR_YYCB), 0), IFNULL(SUM(LR_SJJFJ), 0), IFNULL(SUM(LR_XSFY), 0),
               IFNULL(SUM(LR_GLFY), 0), IFNULL(SUM(LR_CWFY), 0), IFNULL(SUM(LR_LXZC), 0), IFNULL(SUM(LR_YYLR), 0),
               IFNULL(SUM(LR_QTSR), 0), IFNULL(SUM(LR_LRZE), 0), IFNULL(SUM(LR_SDS), 0), IFNULL(SUM(LR_JLR), 0)
          INTO V_LR_YYSR, V_LR_YYCB, V_LR_SJJFJ, V_LR_XSFY, V_LR_GLFY, V_LR_CWFY,
               V_LR_LXZC, V_LR_YYLR, V_LR_QTSR, V_LR_LRZE, V_LR_SDS, V_LR_JLR
          FROM (-- +期末数
                SELECT (CASE B.EWBHXH WHEN 1 THEN B.BNLJS ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN B.BNLJS ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN B.BNLJS ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 6 THEN B.BNLJS ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 7 THEN B.BNLJS ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 8 THEN B.BNLJS ELSE 0 END) AS LR_CWFY,
                       0 AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 9 THEN B.BNLJS ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 12 THEN B.BNLJS ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 14 THEN B.BNLJS ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 15 THEN B.BNLJS ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 16 THEN B.BNLJS ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZ_LRB B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -2 MONTH), '%Y-%m-01') AS DATETIME)
                   AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 1 THEN B.BNLJJE ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN B.BNLJJE ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN B.BNLJJE ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 11 THEN B.BNLJJE ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 14 THEN B.BNLJJE ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 18 THEN B.BNLJJE ELSE 0 END) AS LR_CWFY,
                       (CASE B.EWBHXH WHEN 19 THEN B.BNLJJE ELSE 0 END) AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 21 THEN B.BNLJJE ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 22 THEN B.BNLJJE ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 30 THEN B.BNLJJE ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 31 THEN B.BNLJJE ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 32 THEN B.BNLJJE ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_XQYKJZZ_LRB B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -3 MONTH), '%Y-%m-01') AS DATETIME)
                   AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 1 THEN B.BQJE ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN B.BQJE ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN B.BQJE ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 4 THEN B.BQJE ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 5 THEN B.BQJE ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 6 THEN B.BQJE ELSE 0 END) AS LR_CWFY,
                       0 AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 11 THEN B.BQJE ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 12 THEN B.BQJE ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 15 THEN B.BQJE ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 16 THEN B.BQJE ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 17 THEN B.BQJE ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_LRB B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -3 MONTH), '%Y-%m-01') AS DATETIME)
                   AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 1 THEN B.BQJE ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN B.BQJE ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN B.BQJE ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 4 THEN B.BQJE ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 5 THEN B.BQJE ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 7 THEN B.BQJE ELSE 0 END) AS LR_CWFY,
                       (CASE B.EWBHXH WHEN 8 THEN B.BQJE ELSE 0 END) AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 19 THEN B.BQJE ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 20 THEN B.BQJE ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 22 THEN B.BQJE ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 23 THEN B.BQJE ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 24 THEN B.BQJE ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_LRBYZX B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=CAST(DATE_FORMAT(DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, INTERVAL -3 MONTH), '%Y-%m-01') AS DATETIME)
                   AND A.SSQZ=BJTS_CUR_BGQ_BGQ_Z_001
                   AND A.ZFBZ_1 IS NULL
                 UNION ALL
                -- -期初数
                SELECT (CASE B.EWBHXH WHEN 1 THEN - B.BNLJS ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN - B.BNLJS ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN - B.BNLJS ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 6 THEN - B.BNLJS ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 7 THEN - B.BNLJS ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 8 THEN - B.BNLJS ELSE 0 END) AS LR_CWFY,
                       0 AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 9 THEN - B.BNLJS ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 12 THEN - B.BNLJS ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 14 THEN - B.BNLJS ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 15 THEN - B.BNLJS ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 16 THEN - B.BNLJS ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZ_LRB B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
                   AND EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Q_001)>1
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 1 THEN - B.BNLJJE ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN - B.BNLJJE ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN - B.BNLJJE ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 11 THEN - B.BNLJJE ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 14 THEN - B.BNLJJE ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 18 THEN - B.BNLJJE ELSE 0 END) AS LR_CWFY,
                       (CASE B.EWBHXH WHEN 19 THEN - B.BNLJJE ELSE 0 END) AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 21 THEN - B.BNLJJE ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 22 THEN - B.BNLJJE ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 30 THEN - B.BNLJJE ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 31 THEN - B.BNLJJE ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 32 THEN - B.BNLJJE ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_XQYKJZZ_LRB B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
                   AND EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Q_001)>1
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 1 THEN - B.BQJE ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN - B.BQJE ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN - B.BQJE ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 4 THEN - B.BQJE ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 5 THEN - B.BQJE ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 6 THEN - B.BQJE ELSE 0 END) AS LR_CWFY,
                       0 AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 11 THEN - B.BQJE ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 12 THEN - B.BQJE ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 15 THEN - B.BQJE ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 16 THEN - B.BQJE ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 17 THEN - B.BQJE ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_LRB B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
                   AND EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Q_001)>1
                 UNION ALL
                SELECT (CASE B.EWBHXH WHEN 1 THEN - B.BQJE ELSE 0 END) AS LR_YYSR,
                       (CASE B.EWBHXH WHEN 2 THEN - B.BQJE ELSE 0 END) AS LR_YYCB,
                       (CASE B.EWBHXH WHEN 3 THEN - B.BQJE ELSE 0 END) AS LR_SJJFJ,
                       (CASE B.EWBHXH WHEN 4 THEN - B.BQJE ELSE 0 END) AS LR_XSFY,
                       (CASE B.EWBHXH WHEN 5 THEN - B.BQJE ELSE 0 END) AS LR_GLFY,
                       (CASE B.EWBHXH WHEN 7 THEN - B.BQJE ELSE 0 END) AS LR_CWFY,
                       (CASE B.EWBHXH WHEN 8 THEN - B.BQJE ELSE 0 END) AS LR_LXZC,
                       (CASE B.EWBHXH WHEN 19 THEN - B.BQJE ELSE 0 END) AS LR_YYLR,
                       (CASE B.EWBHXH WHEN 20 THEN - B.BQJE ELSE 0 END) AS LR_QTSR,
                       (CASE B.EWBHXH WHEN 22 THEN - B.BQJE ELSE 0 END) AS LR_LRZE,
                       (CASE B.EWBHXH WHEN 23 THEN - B.BQJE ELSE 0 END) AS LR_SDS,
                       (CASE B.EWBHXH WHEN 24 THEN - B.BQJE ELSE 0 END) AS LR_JLR
                  FROM HX_SB.SB_ZLBSCJB A
                 INNER JOIN HX_SB.SB_CWBB_QYKJZZYBQY_LRBYZX B ON B.ZLBSCJUUID = A.ZLBSCJUUID
                 WHERE A.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND A.SSQQ>=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -3 MONTH) AND A.SSQZ=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
                   AND A.ZFBZ_1 IS NULL
                   AND EXTRACT(MONTH FROM BJTS_CUR_BGQ_BGQ_Q_001)>1
               ) T;

        UPDATE JKGL_DATA_TJ_ZBU
           SET LR_YYSR=V_LR_YYSR,
    LR_YYCB=V_LR_YYCB,
    LR_SJJFJ=V_LR_SJJFJ,
    LR_XSFY=V_LR_XSFY,
    LR_GLFY=V_LR_GLFY,
    LR_CWFY=V_LR_CWFY,
    LR_LXZC=V_LR_LXZC,
    LR_YYLR=V_LR_YYLR,
    LR_QTSR=V_LR_QTSR,
    LR_LRZE=V_LR_LRZE,
    LR_SDS=V_LR_SDS,
    LR_JLR=V_LR_JLR
         WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
        COMMIT;
      END IF;
    END;

    -- V_CW_
    BEGIN
      -- V_CW_MLL  NUMBER(8,2) 财务_毛利率
      IF (V_LR_YYSR IS NOT NULL) AND (V_LR_YYCB IS NOT NULL) AND (V_LR_YYSR<>0) THEN
        SET V_CW_MLL = LEAST(GREATEST(ROUND(100*(V_LR_YYSR-V_LR_YYCB)/V_LR_YYSR,2),-100),100);
      ELSE
        SET V_CW_MLL = NULL;
      END IF;

      --  V_CW_HYSFL  NUMBER(8,2) 财务_还原税负率
      -- 还原税负率=(全部销售收入 * 13% - (进项税额 - 进项税额转出) + (期末存货 - 期初存货) * 13%)/全部销售收入
      IF (V_ZZS_XSE_QB IS NOT NULL) AND (V_ZZS_XSE_QB<>0) THEN
        SET V_CW_HYSFL = LEAST(GREATEST(ROUND(100 * (0.13 * (V_ZZS_XSE_QB + V_ZC_CH_QM - V_ZC_CH_QC) - V_ZZS_JXSE + V_ZZS_JXSEZC) / V_ZZS_XSE_QB, 2),0),100);
      ELSE
        SET V_CW_HYSFL = NULL;
      END IF;

      UPDATE JKGL_DATA_TJ_ZBU
         SET V_CW_MLL=V_CW_MLL,
    V_CW_HYSFL=V_CW_HYSFL
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;
    END;

    -- V_SDS_
    BEGIN
      IF BJTS_CUR_BGQ_ZQLX_001='年' THEN
        -- V_SDS_YYSR        NUMBER(18,2); --     所得税_营业收入
        -- V_SDS_YNSSDE      NUMBER(18,2); --     所得税_应纳税所得额
        SELECT IFNULL(T.YSX, 0), IFNULL(T.JSYJ, 0)
          INTO V_SDS_YYSR, V_SDS_YNSSDE
          FROM HX_SB.SB_SBXX T
         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
           AND T.ZSXM_DM='10104' AND T.YZPZZL_DM='BDA0610994'
           AND T.SKSSQQ=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SKSSQZ=BJTS_CUR_BGQ_BGQ_Z_001
           AND T.ZFBZ_1='N' AND T.GZLX_DM_1 IN ('1','5')
           AND 1=1
LIMIT 1;

        UPDATE JKGL_DATA_TJ_ZBU
           SET SDS_YYSR=V_SDS_YYSR,
    SDS_YNSSDE=V_SDS_YNSSDE
         WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
        COMMIT;
      END IF;
    END;


    -- 计算 JKGL_DATA_TJ_ZBU_CKGB.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_CKGB AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.MYGDQSZ_DM AS GB_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT T.HGGQKA_DM) AS KASL, COUNT(DISTINCT T.SBDWDM) AS SBDWSL, COUNT(DISTINCT T.YSFS_DM) AS YSFSSL
                  FROM CKTS_WBSJ_HG_BGD T
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(V_BGQ_Z, 1)
                   AND T.JGFS_DM<>'1039'
                 GROUP BY T.MYGDQSZ_DM
) AS B
ON A.BGQID=B.BGQID AND A.GB_DM=B.GB_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, KASL = B.KASL, SBDWSL = B.SBDWSL, YSFSSL = B.YSFSSL;
INSERT INTO JKGL_DATA_TJ_ZBU_CKGB (ID,BGQID,GB_DM,CKEUSD,CKERMB,KASL,SBDWSL,YSFSSL)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_CKGB'),B.BGQID,B.GB_DM,B.CKEUSD,B.CKERMB,B.KASL,B.SBDWSL,B.YSFSSL
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.MYGDQSZ_DM AS GB_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT T.HGGQKA_DM) AS KASL, COUNT(DISTINCT T.SBDWDM) AS SBDWSL, COUNT(DISTINCT T.YSFS_DM) AS YSFSSL
                  FROM CKTS_WBSJ_HG_BGD T
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(V_BGQ_Z, 1)
                   AND T.JGFS_DM<>'1039'
                 GROUP BY T.MYGDQSZ_DM
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_CKGB AS A WHERE A.BGQID=B.BGQID AND A.GB_DM=B.GB_DM
);
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_CKKA.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_CKKA AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.HGGQKA_DM AS KA_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT T.SBDWDM) AS SBDWSL
                  FROM CKTS_WBSJ_HG_BGD T
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(V_BGQ_Z, 1)
                   AND T.JGFS_DM<>'1039'
                 GROUP BY T.HGGQKA_DM
) AS B
ON A.BGQID=B.BGQID AND A.KA_DM=B.KA_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, SBDWSL = B.SBDWSL;
INSERT INTO JKGL_DATA_TJ_ZBU_CKKA (ID,BGQID,KA_DM,CKEUSD,CKERMB,SBDWSL)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_CKKA'),B.BGQID,B.KA_DM,B.CKEUSD,B.CKERMB,B.SBDWSL
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.HGGQKA_DM AS KA_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT T.SBDWDM) AS SBDWSL
                  FROM CKTS_WBSJ_HG_BGD T
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(V_BGQ_Z, 1)
                   AND T.JGFS_DM<>'1039'
                 GROUP BY T.HGGQKA_DM
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_CKKA AS A WHERE A.BGQID=B.BGQID AND A.KA_DM=B.KA_DM
);
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_CKSP.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_CKSP AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(T.CKSP_DM,1,8) AS SP8_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       SUM(T.CKSL) AS CKSL, CASE WHEN SUM(T.CKSL)=0 THEN NULL ELSE SUM(T.RMBLAJ)/SUM(T.CKSL) END AS CKDJ
                  FROM CKTS_WBSJ_HG_BGD T
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(V_BGQ_Z, 1)
                   AND T.JGFS_DM<>'1039'
                 GROUP BY SUBSTR(T.CKSP_DM,1,8)
) AS B
ON A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, CKSL = B.CKSL, CKDJ = B.CKDJ;
INSERT INTO JKGL_DATA_TJ_ZBU_CKSP (ID,BGQID,SP8_DM,CKEUSD,CKERMB,CKSL,CKDJ)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_CKSP'),B.BGQID,B.SP8_DM,B.CKEUSD,B.CKERMB,B.CKSL,B.CKDJ
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(T.CKSP_DM,1,8) AS SP8_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       SUM(T.CKSL) AS CKSL, CASE WHEN SUM(T.CKSL)=0 THEN NULL ELSE SUM(T.RMBLAJ)/SUM(T.CKSL) END AS CKDJ
                  FROM CKTS_WBSJ_HG_BGD T
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(V_BGQ_Z, 1)
                   AND T.JGFS_DM<>'1039'
                 GROUP BY SUBSTR(T.CKSP_DM,1,8)
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_CKSP AS A WHERE A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_CKSP AS A
       SET SPDL=SUBSTR(A.SP8_DM,1,2),
    SPMC=(SELECT B.CKSP_MC FROM JCFX_DM_CKSP B WHERE B.CKSP_DM=A.SP8_DM AND 1=1
LIMIT 1)
     WHERE A.BGQID=BJTS_CUR_BGQ_BGQID_001 AND A.SPDL IS NULL;
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_QYXX.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_QYXX AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.FDDBRMC  AS FR_XM, T.FRZJHM AS FR_ZJHM,
                       T.CWFZRXM AS CWR_XM, T.CWFZRSFZJHM AS CWR_ZJHM,
                       T.BSRXM AS BSR_XM, T.BSRSFZJHM AS BSR_ZJHM,
                       TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.DJRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z) AS JYYFSL,
                       TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.SCCKRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z) AS CKYFSL,
                       T.ZCDZ,T.SCJYDZ AS JYDZ,
                       S.SJJYR_XM AS SKR_XM, S.SJJYR_SFZH AS SKR_ZJHM, S.YJBGCS_MJ AS JYCDMJ
                  FROM GS_DJ_CKTMSDAB T
                  LEFT JOIN JKGL_ZLCJ_JGB S ON CAST(S.DJXH AS CHAR)=T.CPCODE
                 WHERE T.CPCODE=CAST(BJTS_CUR_BGQ_DJXH_001 AS CHAR)
) AS B
ON A.BGQID=B.BGQID
SET FR_XM = B.FR_XM, FR_ZJHM = B.FR_ZJHM, CWR_XM = B.CWR_XM, CWR_ZJHM = B.CWR_ZJHM, BSR_XM = B.BSR_XM, BSR_ZJHM = B.BSR_ZJHM, JYYFSL = B.JYYFSL, CKYFSL = B.CKYFSL, ZCDZ = B.ZCDZ, JYDZ = B.JYDZ, SKR_XM = B.SKR_XM, SKR_ZJHM = B.SKR_ZJHM, JYCDMJ = B.JYCDMJ;
INSERT INTO JKGL_DATA_TJ_ZBU_QYXX (BGQID,FR_XM,FR_ZJHM,CWR_XM,CWR_ZJHM,BSR_XM,BSR_ZJHM,JYYFSL,CKYFSL,ZCDZ,JYDZ,SKR_XM,SKR_ZJHM,JYCDMJ)
SELECT B.BGQID,B.FR_XM,B.FR_ZJHM,B.CWR_XM,B.CWR_ZJHM,B.BSR_XM,B.BSR_ZJHM,B.JYYFSL,B.CKYFSL,B.ZCDZ,B.JYDZ,B.SKR_XM,B.SKR_ZJHM,B.JYCDMJ
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.FDDBRMC  AS FR_XM, T.FRZJHM AS FR_ZJHM,
                       T.CWFZRXM AS CWR_XM, T.CWFZRSFZJHM AS CWR_ZJHM,
                       T.BSRXM AS BSR_XM, T.BSRSFZJHM AS BSR_ZJHM,
                       TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.DJRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z) AS JYYFSL,
                       TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.SCCKRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z) AS CKYFSL,
                       T.ZCDZ,T.SCJYDZ AS JYDZ,
                       S.SJJYR_XM AS SKR_XM, S.SJJYR_SFZH AS SKR_ZJHM, S.YJBGCS_MJ AS JYCDMJ
                  FROM GS_DJ_CKTMSDAB T
                  LEFT JOIN JKGL_ZLCJ_JGB S ON CAST(S.DJXH AS CHAR)=T.CPCODE
                 WHERE T.CPCODE=CAST(BJTS_CUR_BGQ_DJXH_001 AS CHAR)
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_QYXX AS A WHERE A.BGQID=B.BGQID
);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_QYXX
       SET FLGLCD =
           (SELECT S.KZXX
              FROM GS_DJ_CKTMSDAB T, GS_DJ_CKTMSDAB_KZ S
             WHERE T.CPCODE=CAST(BJTS_CUR_BGQ_DJXH_001 AS CHAR)
               AND S.NSRDZDAH=T.NSRDZDAH
               AND S.KZLX='FLGLCD' AND (V_BGQ_Z BETWEEN S.ST_DATE AND S.END_DATE) AND S.FLAG='1'
               AND 1=1
LIMIT 1)
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_TSGH.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, S.GHFNSRSBH_1 AS GHFSH, SUM(S.JSJE) AS JHJE, SUM(S.TSE) AS TSE
                  FROM CKTS_SB_MTS_JHMX S
                 WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND S.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY S.GHFNSRSBH_1
) AS B
ON A.BGQID=B.BGQID AND A.GHFSH=B.GHFSH
SET JHJE = B.JHJE, TSE = B.TSE;
INSERT INTO JKGL_DATA_TJ_ZBU_TSGH (ID,BGQID,GHFSH,JHJE,TSE)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_TSGH'),B.BGQID,B.GHFSH,B.JHJE,B.TSE
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, S.GHFNSRSBH_1 AS GHFSH, SUM(S.JSJE) AS JHJE, SUM(S.TSE) AS TSE
                  FROM CKTS_SB_MTS_JHMX S
                 WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND S.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY S.GHFNSRSBH_1
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_TSGH AS A WHERE A.BGQID=B.BGQID AND A.GHFSH=B.GHFSH
);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET FXQYBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_FXQY_SWJG S
                    WHERE S.QYSBH=T.GHFSH
                      AND IFNULL(S.YXQ_Z, CURRENT_TIMESTAMP)>BJTS_CUR_BGQ_BGQ_Q_001);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET FXDQBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_FXDQ_SWJG S
                    WHERE S.XZQH_DM= CASE WHEN LENGTH(T.GHFSH)=15
                                          THEN SUBSTR(T.GHFSH,1,LENGTH(S.XZQH_DM))
                                          ELSE SUBSTR(T.GHFSH,3,LENGTH(S.XZQH_DM)) END
                      AND IFNULL(S.YXQ_Z, CURRENT_TIMESTAMP)>BJTS_CUR_BGQ_BGQ_Q_001);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET SNWBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND '33' <> (CASE WHEN LENGTH(T.GHFSH)=15 THEN SUBSTR(T.GHFSH,1,2) ELSE SUBSTR(T.GHFSH,3,2) END);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET FZCHBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_GHQYXX S
                    WHERE S.QYSBH=T.GHFSH AND IFNULL(S.NSRZT_DM, '03')='05');
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_TSSP.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_TSSP AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(T.CKSP_DM,1,8) AS SP8_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       SUM(S.RMBLAJ) AS CKERMB_STZC, SUM(T.CKSL) AS CKSL, SUM(T.TMSE) AS SBTMSE, SUM(T.JSJE) AS JHJE,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.MYLAJ) / SUM(T.CKSL), 2) END AS CKDJ,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.JSJE) / SUM(T.CKSL), 2) END AS JHDJ,
                       CASE WHEN SUM(T.MYLAJ)<=0 THEN 0 ELSE ROUND((SUM(T.RMBLAJ) - SUM(T.JSJE)) / SUM(T.MYLAJ),2) END AS MMYLR
                  FROM JCFX_DATA_TSSBMX T
                  LEFT JOIN CKTS_SB_MDT_CKMX S ON S.UUID=T.UUID AND S.CKTMSYWLXDMJH LIKE '%STZC%'
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY SUBSTR(T.CKSP_DM,1,8)
) AS B
ON A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, CKERMB_STZC = B.CKERMB_STZC, CKSL = B.CKSL, SBTMSE = B.SBTMSE, JHJE = B.JHJE, CKDJ = B.CKDJ, JHDJ = B.JHDJ, MMYLR = B.MMYLR;
INSERT INTO JKGL_DATA_TJ_ZBU_TSSP (ID,BGQID,SP8_DM,CKEUSD,CKERMB,CKERMB_STZC,CKSL,SBTMSE,JHJE,SP_DL,MMYLR,CKDJ,JHDJ)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_TSSP'),B.BGQID,B.SP8_DM,B.CKEUSD,B.CKERMB,B.CKERMB_STZC,
                    B.CKSL,B.SBTMSE,B.JHJE,SUBSTR(B.SP8_DM,1,2),B.MMYLR,B.CKDJ,B.JHDJ
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(T.CKSP_DM,1,8) AS SP8_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       SUM(S.RMBLAJ) AS CKERMB_STZC, SUM(T.CKSL) AS CKSL, SUM(T.TMSE) AS SBTMSE, SUM(T.JSJE) AS JHJE,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.MYLAJ) / SUM(T.CKSL), 2) END AS CKDJ,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.JSJE) / SUM(T.CKSL), 2) END AS JHDJ,
                       CASE WHEN SUM(T.MYLAJ)<=0 THEN 0 ELSE ROUND((SUM(T.RMBLAJ) - SUM(T.JSJE)) / SUM(T.MYLAJ),2) END AS MMYLR
                  FROM JCFX_DATA_TSSBMX T
                  LEFT JOIN CKTS_SB_MDT_CKMX S ON S.UUID=T.UUID AND S.CKTMSYWLXDMJH LIKE '%STZC%'
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY SUBSTR(T.CKSP_DM,1,8)
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_TSSP AS A WHERE A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSSP AS T
       SET MGBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_MGSP_SWJG S
                    WHERE SUBSTR(T.SP8_DM,1,LENGTH(S.MGSP_DM)) = S.MGSP_DM
                      AND IFNULL(S.YXQ_Z, CURRENT_TIMESTAMP)>BJTS_CUR_BGQ_BGQ_Q_001);
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_DZGF.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_DZGF AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, GFSBH,GFMC,FS,JE,SE,ZYSPMC,ZYSPJE
                  FROM (SELECT Z.GFSBH, MAX(Z.GFMC) AS GFMC, COUNT(1) AS FS, SUM(Z.JE) AS JE, SUM(Z.SE) AS SE,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.SPMC ELSE NULL END) AS ZYSPMC,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.JE   ELSE NULL END) AS ZYSPJE
                          FROM (SELECT P.GFSBH, MAX(P.GFMC) AS GFMC, P.SPMC, SUM(P.JE) AS JE, SUM(P.SE) AS SE,
                                       ROW_NUMBER() OVER(PARTITION BY P.GFSBH ORDER BY SUM(P.JE) DESC) AS RN
                                  FROM (SELECT /*+ PARALLEL(3) */ T1.GMFSBH AS GFSBH,T1.GMFMC AS GFMC,UPPER(S1.MC) AS SPMC,S1.JE,S1.SE
                                          FROM DZDZ.DZDZ_FPXX_DZZP T1 -- 电子专票
                                         INNER JOIN DZDZ.DZDZ_HWXX_DZZP S1 ON S1.FPDM=T1.FPDM AND S1.FPHM=T1.FPHM
                                         WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T1.XSFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T1.FPZTBZ IN ('0','1')
                                           AND S1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S1.SPBM LIKE '1%'
                                         UNION ALL
                                        SELECT /*+ PARALLEL(3) */ T2.GFSBH, T2.GFMC, UPPER(S2.MC) AS SPMC, S2.JE, S2.SE
                                          FROM DZDZ.DZDZ_FPXX_ZZSFP T2 -- 纸质专票
                                         INNER JOIN DZDZ.DZDZ_HWXX_ZZSFP S2 ON S2.FPDM=T2.FPDM AND S2.FPHM=T2.FPHM
                                         WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T2.XFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T2.FPZT_BZ IN ('0','1')
                                           AND S2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S2.SPBM LIKE '1%') P
                                 GROUP BY P.GFSBH, P.SPMC) Z
                         GROUP BY Z.GFSBH
                         ORDER BY SUM(Z.JE) DESC) TT
                 WHERE 1=1
LIMIT 20
) AS B
ON A.BGQID=B.BGQID AND A.GFSBH=B.GFSBH
SET GFMC = B.GFMC, FS = B.FS, JE = B.JE, SE = B.SE, ZYSPMC = B.ZYSPMC, ZYSPJE = B.ZYSPJE;
INSERT INTO JKGL_DATA_TJ_ZBU_DZGF (ID,BGQID,GFSBH,GFMC,FS,JE,SE,ZYSPMC,ZYSPJE)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_DZGF'),B.BGQID,B.GFSBH,B.GFMC,B.FS,B.JE,B.SE,B.ZYSPMC,B.ZYSPJE
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, GFSBH,GFMC,FS,JE,SE,ZYSPMC,ZYSPJE
                  FROM (SELECT Z.GFSBH, MAX(Z.GFMC) AS GFMC, COUNT(1) AS FS, SUM(Z.JE) AS JE, SUM(Z.SE) AS SE,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.SPMC ELSE NULL END) AS ZYSPMC,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.JE   ELSE NULL END) AS ZYSPJE
                          FROM (SELECT P.GFSBH, MAX(P.GFMC) AS GFMC, P.SPMC, SUM(P.JE) AS JE, SUM(P.SE) AS SE,
                                       ROW_NUMBER() OVER(PARTITION BY P.GFSBH ORDER BY SUM(P.JE) DESC) AS RN
                                  FROM (SELECT /*+ PARALLEL(3) */ T1.GMFSBH AS GFSBH,T1.GMFMC AS GFMC,UPPER(S1.MC) AS SPMC,S1.JE,S1.SE
                                          FROM DZDZ.DZDZ_FPXX_DZZP T1 -- 电子专票
                                         INNER JOIN DZDZ.DZDZ_HWXX_DZZP S1 ON S1.FPDM=T1.FPDM AND S1.FPHM=T1.FPHM
                                         WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T1.XSFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T1.FPZTBZ IN ('0','1')
                                           AND S1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S1.SPBM LIKE '1%'
                                         UNION ALL
                                        SELECT /*+ PARALLEL(3) */ T2.GFSBH, T2.GFMC, UPPER(S2.MC) AS SPMC, S2.JE, S2.SE
                                          FROM DZDZ.DZDZ_FPXX_ZZSFP T2 -- 纸质专票
                                         INNER JOIN DZDZ.DZDZ_HWXX_ZZSFP S2 ON S2.FPDM=T2.FPDM AND S2.FPHM=T2.FPHM
                                         WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T2.XFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T2.FPZT_BZ IN ('0','1')
                                           AND S2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S2.SPBM LIKE '1%') P
                                 GROUP BY P.GFSBH, P.SPMC) Z
                         GROUP BY Z.GFSBH
                         ORDER BY SUM(Z.JE) DESC) TT
                 WHERE 1=1
LIMIT 20
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_DZGF AS A WHERE A.BGQID=B.BGQID AND A.GFSBH=B.GFSBH
);
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_DZXF.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_DZXF AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, XFSBH,XFMC,FS,JE,SE,ZYSPMC,ZYSPJE
                  FROM (SELECT Z.XFSBH, MAX(Z.XFMC) AS XFMC, COUNT(1) AS FS, SUM(Z.JE) AS JE, SUM(Z.SE) AS SE,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.SPMC ELSE NULL END) AS ZYSPMC,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.JE   ELSE NULL END) AS ZYSPJE
                          FROM (SELECT P.XFSBH, MAX(P.XFMC) AS XFMC, P.SPMC, SUM(P.JE) AS JE, SUM(P.SE) AS SE,
                                       ROW_NUMBER() OVER(PARTITION BY P.XFSBH ORDER BY SUM(P.JE) DESC) AS RN
                                  FROM (SELECT /*+ PARALLEL(3) */ T1.XSFSBH AS XFSBH,T1.XSFMC AS XFMC,UPPER(S1.MC) AS SPMC,S1.JE,S1.SE
                                          FROM DZDZ.DZDZ_FPXX_DZZP T1 -- 电子专票
                                         INNER JOIN DZDZ.DZDZ_HWXX_DZZP S1 ON S1.FPDM=T1.FPDM AND S1.FPHM=T1.FPHM
                                         WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T1.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T1.FPZTBZ IN ('0','1')
                                           AND S1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S1.SPBM LIKE '1%'
                                         UNION ALL
                                        SELECT /*+ PARALLEL(3) */ T1.XSFSBH AS XFSBH,T1.XSFMC AS XFMC,UPPER(S1.MC) AS SPMC,S1.JE,S1.SE
                                          FROM DZDZ.DZDZ_FPXX_DZZP_YD T1 -- 电子专票（异地）
                                         INNER JOIN DZDZ.DZDZ_HWXX_DZZP_YD S1 ON S1.FPDM=T1.FPDM AND S1.FPHM=T1.FPHM
                                         WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T1.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T1.FPZTBZ IN ('0','1')
                                           AND S1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S1.SPBM LIKE '1%'
                                         UNION ALL
                                        SELECT /*+ PARALLEL(3) */ T2.XFSBH, T2.XFMC, UPPER(S2.MC) AS SPMC, S2.JE, S2.SE
                                          FROM DZDZ.DZDZ_FPXX_ZZSFP T2 -- 纸质专票
                                         INNER JOIN DZDZ.DZDZ_HWXX_ZZSFP S2 ON S2.FPDM=T2.FPDM AND S2.FPHM=T2.FPHM
                                         WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T2.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T2.FPZT_BZ IN ('0','1')
                                           AND S2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S2.SPBM LIKE '1%'
                                         UNION ALL
                                        SELECT /*+ PARALLEL(3) */ T2.XFSBH, T2.XFMC, UPPER(S2.MC) AS SPMC, S2.JE, S2.SE
                                          FROM DZDZ.DZDZ_FPXX_ZZSFP_YD T2 -- 纸质专票（异地）
                                         INNER JOIN DZDZ.DZDZ_HWXX_ZZSFP_YD S2 ON S2.FPDM=T2.FPDM AND S2.FPHM=T2.FPHM
                                         WHERE T2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T2.GFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T2.FPZT_BZ IN ('0','1')
                                           AND S2.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S2.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S2.SPBM LIKE '1%') P
                                 GROUP BY P.XFSBH, P.SPMC) Z
                         GROUP BY Z.XFSBH
                         ORDER BY SUM(Z.JE) DESC) TT
                 WHERE 1=1
LIMIT 20
) AS B
ON A.BGQID=B.BGQID AND A.XFSBH=B.XFSBH
SET XFMC = B.XFMC, FS = B.FS, JE = B.JE, SE = B.SE, ZYSPMC = B.ZYSPMC, ZYSPJE = B.ZYSPJE;
INSERT INTO JKGL_DATA_TJ_ZBU_DZXF (ID,BGQID,XFSBH,XFMC,FS,JE,SE,ZYSPMC,ZYSPJE)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_DZXF'),B.BGQID,B.XFSBH,B.XFMC,B.FS,B.JE,B.SE,B.ZYSPMC,B.ZYSPJE
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, XFSBH,XFMC,FS,JE,SE,ZYSPMC,ZYSPJE
                  FROM (SELECT Z.XFSBH, MAX(Z.XFMC) AS XFMC, COUNT(1) AS FS, SUM(Z.JE) AS JE, SUM(Z.SE) AS SE,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.SPMC ELSE NULL END) AS ZYSPMC,
                               MAX(CASE WHEN Z.RN = 1 THEN Z.JE   ELSE NULL END) AS ZYSPJE
                          FROM (SELECT P.XFSBH, MAX(P.XFMC) AS XFMC, P.SPMC, SUM(P.JE) AS JE, SUM(P.SE) AS SE,
                                       ROW_NUMBER() OVER(PARTITION BY P.XFSBH ORDER BY SUM(P.JE) DESC) AS RN
                                  FROM (SELECT /*+ PARALLEL(3) */ T1.XSFSBH AS XFSBH,T1.XSFMC AS XFMC,UPPER(S1.MC) AS SPMC,S1.JE,S1.SE
                                          FROM DZDZ.DZDZ_FPXX_DZZP T1 -- 电子专票
                                         INNER JOIN DZDZ.DZDZ_HWXX_DZZP S1 ON S1.FPDM=T1.FPDM AND S1.FPHM=T1.FPHM
                                         WHERE T1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND T1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND T1.GMFSBH IN (BJTS_CUR_BGQ_NSRDJNO_001,BJTS_CUR_BGQ_SHXYNO_001)
                                           AND T1.FPZTBZ IN ('0','1')
                                           AND S1.KPYF>=BJTS_CUR_BGQ_YF_Q_001 AND S1.KPYF<=BJTS_CUR_BGQ_YF_Z_001
                                           AND S1.SPBM LIKE '1%'
