DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_AFTER_ETL$$

CREATE PROCEDURE PRO_DEAL_AFTER_ETL
(
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LC_SBYY          VARCHAR(2000);
  DECLARE LD_DEALDATA      DATETIME;          -- 用于基础数据处理的提前量
  DECLARE LN_LOG           BIGINT;
  DECLARE LC_BBNY          VARCHAR(6);   -- 本期制表年月
  DECLARE LD_BBNY_KSNF     DATETIME;          -- 本期制表年月年初
  DECLARE LD_BBNY_KSRQ     DATETIME;          -- 本期制表年月开始日期，一般为制表年月的月初
  DECLARE LD_BBNY_JZRQ     DATETIME;          -- 本期制表年月结束日期，一般为制表年月的下一个月初
  DECLARE LC_DJZCLX        VARCHAR(6);   -- 本期制表年月
  DECLARE GLH_JSJE         DECIMAL(18,2);
  DECLARE GLH_TSL          DECIMAL(18,2);
  DECLARE GLH_TMSE         DECIMAL(18,2);
  DECLARE LN_ALLCK         DECIMAL(18,2);
  DECLARE LN_SNCK          DECIMAL(18,2);
  DECLARE LN_MYLAJ         DECIMAL(18,2);
  DECLARE LN_RMBLAJ        DECIMAL(18,2);
  DECLARE LN_MDTSE         DECIMAL(18,2);
  DECLARE LN_ZH_MDTSE      DECIMAL(18,2);
  DECLARE LN_BYTS_MDTSE    DECIMAL(18,2);
  DECLARE LN_BYBL_MDTSE    DECIMAL(18,2);
  DECLARE LN_ZZS           DECIMAL(18,2);
  DECLARE LN_XFS           DECIMAL(18,2);
  DECLARE LN_MDSE          DECIMAL(18,2);
  DECLARE SN_ZZS           DECIMAL(18,2);
  DECLARE SN_XFS           DECIMAL(18,2);
  DECLARE SN_MDSE          DECIMAL(18,2);
  DECLARE SY_ZZS           DECIMAL(18,2);
  DECLARE SY_XFS           DECIMAL(18,2);
  DECLARE SY_MDSE          DECIMAL(18,2);
  DECLARE LD_LASTRQ        DATETIME;
  DECLARE V_ZLC_FS         DECIMAL(18,2);
  DECLARE V_ZLC_TS_AMT     DECIMAL(18,2);
  DECLARE V_ZLC_MD_AMT     DECIMAL(18,2);
  DECLARE V_ZLC_ZK_AMT     DECIMAL(18,2);
  DECLARE V_FF_DATE        DATETIME;
  DECLARE V_SL_DATE        DATETIME;
  DECLARE V_FH_DATE        DATETIME;
  DECLARE V_FH_USER        VARCHAR(20);
  DECLARE V_YWHZ_DATE      DATETIME;
  DECLARE V_YWHZ_USER      VARCHAR(20);
  DECLARE V_SEHZ_DATE      DATETIME;
  DECLARE V_SEHZ_USER      VARCHAR(20);
  DECLARE V_TSKP_DATE      DATETIME;
  DECLARE V_TSTK_DATE      DATETIME;
  DECLARE LN_I             BIGINT;
  DECLARE V_ZFBZ           CHAR(1);
  DECLARE V_ZFR_DM         VARCHAR(100);
  DECLARE V_ZFRQ           DATETIME;
  DECLARE V_CKSPTSSPLX_DM  CHAR(1);
  DECLARE V_TSL            DECIMAL(18,2);
  DECLARE V_JGFSTSLX_DM    CHAR(1);
  DECLARE V_HYDXZQH_DM     CHAR(4);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  SET LD_DEALDATA =ORA_DATE_ADD(DATE(CURRENT_TIMESTAMP), -(3));
  SET LN_LOG =2;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_AFTER_ETL开始处理！');
  COMMIT;

  -- 获取当前制表区间
  BEGIN
  DECLARE BJTS_SQLCODE_040 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_040 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_040 = MYSQL_ERRNO, BJTS_SQLERRM_040 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_040;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('获取当前制表区间失败！', LC_SBYY);
      COMMIT;

      SET LC_BBNY = DATE_FORMAT(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -1 MONTH), '%Y%m');
      SET LD_BBNY_KSRQ = CAST(DATE_FORMAT(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -1 MONTH), '%Y-%m-01') AS DATETIME);
      SET LD_BBNY_JZRQ = CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
      SET LD_BBNY_KSNF = MAKEDATE(YEAR(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -1 MONTH)), 1);

  END;
SELECT T.BBNY, T.BBNY_KSRQ, T.BBNY_JZRQ, T.BBNY_KSNF
      INTO LC_BBNY, LD_BBNY_KSRQ, LD_BBNY_JZRQ, LD_BBNY_KSNF
      FROM (SELECT *
              FROM TJBB_CS_ZBRQ
             WHERE CURRENT_TIMESTAMP>=BBNY_JZRQ
             ORDER BY BBNY_JZRQ DESC) T
     WHERE 1=1
LIMIT 1;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('获取当前制表区间成功！');
    COMMIT;
  END;

  -- 对部分外贸企业免退税申报，前一次全部分流以后又作废重新申报导致CKTS_LC_SBXX数据重复，LCSLID_SB设置错误进行纠正
  BEGIN
  DECLARE BJTS_SQLCODE_038 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_038 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_038 = MYSQL_ERRNO, BJTS_SQLERRM_038 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_038;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('对部分外贸企业免退税申报重复数据处理失败！', LC_SBYY);
      COMMIT;

  END;
SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_040 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_DUP_DJXH_040 LONGTEXT;
  DECLARE BJTS_CUR_DUP_SSQ_040 LONGTEXT;
  DECLARE BJTS_CUR_DUP_SBPC_040 LONGTEXT;
  DECLARE BJTS_CURSOR_040 CURSOR FOR
SELECT T.DJXH,T.SSQ,T.SBPC
                      FROM CKTS_LC_SBXX T
                     WHERE T.SBYWB_DM='A0301001' AND T.ZFBZ IS NULL
                     GROUP BY T.DJXH,T.SSQ,T.SBPC
                    HAVING COUNT(1)>1;
  OPEN BJTS_CURSOR_040;
  BJTS_CURSOR_LOOP_040: LOOP
    SET BJTS_CURSOR_DONE_040 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_040 = TRUE;
      FETCH BJTS_CURSOR_040 INTO BJTS_CUR_DUP_DJXH_040, BJTS_CUR_DUP_SSQ_040, BJTS_CUR_DUP_SBPC_040;
    END;
    IF BJTS_CURSOR_DONE_040 THEN
      LEAVE BJTS_CURSOR_LOOP_040;
    END IF;
      BEGIN
  DECLARE BJTS_CURSOR_DONE_039 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CURSOR_SKIP_039 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_ZFLC_UUID_039 LONGTEXT;
  DECLARE BJTS_CUR_ZFLC_LCSLID_SB_039 LONGTEXT;
  DECLARE BJTS_CURSOR_039 CURSOR FOR
SELECT S.UUID,S.LCSLID_SB
                         FROM CKTS_LC_SBXX S
                        WHERE S.DJXH=BJTS_CUR_DUP_DJXH_040 AND S.SSQ=BJTS_CUR_DUP_SSQ_040 AND S.SBPC=BJTS_CUR_DUP_SBPC_040 AND S.ZFBZ IS NULL
                          AND S.QDSJ<>(SELECT MAX(R.QDSJ)
                                         FROM CKTS_LC_SBXX R
                                        WHERE R.DJXH=BJTS_CUR_DUP_DJXH_040 AND R.SSQ=BJTS_CUR_DUP_SSQ_040 AND R.SBPC=BJTS_CUR_DUP_SBPC_040);
  OPEN BJTS_CURSOR_039;
  BJTS_CURSOR_LOOP_039: LOOP
    SET BJTS_CURSOR_DONE_039 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_039 = TRUE;
      FETCH BJTS_CURSOR_039 INTO BJTS_CUR_ZFLC_UUID_039, BJTS_CUR_ZFLC_LCSLID_SB_039;
    END;
    IF BJTS_CURSOR_DONE_039 THEN
      LEAVE BJTS_CURSOR_LOOP_039;
    END IF;
    SET BJTS_CURSOR_SKIP_039 = FALSE;
        BEGIN
  DECLARE BJTS_SQLCODE_039 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_039 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION, NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_039 = MYSQL_ERRNO, BJTS_SQLERRM_039 = MESSAGE_TEXT;
            SET BJTS_CURSOR_SKIP_039 = TRUE;

  END;
SELECT A.ZFBZ,A.ZFR_DM,A.ZFRQ
            INTO V_ZFBZ,V_ZFR_DM,V_ZFRQ
            FROM CKTS_LC_SHXX_ZF A
           WHERE A.DJXH=BJTS_CUR_DUP_DJXH_040 AND A.SSQ=BJTS_CUR_DUP_SSQ_040 AND A.SBPC=BJTS_CUR_DUP_SBPC_040 AND A.ZLCLCSLID=BJTS_CUR_ZFLC_LCSLID_SB_039
             AND A.ZFRQ=(SELECT MAX(B.ZFRQ)
                           FROM CKTS_LC_SHXX_ZF B
                          WHERE B.DJXH=BJTS_CUR_DUP_DJXH_040 AND B.SSQ=BJTS_CUR_DUP_SSQ_040 AND B.SBPC=BJTS_CUR_DUP_SBPC_040 AND B.ZLCLCSLID=BJTS_CUR_ZFLC_LCSLID_SB_039)
             AND 1=1
LIMIT 1;
        END;
    IF BJTS_CURSOR_SKIP_039 THEN
      ITERATE BJTS_CURSOR_LOOP_039;
    END IF;

        UPDATE CKTS_LC_SBXX AS A
           SET ZFBZ=V_ZFBZ,
    ZFR_DM=V_ZFR_DM,
    ZFRQ=V_ZFRQ
         WHERE A.UUID=BJTS_CUR_ZFLC_UUID_039;
        UPDATE CKTS_LC_SHXX AS A
           SET ZFBZ=V_ZFBZ,
    ZFR_DM=V_ZFR_DM,
    ZFRQ=V_ZFRQ
         WHERE A.UUID=BJTS_CUR_ZFLC_UUID_039;
        UPDATE CKTS_LC_SHXX AS A
           SET LCSLID_SB=' '
         WHERE A.DJXH=BJTS_CUR_DUP_DJXH_040 AND A.SSQ=BJTS_CUR_DUP_SSQ_040 AND A.SBPC=BJTS_CUR_DUP_SBPC_040 AND A.LCSLID<>BJTS_CUR_ZFLC_LCSLID_SB_039;
        UPDATE CKTS_SB_MTS_CKMX AS A
           SET LCSLID_SB=' '
         WHERE A.LCSLID_SB=BJTS_CUR_ZFLC_LCSLID_SB_039;
        UPDATE CKTS_SB_MTS_JHMX AS A
           SET LCSLID_SB=' '
         WHERE A.LCSLID_SB=BJTS_CUR_ZFLC_LCSLID_SB_039;
        DELETE FROM GLXT_BB_SHXT_LCXX AS A
         WHERE A.UUID=BJTS_CUR_ZFLC_UUID_039;
        COMMIT;
        SET LN_I =LN_I +1;

  END LOOP BJTS_CURSOR_LOOP_039;
  CLOSE BJTS_CURSOR_039;
END;

  END LOOP BJTS_CURSOR_LOOP_040;
  CLOSE BJTS_CURSOR_040;
END;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('对部分外贸企业免退税申报重复数据处理成功！', LN_I));
    COMMIT;
  END;

  -- GLXT_BB_SHXT_DJXX数据处理
  -- 设置备案信息的级次
  BEGIN
  DECLARE BJTS_SQLCODE_037 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_037 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_037 = MYSQL_ERRNO, BJTS_SQLERRM_037 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_037;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('GLXT_BB_SHXT_DJXX数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE GLXT_BB_SHXT_DJXX AS T
       SET SQ_DATE=CAST('2009-11-19' AS DATE)
     WHERE T.CPCODE='10113305000049913646';
    COMMIT;

    -- 外贸综合服务企业
    -- 35号公告+17号公告
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '71'
     WHERE BAJC_YEAR='00' AND WZFQY='Y' AND WZFQY13='Y' AND JSMODE='2';
    COMMIT;
    -- 35号公告
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '72'
     WHERE BAJC_YEAR='00' AND WZFQY='Y' AND JSMODE='2';
    COMMIT;
    -- 17号公告
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '70'
     WHERE BAJC_YEAR='00' AND WZFQY13='Y' AND JSMODE='2';
    COMMIT;
    -- 服务贸易
    -- 国际运输业务
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '60'
     WHERE BAJC_YEAR='00' AND YSFW='Y' AND YSFWCODE LIKE '%01%' AND YSFS IS NOT NULL;
    COMMIT;
    -- 研发设计业务
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '50'
     WHERE BAJC_YEAR='00' AND YSFW='Y' AND YSFWCODE LIKE '%03%' AND (YFSJFW LIKE '%01%' OR YFSJFW LIKE '%03%');
    COMMIT;
    -- 其他服务贸易
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '40'
     WHERE BAJC_YEAR='00' AND YSFW='Y' AND YSFWCODE IS NOT NULL;
    COMMIT;
    -- 其他企业
    -- 周边业务
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '30'
     WHERE BAJC_YEAR='00'
       AND EXISTS (SELECT 1 FROM CKTS_LC_SBXX A WHERE A.TSSWJG_DM=T.SWJGDM AND A.DJXH=T.DJXH_JS AND A.SBYWB_DM IN ('A0302001','A0303001','A0304001') AND A.ZFBZ IS NULL);
    COMMIT;
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '30'
     WHERE BAJC_YEAR='00'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.TSSWJG_DM=T.SWJGDM AND A.DJXH=T.DJXH_JS AND A.TBYY_DM IN ('470','480'));
    COMMIT;
    -- 生产企业
    -- 外商投资企业
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '23'
     WHERE BAJC_YEAR='00' AND JSMODE='1' AND SUBSTR(DJZCLX_JS,0,1) IN ('2','3');
    COMMIT;
    -- 委托出口企业
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '22'
     WHERE BAJC_YEAR='00' AND JSMODE='1' AND LENGTH(QYHGDM)=10 AND QYHGDM LIKE '9%';
    COMMIT;
    -- 内资生产企业
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '21'
     WHERE BAJC_YEAR='00' AND JSMODE='1';
    COMMIT;
    -- 外贸企业
    UPDATE GLXT_BB_SHXT_DJXX AS T
       SET BAJC_YEAR = '10'
     WHERE BAJC_YEAR='00' AND JSMODE='2';
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('GLXT_BB_SHXT_DJXX数据,处理成功！');
    COMMIT;
  END;

  -- 部分生产企业登记注册类型调整过，导致既有内资又有外资，统计级次按最新调整
  BEGIN
  DECLARE BJTS_SQLCODE_035 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_035 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_035 = MYSQL_ERRNO, BJTS_SQLERRM_035 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_035;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('部分生产企业登记注册类型调整过，统计级次按最新调整失败！', LC_SBYY);
      COMMIT;

  END;
BEGIN
  DECLARE BJTS_CURSOR_DONE_038 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CURSOR_SKIP_038 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_DJXH_DJXH_038 LONGTEXT;
  DECLARE BJTS_CURSOR_038 CURSOR FOR
SELECT DJXH FROM CKTS_LC_SHXX
                      WHERE LCJSRQ>=CAST('2024-01-01' AS DATE) AND SBYWB_DM='A0305001' AND LCTJJC IN ('21','23')
                      GROUP BY DJXH HAVING COUNT(DISTINCT LCTJJC)>1;
  OPEN BJTS_CURSOR_038;
  BJTS_CURSOR_LOOP_038: LOOP
    SET BJTS_CURSOR_DONE_038 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_038 = TRUE;
      FETCH BJTS_CURSOR_038 INTO BJTS_CUR_DJXH_DJXH_038;
    END;
    IF BJTS_CURSOR_DONE_038 THEN
      LEAVE BJTS_CURSOR_LOOP_038;
    END IF;
    SET BJTS_CURSOR_SKIP_038 = FALSE;
      BEGIN
  DECLARE BJTS_SQLCODE_036 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_036 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION, NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_036 = MYSQL_ERRNO, BJTS_SQLERRM_036 = MESSAGE_TEXT;
          SET BJTS_CURSOR_SKIP_038 = TRUE;

  END;
SELECT T.DJZCLX_JS
          INTO LC_DJZCLX
          FROM GLXT_BB_SHXT_DJXX T
         WHERE T.DJXH_JS=BJTS_CUR_DJXH_DJXH_038;
      END;
    IF BJTS_CURSOR_SKIP_038 THEN
      ITERATE BJTS_CURSOR_LOOP_038;
    END IF;
      IF SUBSTR(LC_DJZCLX,1,1)='1' THEN
        UPDATE CKTS_LC_SHXX AS T SET LCTJJC='21' WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_038 AND T.LCTJJC='23';
        UPDATE CKTS_LC_YWHZXX AS T SET LCTJJC='21' WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_038 AND T.LCTJJC='23';
        UPDATE CKTS_LC_SEHZXX AS T SET LCTJJC='21' WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_038 AND T.LCTJJC='23';
        COMMIT;
      ELSEIF SUBSTR(LC_DJZCLX,1,1) IN ('2','3') THEN
        UPDATE CKTS_LC_SHXX AS T SET LCTJJC='23' WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_038 AND T.LCTJJC='21';
        UPDATE CKTS_LC_YWHZXX AS T SET LCTJJC='23' WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_038 AND T.LCTJJC='21';
        UPDATE CKTS_LC_SEHZXX AS T SET LCTJJC='23' WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_038 AND T.LCTJJC='21';
        COMMIT;
      END IF;

  END LOOP BJTS_CURSOR_LOOP_038;
  CLOSE BJTS_CURSOR_038;
END;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('部分生产企业登记注册类型调整过，统计级次按最新调整成功！', LN_I));
    COMMIT;
  END;

  -- 部分企业出口与收核登记序号不一致，需要通过CKTS_ZS_DJXHDZB转换
  BEGIN
  DECLARE BJTS_SQLCODE_034 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_034 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_034 = MYSQL_ERRNO, BJTS_SQLERRM_034 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_034;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('出口与收核登记序号不一致，通过CKTS_ZS_DJXHDZB转换失败！', LC_SBYY);
      COMMIT;

  END;
SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_037 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_DJXH_DJXH_CK_037 LONGTEXT;
  DECLARE BJTS_CUR_DJXH_DJXH_ZS_037 LONGTEXT;
  DECLARE BJTS_CURSOR_037 CURSOR FOR
SELECT S.DJXH_CK,S.DJXH_ZS FROM CKTS_ZS_DJXHDZB S;
  OPEN BJTS_CURSOR_037;
  BJTS_CURSOR_LOOP_037: LOOP
    SET BJTS_CURSOR_DONE_037 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_037 = TRUE;
      FETCH BJTS_CURSOR_037 INTO BJTS_CUR_DJXH_DJXH_CK_037, BJTS_CUR_DJXH_DJXH_ZS_037;
    END;
    IF BJTS_CURSOR_DONE_037 THEN
      LEAVE BJTS_CURSOR_LOOP_037;
    END IF;
      UPDATE FG_CKTSFN_HXZG AS T
         SET SKSSSWJG_DM = (SELECT R.SWJGDM
FROM GLXT_BB_SHXT_DJXX R WHERE R.DJXH_JS=BJTS_CUR_DJXH_DJXH_CK_037),
    CPCODE = (SELECT R.CPCODE
FROM GLXT_BB_SHXT_DJXX R WHERE R.DJXH_JS=BJTS_CUR_DJXH_DJXH_CK_037),
    QYHGDM = (SELECT R.QYHGDM
FROM GLXT_BB_SHXT_DJXX R WHERE R.DJXH_JS=BJTS_CUR_DJXH_DJXH_CK_037),
    NSRSBH = (SELECT IFNULL(R.SHXYNO, R.NSRDJNO)
FROM GLXT_BB_SHXT_DJXX R WHERE R.DJXH_JS=BJTS_CUR_DJXH_DJXH_CK_037),
    NSRMC = (SELECT R.NSRMC
FROM GLXT_BB_SHXT_DJXX R WHERE R.DJXH_JS=BJTS_CUR_DJXH_DJXH_CK_037)
       WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_ZS_037;
      COMMIT;
      UPDATE CKTS_ZS_SRTHS AS T
         SET DJXH=BJTS_CUR_DJXH_DJXH_CK_037
       WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_ZS_037;
      COMMIT;
      UPDATE CKTS_ZS_MDTKB AS T
         SET DJXH=BJTS_CUR_DJXH_DJXH_CK_037
       WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_ZS_037;
      COMMIT;
      UPDATE CKTS_ZS_TKGZ AS T
         SET DJXH=BJTS_CUR_DJXH_DJXH_CK_037
       WHERE T.DJXH=BJTS_CUR_DJXH_DJXH_ZS_037;
      COMMIT;
      SET LN_I =LN_I +1;

  END LOOP BJTS_CURSOR_LOOP_037;
  CLOSE BJTS_CURSOR_037;
END;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('出口与收核登记序号不一致，通过CKTS_ZS_DJXHDZB转换成功！', LN_I));
    COMMIT;
  END;

  -- 针对部分税局返纳不符合返纳数据etl条件，设置临时表保存转换
  BEGIN
  DECLARE BJTS_SQLCODE_033 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_033 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_033 = MYSQL_ERRNO, BJTS_SQLERRM_033 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_033;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('青田有企业返纳不符合返纳数据etl条件，设置临时表保存转换失败！', LC_SBYY);
      COMMIT;

  END;
INSERT INTO FG_CKTSFN_HXZG
           (SPUUID,SKSSSWJG_DM,DJXH,CPCODE,QYHGDM,NSRSBH,NSRMC,ZSUUID,DZSPHM,DZSPMXXH,ZSXM_DM,SKSX_DM,YSKM_DM,
           SKSSQQ,SKSSQZ,KJRQ,JSYJ,JKQX,RKRQ,SJJE,YZPZXH_CKTS,XGRQ,SJTB_DATE,DZJG,SKSSSWJG_JS,YZHYTMSKYY_DM,YWHZBUUID,BZ)
    SELECT SPUUID,SKSSSWJG_DM,DJXH,CPCODE,QYHGDM,NSRSBH,NSRMC,ZSUUID,DZSPHM,DZSPMXXH,ZSXM_DM,SKSX_DM,YSKM_DM,
           SKSSQQ,SKSSQZ,KJRQ,JSYJ,JKQX,RKRQ,SJJE,YZPZXH_CKTS,XGRQ,SJTB_DATE,DZJG,SKSSSWJG_JS,YZHYTMSKYY_DM,YWHZBUUID,BZ
      FROM FG_CKTSFN_HXZG_YGP T
     WHERE NOT EXISTS (SELECT 1 FROM FG_CKTSFN_HXZG S WHERE S.SPUUID=T.SPUUID);

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('青田有企业返纳不符合返纳数据etl条件，设置临时表保存转换成功！');
    COMMIT;
  END;

  -- CKTS_SB_MDT_CKMX
  BEGIN
  DECLARE BJTS_SQLCODE_032 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_032 TEXT DEFAULT '';
    -- 删除作废流程信息

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_032 = MYSQL_ERRNO, BJTS_SQLERRM_032 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_032;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MDT_CKMX数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_036 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MDT_LCSLID_SB_036 LONGTEXT;
  DECLARE BJTS_CURSOR_036 CURSOR FOR
SELECT LCSLID_SB FROM CKTS_LC_SBXX WHERE ZFBZ='Y' AND SBYWB_DM='A0305001' AND IFNULL(ZFRQ, QDSJ)>=LD_DEALDATA;
  OPEN BJTS_CURSOR_036;
  BJTS_CURSOR_LOOP_036: LOOP
    SET BJTS_CURSOR_DONE_036 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_036 = TRUE;
      FETCH BJTS_CURSOR_036 INTO BJTS_CUR_MDT_LCSLID_SB_036;
    END;
    IF BJTS_CURSOR_DONE_036 THEN
      LEAVE BJTS_CURSOR_LOOP_036;
    END IF;
      BEGIN
        DELETE FROM CKTS_SB_MDT_CKMX AS T WHERE T.LCSLID=BJTS_CUR_MDT_LCSLID_SB_036;
        DELETE FROM CKTS_SB_MDT_GJYS AS T WHERE T.LCSLID=BJTS_CUR_MDT_LCSLID_SB_036;
        DELETE FROM CKTS_SB_MDT_YFSJ AS T WHERE T.LCSLID=BJTS_CUR_MDT_LCSLID_SB_036;
        COMMIT;
        SET LN_I =LN_I +1;
      END;

  END LOOP BJTS_CURSOR_LOOP_036;
  CLOSE BJTS_CURSOR_036;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('             CKTS_SB_MDT_CKMX删除作废流程信息！', LN_I));
      COMMIT;
    END IF;
    -- 设置LCSLID_SB
    -- 按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX AS T
       SET LCSLID_SB=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND A.SSQ=T.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_SB=' ' AND T.SSQ>='201901';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX分流数据设置LCSLID_SB！');
      COMMIT;
    END IF;
    -- 设置LCSLID_FS
    -- 按税局、企业、业务、准予退税所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX AS T
       SET LCSLID_FS=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.MDTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.MDTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX后期准予退税设置LCSLID_FS！');
      COMMIT;
    END IF;
    -- 按税局、企业、业务、不予退税所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX AS T
       SET LCSLID_FS=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.BYTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.BYTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX后期不予退税设置LCSLID_FS！');
      COMMIT;
    END IF;
    -- 按税局、企业、业务、不予办理所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX AS T
       SET LCSLID_FS=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.BYBLNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.BYBLNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX后期不予办理设置LCSLID_FS！');
      COMMIT;
    END IF;
    -- 企业撤回申报数据
    UPDATE CKTS_SB_MDT_CKMX AS T
       SET LCSLID_FS=T.LCSLID
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.CHBZ='Y';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX撤回申报数据设置LCSLID_FS！');
