      COMMIT;
    END IF;
*/
    -- BYTSBZ：明确
    -- ZBBLBZ：待定
    -- ZYTSBZ：CASE WHEN TRIM(B.MDTSNY) IS NOT NULL THEN 'Y' ELSE 'N' END

    -- 免抵退FSRQ处理
    BEGIN
  DECLARE BJTS_CURSOR_DONE_035 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_LCXX_FH_LCSLID_035 LONGTEXT;
  DECLARE BJTS_LCXX_FH_FSRQ_035 LONGTEXT;
  DECLARE BJTS_CURSOR_035 CURSOR FOR
SELECT T.LCSLID, MIN(S.FSRQ) AS FSRQ
                      FROM CKTS_SB_MDT_CKMX T
                     INNER JOIN CKTS_LC_SHXX R ON R.LCSLID=T.LCSLID
                     INNER JOIN CKTS_LC_YWHZXX S ON S.LCSLID_FS=R.LCSLID_FS
                     WHERE T.FSRQ IS NULL
                     GROUP BY T.LCSLID;
  OPEN BJTS_CURSOR_035;
  BJTS_CURSOR_LOOP_035: LOOP
    SET BJTS_CURSOR_DONE_035 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_035 = TRUE;
      FETCH BJTS_CURSOR_035 INTO BJTS_LCXX_FH_LCSLID_035, BJTS_LCXX_FH_FSRQ_035;
    END;
    IF BJTS_CURSOR_DONE_035 THEN
      LEAVE BJTS_CURSOR_LOOP_035;
    END IF;
      BEGIN
        UPDATE CKTS_SB_MDT_CKMX AS T
           SET FSRQ=BJTS_LCXX_FH_FSRQ_035
         WHERE LCSLID=BJTS_LCXX_FH_LCSLID_035;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_035;
  CLOSE BJTS_CURSOR_035;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX设置FSRQ！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MDT_CKMX数据,处理成功！');
    COMMIT;
  END;

