  -- CKTS_SB_MTS_JHMX, CKTS_SB_MTS_CKMX
  BEGIN
  DECLARE BJTS_SQLCODE_028 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_028 TEXT DEFAULT '';
    -- 删除作废流程信息

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_028 = MYSQL_ERRNO, BJTS_SQLERRM_028 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_028;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MTS_JHMX, CKTS_SB_MTS_CKMX数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_034 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTS_LCSLID_SB_034 LONGTEXT;
  DECLARE BJTS_CURSOR_034 CURSOR FOR
SELECT LCSLID_SB FROM CKTS_LC_SBXX WHERE ZFBZ='Y' AND SBYWB_DM='A0301001' AND IFNULL(ZFRQ, QDSJ)>=LD_DEALDATA;
  OPEN BJTS_CURSOR_034;
  BJTS_CURSOR_LOOP_034: LOOP
    SET BJTS_CURSOR_DONE_034 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_034 = TRUE;
      FETCH BJTS_CURSOR_034 INTO BJTS_CUR_MTS_LCSLID_SB_034;
    END;
    IF BJTS_CURSOR_DONE_034 THEN
      LEAVE BJTS_CURSOR_LOOP_034;
    END IF;
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX AS T SET LCSLID_SB=' ' WHERE T.LCSLID_SB=BJTS_CUR_MTS_LCSLID_SB_034;
        UPDATE CKTS_SB_MTS_CKMX AS T SET LCSLID_SB=' ' WHERE T.LCSLID_SB=BJTS_CUR_MTS_LCSLID_SB_034;
        UPDATE CKTS_SB_MTS_YSFW AS T SET LCSLID_SB=' ' WHERE T.LCSLID_SB=BJTS_CUR_MTS_LCSLID_SB_034;
        COMMIT;
        DELETE FROM CKTS_SB_MTS_JHMX AS T WHERE T.LCSLID=BJTS_CUR_MTS_LCSLID_SB_034;
        DELETE FROM CKTS_SB_MTS_CKMX AS T WHERE T.LCSLID=BJTS_CUR_MTS_LCSLID_SB_034;
        DELETE FROM CKTS_SB_MTS_YSFW AS T WHERE T.LCSLID=BJTS_CUR_MTS_LCSLID_SB_034;
        COMMIT;
        SET LN_I =LN_I +1;
      END;

  END LOOP BJTS_CURSOR_LOOP_034;
  CLOSE BJTS_CURSOR_034;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('             CKTS_SB_MTS_**MX删除作废流程信息！', LN_I));
      COMMIT;
    END IF;

    -- 设置LCSLID_SB
    UPDATE CKTS_SB_MTS_JHMX AS T
       SET LCSLID_SB=T.LCSLID
     WHERE T.LCSLID_SB=' ' AND T.SL<0;
    COMMIT;
    UPDATE CKTS_SB_MTS_CKMX AS T
       SET LCSLID_SB=T.LCSLID
     WHERE T.LCSLID_SB=' ' AND T.CKSL<0;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_*设置LCSLID_SB(红字冲减业务)！');
      COMMIT;
    END IF;
    UPDATE CKTS_SB_MTS_JHMX AS T
       SET LCSLID_SB=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0301001' AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_JHMX设置LCSLID_SB！');
      COMMIT;
    END IF;
    UPDATE CKTS_SB_MTS_CKMX AS T
       SET LCSLID_SB=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_SB_MTS_JHMX A
                             WHERE A.DJXH=T.DJXH AND A.GLH=T.GLH AND A.LCSLID=T.LCSLID
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_CKMX设置LCSLID_SB！');
      COMMIT;
    END IF;

    -- CKMX.JSJE, TSL, TMSE
    -- 每天过程表的数据全部刷新（15-55W）+结果表的增量
    -- 20260728加数据同步时间条件，期望可以用到索引
    SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_033 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTSCK_DJXH_033 LONGTEXT;
  DECLARE BJTS_CUR_MTSCK_GLH_033 LONGTEXT;
  DECLARE BJTS_CUR_MTSCK_CKSP_DM_033 LONGTEXT;
  DECLARE BJTS_CUR_MTSCK_LCSLID_033 LONGTEXT;
  DECLARE BJTS_CUR_MTSCK_LCSLID_SB_033 LONGTEXT;
  DECLARE BJTS_CUR_MTSCK_GLH_CKSL_033 LONGTEXT;
  DECLARE BJTS_CUR_MTSCK_GLH_N_033 LONGTEXT;
  DECLARE BJTS_CURSOR_033 CURSOR FOR
SELECT T.DJXH,T.GLH,T.CKSP_DM,T.LCSLID,IFNULL(T.LCSLID_SB, '1') AS LCSLID_SB,SUM(T.CKSL) AS GLH_CKSL,COUNT(1) AS GLH_N
                        FROM CKTS_SB_MTS_CKMX T
                       WHERE T.SJTB_SJ>=LD_DEALDATA AND IFNULL(T.JSJE, 0)=0
                       GROUP BY T.DJXH,T.GLH,T.CKSP_DM,T.LCSLID,IFNULL(T.LCSLID_SB, '1');
  OPEN BJTS_CURSOR_033;
  BJTS_CURSOR_LOOP_033: LOOP
    SET BJTS_CURSOR_DONE_033 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_033 = TRUE;
      FETCH BJTS_CURSOR_033 INTO BJTS_CUR_MTSCK_DJXH_033, BJTS_CUR_MTSCK_GLH_033, BJTS_CUR_MTSCK_CKSP_DM_033, BJTS_CUR_MTSCK_LCSLID_033, BJTS_CUR_MTSCK_LCSLID_SB_033, BJTS_CUR_MTSCK_GLH_CKSL_033, BJTS_CUR_MTSCK_GLH_N_033;
    END;
    IF BJTS_CURSOR_DONE_033 THEN
      LEAVE BJTS_CURSOR_LOOP_033;
    END IF;
      BEGIN
  DECLARE BJTS_SQLCODE_029 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_029 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_029 = MYSQL_ERRNO, BJTS_SQLERRM_029 = MESSAGE_TEXT;
          SET GLH_JSJE =0;
          SET GLH_TSL =0;
          SET GLH_TMSE =0;

  END;
SELECT SUM(CASE WHEN S.SZ='V' THEN S.JSJE ELSE 0 END), MAX(CASE WHEN S.SZ='V' THEN S.TSL ELSE 0 END), SUM(S.TSE)
          INTO GLH_JSJE, GLH_TSL, GLH_TMSE
          FROM CKTS_SB_MTS_JHMX S
         WHERE S.DJXH=BJTS_CUR_MTSCK_DJXH_033 AND S.GLH=BJTS_CUR_MTSCK_GLH_033 AND S.CKSP_DM=BJTS_CUR_MTSCK_CKSP_DM_033 AND S.LCSLID=BJTS_CUR_MTSCK_LCSLID_033 AND IFNULL(S.LCSLID_SB, '1')=BJTS_CUR_MTSCK_LCSLID_SB_033;
      END;
      UPDATE CKTS_SB_MTS_CKMX AS A
         SET JSJE = CASE WHEN BJTS_CUR_MTSCK_GLH_N_033=1 THEN GLH_JSJE
                           WHEN BJTS_CUR_MTSCK_GLH_CKSL_033=0 THEN (CASE WHEN A.CKSL>0 THEN GLH_JSJE WHEN A.CKSL<0 THEN (-1)*GLH_JSJE ELSE 0 END)
                           ELSE GLH_JSJE * A.CKSL / BJTS_CUR_MTSCK_GLH_CKSL_033 END,
    TSL = GLH_TSL,
    TSE = CASE WHEN BJTS_CUR_MTSCK_GLH_N_033=1 THEN GLH_TMSE
                           WHEN BJTS_CUR_MTSCK_GLH_CKSL_033=0 THEN (CASE WHEN A.CKSL>0 THEN GLH_TMSE WHEN A.CKSL<0 THEN (-1)*GLH_TMSE ELSE 0 END)
                          ELSE GLH_TMSE * A.CKSL / BJTS_CUR_MTSCK_GLH_CKSL_033 END
       WHERE A.DJXH=BJTS_CUR_MTSCK_DJXH_033 AND A.GLH=BJTS_CUR_MTSCK_GLH_033 AND A.CKSP_DM=BJTS_CUR_MTSCK_CKSP_DM_033 AND A.LCSLID=BJTS_CUR_MTSCK_LCSLID_033 AND IFNULL(A.LCSLID_SB, '1')=BJTS_CUR_MTSCK_LCSLID_SB_033;
      COMMIT;
      SET LN_I =LN_I +1;

  END LOOP BJTS_CURSOR_LOOP_033;
  CLOSE BJTS_CURSOR_033;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('             CKTS_SB_MTS_CKMX 设置（JSJE、TSL、TSE）！', LN_I));
      COMMIT;
    END IF;

    -- JHMX.CKRQ_1
    -- 每天过程表的数据全部刷新（15-55W）+结果表的增量
    -- 20260728鉴于查询条件有索引，仅优化关联条件
    SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_032 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTS_UUID_032 LONGTEXT;
  DECLARE BJTS_CUR_MTS_DJXH_032 LONGTEXT;
  DECLARE BJTS_CUR_MTS_GLH_032 LONGTEXT;
  DECLARE BJTS_CUR_MTS_LCSLID_032 LONGTEXT;
  DECLARE BJTS_CUR_MTS_CKRQ_1_032 LONGTEXT;
  DECLARE BJTS_CURSOR_032 CURSOR FOR
SELECT S.UUID,S.DJXH,S.GLH,S.LCSLID,MAX(T.CKRQ_1) AS CKRQ_1
                      FROM CKTS_SB_MTS_JHMX S
                     INNER JOIN CKTS_SB_MTS_CKMX T
                        ON T.DJXH=S.DJXH AND T.GLH=S.GLH AND T.CKSP_DM=S.CKSP_DM AND T.LCSLID=S.LCSLID
                     WHERE S.CKRQ_1=CAST('1900-01-01' AS DATE)
                     GROUP BY S.UUID,S.DJXH,S.GLH,S.LCSLID;
  OPEN BJTS_CURSOR_032;
  BJTS_CURSOR_LOOP_032: LOOP
    SET BJTS_CURSOR_DONE_032 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_032 = TRUE;
      FETCH BJTS_CURSOR_032 INTO BJTS_CUR_MTS_UUID_032, BJTS_CUR_MTS_DJXH_032, BJTS_CUR_MTS_GLH_032, BJTS_CUR_MTS_LCSLID_032, BJTS_CUR_MTS_CKRQ_1_032;
    END;
    IF BJTS_CURSOR_DONE_032 THEN
      LEAVE BJTS_CURSOR_LOOP_032;
    END IF;
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX AS R
           SET CKRQ_1 = BJTS_CUR_MTS_CKRQ_1_032
         WHERE R.UUID=BJTS_CUR_MTS_UUID_032;
        COMMIT;
        SET LN_I =LN_I+1;
      END;

  END LOOP BJTS_CURSOR_LOOP_032;
  CLOSE BJTS_CURSOR_032;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('             CKTS_SB_MTS_JHMX设置CKRQ_1！合计', LN_I));
      COMMIT;
    END IF;

    -- BYBLBZ
    -- 20260728加数据同步时间条件，期望可以用到索引
    SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_031 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTS_DJXH_031 LONGTEXT;
  DECLARE BJTS_CUR_MTS_GLH_031 LONGTEXT;
  DECLARE BJTS_CUR_MTS_LCSLID_031 LONGTEXT;
  DECLARE BJTS_CURSOR_031 CURSOR FOR
SELECT DISTINCT T.DJXH, T.GLH, T.LCSLID
