           SET SJTB_SJ=CURRENT_TIMESTAMP,
    ZBBLBZ='Y'
         WHERE R.DJXH=BJTS_CUR_MTS_DJXH_029 AND R.GLH=BJTS_CUR_MTS_GLH_029 AND R.LCSLID=BJTS_CUR_MTS_LCSLID_029 AND R.ZBBLBZ='N';
        UPDATE CKTS_SB_MTS_CKMX AS R
