    ZBBLBZ='N'
         WHERE R.DJXH=BJTS_CUR_MTS_DJXH_028 AND R.GLH=BJTS_CUR_MTS_GLH_028 AND R.LCSLID=BJTS_CUR_MTS_LCSLID_028 AND R.ZBBLBZ='Y';
