  END;

  -- CKTS_SB_MTS_YSFW
  BEGIN
  DECLARE BJTS_SQLCODE_027 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_027 TEXT DEFAULT '';
    -- 设置LCSLID_SB
    -- 按税局、企业、业务、所属期、批次查找申报流程

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_027 = MYSQL_ERRNO, BJTS_SQLERRM_027 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_027;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MTS_YSFW数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE CKTS_SB_MTS_YSFW AS T
       SET LCSLID_SB=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0301001' AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_YSFW设置LCSLID_SB！');
      COMMIT;
    END IF;
    -- BYTSBZ：明确
    -- ZBBLBZ：待定
    -- ZYTSBZ
    UPDATE CKTS_SB_MTS_YSFW AS T
       SET MTSBZ='Y'
     WHERE T.MTSBZ ='N' AND T.BYTSBZ='N' AND T.BYBLBZ='N' AND T.ZBBLBZ='N'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID AND A.CKTMSHWYSFWLX_DM='2');
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MTS_YSFW数据,处理成功！');
    COMMIT;
  END;

  -- CKTS_SB_WZF_CKMX
  BEGIN
  DECLARE BJTS_SQLCODE_026 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_026 TEXT DEFAULT '';
    -- 删除作废流程信息

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_026 = MYSQL_ERRNO, BJTS_SQLERRM_026 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_026;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_WZF_CKMX数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_026 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTS_LCSLID_SB_026 LONGTEXT;
  DECLARE BJTS_CURSOR_026 CURSOR FOR
SELECT LCSLID_SB FROM CKTS_LC_SBXX WHERE ZFBZ='Y' AND SBYWB_DM='A0310001' AND IFNULL(ZFRQ, QDSJ)>=LD_DEALDATA;
  OPEN BJTS_CURSOR_026;
  BJTS_CURSOR_LOOP_026: LOOP
    SET BJTS_CURSOR_DONE_026 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_026 = TRUE;
      FETCH BJTS_CURSOR_026 INTO BJTS_CUR_MTS_LCSLID_SB_026;
    END;
    IF BJTS_CURSOR_DONE_026 THEN
      LEAVE BJTS_CURSOR_LOOP_026;
    END IF;
      BEGIN
        DELETE FROM CKTS_SB_WZF_CKMX AS T WHERE T.LCSLID=BJTS_CUR_MTS_LCSLID_SB_026;
        COMMIT;
        SET LN_I =LN_I+1;
      END;

  END LOOP BJTS_CURSOR_LOOP_026;
  CLOSE BJTS_CURSOR_026;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('             CKTS_SB_WZF_CKMX删除作废流程信息！', LN_I));
      COMMIT;
    END IF;
    -- 设置LCSLID_SB
    -- 按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_WZF_CKMX AS T
       SET LCSLID_SB=IFNULL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0310001' AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_WZF_CKMX设置LCSLID_SB！');
      COMMIT;
    END IF;
    -- BYTSBZ：明确
    -- ZBBLBZ：待定
    -- ZYTSBZ

    -- 代办退税FSRQ处理
    BEGIN
  DECLARE BJTS_CURSOR_DONE_025 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_LCXX_FH_LCSLID_025 LONGTEXT;
  DECLARE BJTS_LCXX_FH_FSRQ_025 LONGTEXT;
  DECLARE BJTS_CURSOR_025 CURSOR FOR
SELECT T.LCSLID, MIN(S.FSRQ) AS FSRQ
                      FROM CKTS_SB_WZF_CKMX T
                     INNER JOIN CKTS_LC_YWHZXX S ON S.LCSLID_FS=T.LCSLID
                     WHERE T.FSRQ IS NULL
                     GROUP BY T.LCSLID;
  OPEN BJTS_CURSOR_025;
  BJTS_CURSOR_LOOP_025: LOOP
    SET BJTS_CURSOR_DONE_025 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_025 = TRUE;
      FETCH BJTS_CURSOR_025 INTO BJTS_LCXX_FH_LCSLID_025, BJTS_LCXX_FH_FSRQ_025;
    END;
    IF BJTS_CURSOR_DONE_025 THEN
      LEAVE BJTS_CURSOR_LOOP_025;
    END IF;
      BEGIN
        UPDATE CKTS_SB_WZF_CKMX AS T
           SET FSRQ=BJTS_LCXX_FH_FSRQ_025
         WHERE LCSLID=BJTS_LCXX_FH_LCSLID_025;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_025;
  CLOSE BJTS_CURSOR_025;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_WZF_CKMX设置FSRQ！');
      COMMIT;
    END IF;

    UPDATE CKTS_SB_WZF_CKMX AS T
       SET MTSBZ='Y'
     WHERE T.MTSBZ ='N' AND T.BYTSBZ='N' AND T.BYBLBZ='N' AND T.ZBBLBZ='N'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID);
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_WZF_CKMX数据,处理成功！');
    COMMIT;
  END;

  -- CKTS_LC_SBXX（CKQYGLLB_DM、SB_XSEMY,SB_XSERMB,SB_MDTSE,SB_ZZSTSE,SB_XFSTSE,SB_MDSE）
  BEGIN
  DECLARE BJTS_SQLCODE_025 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_025 TEXT DEFAULT '';
    -- 设置分类管理等级（注：还有一部分申报数据在总局分类管理政策之前申报的，已按最接近年份设置分类管理类别，当前无分类的默认C）

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_025 = MYSQL_ERRNO, BJTS_SQLERRM_025 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_025;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SBXX数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE CKTS_LC_SBXX AS T
       SET CKQYGLLB_DM=
           (SELECT KZXX
              FROM GS_DJ_CKTMSDAB A, GS_DJ_CKTMSDAB_KZ B
             WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=CAST(T.DJXH AS CHAR) AND B.KZLX='FLGLCD' AND T.XGRQ BETWEEN B.ST_DATE AND B.END_DATE
               AND 1=1
LIMIT 1)
     WHERE T.CKQYGLLB_DM IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置CKQYGLLB_DM！');
      COMMIT;
    END IF;

    -- 缺免抵退业务申报信息，该部分新增从免抵退汇总表获取

    -- 免退税业务申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX AS T
       SET SB_XSEMY =(SELECT SUM(A.MYLAJ)
                          FROM CKTS_SB_MTS_CKMX A
                         WHERE A.LCSLID_SB=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0301001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    UPDATE CKTS_LC_SBXX AS T
       SET SB_XSERMB = (SELECT SUM(CASE WHEN A.SZ='V' THEN A.JSJE ELSE 0 END)
FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_MDTSE = (SELECT SUM(A.TSE)
FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_ZZSTSE = (SELECT SUM(CASE WHEN A.SZ='V' THEN A.TSE ELSE 0 END)
FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_XFSTSE = (SELECT SUM(CASE WHEN A.SZ='C' THEN A.TSE ELSE 0 END)
FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_MDSE = (SELECT 0
FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0301001' AND T.SB_XSERMB IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置SB_XSEMY(A0301001)！');
      COMMIT;
    END IF;

    -- 外综服业务申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX AS T
       SET SB_XSEMY = (SELECT SUM(A.MYLAJ)
FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_XSERMB = (SELECT SUM(A.JSJE)
FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_MDTSE = (SELECT SUM(A.TSE)
FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_ZZSTSE = (SELECT SUM(A.TSE)
FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_XFSTSE = (SELECT 0
FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB),
    SB_MDSE = (SELECT 0
FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0310001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置SB_XSEMY(A0310001)！');
      COMMIT;
    END IF;

    -- 非自产业务申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX AS T
       SET SB_XSEMY = (SELECT 0
FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_XSERMB = (SELECT SUM(A.JSJE)
FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_MDTSE = (SELECT SUM(A.XFSTSE)
FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_ZZSTSE = (SELECT 0
FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_XFSTSE = (SELECT SUM(A.XFSTSE)
FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_MDSE = (SELECT 0
FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0302001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    -- 旧设备申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX AS T
       SET SB_XSEMY = (SELECT 0
FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_XSERMB = (SELECT SUM(A.SBZYJZ)
FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_MDTSE = (SELECT SUM(A.TSE)
FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_ZZSTSE = (SELECT SUM(A.TSE)
FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_XFSTSE = (SELECT 0
FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_MDSE = (SELECT 0
FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0303001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    -- 购进自用申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX AS T
       SET SB_XSEMY = (SELECT 0
FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_XSERMB = (SELECT SUM(A.JSJE)
FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_MDTSE = (SELECT SUM(A.TSE)
FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_ZZSTSE = (SELECT SUM(A.TSE)
FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_XFSTSE = (SELECT 0
FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB),
    SB_MDSE = (SELECT 0
FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0304001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置SB_XSEMY(特殊业务)！');
      COMMIT;
    END IF;

    -- 部分免退税业务含跨境应税行为，需要两边合计
    BEGIN
  DECLARE BJTS_CURSOR_DONE_024 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTSYSFW_LCSLID_SB_024 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_MYLAJ_024 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_RMBLAJ_024 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_ZZSTSE_024 LONGTEXT;
  DECLARE BJTS_CURSOR_024 CURSOR FOR
SELECT LCSLID_SB, SUM(SKJEMY) AS MYLAJ, SUM(BQQRYSFWYYSRRMBJE) AS RMBLAJ,SUM(ZZSTSE) AS ZZSTSE FROM CKTS_SB_MTS_YSFW GROUP BY LCSLID_SB;
  OPEN BJTS_CURSOR_024;
  BJTS_CURSOR_LOOP_024: LOOP
    SET BJTS_CURSOR_DONE_024 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_024 = TRUE;
      FETCH BJTS_CURSOR_024 INTO BJTS_CUR_MTSYSFW_LCSLID_SB_024, BJTS_CUR_MTSYSFW_MYLAJ_024, BJTS_CUR_MTSYSFW_RMBLAJ_024, BJTS_CUR_MTSYSFW_ZZSTSE_024;
    END;
    IF BJTS_CURSOR_DONE_024 THEN
      LEAVE BJTS_CURSOR_LOOP_024;
    END IF;
      BEGIN
        UPDATE CKTS_LC_SBXX AS T
           SET SB_XSEMY = BJTS_CUR_MTSYSFW_MYLAJ_024 + (SELECT IFNULL(SUM(A.MYLAJ), 0) FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID_SB=BJTS_CUR_MTSYSFW_LCSLID_SB_024),
    SB_XSERMB = BJTS_CUR_MTSYSFW_RMBLAJ_024 + (SELECT IFNULL(SUM(A.JSJE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=BJTS_CUR_MTSYSFW_LCSLID_SB_024 AND A.SZ='V'),
    SB_MDTSE = BJTS_CUR_MTSYSFW_ZZSTSE_024 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=BJTS_CUR_MTSYSFW_LCSLID_SB_024),
    SB_ZZSTSE = BJTS_CUR_MTSYSFW_ZZSTSE_024 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=BJTS_CUR_MTSYSFW_LCSLID_SB_024 AND A.SZ='V'),
    SB_XFSTSE = (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=BJTS_CUR_MTSYSFW_LCSLID_SB_024 AND A.SZ='C'),
    SB_MDSE = 0
         WHERE T.LCSLID_SB=BJTS_CUR_MTSYSFW_LCSLID_SB_024;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_024;
  CLOSE BJTS_CURSOR_024;
END;

    UPDATE CKTS_LC_SBXX AS T
       SET SB_MDTSE=T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE
     WHERE T.ZFBZ IS NULL AND T.SB_MDTSE<>T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE;
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SBXX数据,处理成功！');
    COMMIT;
  END;

  -- CKTS_LC_SHXX数据处理（LCSLID_SB、LCSLID_FS、CKQYGLLB_DM、LCTJJC）
  BEGIN
  DECLARE BJTS_SQLCODE_024 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_024 TEXT DEFAULT '';
    -- 清除作废流程

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_024 = MYSQL_ERRNO, BJTS_SQLERRM_024 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_024;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SHXX数据,LCSLID_SB、LCSLID_FS、CKQYGLLB_DM、LCTJJC,处理失败！', LC_SBYY);
      COMMIT;

  END;
INSERT INTO CKTS_LC_SHXX_ZF
         SELECT * FROM CKTS_LC_SHXX T WHERE T.ZFBZ='Y' AND IFNULL(T.FFBZ, 'N')<>'Y';
    COMMIT;
    DELETE FROM CKTS_LC_SHXX AS T WHERE T.ZFBZ='Y' AND IFNULL(T.FFBZ, 'N')<>'Y';
    COMMIT;
    DELETE FROM CKTS_LC_YWHZXX AS T WHERE T.LCSLID_FS IN (SELECT S.LCSLID_FS FROM CKTS_LC_SHXX_ZF S);
    COMMIT;
    DELETE FROM CKTS_LC_SEHZXX AS T WHERE T.LCSLID_FS IN (SELECT S.LCSLID_FS FROM CKTS_LC_SHXX_ZF S);
    COMMIT;
    DELETE FROM CKTS_LC_SHXX AS T WHERE (T.LCSLID_SB,T.LCSLID,T.QDSJ) IN
           (SELECT S.LCSLID_SB,S.LCSLID,MAX(S.QDSJ) FROM CKTS_LC_SHXX S WHERE S.LCSWSX_DM IN ('LCSXA081038005','LCSXA081039005') GROUP BY S.LCSLID_SB,S.LCSLID HAVING COUNT(1)>1);
    COMMIT;
    DROP TEMPORARY TABLE IF EXISTS BJTS_TMP_CKTS_LC_SHXX_ZF;
    CREATE TEMPORARY TABLE BJTS_TMP_CKTS_LC_SHXX_ZF LIKE CKTS_LC_SHXX_ZF;
    ALTER TABLE BJTS_TMP_CKTS_LC_SHXX_ZF
        ADD UNIQUE KEY BJTS_UK_UUID (UUID);
    INSERT IGNORE INTO BJTS_TMP_CKTS_LC_SHXX_ZF
        SELECT * FROM CKTS_LC_SHXX_ZF;
    DELETE FROM CKTS_LC_SHXX_ZF;
    INSERT INTO CKTS_LC_SHXX_ZF
        SELECT * FROM BJTS_TMP_CKTS_LC_SHXX_ZF;
    DROP TEMPORARY TABLE BJTS_TMP_CKTS_LC_SHXX_ZF;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX删除作废流程！');
      COMMIT;
    END IF;

    -- 审核信息lcslid_sb、lcslid_fs设置
    -- 设置LCSLID_SB
    -- T.LCSWSX_DM='LCSXA081038005'发放以后，免抵退出口明细表中对应调查评估的lcslid会发生变化，是一个新的在业务流程表中不存在的数据，需要通过语句补偿
    DELETE FROM CKTS_LC_SHXX AS T WHERE T.SBYWB_DM='A0305001' AND T.LCSLID<>T.LCSLID_SB AND T.SJTB_BZ='9' AND T.LCJSRQ>CURRENT_TIMESTAMP;
    COMMIT;
    INSERT INTO CKTS_LC_SHXX (UUID,CKTMSHWYSFWLX_DM,LCTJJC,TSSWJG_DM,DJXH,CKQYGLLB_DM,WZHBZ,SBYWB_DM,SSQ,SBPC,LCSLID,LCSLID_SB,LCSLID_FS,QDR_DM,QDSJ,LCJSRQ,XGRQ,SJTB_SJ,SJTB_BZ,ZLCLCSLID,LCSWSX_DM)
    SELECT TT.UUID,A.CKTMSHWYSFWLX_DM,'00',A.TSSWJG_DM,A.DJXH,A.CKQYGLLB_DM,A.WZHBZ,A.SBYWB_DM,A.SSQ,A.SBPC,TT.LCSLID,TT.LCSLID_SB,TT.LCSLID_FS,A.QDR_DM,A.QDSJ,STR_TO_DATE('2100-12-31', '%Y-%m-%d'),A.XGRQ,CURRENT_TIMESTAMP,'9',A.ZLCLCSLID,A.LCSWSX_DM
      FROM CKTS_LC_SHXX A
     INNER JOIN (SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID
                   FROM (SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID FROM CKTS_SB_MDT_CKMX B
                          WHERE B.LCSLID<>B.LCSLID_SB AND NOT EXISTS(SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID=B.LCSLID)
                          GROUP BY LCSLID,LCSLID_SB,LCSLID_FS
                          UNION ALL
                         SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID FROM CKTS_SB_MDT_GJYS C
                          WHERE C.LCSLID<>C.LCSLID_SB AND NOT EXISTS(SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID=C.LCSLID)
                          GROUP BY LCSLID,LCSLID_SB,LCSLID_FS
                          UNION ALL
                         SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID FROM CKTS_SB_MDT_YFSJ D
                          WHERE D.LCSLID<>D.LCSLID_SB AND NOT EXISTS(SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID=D.LCSLID)
                          GROUP BY LCSLID,LCSLID_SB,LCSLID_FS ) T
                  GROUP BY LCSLID,LCSLID_SB,LCSLID_FS
                ) TT ON TT.LCSLID_SB=A.LCSLID;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(A0305001分流信息)！');
      COMMIT;
    END IF;

    -- 设置LCSLID_SB
    -- 特殊政策退税不分流，申报流程等于当前流程，
    UPDATE CKTS_LC_SHXX AS T
       SET LCSLID_SB = T.LCSLID
     WHERE T.LCSLID_SB=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM IN ('A0302001','A0303001','A0304001');
    COMMIT;
    -- 免抵退业务分流程在前一步刷新时申报流程非空，其他主流程申报流程等于当前流程
    UPDATE CKTS_LC_SHXX AS T
       SET LCSLID_SB = IFNULL((SELECT A.LCSLID_SB FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM=T.SBYWB_DM AND A.SSQ=T.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_SB=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM = 'A0305001';
    COMMIT;
    -- 免退税、代办退税按当前流程到对应明细表中找申报流程（必须有明细数据）
    UPDATE CKTS_LC_SHXX AS T
       SET LCSLID_SB = IFNULL((SELECT A.LCSLID_SB FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM=T.SBYWB_DM AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND 1=1
LIMIT 1), ' ')
     WHERE T.LCSLID_SB=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM IN ('A0301001','A0310001');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(LCSLID_SB)！');
      COMMIT;
    END IF;

    -- 设置LCSLID_FS
    -- 非免抵退税业务，复审流程等于当前流程
    UPDATE CKTS_LC_SHXX AS T
       SET LCSLID_FS = T.LCSLID
     WHERE T.LCJSRQ>=LD_DEALDATA AND T.LCSLID_FS=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM IN ('A0301001','A0302001','A0303001','A0304001','A0310001')
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID);
    COMMIT;
    -- 免抵退主流程，复审流程等于当前流程
    -- 免抵退分流程，不用处理
    UPDATE CKTS_LC_SHXX AS T
       SET LCSLID_FS = T.LCSLID
     WHERE T.LCJSRQ>=LD_DEALDATA AND T.LCSLID_FS=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM='A0305001' AND T.LCSLID=T.LCSLID_SB
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(LCSLID_FS)！');
      COMMIT;
    END IF;

    -- 设置分类管理等级（注：还有一部分申报数据在总局分类管理政策之前申报的，已按最接近年份设置分类管理类别，当前无分类的默认C）
    UPDATE CKTS_LC_SHXX AS T
       SET CKQYGLLB_DM=(SELECT KZXX
                            FROM GS_DJ_CKTMSDAB A, GS_DJ_CKTMSDAB_KZ B
                           WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=CAST(T.DJXH AS CHAR) AND B.KZLX='FLGLCD' AND T.QDSJ BETWEEN B.ST_DATE AND B.END_DATE
                             AND 1=1
LIMIT 1)
     WHERE T.CKQYGLLB_DM IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(CKQYGLLB_DM)！');
      COMMIT;
    END IF;

    -- LCTJJC
    -- 35号公告代办退税
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='72'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0310001';
    COMMIT;
    -- 17号公告代办退税
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='71'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.CKTMSYWLXDMJH LIKE 'WMZHFW%');
    COMMIT;
    -- 综服企业自营业务
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='70'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.BAJC_YEAR LIKE '7%');
    COMMIT;
    -- 国际运输业务
    -- 外商投资企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='63'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    -- 委托出口企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='62'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    -- 内资生产企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='61'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB);
    COMMIT;
    -- 研发设计业务
    -- 外商投资企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='53'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    -- 委托出口企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='52'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    -- 内资生产企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='51'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
    COMMIT;
    -- 其他服务贸易
    -- 外商投资企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='43'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    -- 委托出口企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='42'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    -- 内资生产企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='41'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB);
    COMMIT;
    -- 外贸服务贸易
    -- 研发设计业务
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='50'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
    COMMIT;
    -- 其他服务贸易
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='40'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB);
    COMMIT;
    -- 周边业务
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='30'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM IN ('A0302001','A0303001','A0304001');
    COMMIT;
    -- 外商投资企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='23'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    -- 委托出口企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='22'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    -- 内资生产企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='21'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' ';
    COMMIT;
    -- 外贸企业
    UPDATE CKTS_LC_SHXX AS T
       SET LCTJJC='10'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(LCTJJC)！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SHXX数据,LCSLID_SB、LCSLID_FS、CKQYGLLB_DM、LCTJJC,处理成功！');
    COMMIT;
  END;

  -- CKTS_LC_SEHZXX数据处理（GKBL_、XHRQ_、SNCKZB）
  BEGIN
  DECLARE BJTS_SQLCODE_021 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_021 TEXT DEFAULT '';
    -- CKTMSJHSSSWJGDM、MDTKSSSWJGDM补充

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_021 = MYSQL_ERRNO, BJTS_SQLERRM_021 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_021;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SEHZXX数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE CKTS_LC_SEHZXX AS T
       SET CKTMSJHSSSWJGDM=T.TSSWJG_DM
     WHERE T.CKTMSJHSSSWJGDM IS NULL;
    COMMIT;
    UPDATE CKTS_LC_SEHZXX AS T
       SET MDTKSSSWJGDM=T.TSSWJG_DM
     WHERE T.MDTKSSSWJGDM IS NULL;
    COMMIT;
    -- 税额核准数为0的情况更新
    UPDATE CKTS_LC_SEHZXX AS T
       SET GKBL_ZZSTSE=0,
    XHRQ_TK =T.SEHZRQ,
    KPRQ=T.SEHZRQ
     WHERE T.GKBL_ZZSTSE IS NULL AND T.SEHZ_ZZSTSE=0;
    COMMIT;
    UPDATE CKTS_LC_SEHZXX AS T
       SET GKBL_XFSTSE=0,
    XHRQ_XFS =T.SEHZRQ
     WHERE T.GKBL_XFSTSE IS NULL AND T.SEHZ_XFSTSE=0;
    COMMIT;
    UPDATE CKTS_LC_SEHZXX AS T
       SET GKBL_MDSE=0,
    XHRQ_MD =T.SEHZRQ
     WHERE T.GKBL_MDSE IS NULL AND T.SEHZ_MDSE=0;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_(SEHZ_=0)！');
      COMMIT;
    END IF;

    -- 根据收核回推至LD_DEALDATA免抵调数据，更新税额核准表办理数
    BEGIN
  DECLARE BJTS_CURSOR_DONE_023 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_023 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_SEHZ_MDSE_023 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_GKBL_MDSE_023 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_XHRQ_1_023 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_MDTKSSSWJGDM_023 LONGTEXT;
  DECLARE BJTS_CURSOR_023 CURSOR FOR
SELECT R.UUID,R.SEHZ_MDSE,LEAST(R.SEHZ_MDSE,S.MD_AMT,T.JE) AS GKBL_MDSE, T.XHRQ_1, IFNULL(T.HSSWJG_DM, R.CKTMSJHSSSWJGDM) AS MDTKSSSWJGDM
                       FROM CKTS_ZS_TKGZ T
                      INNER JOIN CKTS_ZS_MDTKB S ON S.DJXH=T.DJXH AND S.CKTS_NO=T.BTKGZUUID AND S.KJTKBJ='Y'
                      INNER JOIN CKTS_LC_SEHZXX R ON R.DJXH=T.DJXH AND IFNULL(R.GZTKTZSBH, ORA_CONCAT(R.YWHZBID, R.XH))=S.CKTS_NO AND R.XHRQ_MD>CURRENT_TIMESTAMP
                      WHERE T.XHRQ_1>=LD_DEALDATA AND T.TZSLY='3' AND T.TZLX_DM='1' AND T.GZBZ='Y' AND T.ZFRQ_1 IS NULL
                        AND T.JE>0
                        AND NOT EXISTS (SELECT 1
                                          FROM CKTS_LC_SEHZXX Q
                                         WHERE Q.DJXH=T.DJXH
                                           AND IFNULL(Q.GZTKTZSBH, ORA_CONCAT(Q.YWHZBID, Q.XH))=S.CKTS_NO
                                           AND Q.XHRQ_MD=T.XHRQ_1);
  OPEN BJTS_CURSOR_023;
  BJTS_CURSOR_LOOP_023: LOOP
    SET BJTS_CURSOR_DONE_023 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_023 = TRUE;
      FETCH BJTS_CURSOR_023 INTO BJTS_CUR_TKXX_UUID_023, BJTS_CUR_TKXX_SEHZ_MDSE_023, BJTS_CUR_TKXX_GKBL_MDSE_023, BJTS_CUR_TKXX_XHRQ_1_023, BJTS_CUR_TKXX_MDTKSSSWJGDM_023;
    END;
    IF BJTS_CURSOR_DONE_023 THEN
      LEAVE BJTS_CURSOR_LOOP_023;
    END IF;
      BEGIN
        IF BJTS_CUR_TKXX_SEHZ_MDSE_023<=BJTS_CUR_TKXX_GKBL_MDSE_023 THEN
          UPDATE CKTS_LC_SEHZXX AS T
             SET GKBL_MDSE = BJTS_CUR_TKXX_GKBL_MDSE_023,
    XHRQ_MD = BJTS_CUR_TKXX_XHRQ_1_023,
    MDTKSSSWJGDM = BJTS_CUR_TKXX_MDTKSSSWJGDM_023
           WHERE T.UUID=BJTS_CUR_TKXX_UUID_023;
          COMMIT;
        ELSE
          INSERT INTO CKTS_LC_SEHZXX(UUID,LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                      SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                      GZTKTZSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                      SEHZ_MDTSE,SEHZ_ZZSTSE,SEHZ_XFSTSE,SEHZ_MDSE,
                      GKBL_MDTSE,GKBL_ZZSTSE,GKBL_XFSTSE,GKBL_MDSE)
               SELECT ORA_CONCAT(ORA_CONCAT('YANGUOPINGXTYW', DATE_FORMAT(CURRENT_TIMESTAMP, '%Y%m%d')), CAST(SEQ_NEXTVAL('SEQ_DEAL_TKGZ') AS CHAR)),
                      LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                      SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                      GZTKTZSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                      BJTS_CUR_TKXX_SEHZ_MDSE_023-BJTS_CUR_TKXX_GKBL_MDSE_023,0,0,BJTS_CUR_TKXX_SEHZ_MDSE_023-BJTS_CUR_TKXX_GKBL_MDSE_023,
                      0,0,0,0
                 FROM CKTS_LC_SEHZXX
                WHERE UUID=BJTS_CUR_TKXX_UUID_023;
          UPDATE CKTS_LC_SEHZXX AS T
             SET SEHZ_MDTSE = T.SEHZ_ZZSTSE + T.SEHZ_XFSTSE + BJTS_CUR_TKXX_GKBL_MDSE_023,
    SEHZ_MDSE = BJTS_CUR_TKXX_GKBL_MDSE_023,
    GKBL_MDSE = BJTS_CUR_TKXX_GKBL_MDSE_023,
    XHRQ_MD = BJTS_CUR_TKXX_XHRQ_1_023,
    MDTKSSSWJGDM = BJTS_CUR_TKXX_MDTKSSSWJGDM_023
           WHERE T.UUID=BJTS_CUR_TKXX_UUID_023;
          COMMIT;
        END IF;
      END;

  END LOOP BJTS_CURSOR_LOOP_023;
  CLOSE BJTS_CURSOR_023;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_MDSE(SEHZ_<>0)！');
      COMMIT;
    END IF;

    -- 根据收核回推至LD_DEALDATA增值税退库数据，更新税额核准表办理数
    -- KPRQ
    BEGIN
  DECLARE BJTS_CURSOR_DONE_022 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_022 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_KPRQ_022 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_THRQ_1_022 LONGTEXT;
  DECLARE BJTS_CURSOR_022 CURSOR FOR
SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))='SJQY' AND S.KPRQ>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTUUID AND T.XHRQ_TK>CURRENT_TIMESTAMP;
  OPEN BJTS_CURSOR_022;
  BJTS_CURSOR_LOOP_022: LOOP
    SET BJTS_CURSOR_DONE_022 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_022 = TRUE;
      FETCH BJTS_CURSOR_022 INTO BJTS_CUR_TKXX_UUID_022, BJTS_CUR_TKXX_KPRQ_022, BJTS_CUR_TKXX_THRQ_1_022;
    END;
    IF BJTS_CURSOR_DONE_022 THEN
      LEAVE BJTS_CURSOR_LOOP_022;
    END IF;
      BEGIN
        IF BJTS_CUR_TKXX_THRQ_1_022 IS NOT NULL THEN
          UPDATE CKTS_LC_SEHZXX AS T
             SET GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
    XHRQ_TK = BJTS_CUR_TKXX_THRQ_1_022,
    KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_022,T.SEHZRQ)
           WHERE T.UUID=BJTS_CUR_TKXX_UUID_022;
        ELSE
          UPDATE CKTS_LC_SEHZXX AS T
             SET KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_022,T.SEHZRQ)
           WHERE T.UUID=BJTS_CUR_TKXX_UUID_022;
        END IF;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_022;
  CLOSE BJTS_CURSOR_022;
END;
    -- THRQ_1
    BEGIN
  DECLARE BJTS_CURSOR_DONE_021 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_021 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_KPRQ_021 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_THRQ_1_021 LONGTEXT;
  DECLARE BJTS_CURSOR_021 CURSOR FOR
SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))='SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTUUID AND T.XHRQ_TK>CURRENT_TIMESTAMP;
  OPEN BJTS_CURSOR_021;
  BJTS_CURSOR_LOOP_021: LOOP
    SET BJTS_CURSOR_DONE_021 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_021 = TRUE;
      FETCH BJTS_CURSOR_021 INTO BJTS_CUR_TKXX_UUID_021, BJTS_CUR_TKXX_KPRQ_021, BJTS_CUR_TKXX_THRQ_1_021;
    END;
    IF BJTS_CURSOR_DONE_021 THEN
      LEAVE BJTS_CURSOR_LOOP_021;
    END IF;
      BEGIN
        UPDATE CKTS_LC_SEHZXX AS T
           SET GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
    XHRQ_TK = BJTS_CUR_TKXX_THRQ_1_021,
    KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_021,T.SEHZRQ)
         WHERE T.UUID=BJTS_CUR_TKXX_UUID_021;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_021;
  CLOSE BJTS_CURSOR_021;
END;
    -- KPRQ
    BEGIN
  DECLARE BJTS_CURSOR_DONE_020 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_020 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_KPRQ_020 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_THRQ_1_020 LONGTEXT;
  DECLARE BJTS_CURSOR_020 CURSOR FOR
SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))<>'SJQY' AND S.KPRQ>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTLYUUID AND T.XHRQ_TK>CURRENT_TIMESTAMP;
  OPEN BJTS_CURSOR_020;
  BJTS_CURSOR_LOOP_020: LOOP
    SET BJTS_CURSOR_DONE_020 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_020 = TRUE;
      FETCH BJTS_CURSOR_020 INTO BJTS_CUR_TKXX_UUID_020, BJTS_CUR_TKXX_KPRQ_020, BJTS_CUR_TKXX_THRQ_1_020;
    END;
    IF BJTS_CURSOR_DONE_020 THEN
      LEAVE BJTS_CURSOR_LOOP_020;
    END IF;
      BEGIN
        IF BJTS_CUR_TKXX_THRQ_1_020 IS NOT NULL THEN
          UPDATE CKTS_LC_SEHZXX AS T
             SET GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
    XHRQ_TK = BJTS_CUR_TKXX_THRQ_1_020,
    KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_020,T.SEHZRQ)
           WHERE T.UUID=BJTS_CUR_TKXX_UUID_020;
        ELSE
          UPDATE CKTS_LC_SEHZXX AS T
             SET KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_020,T.SEHZRQ)
           WHERE T.UUID=BJTS_CUR_TKXX_UUID_020;
        END IF;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_020;
  CLOSE BJTS_CURSOR_020;
END;
    -- THRQ_1
    BEGIN
  DECLARE BJTS_CURSOR_DONE_019 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_019 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_KPRQ_019 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_THRQ_1_019 LONGTEXT;
  DECLARE BJTS_CURSOR_019 CURSOR FOR
SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))<>'SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTLYUUID AND T.XHRQ_TK>CURRENT_TIMESTAMP;
  OPEN BJTS_CURSOR_019;
  BJTS_CURSOR_LOOP_019: LOOP
    SET BJTS_CURSOR_DONE_019 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_019 = TRUE;
      FETCH BJTS_CURSOR_019 INTO BJTS_CUR_TKXX_UUID_019, BJTS_CUR_TKXX_KPRQ_019, BJTS_CUR_TKXX_THRQ_1_019;
    END;
    IF BJTS_CURSOR_DONE_019 THEN
      LEAVE BJTS_CURSOR_LOOP_019;
    END IF;
      BEGIN
        UPDATE CKTS_LC_SEHZXX AS T
           SET GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
    XHRQ_TK = BJTS_CUR_TKXX_THRQ_1_019,
    KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_019,T.SEHZRQ)
         WHERE T.UUID=BJTS_CUR_TKXX_UUID_019;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_019;
  CLOSE BJTS_CURSOR_019;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_ZZSTSE(SEHZ_>0)！');
      COMMIT;
    END IF;
    -- 增值税审核数为负处理
    BEGIN
  DECLARE BJTS_CURSOR_DONE_018 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CURSOR_SKIP_018 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_018 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_DJXH_018 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_ZZSSSSRTHSBH_018 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_SEHZ_ZZSTSE_018 LONGTEXT;
  DECLARE BJTS_CURSOR_018 CURSOR FOR
SELECT T.UUID,T.DJXH,T.ZZSSSSRTHSBH,T.SEHZ_ZZSTSE FROM CKTS_LC_SEHZXX T
                      WHERE T.SEHZ_ZZSTSE<0 AND T.XHRQ_TK>CURRENT_TIMESTAMP AND T.ZZSSSSRTHSBH IS NOT NULL;
  OPEN BJTS_CURSOR_018;
  BJTS_CURSOR_LOOP_018: LOOP
    SET BJTS_CURSOR_DONE_018 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_018 = TRUE;
      FETCH BJTS_CURSOR_018 INTO BJTS_CUR_TKXX_UUID_018, BJTS_CUR_TKXX_DJXH_018, BJTS_CUR_TKXX_ZZSSSSRTHSBH_018, BJTS_CUR_TKXX_SEHZ_ZZSTSE_018;
    END;
    IF BJTS_CURSOR_DONE_018 THEN
      LEAVE BJTS_CURSOR_LOOP_018;
    END IF;
    SET BJTS_CURSOR_SKIP_018 = FALSE;
      BEGIN
        -- 检查是否正负对冲及对冲后剩余税额
        SELECT SUM(T.SEHZ_ZZSTSE),SUM(IFNULL(T.GKBL_ZZSTSE, 0))
          INTO LN_ZZS,SN_ZZS
          FROM CKTS_LC_SEHZXX T
         WHERE T.DJXH=BJTS_CUR_TKXX_DJXH_018 AND T.ZZSSSSRTHSBH=BJTS_CUR_TKXX_ZZSSSSRTHSBH_018;
        IF LN_ZZS=0 THEN
          -- 对冲后为0
          UPDATE CKTS_LC_SEHZXX AS T
             SET GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
    KPRQ = T.SEHZRQ,
    XHRQ_TK = T.SEHZRQ
           WHERE T.DJXH=BJTS_CUR_TKXX_DJXH_018 AND T.ZZSSSSRTHSBH=BJTS_CUR_TKXX_ZZSSSSRTHSBH_018;
          COMMIT;
        ELSEIF LN_ZZS<0 THEN
          -- 对冲后为负数，需要返纳，考虑用户分次返纳的情况
          BEGIN
  DECLARE BJTS_SQLCODE_023 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_023 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION, NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_023 = MYSQL_ERRNO, BJTS_SQLERRM_023 = MESSAGE_TEXT;
              SET BJTS_CURSOR_SKIP_018 = TRUE;

  END;
SELECT COUNT(1),SUM(S.SJJE),MAX(S.KJRQ),MAX(S.RKRQ)
              INTO LN_I, SY_ZZS, V_TSKP_DATE,V_TSTK_DATE
              FROM FG_CKTSFN_HXZG S
             WHERE S.DJXH=BJTS_CUR_TKXX_DJXH_018 AND S.YZPZXH_CKTS=BJTS_CUR_TKXX_ZZSSSSRTHSBH_018 AND S.RKRQ IS NOT NULL;
            IF LN_I>0 THEN
              -- 存在返纳入库记录的时候判断
              IF SY_ZZS+LN_ZZS=0 THEN
                -- 返纳数+税额核准数=0，表示对应退还书已全部返纳
                UPDATE CKTS_LC_SEHZXX AS T
                   SET GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
    KPRQ = V_TSKP_DATE,
    XHRQ_TK = V_TSTK_DATE
                 WHERE T.DJXH=BJTS_CUR_TKXX_DJXH_018 AND T.ZZSSSSRTHSBH=BJTS_CUR_TKXX_ZZSSSSRTHSBH_018
                   AND T.XHRQ_TK>CURRENT_TIMESTAMP;
                COMMIT;
              ELSEIF SY_ZZS+SN_ZZS+BJTS_CUR_TKXX_SEHZ_ZZSTSE_018>=0 THEN
                -- 返纳数+已办理数+当前未销号记录核准数>=0，表示对应未销号记录已全部返纳
                UPDATE CKTS_LC_SEHZXX AS T
                   SET GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
    KPRQ = V_TSKP_DATE,
    XHRQ_TK = V_TSTK_DATE
                 WHERE T.UUID=BJTS_CUR_TKXX_UUID_018;
                COMMIT;
              ELSEIF SY_ZZS+SN_ZZS>0 THEN
                -- 返纳数+已办理数>0，表示对应未销号记录可部分返纳，按（SY_ZZS+SN_ZZS）拆分已返纳部分
                INSERT INTO CKTS_LC_SEHZXX(UUID,LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            ZZSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            SEHZ_MDTSE,SEHZ_ZZSTSE,SEHZ_XFSTSE,SEHZ_MDSE,
                            GKBL_MDTSE,GKBL_ZZSTSE,GKBL_XFSTSE,GKBL_MDSE)
                     SELECT ORA_CONCAT(ORA_CONCAT('YANGUOPINGXTYW', DATE_FORMAT(CURRENT_TIMESTAMP, '%Y%m%d')), CAST(SEQ_NEXTVAL('SEQ_DEAL_TKGZ') AS CHAR)),
                            LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            ZZSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            (SY_ZZS+SN_ZZS)+BJTS_CUR_TKXX_SEHZ_ZZSTSE_018,(SY_ZZS+SN_ZZS)+BJTS_CUR_TKXX_SEHZ_ZZSTSE_018,0,0,
                            0,0,0,0
                       FROM CKTS_LC_SEHZXX
                      WHERE UUID=BJTS_CUR_TKXX_UUID_018;
                UPDATE CKTS_LC_SEHZXX AS T
                   SET SEHZ_MDTSE = 0 - (SY_ZZS+SN_ZZS) + T.SEHZ_XFSTSE + T.SEHZ_MDSE,
    SEHZ_ZZSTSE = 0 - (SY_ZZS+SN_ZZS),
    GKBL_ZZSTSE = 0 - (SY_ZZS+SN_ZZS),
    KPRQ = V_TSKP_DATE,
    XHRQ_TK = V_TSTK_DATE
                 WHERE T.UUID=BJTS_CUR_TKXX_UUID_018;
                COMMIT;
              END IF;
            END IF;
          END;
        END IF;
      END;

    IF BJTS_CURSOR_SKIP_018 THEN
      ITERATE BJTS_CURSOR_LOOP_018;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_018;
  CLOSE BJTS_CURSOR_018;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_ZZSTSE(SEHZ_<0)(对冲/返纳)！');
      COMMIT;
    END IF;

    -- 根据收核回推两天消费税退库数据，更新税额核准表办理数
    BEGIN
  DECLARE BJTS_CURSOR_DONE_017 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_017 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_KPRQ_017 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_THRQ_1_017 LONGTEXT;
  DECLARE BJTS_CURSOR_017 CURSOR FOR
SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))='SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.XFSSSSRTHSBH=S.YDTUUID AND T.XHRQ_XFS>CURRENT_TIMESTAMP;
  OPEN BJTS_CURSOR_017;
  BJTS_CURSOR_LOOP_017: LOOP
    SET BJTS_CURSOR_DONE_017 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_017 = TRUE;
      FETCH BJTS_CURSOR_017 INTO BJTS_CUR_TKXX_UUID_017, BJTS_CUR_TKXX_KPRQ_017, BJTS_CUR_TKXX_THRQ_1_017;
    END;
    IF BJTS_CURSOR_DONE_017 THEN
      LEAVE BJTS_CURSOR_LOOP_017;
    END IF;
      BEGIN
        UPDATE CKTS_LC_SEHZXX AS T
           SET GKBL_XFSTSE=T.SEHZ_XFSTSE,
    XHRQ_XFS = BJTS_CUR_TKXX_THRQ_1_017,
    KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_017,T.SEHZRQ)
         WHERE T.UUID=BJTS_CUR_TKXX_UUID_017;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_017;
  CLOSE BJTS_CURSOR_017;
END;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_016 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_016 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_KPRQ_016 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_THRQ_1_016 LONGTEXT;
  DECLARE BJTS_CURSOR_016 CURSOR FOR
SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))<>'SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.XFSSSSRTHSBH=S.YDTLYUUID AND T.XHRQ_XFS>CURRENT_TIMESTAMP;
  OPEN BJTS_CURSOR_016;
  BJTS_CURSOR_LOOP_016: LOOP
    SET BJTS_CURSOR_DONE_016 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_016 = TRUE;
      FETCH BJTS_CURSOR_016 INTO BJTS_CUR_TKXX_UUID_016, BJTS_CUR_TKXX_KPRQ_016, BJTS_CUR_TKXX_THRQ_1_016;
    END;
    IF BJTS_CURSOR_DONE_016 THEN
      LEAVE BJTS_CURSOR_LOOP_016;
    END IF;
      BEGIN
        UPDATE CKTS_LC_SEHZXX AS T
           SET GKBL_XFSTSE=T.SEHZ_XFSTSE,
    XHRQ_XFS = BJTS_CUR_TKXX_THRQ_1_016,
    KPRQ = GREATEST(BJTS_CUR_TKXX_KPRQ_016,T.SEHZRQ)
         WHERE T.UUID=BJTS_CUR_TKXX_UUID_016;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_016;
  CLOSE BJTS_CURSOR_016;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_XFSTSE(SEHZ_<>0)！');
      COMMIT;
    END IF;
    -- 消费税审核数为负处理
    BEGIN
  DECLARE BJTS_CURSOR_DONE_015 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CURSOR_SKIP_015 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_UUID_015 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_DJXH_015 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_XFSSSSRTHSBH_015 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_SEHZ_XFSTSE_015 LONGTEXT;
  DECLARE BJTS_CURSOR_015 CURSOR FOR
SELECT T.UUID,T.DJXH,T.XFSSSSRTHSBH,T.SEHZ_XFSTSE FROM CKTS_LC_SEHZXX T
                     WHERE T.SEHZ_XFSTSE<0 AND T.XHRQ_XFS>CURRENT_TIMESTAMP AND T.XFSSSSRTHSBH IS NOT NULL;
  OPEN BJTS_CURSOR_015;
  BJTS_CURSOR_LOOP_015: LOOP
    SET BJTS_CURSOR_DONE_015 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_015 = TRUE;
      FETCH BJTS_CURSOR_015 INTO BJTS_CUR_TKXX_UUID_015, BJTS_CUR_TKXX_DJXH_015, BJTS_CUR_TKXX_XFSSSSRTHSBH_015, BJTS_CUR_TKXX_SEHZ_XFSTSE_015;
    END;
    IF BJTS_CURSOR_DONE_015 THEN
      LEAVE BJTS_CURSOR_LOOP_015;
    END IF;
    SET BJTS_CURSOR_SKIP_015 = FALSE;
      BEGIN
        -- 检查是否正负对冲及对冲后剩余税额
        SELECT SUM(T.SEHZ_XFSTSE),SUM(IFNULL(T.GKBL_XFSTSE, 0))
          INTO LN_XFS,SN_XFS
          FROM CKTS_LC_SEHZXX T
         WHERE T.DJXH=BJTS_CUR_TKXX_DJXH_015 AND T.XFSSSSRTHSBH=BJTS_CUR_TKXX_XFSSSSRTHSBH_015;
        IF LN_XFS=0 THEN
          -- 对冲后为0
          UPDATE CKTS_LC_SEHZXX AS T
             SET GKBL_XFSTSE=T.SEHZ_XFSTSE,
    KPRQ = T.SEHZRQ,
    XHRQ_XFS = T.SEHZRQ
           WHERE T.DJXH=BJTS_CUR_TKXX_DJXH_015 AND T.XFSSSSRTHSBH=BJTS_CUR_TKXX_XFSSSSRTHSBH_015;
          COMMIT;
        ELSEIF LN_XFS<0 THEN
          -- 对冲后为负数，需要返纳，考虑用户分次返纳的情况
          BEGIN
  DECLARE BJTS_SQLCODE_022 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_022 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION, NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_022 = MYSQL_ERRNO, BJTS_SQLERRM_022 = MESSAGE_TEXT;
              SET BJTS_CURSOR_SKIP_015 = TRUE;

  END;
SELECT COUNT(1),SUM(S.SJJE),MAX(S.KJRQ),MAX(S.RKRQ)
              INTO LN_I, SY_XFS, V_TSKP_DATE,V_TSTK_DATE
              FROM FG_CKTSFN_HXZG S
             WHERE S.DJXH=BJTS_CUR_TKXX_DJXH_015 AND S.YZPZXH_CKTS=BJTS_CUR_TKXX_XFSSSSRTHSBH_015 AND S.RKRQ IS NOT NULL;
            IF LN_I>0 THEN
              -- 存在返纳入库记录的时候判断
              IF SY_XFS+LN_XFS=0 THEN
                -- 返纳数+税额核准数=0，表示对应退还书已全部返纳
                UPDATE CKTS_LC_SEHZXX AS T
                   SET GKBL_XFSTSE=T.SEHZ_XFSTSE,
    KPRQ = V_TSKP_DATE,
    XHRQ_XFS = V_TSTK_DATE
                 WHERE T.DJXH=BJTS_CUR_TKXX_DJXH_015 AND T.XFSSSSRTHSBH=BJTS_CUR_TKXX_XFSSSSRTHSBH_015
                   AND T.XHRQ_XFS>CURRENT_TIMESTAMP;
                COMMIT;
              ELSEIF SY_XFS+SN_XFS+BJTS_CUR_TKXX_SEHZ_XFSTSE_015>=0 THEN
                -- 返纳数+已办理数+当前未销号记录核准数>=0，表示对应未销号记录已全部返纳
                UPDATE CKTS_LC_SEHZXX AS T
                   SET GKBL_XFSTSE=T.SEHZ_XFSTSE,
    KPRQ = V_TSKP_DATE,
    XHRQ_XFS = V_TSTK_DATE
                 WHERE T.UUID=BJTS_CUR_TKXX_UUID_015;
                COMMIT;
              ELSEIF SY_XFS+SN_XFS>0 THEN
                -- 返纳数+已办理数>0，表示对应未销号记录可部分返纳，按（SY_XFS+SN_XFS）拆分已返纳部分
                INSERT INTO CKTS_LC_SEHZXX(UUID,LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            XFSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            SEHZ_MDTSE,SEHZ_ZZSTSE,SEHZ_XFSTSE,SEHZ_MDSE,
                            GKBL_MDTSE,GKBL_ZZSTSE,GKBL_XFSTSE,GKBL_MDSE)
                     SELECT ORA_CONCAT(ORA_CONCAT('YANGUOPINGXTYW', DATE_FORMAT(CURRENT_TIMESTAMP, '%Y%m%d')), CAST(SEQ_NEXTVAL('SEQ_DEAL_TKGZ') AS CHAR)),
                            LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            XFSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            (SY_XFS+SN_XFS)+BJTS_CUR_TKXX_SEHZ_XFSTSE_015,0,(SY_XFS+SN_XFS)+BJTS_CUR_TKXX_SEHZ_XFSTSE_015,0,
                            0,0,0,0
                       FROM CKTS_LC_SEHZXX
                      WHERE UUID=BJTS_CUR_TKXX_UUID_015;
                UPDATE CKTS_LC_SEHZXX AS T
                   SET SEHZ_MDTSE = 0 - (SY_XFS+SN_XFS) + T.SEHZ_ZZSTSE + T.SEHZ_MDSE,
    SEHZ_XFSTSE = 0 - (SY_XFS+SN_XFS),
    GKBL_XFSTSE = 0 - (SY_XFS+SN_XFS),
    KPRQ = V_TSKP_DATE,
    XHRQ_XFS = V_TSTK_DATE
                 WHERE T.UUID=BJTS_CUR_TKXX_UUID_015;
                COMMIT;
              END IF;
            END IF;
          END;
        END IF;
      END;

    IF BJTS_CURSOR_SKIP_015 THEN
      ITERATE BJTS_CURSOR_LOOP_015;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_015;
  CLOSE BJTS_CURSOR_015;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_XFSTSE(SEHZ_<0)(对冲/返纳)！');
      COMMIT;
    END IF;

    UPDATE CKTS_LC_SEHZXX AS T
       SET GKBL_MDTSE=IFNULL(T.GKBL_ZZSTSE, 0)+IFNULL(T.GKBL_XFSTSE, 0)+IFNULL(T.GKBL_MDSE, 0)
     WHERE GREATEST(T.XHRQ_TK,T.XHRQ_MD,T.XHRQ_XFS)>=LD_DEALDATA;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_MDTSE=GKBL_ZZSTSE+GKBL_XFSTSE+GKBL_MDSE！');
      COMMIT;
    END IF;

    -- 部分税局征管与退税需要调整对应关系
    UPDATE CKTS_LC_SEHZXX AS T SET CKTMSJHSSSWJGDM='13311930000' WHERE T.CKTMSJHSSSWJGDM='13311910000';
    COMMIT;
    UPDATE CKTS_LC_SEHZXX AS T SET MDTKSSSWJGDM='13311930000' WHERE T.MDTKSSSWJGDM='13311910000';
    COMMIT;
    UPDATE FG_CKTSFN_HXZG AS T SET SKSSSWJG_DM='13311930000' WHERE T.SKSSSWJG_DM='13311910000';
    COMMIT;
    UPDATE CKTS_LC_SEHZXX AS T SET CKTMSJHSSSWJGDM='13307030000' WHERE T.CKTMSJHSSSWJGDM='13307920000';
    COMMIT;
    UPDATE CKTS_LC_SEHZXX AS T SET MDTKSSSWJGDM='13307030000' WHERE T.MDTKSSSWJGDM='13307920000';
    COMMIT;
    UPDATE FG_CKTSFN_HXZG AS T SET SKSSSWJG_DM='13307030000' WHERE T.SKSSSWJG_DM='13307920000';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX（丽水二分局, 金华金义局）！');
      COMMIT;
    END IF;

    -- 设置上年出口占比
    UPDATE CKTS_LC_SEHZXX AS T
       SET SSQ='200001'
     WHERE T.SSQ IS NULL;
    COMMIT;
    -- 非免抵退业务，按所属期确定上年与本年（非0即1）
    UPDATE CKTS_LC_SEHZXX AS T
       SET SNCKZB=(CASE WHEN T.SSQ<(ORA_CONCAT(DATE_FORMAT(T.SEHZRQ, '%Y'), '01')) THEN 1 ELSE 0 END)
     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM<>'A0305001';
    COMMIT;
    -- 免抵退上年申报数据（1）
    UPDATE CKTS_LC_SEHZXX AS T
       SET SNCKZB=1
     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM='A0305001' AND T.SSQ<(ORA_CONCAT(DATE_FORMAT(T.SEHZRQ, '%Y'), '01'));
    COMMIT;
    -- 免抵退本年服务贸易（0）
    UPDATE CKTS_LC_SEHZXX AS T
       SET SNCKZB=0
     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM='A0305001' AND T.SSQ>=(ORA_CONCAT(DATE_FORMAT(T.SEHZRQ, '%Y'), '01')) AND T.CKTMSHWYSFWLX_DM='2';
    COMMIT;
    -- 免抵退本年申报业务，区分
    BEGIN
  DECLARE BJTS_CURSOR_DONE_014 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MDT_UUID_014 LONGTEXT;
  DECLARE BJTS_CUR_MDT_LCSLID_FS_014 LONGTEXT;
  DECLARE BJTS_CUR_MDT_SEHZRQ_014 LONGTEXT;
  DECLARE BJTS_CURSOR_014 CURSOR FOR
SELECT T.UUID, T.LCSLID_FS, T.SEHZRQ FROM CKTS_LC_SEHZXX T
                     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM='A0305001' AND T.SSQ>=(ORA_CONCAT(DATE_FORMAT(T.SEHZRQ, '%Y'), '01')) AND T.CKTMSHWYSFWLX_DM='1';
  OPEN BJTS_CURSOR_014;
  BJTS_CURSOR_LOOP_014: LOOP
    SET BJTS_CURSOR_DONE_014 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_014 = TRUE;
      FETCH BJTS_CURSOR_014 INTO BJTS_CUR_MDT_UUID_014, BJTS_CUR_MDT_LCSLID_FS_014, BJTS_CUR_MDT_SEHZRQ_014;
    END;
    IF BJTS_CURSOR_DONE_014 THEN
      LEAVE BJTS_CURSOR_LOOP_014;
    END IF;
      BEGIN
        SELECT IFNULL(SUM(A.MDTSE), 0)
          INTO LN_ALLCK
          FROM CKTS_SB_MDT_CKMX A
         WHERE A.LCSLID_FS=BJTS_CUR_MDT_LCSLID_FS_014;
        SELECT IFNULL(SUM(A.MDTSE), 0)
          INTO LN_SNCK
          FROM CKTS_SB_MDT_CKMX A
         WHERE A.LCSLID_FS=BJTS_CUR_MDT_LCSLID_FS_014
           AND A.CKRQ_1<MAKEDATE(YEAR(BJTS_CUR_MDT_SEHZRQ_014), 1);
        UPDATE CKTS_LC_SEHZXX AS T
           SET SNCKZB=(CASE WHEN LN_SNCK<=0 THEN 0 ELSE (CASE WHEN LN_ALLCK<=LN_SNCK THEN 1 ELSE LN_SNCK / LN_ALLCK END) END)
         WHERE T.UUID=BJTS_CUR_MDT_UUID_014;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_014;
  CLOSE BJTS_CURSOR_014;
END;
    -- 以前年度税额核准，结转到本年未结束流程
    UPDATE CKTS_LC_SEHZXX AS T
       SET SNCKZB=1
     WHERE T.SNCKZB<>1 AND T.SEHZRQ<MAKEDATE(YEAR(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -1 MONTH)), 1) AND GREATEST(T.XHRQ_TK,T.XHRQ_MD,T.XHRQ_XFS)>=MAKEDATE(YEAR(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -1 MONTH)), 1);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX(SNCKZB)！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SEHZXX数据,处理成功！');
    COMMIT;
  END;

  -- CKTS_LC_YWHZXX数据处理（FSRQ、YWHZWCBZ、SEHZWCBZ、CKQYGLLB_DM、WZHBZ、LCTJJC）
  BEGIN
  DECLARE BJTS_SQLCODE_020 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_020 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_020 = MYSQL_ERRNO, BJTS_SQLERRM_020 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_020;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_YWHZXX数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE CKTS_LC_YWHZXX AS T
       SET SSQ='200001'
     WHERE T.SSQ IS NULL;
    COMMIT;
    -- YWHZWCBZ，用于省局报表统计可调库资源
    UPDATE CKTS_LC_YWHZXX AS T
       SET YWHZWCBZ='N'
     WHERE T.YWHZWCBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.YWHZWCBZ！');
      COMMIT;
    END IF;
    -- FSRQ，用于更新明细表复审日期，从而统计省局分类报表
    UPDATE CKTS_LC_YWHZXX AS T
       SET FSRQ=T.YWHZRQ
     WHERE T.YWHZWCBZ='Y' AND T.FSRQ>T.YWHZRQ;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.FSRQ！');
      COMMIT;
    END IF;
    -- SEHZWCBZ，用于后续结束流程
    UPDATE CKTS_LC_YWHZXX AS T
       SET SEHZWCBZ='N'
     WHERE T.SEHZWCBZ IS NULL;
    COMMIT;
    UPDATE CKTS_LC_YWHZXX AS T
       SET SEHZWCBZ='Y'
     WHERE T.FS_MDTSE=0 AND T.YWHZWCBZ='Y' AND T.SEHZWCBZ='N';
    COMMIT;

    BEGIN
  DECLARE BJTS_CURSOR_DONE_013 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TKXX_YWHZBUUID_013 LONGTEXT;
  DECLARE BJTS_CUR_TKXX_FS_MDTSE_013 LONGTEXT;
  DECLARE BJTS_CURSOR_013 CURSOR FOR
SELECT T.YWHZBUUID, T.FS_MDTSE FROM CKTS_LC_YWHZXX T WHERE T.SEHZWCBZ='N' AND EXISTS (SELECT 1 FROM CKTS_LC_SEHZXX S WHERE S.YWHZBUUID=T.YWHZBUUID);
  OPEN BJTS_CURSOR_013;
  BJTS_CURSOR_LOOP_013: LOOP
    SET BJTS_CURSOR_DONE_013 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_013 = TRUE;
      FETCH BJTS_CURSOR_013 INTO BJTS_CUR_TKXX_YWHZBUUID_013, BJTS_CUR_TKXX_FS_MDTSE_013;
    END;
    IF BJTS_CURSOR_DONE_013 THEN
      LEAVE BJTS_CURSOR_LOOP_013;
    END IF;
      BEGIN
        SELECT SUM(A.GKBL_MDTSE+A.BYHZ_MDTSE)
          INTO LN_MDTSE
          FROM CKTS_LC_SEHZXX A
         WHERE A.YWHZBUUID=BJTS_CUR_TKXX_YWHZBUUID_013;
        IF LN_MDTSE=BJTS_CUR_TKXX_FS_MDTSE_013 THEN
          UPDATE CKTS_LC_YWHZXX AS T
             SET SEHZWCBZ='Y'
           WHERE T.YWHZBUUID=BJTS_CUR_TKXX_YWHZBUUID_013;
          COMMIT;
        END IF;
      END;

  END LOOP BJTS_CURSOR_LOOP_013;
  CLOSE BJTS_CURSOR_013;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.SEHZWCBZ！');
      COMMIT;
    END IF;
    -- 部分单机版老数据无流程信息，不处理，仅处理有流程信息的数据
    -- 根据审核信息设置分类管理等级
    UPDATE CKTS_LC_YWHZXX AS T
       SET CKQYGLLB_DM=(SELECT A.CKQYGLLB_DM
                            FROM CKTS_LC_SHXX A
                           WHERE A.LCSLID_FS=T.LCSLID_FS
                             AND 1=1
LIMIT 1)
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    -- 无审核信息数据设置分类管理等级
    UPDATE CKTS_LC_YWHZXX AS T
       SET CKQYGLLB_DM=(SELECT KZXX
                            FROM GS_DJ_CKTMSDAB A, GS_DJ_CKTMSDAB_KZ B
                           WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=CAST(T.DJXH AS CHAR) AND B.KZLX='FLGLCD' AND T.FSRQ BETWEEN B.ST_DATE AND B.END_DATE
                             AND 1=1
LIMIT 1)
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    -- 无审核信息数据设置分类管理等级，复审日期未实行分类管理政策，按当前
    UPDATE CKTS_LC_YWHZXX AS T
       SET CKQYGLLB_DM=(SELECT FLGLCD
                            FROM GLXT_BB_SHXT_DJXX A
                           WHERE A.DJXH_JS=T.DJXH
                             AND 1=1
LIMIT 1)
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    UPDATE CKTS_LC_YWHZXX AS T
       SET CKQYGLLB_DM='M'
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.CKQYGLLB_DM！');
      COMMIT;
    END IF;

    -- 根据审核信息设置无纸化标志
    UPDATE CKTS_LC_YWHZXX AS T
       SET WZHBZ=(SELECT A.WZHBZ
                      FROM CKTS_LC_SHXX A
                     WHERE A.LCSLID_FS=T.LCSLID_FS
                       AND 1=1
LIMIT 1)
     WHERE T.LCSLID_FS IS NOT NULL AND T.WZHBZ IS NULL;
    COMMIT;
    -- 无审核信息数据设置无纸化标志
    UPDATE CKTS_LC_YWHZXX AS T
       SET WZHBZ='Y'
     WHERE T.WZHBZ IS NULL
       AND EXISTS (SELECT 1
                     FROM GS_DJ_CKTMSDAB A, GS_DJ_CKTMSDAB_KZ B
                    WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=CAST(T.DJXH AS CHAR) AND B.KZLX='WZHQY'
                      AND ((T.FSRQ BETWEEN B.ST_DATE AND B.END_DATE) OR (DATE(CURRENT_TIMESTAMP) BETWEEN B.ST_DATE AND B.END_DATE)));
    COMMIT;
    UPDATE CKTS_LC_YWHZXX AS T
       SET WZHBZ='N'
     WHERE T.WZHBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.WZHBZ！');
      COMMIT;
    END IF;

    -- 根据审核信息设置LCTJJC
    BEGIN
  DECLARE BJTS_CURSOR_DONE_012 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_HZXX_YWHZBUUID_012 LONGTEXT;
  DECLARE BJTS_CUR_HZXX_CKTMSHWYSFWLX_DM_012 LONGTEXT;
  DECLARE BJTS_CUR_HZXX_LCTJJC_012 LONGTEXT;
  DECLARE BJTS_CURSOR_012 CURSOR FOR
SELECT T.YWHZBUUID,T.CKTMSHWYSFWLX_DM,MAX(S.LCTJJC) AS LCTJJC
                       FROM CKTS_LC_YWHZXX T
                      INNER JOIN CKTS_LC_SHXX S ON S.LCSLID_FS=T.LCSLID_FS
                      WHERE T.LCSLID_FS IS NOT NULL AND T.LCTJJC='00'
                      GROUP BY T.YWHZBUUID,T.CKTMSHWYSFWLX_DM;
  OPEN BJTS_CURSOR_012;
  BJTS_CURSOR_LOOP_012: LOOP
    SET BJTS_CURSOR_DONE_012 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_012 = TRUE;
      FETCH BJTS_CURSOR_012 INTO BJTS_CUR_HZXX_YWHZBUUID_012, BJTS_CUR_HZXX_CKTMSHWYSFWLX_DM_012, BJTS_CUR_HZXX_LCTJJC_012;
    END;
    IF BJTS_CURSOR_DONE_012 THEN
      LEAVE BJTS_CURSOR_LOOP_012;
    END IF;
      UPDATE CKTS_LC_YWHZXX AS A
         SET LCTJJC=(CASE WHEN (BJTS_CUR_HZXX_LCTJJC_012 IN ('72','71','70','30','23','22','21','10')) OR (BJTS_CUR_HZXX_CKTMSHWYSFWLX_DM_012='2') THEN BJTS_CUR_HZXX_LCTJJC_012
                            ELSE (CASE WHEN BJTS_CUR_HZXX_LCTJJC_012 IN ('63','53','43') THEN '23'
                                       WHEN BJTS_CUR_HZXX_LCTJJC_012 IN ('62','52','42') THEN '22'
                                       WHEN BJTS_CUR_HZXX_LCTJJC_012 IN ('61','51','41') THEN '21'
                                       WHEN BJTS_CUR_HZXX_LCTJJC_012 IN ('50','40') THEN '10'
                                       ELSE '00'
                                 END)
                      END)
       WHERE A.YWHZBUUID=BJTS_CUR_HZXX_YWHZBUUID_012;
      COMMIT;

  END LOOP BJTS_CURSOR_LOOP_012;
  CLOSE BJTS_CURSOR_012;
END;

    -- 解除暂不办理退税（免退税）
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='10'
     WHERE T.LCTJJC='00'
       AND T.SBYWB_DM='LCSXA082038001';
    COMMIT;
    -- 解除暂不办理退税（周边）
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='30'
     WHERE T.LCTJJC='00'
       AND T.SBYWB_DM='LCSXA082039001';
    COMMIT;
    -- 解除暂不办理退税（代办退税）
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='72'
     WHERE T.LCTJJC='00'
       AND T.SBYWB_DM='LCSXA082040001';
    COMMIT;
    -- 离境退税
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='30',
    SBYWB_DM='LCSXA082042001'
     WHERE T.LCTJJC='00'
       AND T.TBYY_DM='470';
    COMMIT;
    -- 外商投资企业
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='23'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='1' AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    -- 委托出口企业
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='22'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='1' AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    -- 内资生产企业
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='21'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='1');
    COMMIT;
    -- 外贸企业
    UPDATE CKTS_LC_YWHZXX AS T
       SET LCTJJC='10'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='2');
    COMMIT;

    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.LCTJJC！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_YWHZXX数据,处理成功！');
    COMMIT;
  END;

  -- CKTS_LC_SEHZXX数据处理（设置分类管理等级、无纸化标志、所属期、复审lcslid及统计级次）
  BEGIN
  DECLARE BJTS_SQLCODE_019 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_019 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_019 = MYSQL_ERRNO, BJTS_SQLERRM_019 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_019;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SEHZXX(设置分类管理等级、无纸化标志、所属期、复审lcslid及统计级次),处理失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE CKTS_LC_SEHZXX AS T
       SET SBYWB_DM = (SELECT A.SBYWB_DM
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    SSQ = (SELECT A.SSQ
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    SBPC = (SELECT A.SBPC
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    CKQYGLLB_DM = (SELECT A.CKQYGLLB_DM
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    WZHBZ = (SELECT A.WZHBZ
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    LCTJJC = (SELECT A.LCTJJC
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    CKTMSHWYSFWLX_DM = (SELECT A.CKTMSHWYSFWLX_DM
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1)
     WHERE T.LCTJJC='00';
    COMMIT;

    UPDATE CKTS_LC_SEHZXX AS T
       SET SBYWB_DM = (SELECT A.SBYWB_DM
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    SSQ = (SELECT A.SSQ
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    SBPC = (SELECT A.SBPC
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    CKQYGLLB_DM = (SELECT A.CKQYGLLB_DM
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    WZHBZ = (SELECT A.WZHBZ
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    LCTJJC = (SELECT A.LCTJJC
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1),
    CKTMSHWYSFWLX_DM = (SELECT A.CKTMSHWYSFWLX_DM
FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND 1=1
LIMIT 1)
     WHERE T.SBYWB_DM IS NULL;
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SEHZXX(设置分类管理等级、无纸化标志、所属期、复审lcslid及统计级次),处理成功！');
  END;

  -- CKTS_LC_SHXX数据处理（SB_、ZH_、BY_、ZY_、BYBL_、SNBL_、SYBL_）
  BEGIN
  DECLARE BJTS_SQLCODE_018 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_018 TEXT DEFAULT '';
    -- 免抵退业务审核信息

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_018 = MYSQL_ERRNO, BJTS_SQLERRM_018 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_018;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SHXX数据处理（SB_、ZH_、BY_、ZY_、SNBL_、SYBL_）处理失败！', LC_SBYY);
      COMMIT;

  END;
BEGIN
  DECLARE BJTS_CURSOR_DONE_011 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SHXX_UUID_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_LCSLID_SB_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_LCSLID_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_LCSLID_FS_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SJTB_BZ_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_MDTSE_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_ZZSTSE_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_XFSTSE_011 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_MDSE_011 LONGTEXT;
  DECLARE BJTS_CURSOR_011 CURSOR FOR
SELECT T.UUID,T.LCSLID_SB,T.LCSLID,T.LCSLID_FS,T.SJTB_BZ,IFNULL(S.SB_MDTSE, 0) AS SB_MDTSE,S.SB_ZZSTSE,S.SB_XFSTSE,S.SB_MDSE
                       FROM CKTS_LC_SHXX T
                      INNER JOIN CKTS_LC_SBXX S ON S.LCSLID_SB=T.LCSLID_SB
                      WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA);
  OPEN BJTS_CURSOR_011;
  BJTS_CURSOR_LOOP_011: LOOP
    SET BJTS_CURSOR_DONE_011 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_011 = TRUE;
      FETCH BJTS_CURSOR_011 INTO BJTS_CUR_SHXX_UUID_011, BJTS_CUR_SHXX_LCSLID_SB_011, BJTS_CUR_SHXX_LCSLID_011, BJTS_CUR_SHXX_LCSLID_FS_011, BJTS_CUR_SHXX_SJTB_BZ_011, BJTS_CUR_SHXX_SB_MDTSE_011, BJTS_CUR_SHXX_SB_ZZSTSE_011, BJTS_CUR_SHXX_SB_XFSTSE_011, BJTS_CUR_SHXX_SB_MDSE_011;
    END;
    IF BJTS_CURSOR_DONE_011 THEN
      LEAVE BJTS_CURSOR_LOOP_011;
    END IF;
      BEGIN
        IF (BJTS_CUR_SHXX_SJTB_BZ_011='9') AND (BJTS_CUR_SHXX_LCSLID_011<>BJTS_CUR_SHXX_LCSLID_SB_011) AND (TRIM(BJTS_CUR_SHXX_LCSLID_FS_011) IS NOT NULL) THEN
          UPDATE CKTS_LC_SHXX AS R
             SET FFBZ = (SELECT S.FFBZ
FROM CKTS_LC_SHXX S
                                            WHERE S.LCSLID_SB=BJTS_CUR_SHXX_LCSLID_FS_011
                                              AND S.LCSLID=BJTS_CUR_SHXX_LCSLID_FS_011
                                              AND 1=1
LIMIT 1),
    FFR_DM = (SELECT S.FFR_DM
FROM CKTS_LC_SHXX S
                                            WHERE S.LCSLID_SB=BJTS_CUR_SHXX_LCSLID_FS_011
                                              AND S.LCSLID=BJTS_CUR_SHXX_LCSLID_FS_011
                                              AND 1=1
LIMIT 1),
    FFRQ = (SELECT S.FFRQ
FROM CKTS_LC_SHXX S
                                            WHERE S.LCSLID_SB=BJTS_CUR_SHXX_LCSLID_FS_011
                                              AND S.LCSLID=BJTS_CUR_SHXX_LCSLID_FS_011
                                              AND 1=1
LIMIT 1)
           WHERE R.UUID=BJTS_CUR_SHXX_UUID_011;
          COMMIT;
        END IF;

        SELECT IFNULL(SUM(TT.YSFWYYEMY), 0), IFNULL(SUM(TT.YSFWYYERMB), 0), IFNULL(SUM(TT.MDTSE), 0), IFNULL(SUM(CASE WHEN TT.BYBLBZ='Y' THEN TT.MDTSE ELSE 0 END), 0)
          INTO LN_MYLAJ, LN_RMBLAJ, LN_MDTSE, LN_BYBL_MDTSE
          FROM (SELECT A.YSFWYYEMY,A.YSFWYYERMB,A.MDTSE,A.BYBLBZ FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID=BJTS_CUR_SHXX_LCSLID_011
                 UNION ALL
                SELECT B.YSFWYYEMY,B.YSFWYYERMB,B.MDTSE,B.BYBLBZ FROM CKTS_SB_MDT_YFSJ B WHERE B.LCSLID=BJTS_CUR_SHXX_LCSLID_011
                 UNION ALL
                SELECT C.MYLAJ AS YSFWYYEMY,C.RMBLAJ AS YSFWYYERMB,C.MDTSE,C.BYBLBZ FROM CKTS_SB_MDT_CKMX C WHERE C.LCSLID=BJTS_CUR_SHXX_LCSLID_011) TT;
        IF BJTS_CUR_SHXX_SB_MDTSE_011=0 THEN
          UPDATE CKTS_LC_SHXX AS A
             SET SB_XSEMY=LN_MYLAJ,
    SB_XSERMB=LN_RMBLAJ,
    SB_MDTSE=0,
    SB_ZZSTSE=0,
    SB_XFSTSE=0,
    SB_MDSE=0,
    BYBL_MDTSE=0,
    BYBL_ZZSTSE=0,
    BYBL_XFSTSE=0,
    BYBL_MDSE=0
           WHERE A.UUID=BJTS_CUR_SHXX_UUID_011;
        ELSE
          UPDATE CKTS_LC_SHXX AS A
             SET SB_XSEMY=LN_MYLAJ,
    SB_XSERMB=LN_RMBLAJ,
    SB_MDTSE =LN_MDTSE,
    SB_ZZSTSE=LN_MDTSE * BJTS_CUR_SHXX_SB_ZZSTSE_011 / BJTS_CUR_SHXX_SB_MDTSE_011,
    SB_XFSTSE=LN_MDTSE * BJTS_CUR_SHXX_SB_XFSTSE_011 / BJTS_CUR_SHXX_SB_MDTSE_011,
    SB_MDSE  =LN_MDTSE * BJTS_CUR_SHXX_SB_MDSE_011   / BJTS_CUR_SHXX_SB_MDTSE_011,
    BYBL_MDTSE =LN_BYBL_MDTSE,
    BYBL_ZZSTSE=LN_BYBL_MDTSE * BJTS_CUR_SHXX_SB_ZZSTSE_011 / BJTS_CUR_SHXX_SB_MDTSE_011,
    BYBL_XFSTSE=LN_BYBL_MDTSE * BJTS_CUR_SHXX_SB_XFSTSE_011 / BJTS_CUR_SHXX_SB_MDTSE_011,
    BYBL_MDSE  =LN_BYBL_MDTSE * BJTS_CUR_SHXX_SB_MDSE_011   / BJTS_CUR_SHXX_SB_MDTSE_011
           WHERE A.UUID=BJTS_CUR_SHXX_UUID_011;
        END IF;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_011;
  CLOSE BJTS_CURSOR_011;
END;
    UPDATE CKTS_LC_SHXX AS T
       SET SB_MDTSE=T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE
     WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL AND T.SB_MDTSE<>T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(免抵退业务审核信息SB_)！');
      COMMIT;
    END IF;

    BEGIN
  DECLARE BJTS_CURSOR_DONE_010 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SHXX_UUID_010 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_LCSLID_010 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_MDTSE_010 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_ZZSTSE_010 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_XFSTSE_010 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SB_MDSE_010 LONGTEXT;
  DECLARE BJTS_CURSOR_010 CURSOR FOR
SELECT T.UUID,T.LCSLID,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE
                       FROM CKTS_LC_SHXX T
                      WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
                        AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID_FS);
  OPEN BJTS_CURSOR_010;
  BJTS_CURSOR_LOOP_010: LOOP
    SET BJTS_CURSOR_DONE_010 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_010 = TRUE;
      FETCH BJTS_CURSOR_010 INTO BJTS_CUR_SHXX_UUID_010, BJTS_CUR_SHXX_LCSLID_010, BJTS_CUR_SHXX_SB_MDTSE_010, BJTS_CUR_SHXX_SB_ZZSTSE_010, BJTS_CUR_SHXX_SB_XFSTSE_010, BJTS_CUR_SHXX_SB_MDSE_010;
    END;
    IF BJTS_CURSOR_DONE_010 THEN
      LEAVE BJTS_CURSOR_LOOP_010;
    END IF;
      BEGIN
        SELECT IFNULL(SUM(CASE WHEN TT.ZHBZ_1='Y' THEN TT.MDTSE ELSE 0 END), 0),
               IFNULL(SUM(CASE WHEN TT.BYTSBZ='Y' THEN TT.MDTSE ELSE 0 END), 0)
          INTO LN_ZH_MDTSE, LN_BYTS_MDTSE
          FROM (SELECT A.MDTSE,A.ZHBZ_1,A.BYTSBZ FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID=BJTS_CUR_SHXX_LCSLID_010
                 UNION ALL
                SELECT B.MDTSE,B.ZHBZ_1,B.BYTSBZ FROM CKTS_SB_MDT_YFSJ B WHERE B.LCSLID=BJTS_CUR_SHXX_LCSLID_010
                 UNION ALL
                SELECT C.MDTSE,C.ZHBZ_1,C.BYTSBZ FROM CKTS_SB_MDT_CKMX C WHERE C.LCSLID=BJTS_CUR_SHXX_LCSLID_010) TT;
        UPDATE CKTS_LC_SHXX AS A
           SET ZH_MDTSE = LN_ZH_MDTSE,
    ZH_XFSTSE=0,
    ZH_ZZSTSE= LN_ZH_MDTSE * CASE WHEN BJTS_CUR_SHXX_SB_MDTSE_010=0 THEN 1 ELSE BJTS_CUR_SHXX_SB_ZZSTSE_010 / BJTS_CUR_SHXX_SB_MDTSE_010 END,
    ZH_MDSE  = LN_ZH_MDTSE * CASE WHEN BJTS_CUR_SHXX_SB_MDTSE_010=0 THEN 0 ELSE BJTS_CUR_SHXX_SB_MDSE_010 / BJTS_CUR_SHXX_SB_MDTSE_010 END,
    BY_MDTSE = LN_BYTS_MDTSE,
    BY_XFSTSE=0,
    BY_ZZSTSE= LN_BYTS_MDTSE * CASE WHEN BJTS_CUR_SHXX_SB_MDTSE_010=0 THEN 1 ELSE BJTS_CUR_SHXX_SB_ZZSTSE_010 / BJTS_CUR_SHXX_SB_MDTSE_010 END,
    BY_MDSE  = LN_BYTS_MDTSE * CASE WHEN BJTS_CUR_SHXX_SB_MDTSE_010=0 THEN 0 ELSE BJTS_CUR_SHXX_SB_MDSE_010 / BJTS_CUR_SHXX_SB_MDTSE_010 END
         WHERE A.UUID=BJTS_CUR_SHXX_UUID_010;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_010;
  CLOSE BJTS_CURSOR_010;
END;
    IF LN_LOG>1 THEN
