    -- 部分免退税业务含跨境应税行为，需要两边合计
    BEGIN
  DECLARE BJTS_CURSOR_DONE_009 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTSYSFW_LCSLID_009 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_MYLAJ_009 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_RMBLAJ_009 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_ZZSTSE_009 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_BY_ZZSTSE_009 LONGTEXT;
  DECLARE BJTS_CUR_MTSYSFW_BYBL_ZZSTSE_009 LONGTEXT;
  DECLARE BJTS_CURSOR_009 CURSOR FOR
SELECT LCSLID, SUM(SKJEMY) AS MYLAJ, SUM(BQQRYSFWYYSRRMBJE) AS RMBLAJ,SUM(ZZSTSE) AS ZZSTSE,
                               SUM(CASE WHEN BYTSBZ='Y' THEN ZZSTSE ELSE 0 END) AS BY_ZZSTSE, SUM(CASE WHEN BYBLBZ='Y' THEN ZZSTSE ELSE 0 END) AS BYBL_ZZSTSE
                          FROM CKTS_SB_MTS_YSFW GROUP BY LCSLID;
  OPEN BJTS_CURSOR_009;
  BJTS_CURSOR_LOOP_009: LOOP
    SET BJTS_CURSOR_DONE_009 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_009 = TRUE;
      FETCH BJTS_CURSOR_009 INTO BJTS_CUR_MTSYSFW_LCSLID_009, BJTS_CUR_MTSYSFW_MYLAJ_009, BJTS_CUR_MTSYSFW_RMBLAJ_009, BJTS_CUR_MTSYSFW_ZZSTSE_009, BJTS_CUR_MTSYSFW_BY_ZZSTSE_009, BJTS_CUR_MTSYSFW_BYBL_ZZSTSE_009;
    END;
    IF BJTS_CURSOR_DONE_009 THEN
      LEAVE BJTS_CURSOR_LOOP_009;
    END IF;
      BEGIN
        UPDATE CKTS_LC_SHXX AS T
           SET SB_XSEMY = BJTS_CUR_MTSYSFW_MYLAJ_009 + (SELECT IFNULL(SUM(A.MYLAJ), 0) FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009),
    SB_XSERMB = BJTS_CUR_MTSYSFW_RMBLAJ_009 + (SELECT IFNULL(SUM(A.JSJE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.SZ='V'),
    SB_MDTSE = BJTS_CUR_MTSYSFW_ZZSTSE_009 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009),
    SB_ZZSTSE = BJTS_CUR_MTSYSFW_ZZSTSE_009 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.SZ='V'),
    SB_XFSTSE = (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.SZ='C'),
    SB_MDSE = 0,
    BY_MDTSE = BJTS_CUR_MTSYSFW_BY_ZZSTSE_009 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.BYTSBZ='Y'),
    BY_ZZSTSE = BJTS_CUR_MTSYSFW_BY_ZZSTSE_009 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.BYTSBZ='Y' AND A.SZ='V'),
    BY_XFSTSE = (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.BYTSBZ='Y' AND A.SZ='C'),
    BY_MDSE = 0,
    ZH_MDTSE = (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.ZBBLBZ='Y'),
    ZH_ZZSTSE = (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.ZBBLBZ='Y' AND A.SZ='V'),
    ZH_XFSTSE = (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.ZBBLBZ='Y' AND A.SZ='C'),
    ZH_MDSE = 0,
    BYBL_MDTSE = BJTS_CUR_MTSYSFW_BYBL_ZZSTSE_009 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.BYBLBZ='Y'),
    BYBL_ZZSTSE = BJTS_CUR_MTSYSFW_BYBL_ZZSTSE_009 + (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.BYBLBZ='Y' AND A.SZ='V'),
    BYBL_XFSTSE = (SELECT IFNULL(SUM(A.TSE), 0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009 AND A.BYBLBZ='Y' AND A.SZ='C'),
    BYBL_MDSE = 0
         WHERE T.LCSLID=BJTS_CUR_MTSYSFW_LCSLID_009;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_009;
  CLOSE BJTS_CURSOR_009;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(部分免退税业务含跨境应税行为)！');
      COMMIT;
    END IF;

    -- 根据业务核准表设置准予退税信息
    BEGIN
  DECLARE BJTS_CURSOR_DONE_008 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SHXX_LCSLID_FS_008 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_LCSLID_DUP_008 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_LCSLID_MDTSE_008 LONGTEXT;
  DECLARE BJTS_CURSOR_008 CURSOR FOR
SELECT T.LCSLID_FS, COUNT(1) AS LCSLID_DUP,
                            SUM(IFNULL(T.SB_MDTSE, 0)-IFNULL(T.BYBL_MDTSE, 0)-IFNULL(T.BY_MDTSE, 0)-IFNULL(T.ZH_MDTSE, 0)) AS LCSLID_MDTSE
                       FROM CKTS_LC_SHXX T
                      WHERE T.ZFBZ IS NULL AND T.LCJSRQ>=LD_DEALDATA
                        AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
                      GROUP BY T.LCSLID_FS;
  OPEN BJTS_CURSOR_008;
  BJTS_CURSOR_LOOP_008: LOOP
    SET BJTS_CURSOR_DONE_008 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_008 = TRUE;
      FETCH BJTS_CURSOR_008 INTO BJTS_CUR_SHXX_LCSLID_FS_008, BJTS_CUR_SHXX_LCSLID_DUP_008, BJTS_CUR_SHXX_LCSLID_MDTSE_008;
    END;
    IF BJTS_CURSOR_DONE_008 THEN
      LEAVE BJTS_CURSOR_LOOP_008;
    END IF;
      BEGIN
        SELECT IFNULL(SUM(A.FS_MDTSE), 0),IFNULL(SUM(A.FS_ZZSTSE), 0),IFNULL(SUM(A.FS_XFSTSE), 0),IFNULL(SUM(A.FS_MDSE), 0)
          INTO LN_MDTSE, LN_ZZS, LN_XFS, LN_MDSE
          FROM CKTS_LC_YWHZXX A
         WHERE A.LCSLID_FS=BJTS_CUR_SHXX_LCSLID_FS_008;
        SELECT IFNULL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSNF THEN B.GKBL_ZZSTSE ELSE 0 END), 0),
               IFNULL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSNF THEN B.GKBL_XFSTSE ELSE 0 END), 0),
               IFNULL(SUM(CASE WHEN B.XHRQ_MD<LD_BBNY_KSNF THEN B.GKBL_MDSE ELSE 0 END), 0),
               IFNULL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSRQ THEN B.GKBL_ZZSTSE ELSE 0 END), 0),
               IFNULL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSRQ THEN B.GKBL_XFSTSE ELSE 0 END), 0),
               IFNULL(SUM(CASE WHEN B.XHRQ_MD<LD_BBNY_KSRQ THEN B.GKBL_MDSE ELSE 0 END), 0)
          INTO SN_ZZS, SN_XFS, SN_MDSE, SY_ZZS, SY_XFS, SY_MDSE
          FROM CKTS_LC_YWHZXX A
         INNER JOIN CKTS_LC_SEHZXX B ON B.YWHZBUUID=A.YWHZBUUID
         WHERE A.LCSLID_FS=BJTS_CUR_SHXX_LCSLID_FS_008;
        IF BJTS_CUR_SHXX_LCSLID_DUP_008=1 THEN
          UPDATE CKTS_LC_SHXX AS A
             SET ZY_MDTSE = LN_MDTSE,
    ZY_ZZSTSE= LN_ZZS,
    ZY_XFSTSE=LN_XFS,
    ZY_MDSE  = LN_MDSE,
    SNBL_MDTSE= SN_ZZS + SN_XFS + SN_MDSE,
    SNBL_ZZSTSE= SN_ZZS,
    SNBL_XFSTSE= SN_XFS,
    SNBL_MDSE= SN_MDSE,
    SYBL_MDTSE= SY_ZZS + SY_XFS + SY_MDSE,
    SYBL_ZZSTSE= SY_ZZS,
    SYBL_XFSTSE= SY_XFS,
    SYBL_MDSE= SY_MDSE
           WHERE A.LCSLID_FS=BJTS_CUR_SHXX_LCSLID_FS_008;
        ELSEIF BJTS_CUR_SHXX_LCSLID_MDTSE_008<>0 THEN
          UPDATE CKTS_LC_SHXX AS A
             SET ZY_MDTSE = LN_MDTSE * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    ZY_ZZSTSE= LN_ZZS * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    ZY_XFSTSE=LN_XFS * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    ZY_MDSE  = LN_MDSE * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SNBL_MDTSE= (SN_ZZS + SN_XFS + SN_MDSE) * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SNBL_ZZSTSE= SN_ZZS * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SNBL_XFSTSE= SN_XFS * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SNBL_MDSE= SN_MDSE * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SYBL_MDTSE= (SY_ZZS + SY_XFS + SY_MDSE) * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SYBL_ZZSTSE= SY_ZZS * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SYBL_XFSTSE= SY_XFS * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008,
    SYBL_MDSE= SY_MDSE * (IFNULL(A.SB_MDTSE, 0)-IFNULL(A.BYBL_MDTSE, 0)-IFNULL(A.BY_MDTSE, 0)-IFNULL(A.ZH_MDTSE, 0)) / BJTS_CUR_SHXX_LCSLID_MDTSE_008
           WHERE A.LCSLID_FS=BJTS_CUR_SHXX_LCSLID_FS_008;
        END IF;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_008;
  CLOSE BJTS_CURSOR_008;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(根据业务核准表设置准予退税信息)！');
      COMMIT;
    END IF;

    UPDATE CKTS_LC_SHXX AS T
       SET BYHZ_MDTSE = (SELECT IFNULL(SUM(A.BYHZ_MDTSE), 0)
FROM CKTS_LC_SEHZXX A
             WHERE A.LCSLID_FS=T.LCSLID_FS AND A.SEHZRQ<CURRENT_TIMESTAMP),
    BYHZ_ZZSTSE = (SELECT IFNULL(SUM(A.BYHZ_ZZSTSE), 0)
FROM CKTS_LC_SEHZXX A
             WHERE A.LCSLID_FS=T.LCSLID_FS AND A.SEHZRQ<CURRENT_TIMESTAMP),
    BYHZ_XFSTSE = (SELECT IFNULL(SUM(A.BYHZ_XFSTSE), 0)
FROM CKTS_LC_SEHZXX A
             WHERE A.LCSLID_FS=T.LCSLID_FS AND A.SEHZRQ<CURRENT_TIMESTAMP),
    BYHZ_MDSE = (SELECT IFNULL(SUM(A.BYHZ_MDSE), 0)
FROM CKTS_LC_SEHZXX A
             WHERE A.LCSLID_FS=T.LCSLID_FS AND A.SEHZRQ<CURRENT_TIMESTAMP)
     WHERE T.LCJSRQ>=LD_DEALDATA ;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX.BYHZ_MDTSE！');
      COMMIT;
    END IF;

    UPDATE CKTS_LC_SHXX AS T
       SET ZH_MDTSE=T.ZH_ZZSTSE+T.ZH_XFSTSE+T.ZH_MDSE
     WHERE T.ZFBZ IS NULL AND T.ZH_MDTSE<>T.ZH_ZZSTSE+T.ZH_XFSTSE+T.ZH_MDSE;
    COMMIT;
    UPDATE CKTS_LC_SHXX AS T
       SET BY_MDTSE=T.BY_ZZSTSE+T.BY_XFSTSE+T.BY_MDSE
     WHERE T.ZFBZ IS NULL AND T.BY_MDTSE<>T.BY_ZZSTSE+T.BY_XFSTSE+T.BY_MDSE;
    COMMIT;
    UPDATE CKTS_LC_SHXX AS T
       SET ZY_MDTSE=T.ZY_ZZSTSE+T.ZY_XFSTSE+T.ZY_MDSE
     WHERE T.ZFBZ IS NULL AND T.ZY_MDTSE<>T.ZY_ZZSTSE+T.ZY_XFSTSE+T.ZY_MDSE;
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SHXX数据处理（SB_、ZH_、BY_、ZY_、SNBL_、SYBL_）处理成功！');
    COMMIT;
  END;

  -- CKTS_LC_SHXX数据处理（判断LCJSRQ、LASTOPDATE）
  BEGIN
  DECLARE BJTS_SQLCODE_017 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_017 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_017 = MYSQL_ERRNO, BJTS_SQLERRM_017 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_017;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SHXX数据（LCJSRQ、LASTOPDATE）处理失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = CAST('2100-12-31' AS DATE)
     WHERE T.LCJSRQ IS NULL;
    COMMIT;
    -- 申报数为0
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND IFNULL(T.SB_MDTSE, 0)=0
       AND IFNULL(T.ZY_MDTSE, 0)=0
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    -- 复核数为0
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND T.SB_MDTSE>0
       AND T.SB_MDTSE=T.BYBL_MDTSE + IFNULL(T.BY_MDTSE, 0)+IFNULL(T.ZH_MDTSE, 0)
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    -- 核准数为0
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND T.ZY_MDTSE>0
       AND T.ZY_MDTSE=T.BYHZ_MDTSE
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    -- 有税额且税额核准全部完成
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = (SELECT MAX(GREATEST(A.XHRQ_TK,A.XHRQ_MD,A.XHRQ_XFS)) FROM CKTS_LC_SEHZXX A WHERE A.LCSLID_FS=T.LCSLID_FS)
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='Y' AND B.FS_MDTSE<>0)
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='N')
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    -- 无税额且税额核准全部完成
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='Y' AND B.FS_MDTSE=0)
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='N')
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    -- 流程有子流程也本身无明细数据
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND IFNULL(T.SB_MDTSE, 0)=0
       AND EXISTS (SELECT 1 FROM CKTS_LC_SHXX R WHERE R.LCSLID_SB=T.LCSLID_SB AND R.ZLCLCSLID=T.LCSLID)
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    -- 免抵退分流程复核数=0
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = T.FFRQ
     WHERE T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9'
       AND T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID_FS AND A.FS_MDTSE=0)
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.FS_MDTSE<>0);
    COMMIT;
    -- 免抵退分流程复核数<>0
    UPDATE CKTS_LC_SHXX AS T
       SET LCJSRQ = (SELECT MAX(GREATEST(A.XHRQ_TK,A.XHRQ_MD,A.XHRQ_XFS))
                         FROM CKTS_LC_SEHZXX A
                        WHERE A.LCSLID_FS=T.LCSLID_FS)
     WHERE T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9'
       AND T.LCJSRQ>=LD_DEALDATA
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='Y')
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX C WHERE C.LCSLID_FS=T.LCSLID_FS AND C.SEHZWCBZ='N');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX.LCJSRQ！');
      COMMIT;
    END IF;

    -- LASTOPDATE，流程已结束的按结束日期
    UPDATE CKTS_LC_SHXX AS T
       SET LASTOPDATE = T.LCJSRQ
     WHERE T.LCJSRQ<=CURRENT_TIMESTAMP AND T.LCJSRQ<>T.LASTOPDATE
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;

    BEGIN
  DECLARE BJTS_CURSOR_DONE_007 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_LCSLID_UUID_007 LONGTEXT;
  DECLARE BJTS_CUR_LCSLID_LCSLID_FS_007 LONGTEXT;
  DECLARE BJTS_CUR_LCSLID_SHSJ_007 LONGTEXT;
  DECLARE BJTS_CURSOR_007 CURSOR FOR
SELECT S.UUID,S.LCSLID_FS,IFNULL(S.FFRQ, S.QDSJ) AS SHSJ
                         FROM CKTS_LC_SHXX S
                        WHERE S.LCJSRQ>=LD_DEALDATA;
  OPEN BJTS_CURSOR_007;
  BJTS_CURSOR_LOOP_007: LOOP
    SET BJTS_CURSOR_DONE_007 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_007 = TRUE;
      FETCH BJTS_CURSOR_007 INTO BJTS_CUR_LCSLID_UUID_007, BJTS_CUR_LCSLID_LCSLID_FS_007, BJTS_CUR_LCSLID_SHSJ_007;
    END;
    IF BJTS_CURSOR_DONE_007 THEN
      LEAVE BJTS_CURSOR_LOOP_007;
    END IF;
      BEGIN
        SET LD_LASTRQ = BJTS_CUR_LCSLID_SHSJ_007;

        SELECT GREATEST(LD_LASTRQ,IFNULL(MAX(FSRQ), LD_LASTRQ),IFNULL(MAX(YWHZRQ), LD_LASTRQ))
          INTO LD_LASTRQ
          FROM CKTS_LC_YWHZXX
         WHERE LCSLID_FS=BJTS_CUR_LCSLID_LCSLID_FS_007;
        SELECT GREATEST(LD_LASTRQ,IFNULL(MAX(SEHZRQ), LD_LASTRQ),IFNULL(MAX((CASE XHRQ_TK WHEN CAST('2100-12-31' AS DATE) THEN LD_LASTRQ ELSE XHRQ_TK END)), LD_LASTRQ),IFNULL(MAX((CASE XHRQ_MD WHEN CAST('2100-12-31' AS DATE) THEN LD_LASTRQ ELSE XHRQ_MD END)), LD_LASTRQ),IFNULL(MAX((CASE XHRQ_XFS WHEN CAST('2100-12-31' AS DATE) THEN LD_LASTRQ ELSE XHRQ_XFS END)), LD_LASTRQ))
          INTO LD_LASTRQ
          FROM CKTS_LC_SEHZXX
         WHERE LCSLID_FS=BJTS_CUR_LCSLID_LCSLID_FS_007;

        UPDATE CKTS_LC_SHXX AS T
           SET LASTOPDATE = LD_LASTRQ
         WHERE T.UUID=BJTS_CUR_LCSLID_UUID_007 AND T.LASTOPDATE<LD_LASTRQ;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_007;
  CLOSE BJTS_CURSOR_007;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX.LASTOPDATE！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SHXX数据（LCJSRQ、LASTOPDATE）处理成功！');
    COMMIT;
  END;

  -- 每月初，进行报表中间数据提取，包括未申报数据、跨境电商数据、明细复审时间及分类统计数据，然后调用报表初始化过程
  -- CKTS_WBSJ_BGD_9X10数据
  -- 20250718，基于态势感知新业态9810数据展现需求，9X10数据改为每日gcb数据全部刷新，jgb数据按提前量增量刷新
  BEGIN
  DECLARE BJTS_SQLCODE_016 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_016 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_016 = MYSQL_ERRNO, BJTS_SQLERRM_016 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_016;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_WBSJ_BGD_9X10数据,处理失败！', LC_SBYY);
      COMMIT;

  END;
DELETE FROM CKTS_WBSJ_BGD_9X10 AS A WHERE A.SJLY='1';
    COMMIT;

    UPDATE CKTS_WBSJ_BGD_9X10 AS A
JOIN (
SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0305001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       IFNULL(T.CKBGDH, T.DLCKHWZMHM) AS CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.MDTSE,
                       ROUND(T.MDTSE * CASE WHEN S.MDTSEHJ<=0 THEN 0 ELSE S.YTSE_1/S.MDTSEHJ END, 2) AS TSE,
                       CASE WHEN T.MDTSNY IS NULL THEN 'N' ELSE 'Y' END AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_MDT_CKMX T
                 INNER JOIN CKTS_SB_MDT_SBDSHZ S ON S.LCSLID=T.LCSLID_SB
                 WHERE T.SJLY='1'
                   AND T.TDCODE IN ('9610','9710','9810')
                 UNION ALL
                SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0305001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       IFNULL(T.CKBGDH, T.DLCKHWZMHM) AS CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.MDTSE,
                       ROUND(T.MDTSE * CASE WHEN S.MDTSEHJ<=0 THEN 0 ELSE S.YTSE_1/S.MDTSEHJ END, 2) AS TSE,
                       CASE WHEN T.MDTSNY IS NULL THEN 'N' ELSE 'Y' END AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_MDT_CKMX T
                 INNER JOIN CKTS_SB_MDT_SBDSHZ S ON S.LCSLID=T.LCSLID_FS
                 WHERE T.SJLY='2'
                   AND T.SJTB_SJ>=LD_DEALDATA
                   AND T.TDCODE IN ('9610','9710','9810')
                 UNION ALL
                SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0301001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       IFNULL(T.CKBGDH, T.DLCKHWZMHM) AS CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.TSE AS MDTSE,T.TSE,
