  -- CKTS_WBSJ_BGD_WSB数据处理
  -- 20251204，因为未申报报关单处理比较耗时，提前至月底前一天执行
  IF DATE(CURRENT_TIMESTAMP) = ORA_DATE_ADD(DATE_ADD(LD_BBNY_JZRQ, INTERVAL 1 MONTH), -(1)) THEN
    BEGIN
  DECLARE BJTS_SQLCODE_015 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_015 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_015 = MYSQL_ERRNO, BJTS_SQLERRM_015 = MESSAGE_TEXT;
        SET LC_SBYY =BJTS_SQLERRM_015;
