        COMMIT;

  END;
SET @BJTS_DYNAMIC_SQL_001 = 'TRUNCATE TABLE CKTS_WBSJ_BGD_WSB';
PREPARE BJTS_DYNAMIC_STMT_001 FROM @BJTS_DYNAMIC_SQL_001;
EXECUTE BJTS_DYNAMIC_STMT_001;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_001;
      COMMIT;
      -- 插入生产、外贸企业所有未申报报关单数据
      INSERT INTO CKTS_WBSJ_BGD_WSB(UUID,TSSWJG_DM,DJXH,CKBGDH,CKRQ_1,CKSP_DM,JGFS_DM,RMBLAJ,MYLAJ,BAH)
           SELECT T.UUID,T.TSSWJG_DM_1,T.DJXH,T.CKBGDH,T.CKRQ_1,T.CKSP_DM,T.JGFS_DM,T.RMBLAJ,T.MYLAJ,T.BAH
             FROM GLXT_BB_SHXT_DJXX S, CKTS_WBSJ_HG_BGD T
            WHERE S.JSMODE IN ('1','2')
              AND IFNULL(S.ZX_FLAG, 'N')='N'
              AND S.DJXH_JS=T.DJXH
              AND T.TSSBSL+T.DLSBSL+T.TYSL=0
              AND T.JGFS_DM<>'1039';
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             插入生产、外贸企业所有未申报报关单数据！');
        COMMIT;
      END IF;
      -- 删除免税贸易方式
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_DM_HGJGFS
                       WHERE JGFS_DM = CKTS_WBSJ_BGD_WSB.JGFS_DM
                         AND JGFSTSLX_DM = '0');
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             删除免税贸易方式！');
        COMMIT;
      END IF;
      -- 删除禁止出口商品或不退税商品、免税商品
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_DM_TSLVWK
                       WHERE CKSP_DM = CKTS_WBSJ_BGD_WSB.CKSP_DM
                         AND CKTS_WBSJ_BGD_WSB.CKRQ_1 BETWEEN YXQQ AND YXQZ
                         AND CKSPTSSPLX_DM IN ('1','2'));
      COMMIT;
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_DM_TSLVWK
                       WHERE CKSP_DM = SUBSTR(CKTS_WBSJ_BGD_WSB.CKSP_DM,1,8)
                         AND CKTS_WBSJ_BGD_WSB.CKRQ_1 BETWEEN YXQQ AND YXQZ
                         AND CKSPTSSPLX_DM IN ('1','2'));
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             删除禁止出口商品或不退税商品、免税商品！');
        COMMIT;
      END IF;
      -- 删除生产企业免抵退已申报数据
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_SB_MDT_CKMX
                       WHERE DJXH = CKTS_WBSJ_BGD_WSB.DJXH
                         AND CKBGDH = CKTS_WBSJ_BGD_WSB.CKBGDH);
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             删除生产企业免抵退已申报数据！');
        COMMIT;
      END IF;
      -- 删除外贸免退税已申报数据
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_SB_MTS_CKMX
                       WHERE DJXH = CKTS_WBSJ_BGD_WSB.DJXH
                         AND CKBGDH = CKTS_WBSJ_BGD_WSB.CKBGDH);
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             删除外贸免退税已申报数据！');
        COMMIT;
      END IF;
      -- 删除外综服代办退税已申报数据
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_SB_WZF_CKMX
                       WHERE DJXH = CKTS_WBSJ_BGD_WSB.DJXH
                         AND CKBGDH = CKTS_WBSJ_BGD_WSB.CKBGDH);
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             删除外综服代办退税已申报数据！');
        COMMIT;
      END IF;
      -- 删除其他业务已申报数据
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_SB_FZC_SBMX
                       WHERE DJXH = CKTS_WBSJ_BGD_WSB.DJXH
                         AND CKBGDH = CKTS_WBSJ_BGD_WSB.CKBGDH);
      COMMIT;
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM CKTS_SB_YS_SBMX
                       WHERE DJXH = CKTS_WBSJ_BGD_WSB.DJXH
                         AND CKBGDH = CKTS_WBSJ_BGD_WSB.CKBGDH);
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             删除其他业务已申报数据！');
        COMMIT;
      END IF;
      -- 删除长期未申报已确认已审核数据
      DELETE FROM CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM RCGL_CQWSB_DATA
                       WHERE DJXH = CKTS_WBSJ_BGD_WSB.DJXH
                         AND CKBGDH = CKTS_WBSJ_BGD_WSB.CKBGDH
                         AND SWSH_ZT='1');
      COMMIT;

      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_WBSJ_BGD_WSB数据,处理成功！');
      COMMIT;
    END;
  END IF;

