                  SUM(CASE WHEN GBCODE='502' THEN MYLAJ ELSE 0 END),
                  SUM(CASE WHEN GBCODE='502' THEN JSJE ELSE 0 END),
                  SUM(CASE WHEN GBCODE='502' THEN TSE ELSE 0 END)
             FROM CKTS_SB_WZF_CKMX T
            WHERE T.FSRQ>=LD_BBNY_KSRQ AND T.FSRQ<LD_BBNY_JZRQ
            GROUP BY T.TSSWJG_DM, CAST(T.DJXH AS CHAR);
      COMMIT;

