      -- A0310001
      INSERT INTO TJBB_FHXX_TSLV(SBYWBDM,SSNY,SWCODE,XMFL,USD_AMT,RMB_AMT,TS_AMT)
           SELECT 'A0310001', LC_BBNY, T.TSSWJG_DM, T.TSL, SUM(T.MYLAJ), SUM(T.JSJE), SUM(T.TSE)
             FROM CKTS_SB_WZF_CKMX T
            WHERE T.FSRQ>=LD_BBNY_KSRQ AND T.FSRQ<LD_BBNY_JZRQ AND T.TSL IS NOT NULL
            GROUP BY T.TSSWJG_DM, T.TSL;
      COMMIT;

      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('TJBB_FHXX_TSLV数据,处理成功！');
      COMMIT;

    END;

    -- 初始化报表
    CALL PRO_TJBB_CSH_ALL(LC_BBNY);
  END IF;

  -- 每月初+1，处理省局月报表/出口退税月报表（不计结转）
  IF DATE(CURRENT_TIMESTAMP) = ORA_DATE_ADD(LD_BBNY_JZRQ, 1) THEN
    CALL PRO_TJBB_CSH_B03B07(LC_BBNY);
  END IF;

  -- 每月初+2，处理绩效考核月报表
  IF DATE(CURRENT_TIMESTAMP) = ORA_DATE_ADD(LD_BBNY_JZRQ, 2) THEN
    BEGIN
  DECLARE BJTS_CURSOR_DONE_006 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_LSF_SWJG_SWJG_DM_006 LONGTEXT;
  DECLARE BJTS_LSF_SWJG_YXWS_006 LONGTEXT;
  DECLARE BJTS_CURSOR_006 CURSOR FOR
SELECT SWJG_DM,YXWS FROM DM_SWJG WHERE TSJG_BZ='1' AND QYBZ='Y' ORDER BY YXWS DESC,SWJG_DM;
  OPEN BJTS_CURSOR_006;
  BJTS_CURSOR_LOOP_006: LOOP
    SET BJTS_CURSOR_DONE_006 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_006 = TRUE;
      FETCH BJTS_CURSOR_006 INTO BJTS_LSF_SWJG_SWJG_DM_006, BJTS_LSF_SWJG_YXWS_006;
    END;
    IF BJTS_CURSOR_DONE_006 THEN
      LEAVE BJTS_CURSOR_LOOP_006;
    END IF;
      INSERT INTO JXKH_TJBB(TJMONTH,SWCODE,FLGLCD,SBHS,SBPCS,SL_DAY,SH_DAY,HZ_DAY,KP_DAY,HJ_DAY)
           SELECT LC_BBNY,BJTS_LSF_SWJG_SWJG_DM_006,TT.FLGLCD,TT.SBHS,TT.SBPCS,TT.SL_DAY,TT.SH_DAY,TT.HZ_DAY,TT.KP_DAY,TT.HJ_DAY
             FROM ((SELECT T.CKQYGLLB_DM AS FLGLCD,
                           COUNT(DISTINCT T.DJXH) AS SBHS,COUNT(1) AS SBPCS,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SL_DAY ELSE NULL END),2) AS SL_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SH_DAY ELSE NULL END),2) AS SH_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.HZ_DAY ELSE NULL END),2) AS HZ_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.KP_DAY ELSE NULL END),2) AS KP_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SUM_DAY ELSE NULL END),2) AS HJ_DAY
                      FROM GLXT_BB_SHXT_LCXX T
                     WHERE T.SWJGDM LIKE ORA_CONCAT(SUBSTR(BJTS_LSF_SWJG_SWJG_DM_006,1,BJTS_LSF_SWJG_YXWS_006), '%')
                       AND T.SL_DATE>=LD_BBNY_KSNF
                       AND T.SL_DATE< LD_BBNY_JZRQ
                     GROUP BY T.CKQYGLLB_DM
                   )
                     UNION ALL
                   (SELECT '0' AS FLGLCD,
                           COUNT(DISTINCT T.DJXH) AS SBHS,COUNT(1) AS SBPCS,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SL_DAY ELSE NULL END),2) AS SL_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SH_DAY ELSE NULL END),2) AS SH_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.HZ_DAY ELSE NULL END),2) AS HZ_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.KP_DAY ELSE NULL END),2) AS KP_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SUM_DAY ELSE NULL END),2) AS HJ_DAY
                      FROM GLXT_BB_SHXT_LCXX T
                     WHERE T.SWJGDM LIKE ORA_CONCAT(SUBSTR(BJTS_LSF_SWJG_SWJG_DM_006,1,BJTS_LSF_SWJG_YXWS_006), '%')
                       AND T.SL_DATE>=LD_BBNY_KSNF
                       AND T.SL_DATE< LD_BBNY_JZRQ
                   )
                  ) TT
            ORDER BY FLGLCD;
      COMMIT;

  END LOOP BJTS_CURSOR_LOOP_006;
  CLOSE BJTS_CURSOR_006;
END;
    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('处理绩效考核月报表成功！');
    COMMIT;
  END IF;

  -- 每月初+3，处理健康管理供货企业增量
  IF DATE(CURRENT_TIMESTAMP) = ORA_DATE_ADD(LD_BBNY_JZRQ, 3) THEN
    BEGIN
      INSERT INTO JKGL_GY_GHQYXX (QYSBH,CR_TIME)
SELECT B.GHFNSRSBH_1,CURRENT_TIMESTAMP
FROM (
SELECT DISTINCT T.GHFNSRSBH_1
                    FROM CKTS_SB_MTS_JHMX T
                   WHERE T.SBRQ>=LD_BBNY_KSRQ
                     AND T.GHFNSRSBH_1 IS NOT NULL
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_GY_GHQYXX AS A WHERE A.QYSBH=B.GHFNSRSBH_1
);
      COMMIT;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('增量JKGL_GY_GHQYXX处理成功！');
      COMMIT;
    END;
  END IF;

  -- 每月初+4，日常风险指标扫描
  IF DATE(CURRENT_TIMESTAMP) = ORA_DATE_ADD(LD_BBNY_JZRQ, 4) THEN
    CALL PRO_FXGL_COMPUTE_MAIN();
    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('日常风险指标扫描处理成功！');
    COMMIT;
  END IF;

  -- 每年初+5，处理GLXT_BB_SHXT_DJXX的出口规模等数据
  IF DATE(CURRENT_TIMESTAMP) = ORA_DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), 5) THEN
    CALL PRO_DEAL_JCFX_NSR_BLV();
    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('GLXT_BB_SHXT_DJXX的出口规模等数据处理成功！');
    COMMIT;
  END IF;

  -- GLXT_BB_SHXT_LCXX数据处理
  BEGIN
  DECLARE BJTS_SQLCODE_005 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_005 TEXT DEFAULT '';
    -- 增加新的企业申报信息

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_005 = MYSQL_ERRNO, BJTS_SQLERRM_005 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_005;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('同步GLXT_BB_SHXT_LCXX处理失败！', LC_SBYY);
      COMMIT;

  END;
INSERT INTO GLXT_BB_SHXT_LCXX(UUID,SWJGDM,ZBSWCODE,DJXH,CKQYGLLB_DM,SBYWB_DM,SB_YM,SB_PC,LCSLID,BJTS_DATE,SB_DATE,SL_DATE,SL_USER,USD_AMT,RMB_AMT,SB_TS_AMT,SB_MD_AMT,WZHBZ)
         SELECT T.UUID,T.TSSWJG_DM,T.TSSWJG_DM,T.DJXH,T.CKQYGLLB_DM,T.SBYWB_DM,T.SSQ,T.SBPC,T.LCSLID_SB,T.SBRQ,T.QDSJ,T.DYSLTZSJ,T.QDR_DM,T.SB_XSEMY,T.SB_XSERMB,T.SB_ZZSTSE+T.SB_XFSTSE,T.SB_MDSE,T.WZHBZ
           FROM CKTS_LC_SBXX T
          WHERE T.ZFBZ IS NULL
            AND T.SJTB_BZ='2'
            AND NOT EXISTS (SELECT 1 FROM GLXT_BB_SHXT_LCXX S WHERE S.UUID=T.UUID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             GLXT_BB_SHXT_LCXX.增加新的申报信息！');
      COMMIT;
    END IF;

    -- 删除已作废的流程
    DELETE FROM GLXT_BB_SHXT_LCXX AS T WHERE NOT EXISTS (SELECT 1 FROM CKTS_LC_SBXX S WHERE S.UUID=T.UUID AND IFNULL(S.ZFBZ, 'N')='N');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             GLXT_BB_SHXT_LCXX.删除已作废流程！');
      COMMIT;
    END IF;

    -- 主流程未发放之前，更新主流程信息
    SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_005 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_LCXX_UUID_005 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_LCSLID_005 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_SB_DATE_005 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_SL_DATE_005 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_CKQYGLLB_DM_005 LONGTEXT;
  DECLARE BJTS_CURSOR_005 CURSOR FOR
SELECT T.UUID,T.LCSLID,IFNULL(T.BJTS_DATE, T.SB_DATE) AS SB_DATE,T.SL_DATE,T.CKQYGLLB_DM FROM GLXT_BB_SHXT_LCXX T WHERE IFNULL(T.ZLC_FFRQ, CAST('2100-12-31' AS DATE))>=LD_DEALDATA;
  OPEN BJTS_CURSOR_005;
  BJTS_CURSOR_LOOP_005: LOOP
    SET BJTS_CURSOR_DONE_005 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_005 = TRUE;
      FETCH BJTS_CURSOR_005 INTO BJTS_CUR_LCXX_UUID_005, BJTS_CUR_LCXX_LCSLID_005, BJTS_CUR_LCXX_SB_DATE_005, BJTS_CUR_LCXX_SL_DATE_005, BJTS_CUR_LCXX_CKQYGLLB_DM_005;
    END;
    IF BJTS_CURSOR_DONE_005 THEN
      LEAVE BJTS_CURSOR_LOOP_005;
    END IF;
      BEGIN
        SET V_SL_DATE = BJTS_CUR_LCXX_SL_DATE_005;
        -- SL_DATE IS NULL
        IF V_SL_DATE IS NULL THEN
          SELECT A.DYSLTZSJ
            INTO V_SL_DATE
            FROM CKTS_LC_SBXX A
           WHERE A.UUID=BJTS_CUR_LCXX_UUID_005;
        END IF;
        -- 主流程复审数
        SELECT COUNT(1), IFNULL(SUM(S.FS_ZZSTSE+S.FS_XFSTSE), 0), IFNULL(SUM(S.FS_MDSE), 0), IFNULL(SUM(S.ZK_ZZSTSE+S.ZK_XFSTSE), 0)
          INTO V_ZLC_FS, V_ZLC_TS_AMT, V_ZLC_MD_AMT, V_ZLC_ZK_AMT
          FROM CKTS_LC_YWHZXX S
         WHERE S.LCSLID_FS=BJTS_CUR_LCXX_LCSLID_005;
        IF V_ZLC_FS=0 THEN
          -- 未复审，按主流程申报数以及发放时间
          SELECT IFNULL(SUM(S.SB_ZZSTSE+S.SB_XFSTSE), 0), IFNULL(SUM(S.SB_MDSE), 0), MIN(S.FFRQ)
            INTO V_ZLC_TS_AMT, V_ZLC_MD_AMT, V_FF_DATE
            FROM CKTS_LC_SHXX S
           WHERE S.LCSLID=BJTS_CUR_LCXX_LCSLID_005;
          IF V_FF_DATE > CURRENT_TIMESTAMP THEN
            SET V_FF_DATE =NULL;
          END IF;
          -- 如果已经发放且没有业务核准表，说明全部暂缓或不予了
          IF V_FF_DATE IS NOT NULL THEN
            SET V_ZLC_TS_AMT =0;
            SET V_ZLC_MD_AMT =0;
            IF V_SL_DATE IS NULL THEN
              SET V_SL_DATE =V_FF_DATE;
            END IF;
          END IF;
          UPDATE GLXT_BB_SHXT_LCXX AS S
             SET ZLC_TS_AMT=V_ZLC_TS_AMT,
    ZLC_MD_AMT=V_ZLC_MD_AMT,
    ZLC_FFRQ=V_FF_DATE,
    SL_DATE=V_SL_DATE,
    BLJZ_DATE=COMPUTE_BLJZDATE(BJTS_CUR_LCXX_CKQYGLLB_DM_005, V_SL_DATE),
    FH_DATE=V_FF_DATE,
    SL_DAY=COMPUTE_BLDATE(V_SL_DATE, BJTS_CUR_LCXX_SB_DATE_005),
    SH_DAY=COMPUTE_BLDATE(V_FF_DATE, V_SL_DATE),
    HZ_DAY=0,
    KP_DAY=0
           WHERE S.UUID=BJTS_CUR_LCXX_UUID_005;
          COMMIT;
        ELSE
          -- 已复审，取业务核准表的复审数
          SELECT FSRQ, FSR_DM, YWHZRQ, YWHZR_DM
            INTO V_FH_DATE, V_FH_USER, V_YWHZ_DATE, V_YWHZ_USER
            FROM (SELECT S.FSRQ, S.FSR_DM, S.YWHZRQ,S.YWHZR_DM
                    FROM CKTS_LC_YWHZXX S
                   WHERE S.LCSLID_FS=BJTS_CUR_LCXX_LCSLID_005
                   ORDER BY S.FSRQ) AS BJTS_DERIVED_001
           WHERE 1=1
LIMIT 1;
          IF (V_FH_DATE > CURRENT_TIMESTAMP) OR (V_FH_DATE=CAST('1900-01-01' AS DATE)) THEN
            SET V_FH_DATE =NULL;
          END IF;
          IF (V_YWHZ_DATE > CURRENT_TIMESTAMP) OR (V_YWHZ_DATE=CAST('1900-01-01' AS DATE)) THEN
            SET V_YWHZ_DATE =NULL;
          END IF;
          IF V_ZLC_TS_AMT - V_ZLC_ZK_AMT <=0 THEN
            -- 复审退税额=0
            IF (V_YWHZ_DATE IS NULL) AND (V_FF_DATE IS NOT NULL) THEN
              SET V_YWHZ_DATE =V_FF_DATE;
            END IF;
            IF (V_FH_DATE IS NULL) AND (V_YWHZ_DATE IS NOT NULL) THEN
              SET V_FH_DATE =V_YWHZ_DATE;
            END IF;
            IF (V_SL_DATE IS NULL) AND (V_FH_DATE IS NOT NULL) THEN
              SET V_SL_DATE =V_FH_DATE;
            END IF;
            UPDATE GLXT_BB_SHXT_LCXX AS S
               SET ZLC_TS_AMT=V_ZLC_TS_AMT,
    ZLC_MD_AMT=V_ZLC_MD_AMT,
    ZLC_FFRQ=(SELECT R.FFRQ FROM CKTS_LC_SHXX R WHERE R.UUID=BJTS_CUR_LCXX_UUID_005),
    SL_DATE=V_SL_DATE,
    BLJZ_DATE=COMPUTE_BLJZDATE(BJTS_CUR_LCXX_CKQYGLLB_DM_005, V_SL_DATE),
    FH_DATE=V_FH_DATE,
    FH_USER=V_FH_USER,
    YWHZ_DATE=V_YWHZ_DATE,
    YWHZ_USER=V_YWHZ_USER,
    SL_DAY=COMPUTE_BLDATE(V_SL_DATE, BJTS_CUR_LCXX_SB_DATE_005),
    SH_DAY=COMPUTE_BLDATE(V_FH_DATE, V_SL_DATE),
    HZ_DAY=COMPUTE_BLDATE(V_YWHZ_DATE, V_FH_DATE),
    KP_DAY=0
             WHERE S.UUID=BJTS_CUR_LCXX_UUID_005;
            COMMIT;
            IF V_ZLC_MD_AMT>0 THEN
              BEGIN
  DECLARE BJTS_SQLCODE_008 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_008 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_008 = MYSQL_ERRNO, BJTS_SQLERRM_008 = MESSAGE_TEXT;
                  SET V_SEHZ_DATE =NULL;
                  SET V_SEHZ_USER =NULL;

  END;
SELECT SEHZRQ, SEHZR_DM
                  INTO V_SEHZ_DATE, V_SEHZ_USER
                  FROM (SELECT S.SEHZRQ, S.SEHZR_DM
                          FROM CKTS_LC_SEHZXX S
                         WHERE S.LCSLID_FS=BJTS_CUR_LCXX_LCSLID_005
                         ORDER BY SEHZRQ) AS BJTS_DERIVED_002
                 WHERE 1=1
LIMIT 1;
              END;
              UPDATE GLXT_BB_SHXT_LCXX AS S
                 SET SEHZ_DATE=V_SEHZ_DATE,
    SEHZ_USER=V_SEHZ_USER
               WHERE S.UUID=BJTS_CUR_LCXX_UUID_005;
              COMMIT;
            END IF;
          ELSE
            -- 复审退税额<>0
            BEGIN
  DECLARE BJTS_SQLCODE_007 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_007 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_007 = MYSQL_ERRNO, BJTS_SQLERRM_007 = MESSAGE_TEXT;
                SET V_SEHZ_DATE =NULL;
                SET V_SEHZ_USER =NULL;
                SET V_TSKP_DATE =NULL;
                SET V_TSTK_DATE =NULL;

  END;
SELECT SEHZRQ, SEHZR_DM, KPRQ, XHRQ
                INTO V_SEHZ_DATE, V_SEHZ_USER, V_TSKP_DATE, V_TSTK_DATE
                FROM (SELECT S.SEHZRQ, S.SEHZR_DM, S.KPRQ, (CASE WHEN S.SEHZ_ZZSTSE+S.BYHZ_ZZSTSE<>0 THEN S.XHRQ_TK ELSE S.XHRQ_XFS END) AS XHRQ
                        FROM CKTS_LC_SEHZXX S
                       WHERE S.LCSLID_FS=BJTS_CUR_LCXX_LCSLID_005
                         AND S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE+S.BYHZ_ZZSTSE+S.BYHZ_XFSTSE<>0
                       ORDER BY SEHZRQ) AS BJTS_DERIVED_003
               WHERE 1=1
LIMIT 1;
            END;
            IF V_SEHZ_DATE > CURRENT_TIMESTAMP THEN
              SET V_SEHZ_DATE =NULL;
            END IF;
            IF V_TSKP_DATE > CURRENT_TIMESTAMP THEN
              SET V_TSKP_DATE =NULL;
            END IF;
            IF V_TSTK_DATE > CURRENT_TIMESTAMP THEN
              SET V_TSTK_DATE =NULL;
            END IF;
            IF (V_YWHZ_DATE IS NULL) AND (V_SEHZ_DATE IS NOT NULL) THEN
              SET V_YWHZ_DATE =V_SEHZ_DATE;
            END IF;
            IF (V_FH_DATE IS NULL) AND (V_YWHZ_DATE IS NOT NULL) THEN
              SET V_FH_DATE =V_YWHZ_DATE;
            END IF;
            IF (V_SL_DATE IS NULL) AND (V_FH_DATE IS NOT NULL) THEN
              SET V_SL_DATE =V_FH_DATE;
            END IF;
            UPDATE GLXT_BB_SHXT_LCXX AS S
               SET ZLC_TS_AMT=V_ZLC_TS_AMT,
    ZLC_MD_AMT=V_ZLC_MD_AMT,
    ZLC_FFRQ=GREATEST(V_TSKP_DATE,(SELECT R.FFRQ FROM CKTS_LC_SHXX R WHERE R.UUID=BJTS_CUR_LCXX_UUID_005)),
    SL_DATE=V_SL_DATE,
    BLJZ_DATE=COMPUTE_BLJZDATE(BJTS_CUR_LCXX_CKQYGLLB_DM_005, V_SL_DATE),
    FH_DATE=V_FH_DATE,
    FH_USER=V_FH_USER,
    YWHZ_DATE=V_YWHZ_DATE,
    YWHZ_USER=V_YWHZ_USER,
    SEHZ_DATE=V_SEHZ_DATE,
    SEHZ_USER=V_SEHZ_USER,
    TSKP_DATE=V_TSKP_DATE,
    TSTK_DATE=V_TSTK_DATE,
    SL_DAY=COMPUTE_BLDATE(V_SL_DATE, BJTS_CUR_LCXX_SB_DATE_005),
    SH_DAY=COMPUTE_BLDATE(V_FH_DATE, V_SL_DATE),
    HZ_DAY=COMPUTE_BLDATE(V_SEHZ_DATE, V_FH_DATE),
    KP_DAY=COMPUTE_BLDATE(V_TSKP_DATE, V_SEHZ_DATE)
             WHERE S.UUID=BJTS_CUR_LCXX_UUID_005;
            COMMIT;
          END IF;
        END IF;
        UPDATE GLXT_BB_SHXT_LCXX AS S
           SET SUM_DAY=S.SH_DAY + S.HZ_DAY + S.KP_DAY
         WHERE S.UUID=BJTS_CUR_LCXX_UUID_005;
        COMMIT;

        SET LN_I =LN_I +1;
      END;

  END LOOP BJTS_CURSOR_LOOP_005;
  CLOSE BJTS_CURSOR_005;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('             GLXT_BB_SHXT_LCXX.更新主流程信息！', LN_I));
      COMMIT;
    END IF;

    -- 部分流程开票日期与退库日期差距较大，导致退库日期没有赋值，进行补偿
    BEGIN
  DECLARE BJTS_CURSOR_DONE_004 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_LCXX_UUID_004 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_LCSLID_004 LONGTEXT;
  DECLARE BJTS_CURSOR_004 CURSOR FOR
SELECT T.UUID,T.LCSLID
                       FROM GLXT_BB_SHXT_LCXX T
                      WHERE T.TSKP_DATE>=ORA_DATE_ADD(LD_DEALDATA, -(7)) AND T.TSKP_DATE<=LD_DEALDATA AND T.TSTK_DATE IS NULL;
  OPEN BJTS_CURSOR_004;
  BJTS_CURSOR_LOOP_004: LOOP
    SET BJTS_CURSOR_DONE_004 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_004 = TRUE;
      FETCH BJTS_CURSOR_004 INTO BJTS_CUR_LCXX_UUID_004, BJTS_CUR_LCXX_LCSLID_004;
    END;
    IF BJTS_CURSOR_DONE_004 THEN
      LEAVE BJTS_CURSOR_LOOP_004;
    END IF;
      BEGIN
        BEGIN
  DECLARE BJTS_SQLCODE_006 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_006 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_006 = MYSQL_ERRNO, BJTS_SQLERRM_006 = MESSAGE_TEXT;
            SET V_TSTK_DATE =NULL;

  END;
SELECT XHRQ
            INTO V_TSTK_DATE
            FROM (SELECT (CASE WHEN S.SEHZ_ZZSTSE+S.BYHZ_ZZSTSE<>0 THEN S.XHRQ_TK ELSE S.XHRQ_XFS END) AS XHRQ
                    FROM CKTS_LC_SEHZXX S
                   WHERE S.LCSLID_FS=BJTS_CUR_LCXX_LCSLID_004
                     AND S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE+S.BYHZ_ZZSTSE+S.BYHZ_XFSTSE<>0
                   ORDER BY SEHZRQ) AS BJTS_DERIVED_004
           WHERE 1=1
LIMIT 1;
        END;
        IF V_TSTK_DATE > CURRENT_TIMESTAMP THEN
          SET V_TSTK_DATE =NULL;
        END IF;
        UPDATE GLXT_BB_SHXT_LCXX AS S
           SET TSTK_DATE=V_TSTK_DATE
         WHERE S.UUID=BJTS_CUR_LCXX_UUID_004;
        COMMIT;
      END;

  END LOOP BJTS_CURSOR_LOOP_004;
  CLOSE BJTS_CURSOR_004;
END;

    -- 流程未全部结束的，更新总数流程信息
    SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_003 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_LCXX_UUID_003 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_SBYWB_DM_003 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_LCSLID_003 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_SB_DATE_003 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_SL_DATE_003 LONGTEXT;
  DECLARE BJTS_CUR_LCXX_CKQYGLLB_DM_003 LONGTEXT;
  DECLARE BJTS_CURSOR_003 CURSOR FOR
SELECT T.UUID,T.SBYWB_DM,T.LCSLID,T.SB_DATE,T.SL_DATE,T.CKQYGLLB_DM FROM GLXT_BB_SHXT_LCXX T WHERE IFNULL(T.LCJSRQ, CAST('2100-12-31' AS DATE))>=LD_DEALDATA;
  OPEN BJTS_CURSOR_003;
  BJTS_CURSOR_LOOP_003: LOOP
    SET BJTS_CURSOR_DONE_003 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_003 = TRUE;
      FETCH BJTS_CURSOR_003 INTO BJTS_CUR_LCXX_UUID_003, BJTS_CUR_LCXX_SBYWB_DM_003, BJTS_CUR_LCXX_LCSLID_003, BJTS_CUR_LCXX_SB_DATE_003, BJTS_CUR_LCXX_SL_DATE_003, BJTS_CUR_LCXX_CKQYGLLB_DM_003;
    END;
    IF BJTS_CURSOR_DONE_003 THEN
      LEAVE BJTS_CURSOR_LOOP_003;
    END IF;
      BEGIN
        UPDATE GLXT_BB_SHXT_LCXX AS S
           SET USD_AMT = (SELECT R.SB_XSEMY
FROM CKTS_LC_SBXX R
                 WHERE R.UUID=BJTS_CUR_LCXX_UUID_003),
    RMB_AMT = (SELECT R.SB_XSERMB
FROM CKTS_LC_SBXX R
                 WHERE R.UUID=BJTS_CUR_LCXX_UUID_003),
    SB_TS_AMT = (SELECT R.SB_ZZSTSE+R.SB_XFSTSE
FROM CKTS_LC_SBXX R
                 WHERE R.UUID=BJTS_CUR_LCXX_UUID_003),
    SB_MD_AMT = (SELECT R.SB_MDSE
FROM CKTS_LC_SBXX R
                 WHERE R.UUID=BJTS_CUR_LCXX_UUID_003)
         WHERE S.UUID=BJTS_CUR_LCXX_UUID_003
           AND S.USD_AMT IS NULL;
        COMMIT;
        UPDATE GLXT_BB_SHXT_LCXX AS S
           SET BYBL_AMT = (SELECT IFNULL(SUM(R.BYBL_MDTSE), 0)
FROM CKTS_LC_SHXX R
                 WHERE R.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003),
    BYTS_AMT = (SELECT IFNULL(SUM(R.BY_MDTSE), 0)
FROM CKTS_LC_SHXX R
                 WHERE R.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003),
    ZH_AMT = (SELECT IFNULL(SUM(CASE WHEN R.LCSLID<>R.LCSLID_SB AND R.LCSLID_FS IS NULL THEN R.SB_MDTSE ELSE 0 END), 0)
FROM CKTS_LC_SHXX R
                 WHERE R.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003),
    ZBBL_AMT = (SELECT IFNULL(SUM(R.ZH_MDTSE), 0)
FROM CKTS_LC_SHXX R
                 WHERE R.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003),
    LCJSRQ = (SELECT CASE WHEN MAX(R.LCJSRQ)>CURRENT_TIMESTAMP THEN NULL ELSE MAX(R.LCJSRQ) END
FROM CKTS_LC_SHXX R
                 WHERE R.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)
         WHERE S.UUID=BJTS_CUR_LCXX_UUID_003;
        COMMIT;
        IF BJTS_CUR_LCXX_SBYWB_DM_003='A0305001' THEN
          UPDATE GLXT_BB_SHXT_LCXX AS S
             SET FH_TS_AMT = (SELECT IFNULL(SUM(R.FS_ZZSTSE+R.FS_XFSTSE), 0)
FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    FH_MD_AMT = (SELECT IFNULL(SUM(R.FS_MDSE), 0)
FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    ZK_AMT = (SELECT IFNULL(SUM(R.ZK_ZZSTSE+R.ZK_XFSTSE), 0)
FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003)
           WHERE S.UUID=BJTS_CUR_LCXX_UUID_003;
          COMMIT;
          UPDATE GLXT_BB_SHXT_LCXX AS S
             SET SEHZ_TS_AMT = (SELECT IFNULL(SUM(R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    SEHZ_MD_AMT = (SELECT IFNULL(SUM(R.SEHZ_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    BYHZ_TS_AMT = (SELECT IFNULL(SUM(R.BYHZ_ZZSTSE+R.BYHZ_XFSTSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    BYHZ_MD_AMT = (SELECT IFNULL(SUM(R.BYHZ_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    KP_TS_AMT = (SELECT IFNULL(SUM(CASE WHEN R.KPRQ<CURRENT_TIMESTAMP THEN R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE ELSE 0 END), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    KP_MD_AMT = (SELECT IFNULL(SUM(R.GKBL_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    TK_TS_AMT = (SELECT IFNULL(SUM(R.GKBL_ZZSTSE+R.GKBL_XFSTSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003),
    TK_MD_AMT = (SELECT IFNULL(SUM(R.GKBL_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =BJTS_CUR_LCXX_LCSLID_003)
           WHERE S.UUID=BJTS_CUR_LCXX_UUID_003;
          COMMIT;
        ELSE
          UPDATE GLXT_BB_SHXT_LCXX AS S
             SET FH_TS_AMT = (SELECT IFNULL(SUM(R.FS_ZZSTSE+R.FS_XFSTSE), 0)
FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    FH_MD_AMT = (SELECT IFNULL(SUM(R.FS_MDSE), 0)
FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    ZK_AMT = (SELECT IFNULL(SUM(R.ZK_ZZSTSE+R.ZK_XFSTSE), 0)
FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003))
           WHERE S.UUID=BJTS_CUR_LCXX_UUID_003;
          COMMIT;
          UPDATE GLXT_BB_SHXT_LCXX AS S
             SET SEHZ_TS_AMT = (SELECT IFNULL(SUM(R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    SEHZ_MD_AMT = (SELECT IFNULL(SUM(R.SEHZ_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    BYHZ_TS_AMT = (SELECT IFNULL(SUM(R.BYHZ_ZZSTSE+R.BYHZ_XFSTSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    BYHZ_MD_AMT = (SELECT IFNULL(SUM(R.BYHZ_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    KP_TS_AMT = (SELECT IFNULL(SUM(CASE WHEN R.KPRQ<CURRENT_TIMESTAMP THEN R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE ELSE 0 END), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    KP_MD_AMT = (SELECT IFNULL(SUM(R.GKBL_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    TK_TS_AMT = (SELECT IFNULL(SUM(R.GKBL_ZZSTSE+R.GKBL_XFSTSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003)),
    TK_MD_AMT = (SELECT IFNULL(SUM(R.GKBL_MDSE), 0)
FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003))
           WHERE S.UUID=BJTS_CUR_LCXX_UUID_003;
          COMMIT;
        END IF;
        UPDATE GLXT_BB_SHXT_LCXX AS S
           SET YSFW_FLAG='Y'
         WHERE S.UUID=BJTS_CUR_LCXX_UUID_003
           AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS R WHERE R.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003
                       UNION ALL
                       SELECT 1 FROM CKTS_SB_MDT_YFSJ U WHERE U.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003
                       UNION ALL
                       SELECT 1 FROM CKTS_SB_MTS_YSFW V WHERE V.LCSLID_SB=BJTS_CUR_LCXX_LCSLID_003);
        COMMIT;
        SET LN_I =LN_I +1;
      END;

  END LOOP BJTS_CURSOR_LOOP_003;
  CLOSE BJTS_CURSOR_003;
END;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('             GLXT_BB_SHXT_LCXX.更新流程总退税信息！', LN_I));
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('同步GLXT_BB_SHXT_LCXX处理成功！');
    COMMIT;
  END;

  -- 报关单征免退税性质处理
  BEGIN
  DECLARE BJTS_CURSOR_DONE_002 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGD_CKBGDH_002 LONGTEXT;
  DECLARE BJTS_CUR_BGD_DJXH_002 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKRQ_1_002 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKSP_DM_002 LONGTEXT;
  DECLARE BJTS_CUR_BGD_JGFS_DM_002 LONGTEXT;
  DECLARE BJTS_CUR_BGD_HZDWDQ_DM_002 LONGTEXT;
  DECLARE BJTS_CUR_BGD_JSMODE_002 LONGTEXT;
  DECLARE BJTS_CURSOR_002 CURSOR FOR
SELECT T.CKBGDH,T.DJXH,T.CKRQ_1,T.CKSP_DM,T.JGFS_DM,T.HZDWDQ_DM,IFNULL(S.JSMODE, '9') AS JSMODE
                    FROM CKTS_WBSJ_HG_BGD T
                    LEFT JOIN GLXT_BB_SHXT_DJXX S ON S.DJXH_JS=T.DJXH
                   WHERE T.SJTB_SJ>=LD_DEALDATA;
  OPEN BJTS_CURSOR_002;
  BJTS_CURSOR_LOOP_002: LOOP
    SET BJTS_CURSOR_DONE_002 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_002 = TRUE;
      FETCH BJTS_CURSOR_002 INTO BJTS_CUR_BGD_CKBGDH_002, BJTS_CUR_BGD_DJXH_002, BJTS_CUR_BGD_CKRQ_1_002, BJTS_CUR_BGD_CKSP_DM_002, BJTS_CUR_BGD_JGFS_DM_002, BJTS_CUR_BGD_HZDWDQ_DM_002, BJTS_CUR_BGD_JSMODE_002;
    END;
    IF BJTS_CURSOR_DONE_002 THEN
      LEAVE BJTS_CURSOR_LOOP_002;
    END IF;
    BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_004 = MYSQL_ERRNO, BJTS_SQLERRM_004 = MESSAGE_TEXT;
        -- 找不到对应的基本商品
        SET V_HYDXZQH_DM ='0000';

  END;
SELECT S.XZQH_DM
        INTO V_HYDXZQH_DM
        FROM DM_HGHYD S
       WHERE S.HGHYD_DM=BJTS_CUR_BGD_HZDWDQ_DM_002
         AND 1=1
LIMIT 1;
    END;

    BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
        -- 找不到对应的基本商品
        SET V_CKSPTSSPLX_DM ='0';
        SET V_TSL =0;

  END;
SELECT CKSPTSSPLX_DM,TSL
        INTO V_CKSPTSSPLX_DM, V_TSL
        FROM (SELECT CKSPTSSPLX_DM,TSL
                FROM (SELECT IFNULL(A.CKSPTSSPLX_DM, '0') AS CKSPTSSPLX_DM,A.TSL
                        FROM CKTS_DM_TSLVWK A
                       WHERE A.CKSP_DM LIKE ORA_CONCAT(BJTS_CUR_BGD_CKSP_DM_002, '%') AND (BJTS_CUR_BGD_CKRQ_1_002 BETWEEN A.YXQQ AND A.YXQZ) AND A.JBSPBZ='Y'
                       UNION ALL
                      SELECT IFNULL(B.CKSPTSSPLX_DM, '0') AS CKSPTSSPLX_DM,B.TSL
                        FROM CKTS_DM_TSLVWK B
                       WHERE B.CKSP_DM = SUBSTR(BJTS_CUR_BGD_CKSP_DM_002,1,8) AND (BJTS_CUR_BGD_CKRQ_1_002 BETWEEN B.YXQQ AND B.YXQZ) AND B.JBSPBZ='Y'
                      ) S
               ORDER BY TSL DESC) R
       WHERE 1=1
LIMIT 1;
    END;

    BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
        SET V_JGFSTSLX_DM ='1';

  END;
SELECT JGFSTSLX_DM
        INTO V_JGFSTSLX_DM
        FROM CKTS_DM_HGJGFS A
       WHERE A.JGFS_DM=BJTS_CUR_BGD_JGFS_DM_002;
    END;

    UPDATE CKTS_WBSJ_HG_BGD AS S
       SET HYDXZQH_DM=V_HYDXZQH_DM,
    ZMTBZ=CASE WHEN BJTS_CUR_BGD_JGFS_DM_002 IN ('0214','0255') THEN '2' -- 来料加工复出口业务，免税
                        WHEN V_CKSPTSSPLX_DM='1' THEN '1' -- 征税
                        WHEN V_CKSPTSSPLX_DM='2' THEN '2' -- 免税
                        WHEN V_JGFSTSLX_DM='0' THEN '0' -- 监管方式不退税
                        WHEN BJTS_CUR_BGD_JSMODE_002 IN ('3','9') THEN '3' -- 退税计算方式不退税
                        ELSE 'T' END,
    -- 退税
           S.TSL=CASE WHEN BJTS_CUR_BGD_JGFS_DM_002 IN ('0214','0255') THEN 0 -- 来料加工复出口业务，免税
                        WHEN V_CKSPTSSPLX_DM='1' THEN 0 -- 征税
                        WHEN V_CKSPTSSPLX_DM='2' THEN 0 -- 免税
                        WHEN V_JGFSTSLX_DM='0' THEN 0 -- 监管方式不退税
                        WHEN BJTS_CUR_BGD_JSMODE_002 IN ('3','9') THEN 0 -- 退税计算方式不退税
                        ELSE V_TSL END
     WHERE S.CKBGDH=BJTS_CUR_BGD_CKBGDH_002 AND S.DJXH=BJTS_CUR_BGD_DJXH_002;
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_002;
  CLOSE BJTS_CURSOR_002;
END;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_WBSJ_HG_BGD更新征免税标志完成！');
  COMMIT;

  -- 监测分析数据处理
  CALL PRO_DEAL_JCFX_NSR_BADJ();
  -- PRO_DEAL_JCFX_DATA_BGDMX;
  CALL PRO_DEAL_JCFX_DATA_TSSBMX();
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_JCFX_DATA_*成功！');
  COMMIT;

  -- 风险出口数据处理
  CALL PRO_FXGL_FXSPCK_DZXX();
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('风险出口数据处理成功！');
  COMMIT;

  -- 海外仓预退税企业处理
  CALL PRO_DEAL_HWCYTS();
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('海外仓预退税企业处理成功！');
  COMMIT;

  -- 绍兴报关单物流信息（车牌号、起运日期、起运地）提取
  CALL PRO_FXGL_SZYJ_WLXX();
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('报关单物流信息处理成功！');
  COMMIT;

  -- 长期未申报出口业务退税清理
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CQWSB_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_CQWSB_CKBGDH_001 LONGTEXT;
  DECLARE BJTS_CUR_CQWSB_CYTSSBJL_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT S.DJXH,S.CKBGDH,S.CYTSSBJL
                      FROM RCGL_CQWSB_DATA S
                     WHERE S.QYQR_ZT='3' AND S.JS_ZT='1' AND S.SWSH_ZT='1' AND S.YSB_TSE IS NULL;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CQWSB_DJXH_001, BJTS_CUR_CQWSB_CKBGDH_001, BJTS_CUR_CQWSB_CYTSSBJL_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    IF SUBSTR(BJTS_CUR_CQWSB_CYTSSBJL_001,5,3)='133' THEN
      -- 代理证明，退运证明
      SET LN_ZZS =0;
      SET LN_MDSE =0;
    ELSE
      -- 退税申报
      BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
          -- 找不到对应的记录，可能未复审、不予办理
          SET LN_ZZS =NULL;
          SET LN_MDSE =NULL;

  END;
SELECT SUM(TSE), SUM(MDE)
          INTO LN_ZZS, LN_MDSE
          FROM (SELECT SUM(A.TMSE) AS TSE, 0 AS MDE
                  FROM JCFX_DATA_TSSBMX A
                 WHERE A.DJXH=BJTS_CUR_CQWSB_DJXH_001
                   AND A.CKBGDH=BJTS_CUR_CQWSB_CKBGDH_001
                   AND A.SBYWLX<>'1'
                 UNION ALL
                SELECT SUM(ROUND(A.TMSE * CASE WHEN B.MDTSEHJ<=0 THEN 0 ELSE B.YTSE_1/B.MDTSEHJ END, 2)) AS TSE,
                       SUM(A.TMSE) - SUM(ROUND(A.TMSE * CASE WHEN B.MDTSEHJ<=0 THEN 0 ELSE B.YTSE_1/B.MDTSEHJ END, 2)) AS MDE
                  FROM JCFX_DATA_TSSBMX A
                 INNER JOIN CKTS_SB_MDT_SBDSHZ B ON B.LCSLID=A.LCSLID
                 WHERE A.DJXH=BJTS_CUR_CQWSB_DJXH_001
                   AND A.CKBGDH=BJTS_CUR_CQWSB_CKBGDH_001
                   AND A.SBYWLX='1') AS BJTS_DERIVED_005;
      END;
    END IF;
    IF LN_ZZS IS NOT NULL THEN
      UPDATE RCGL_CQWSB_DATA AS T
         SET YSB_TSE=LN_ZZS,
    YSB_MDE=LN_MDSE
       WHERE T.DJXH=BJTS_CUR_CQWSB_DJXH_001
         AND T.CKBGDH=BJTS_CUR_CQWSB_CKBGDH_001;
      COMMIT;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('长期未申报出口业务退税清理成功！');
  COMMIT;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_AFTER_ETL处理成功！');
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DEAL_AFTER_ETL.sql

-- ======================================================================
-- [009/146] BEGIN SOURCE: PRO_DEAL_HWCYTS.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_HWCYTS$$

CREATE PROCEDURE PRO_DEAL_HWCYTS()
/*
 * 处理海外仓预退税数据
 */
routine_body: BEGIN
  DECLARE V_BEGINDATE      DATETIME;
  DECLARE LC_SBYY          VARCHAR(2000);

  SET V_BEGINDATE = ORA_DATE_ADD(DATE(CURRENT_TIMESTAMP), -(3));

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('RCGL_SDQY_9810数据处理开始...');
  COMMIT;

  -- 免抵退税
  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_003;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MDT_CKMX-->RCGL_SDQY_9810失败！', LC_SBYY);
      COMMIT;

  END;
INSERT INTO RCGL_SDQY_9810 (ID,DJXH,NSRSBH,NSRMC,SWJGDM,QYBJ,CJR,CRTIME)
SELECT B.DJXH,B.DJXH,B.NSRSBH,B.NSRMC,B.TSSWJG_DM,'Y','SYSTEM',CURRENT_TIMESTAMP
FROM (
SELECT DISTINCT S.DJXH,IFNULL(T.SHXYNO, T.NSRDJNO) AS NSRSBH,T.NSRMC,S.TSSWJG_DM
                  FROM CKTS_SB_MDT_CKMX S
                 INNER JOIN GLXT_BB_SHXT_DJXX T ON T.DJXH_JS=S.DJXH
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND REGEXP_LIKE(S.CKTMSYWLXDMJH,'HWC-YT')
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM RCGL_SDQY_9810 AS A WHERE A.DJXH=B.DJXH
);
    COMMIT;
  END;

  -- 免退税
  BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_002;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MTS_CKMX-->RCGL_SDQY_9810失败！', LC_SBYY);
      COMMIT;

  END;
INSERT INTO RCGL_SDQY_9810 (ID,DJXH,NSRSBH,NSRMC,SWJGDM,QYBJ,CJR,CRTIME)
SELECT B.DJXH,B.DJXH,B.NSRSBH,B.NSRMC,B.TSSWJG_DM,'Y','SYSTEM',CURRENT_TIMESTAMP
FROM (
SELECT DISTINCT S.DJXH,IFNULL(T.SHXYNO, T.NSRDJNO) AS NSRSBH,T.NSRMC,S.TSSWJG_DM
                  FROM CKTS_SB_MTS_CKMX S
                 INNER JOIN GLXT_BB_SHXT_DJXX T ON T.DJXH_JS=S.DJXH
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND REGEXP_LIKE(S.CKTMSYWLXDMJH,'HWC-YT')
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM RCGL_SDQY_9810 AS A WHERE A.DJXH=B.DJXH
);
    COMMIT;
  END;

  -- 代办退税
  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_001;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_WZF_CKMX-->RCGL_SDQY_9810失败！', LC_SBYY);
      COMMIT;

  END;
INSERT INTO RCGL_SDQY_9810 (ID,DJXH,NSRSBH,NSRMC,SWJGDM,QYBJ,CJR,CRTIME)
SELECT B.DJXH,B.DJXH,B.NSRSBH,B.NSRMC,B.TSSWJG_DM,'Y','SYSTEM',CURRENT_TIMESTAMP
FROM (
SELECT DISTINCT S.DJXH,IFNULL(T.SHXYNO, T.NSRDJNO) AS NSRSBH,T.NSRMC,S.TSSWJG_DM
                  FROM CKTS_SB_WZF_CKMX S
                 INNER JOIN GLXT_BB_SHXT_DJXX T ON T.DJXH_JS=S.DJXH
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND REGEXP_LIKE(S.CKTMSYWLXDMJH,'HWC-YT')
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM RCGL_SDQY_9810 AS A WHERE A.DJXH=B.DJXH
);
    COMMIT;
  END;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('RCGL_SDQY_9810数据处理结束。');
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DEAL_HWCYTS.sql

-- ======================================================================
-- [010/146] BEGIN SOURCE: PRO_DEAL_JCFX_DATA_BGDMX.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_JCFX_DATA_BGDMX$$

CREATE PROCEDURE PRO_DEAL_JCFX_DATA_BGDMX()
routine_body: BEGIN
  DECLARE V_BEGINDATE      DATETIME;
  DECLARE V_TSSWJG_DM      VARCHAR(11);
  DECLARE V_CKSPTSSPLX_DM  CHAR(1);
  DECLARE V_TSL            DECIMAL(18,2);
  DECLARE V_JGFSTSLX_DM    CHAR(1);
  DECLARE V_HYDXZQH_DM     CHAR(4);
  DECLARE LN_ROWS          BIGINT;
  DECLARE LN_REC           BIGINT;
  DECLARE LN_UNIT          BIGINT;

  SELECT DATE(MAX(T.SJGXSJ))
    INTO V_BEGINDATE
    FROM JCFX_DATA_BGDMX T;

  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_WBSJ_HG_BGD T
   WHERE T.SJTB_SJ>=V_BEGINDATE;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('PRO_DEAL_JCFX_DATA_BGDMX 开始运行，记录总数：', LN_ROWS));
  COMMIT;

  -- 增量用数据更新时间
  SET LN_REC =0;
  SET LN_UNIT =0;
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGD_UUID_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_TSSWJG_DM_1_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKBGDH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKNY_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKRQ_1_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKSP_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_HGGQKA_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_MYGDQSZ_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_JGFS_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_HZDWDQ_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKSL_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_MYLAJ_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_RMBLAJ_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_TSSBSL_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_DLSBSL_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_TYSL_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_MYLAJ_YSB_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_SJTB_SJ_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.UUID,T.TSSWJG_DM_1,T.DJXH,T.CKBGDH,T.CKNY,T.CKRQ_1,T.CKSP_DM,
                         T.HGGQKA_DM,T.MYGDQSZ_DM,T.JGFS_DM,T.HZDWDQ_DM,
                         T.CKSL,T.MYLAJ,T.RMBLAJ,T.TSSBSL,T.DLSBSL,T.TYSL,
                         CASE WHEN T.TSSBSL+T.DLSBSL+T.TYSL>T.CKSL+1 THEN T.CKSL / (T.TSSBSL+T.DLSBSL+T.TYSL) ELSE 1 END
                           * (T.TSSBMYLAJ + T.DLSBMYLAJ + T.TYMYLAJ) AS MYLAJ_YSB,
                         T.SJTB_SJ
                    FROM CKTS_WBSJ_HG_BGD T
                   WHERE T.SJTB_SJ>=V_BEGINDATE;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_BGD_UUID_001, BJTS_CUR_BGD_TSSWJG_DM_1_001, BJTS_CUR_BGD_DJXH_001, BJTS_CUR_BGD_CKBGDH_001, BJTS_CUR_BGD_CKNY_001, BJTS_CUR_BGD_CKRQ_1_001, BJTS_CUR_BGD_CKSP_DM_001, BJTS_CUR_BGD_HGGQKA_DM_001, BJTS_CUR_BGD_MYGDQSZ_DM_001, BJTS_CUR_BGD_JGFS_DM_001, BJTS_CUR_BGD_HZDWDQ_DM_001, BJTS_CUR_BGD_CKSL_001, BJTS_CUR_BGD_MYLAJ_001, BJTS_CUR_BGD_RMBLAJ_001, BJTS_CUR_BGD_TSSBSL_001, BJTS_CUR_BGD_DLSBSL_001, BJTS_CUR_BGD_TYSL_001, BJTS_CUR_BGD_MYLAJ_YSB_001, BJTS_CUR_BGD_SJTB_SJ_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_004 = MYSQL_ERRNO, BJTS_SQLERRM_004 = MESSAGE_TEXT;
        -- 找不到对应的基本商品
        INSERT INTO JCFX_DATA_BGDMX(UUID,TSSWJG_DM,DJXH,CKBGDH,NY,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,MYLAJ,RMBLAJ,MYLAJ_YSB,SJGXSJ)
             VALUES (BJTS_CUR_BGD_UUID_001,BJTS_CUR_BGD_TSSWJG_DM_1_001,BJTS_CUR_BGD_DJXH_001,BJTS_CUR_BGD_CKBGDH_001,BJTS_CUR_BGD_CKNY_001,BJTS_CUR_BGD_CKRQ_1_001,BJTS_CUR_BGD_CKSP_DM_001,BJTS_CUR_BGD_HGGQKA_DM_001,BJTS_CUR_BGD_MYGDQSZ_DM_001,BJTS_CUR_BGD_JGFS_DM_001,BJTS_CUR_BGD_HZDWDQ_DM_001,BJTS_CUR_BGD_MYLAJ_001,BJTS_CUR_BGD_RMBLAJ_001,BJTS_CUR_BGD_MYLAJ_YSB_001,BJTS_CUR_BGD_SJTB_SJ_001);
        COMMIT;

  END;
SELECT A.TSSWJG_DM
        INTO V_TSSWJG_DM
        FROM JCFX_DATA_BGDMX A
       WHERE A.DJXH=BJTS_CUR_BGD_DJXH_001 AND A.CKBGDH=BJTS_CUR_BGD_CKBGDH_001;

      IF V_TSSWJG_DM=BJTS_CUR_BGD_TSSWJG_DM_1_001 THEN
        UPDATE JCFX_DATA_BGDMX AS A
           SET UUID=BJTS_CUR_BGD_UUID_001,
    NY=BJTS_CUR_BGD_CKNY_001,
    CKRQ=BJTS_CUR_BGD_CKRQ_1_001,
    CKSP_DM=BJTS_CUR_BGD_CKSP_DM_001,
    HGGQKA_DM=BJTS_CUR_BGD_HGGQKA_DM_001,
    MYGDQSZ_DM=BJTS_CUR_BGD_MYGDQSZ_DM_001,
    JGFS_DM=BJTS_CUR_BGD_JGFS_DM_001,
    HZDWDQ_DM=BJTS_CUR_BGD_HZDWDQ_DM_001,
    MYLAJ=BJTS_CUR_BGD_MYLAJ_001,
    RMBLAJ=BJTS_CUR_BGD_RMBLAJ_001,
    MYLAJ_YSB=BJTS_CUR_BGD_MYLAJ_YSB_001,
    SJGXSJ=BJTS_CUR_BGD_SJTB_SJ_001
         WHERE A.DJXH=BJTS_CUR_BGD_DJXH_001 AND A.CKBGDH=BJTS_CUR_BGD_CKBGDH_001;
        COMMIT;
      ELSE
        DELETE FROM JCFX_DATA_BGDMX AS A WHERE A.DJXH=BJTS_CUR_BGD_DJXH_001 AND A.CKBGDH=BJTS_CUR_BGD_CKBGDH_001;
        COMMIT;
        INSERT INTO JCFX_DATA_BGDMX(UUID,TSSWJG_DM,DJXH,CKBGDH,NY,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,MYLAJ,RMBLAJ,MYLAJ_YSB,SJGXSJ)
             VALUES (BJTS_CUR_BGD_UUID_001,BJTS_CUR_BGD_TSSWJG_DM_1_001,BJTS_CUR_BGD_DJXH_001,BJTS_CUR_BGD_CKBGDH_001,BJTS_CUR_BGD_CKNY_001,BJTS_CUR_BGD_CKRQ_1_001,BJTS_CUR_BGD_CKSP_DM_001,BJTS_CUR_BGD_HGGQKA_DM_001,BJTS_CUR_BGD_MYGDQSZ_DM_001,BJTS_CUR_BGD_JGFS_DM_001,BJTS_CUR_BGD_HZDWDQ_DM_001,BJTS_CUR_BGD_MYLAJ_001,BJTS_CUR_BGD_RMBLAJ_001,BJTS_CUR_BGD_MYLAJ_YSB_001,BJTS_CUR_BGD_SJTB_SJ_001);
        COMMIT;
      END IF;
    END;

    BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
        -- 找不到对应的基本商品
        SET V_HYDXZQH_DM ='0000';

  END;
SELECT S.XZQH_DM
        INTO V_HYDXZQH_DM
        FROM DM_HGHYD S
       WHERE S.HGHYD_DM=BJTS_CUR_BGD_HZDWDQ_DM_001
         AND 1=1
LIMIT 1;
    END;

    BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
        -- 找不到对应的基本商品
        SET V_CKSPTSSPLX_DM ='0';
        SET V_TSL =0;

  END;
SELECT CKSPTSSPLX_DM,TSL
        INTO V_CKSPTSSPLX_DM, V_TSL
        FROM (SELECT CKSPTSSPLX_DM,TSL
                FROM (SELECT IFNULL(A.CKSPTSSPLX_DM, '0') AS CKSPTSSPLX_DM,A.TSL
                        FROM CKTS_DM_TSLVWK A
                       WHERE A.CKSP_DM LIKE ORA_CONCAT(BJTS_CUR_BGD_CKSP_DM_001, '%') AND (BJTS_CUR_BGD_CKRQ_1_001 BETWEEN A.YXQQ AND A.YXQZ) AND A.JBSPBZ='Y'
                       UNION ALL
                      SELECT IFNULL(B.CKSPTSSPLX_DM, '0') AS CKSPTSSPLX_DM,B.TSL
                        FROM CKTS_DM_TSLVWK B
                       WHERE B.CKSP_DM = SUBSTR(BJTS_CUR_BGD_CKSP_DM_001,1,8) AND (BJTS_CUR_BGD_CKRQ_1_001 BETWEEN B.YXQQ AND B.YXQZ) AND B.JBSPBZ='Y'
                      ) S
               ORDER BY TSL DESC) R
       WHERE 1=1
LIMIT 1;
    END;

    BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
        SET V_JGFSTSLX_DM ='1';

  END;
SELECT JGFSTSLX_DM
        INTO V_JGFSTSLX_DM
        FROM CKTS_DM_HGJGFS A
       WHERE A.JGFS_DM=BJTS_CUR_BGD_JGFS_DM_001;
    END;

    IF V_CKSPTSSPLX_DM='1' THEN
      UPDATE JCFX_DATA_BGDMX AS T
         SET MYLAJ_ZS=T.MYLAJ,
    HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.CKBGDH=BJTS_CUR_BGD_CKBGDH_001;
    ELSEIF V_CKSPTSSPLX_DM='2' THEN
      UPDATE JCFX_DATA_BGDMX AS T
         SET MYLAJ_MS=T.MYLAJ,
    HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.CKBGDH=BJTS_CUR_BGD_CKBGDH_001;
    ELSEIF V_JGFSTSLX_DM='0' THEN
      UPDATE JCFX_DATA_BGDMX AS T
         SET MYLAJ_BTS=T.MYLAJ,
    HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.CKBGDH=BJTS_CUR_BGD_CKBGDH_001;
    ELSE
      UPDATE JCFX_DATA_BGDMX AS T
         SET MYLAJ_KTS=T.MYLAJ,
    TSL=V_TSL,
    YGTMSE=ROUND(T.RMBLAJ * V_TSL / 100,2),
    HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.CKBGDH=BJTS_CUR_BGD_CKBGDH_001;
    END IF;
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_JCFX_DATA_BGDMX 处理结束！');
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DEAL_JCFX_DATA_BGDMX.sql

-- ======================================================================
-- [011/146] BEGIN SOURCE: PRO_DEAL_JCFX_DATA_QYYHZ_INIT.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_JCFX_DATA_QYYHZ_INIT$$

CREATE PROCEDURE PRO_DEAL_JCFX_DATA_QYYHZ_INIT()
/*
 * 每月月初，取JCFX_NSR_BADJ_TOHZ表中记录并初始化JCFX_DATA_QYYHZ
 */
routine_body: BEGIN
  DECLARE LD_ENDMONTH          DATETIME;             -- 上上月，汇总截止月份，老企业汇总起始月份
  DECLARE LD_DEALMONTH         DATETIME;             -- 按月汇总的控制时间（月初）
  DECLARE LD_NEXTMONTH         DATETIME;             -- 按月汇总的控制时间（下月初）
  DECLARE LC_NY                VARCHAR(6);      -- 开票月份，财务报表、纳税申报表所属期止月份，免抵退申报所属期或免退税申报月份
  DECLARE LD_NEWMONTH          DATETIME;             -- 新增商品、供应商的控制时间（月初）
  DECLARE LC_NEWNY             VARCHAR(6);      -- 新增商品、供应商的控制时间（月份）
  -- JCFX_DATA_QYYHZ.ck
  DECLARE LN_CK_SB_XSEMY        DECIMAL(18,2);     -- 出口_销售美元
  DECLARE LN_CK_SB_XSERMB       DECIMAL(18,2);     -- 出口_销售人民币
  DECLARE LN_CK_SB_JSJE         DECIMAL(18,2);     -- 出口_计税金额
  DECLARE LN_CK_SB_JHCB         DECIMAL(18,2);     -- 出口_进货成本
  DECLARE LN_CK_SB_TSE          DECIMAL(18,2);     -- 出口_申报退税
  DECLARE LN_CK_SB_MDE          DECIMAL(18,2);     -- 出口_申报免抵
  DECLARE LN_CK_HZ_TSE          DECIMAL(18,2);     -- 出口_核准退税
  DECLARE LN_CK_HZ_MDE          DECIMAL(18,2);     -- 出口_核准免抵
  DECLARE LN_CK_BL_TSE          DECIMAL(18,2);     -- 出口_办理退税
  DECLARE LN_CK_BL_MDE          DECIMAL(18,2);     -- 出口_办理免抵
  DECLARE LN_CK_XZSP_CKE        DECIMAL(18,2);     -- 出口_新增商品出口额
  DECLARE LN_CK_XZGHS_JSJE      DECIMAL(18,2);     -- 出口_新增供应商计税金额
  DECLARE LN_CK_TSSP_CKE        DECIMAL(18,2);     -- 出口_特殊商品出口额
  DECLARE LN_CK_MGSP_CKE        DECIMAL(18,2);     -- 出口_敏感商品出口额
  DECLARE LN_CK_MGKA_CKE        DECIMAL(18,2);     -- 出口_敏感口岸出口额
  DECLARE LN_CNT                INTEGER;          -- 统计数

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_NSR_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_NSR_NSRSBH_001 LONGTEXT;
  DECLARE BJTS_CUR_NSR_SHXYDM_001 LONGTEXT;
  DECLARE BJTS_CUR_NSR_SWJGDM_001 LONGTEXT;
  DECLARE BJTS_CUR_NSR_JLXZSJ_001 LONGTEXT;
  DECLARE BJTS_CUR_NSR_BACHSJ_001 LONGTEXT;
  DECLARE BJTS_CUR_NSR_JCFXSJ_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DJXH,NSRSBH,IFNULL(SHXYDM, NSRSBH) AS SHXYDM,SWJGDM,JLXZSJ,BACHSJ,JCFXSJ FROM JCFX_NSR_BADJ_TOHZ;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_NSR_DJXH_001, BJTS_CUR_NSR_NSRSBH_001, BJTS_CUR_NSR_SHXYDM_001, BJTS_CUR_NSR_SWJGDM_001, BJTS_CUR_NSR_JLXZSJ_001, BJTS_CUR_NSR_BACHSJ_001, BJTS_CUR_NSR_JCFXSJ_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    IF BJTS_CUR_NSR_JCFXSJ_001 IS NULL THEN -- 根据上一次监测分析时间是否为空判定是否新增企业
      SET LD_DEALMONTH =DATE_ADD(MAKEDATE(YEAR(BJTS_CUR_NSR_JLXZSJ_001), 1), INTERVAL -24 MONTH); -- 新增企业汇总起始月份，上上年
    ELSE
      BEGIN
  DECLARE BJTS_SQLCODE_007 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_007 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_007 = MYSQL_ERRNO, BJTS_SQLERRM_007 = MESSAGE_TEXT;
          SET LD_DEALMONTH = NULL;

  END;
SELECT STR_TO_DATE(ORA_CONCAT(MAX(S.NY), '01'), '%Y%m%d')
          INTO LD_DEALMONTH
          FROM JCFX_DATA_QYYHZ S
          WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001;
      END;
      IF LD_DEALMONTH IS NULL THEN
        SET LD_DEALMONTH =DATE_ADD(CAST(DATE_FORMAT(BJTS_CUR_NSR_JCFXSJ_001, '%Y-%m-01') AS DATETIME), INTERVAL -2 MONTH); -- 老企业汇总起始月份，上上月
      END IF;
    END IF;
    -- 终止月份，上上月、备案撤回月份（未撤回按系统日期比较）较小者
    SET LD_ENDMONTH =LEAST(DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -2 MONTH),CAST(DATE_FORMAT(IFNULL(BJTS_CUR_NSR_BACHSJ_001, CURRENT_TIMESTAMP), '%Y-%m-01') AS DATETIME));

    -- DEBUG
    BJTS_LOOP_001: LOOP
      IF LD_DEALMONTH > LD_ENDMONTH THEN LEAVE BJTS_LOOP_001; END IF;
      -- 日期赋值
      SET LD_NEXTMONTH =DATE_ADD(LD_DEALMONTH, INTERVAL 1 MONTH);
      SET LC_NY =DATE_FORMAT(LD_DEALMONTH, '%Y%m');
      SET LD_NEWMONTH =DATE_ADD(LD_DEALMONTH, INTERVAL -6 MONTH);
      SET LC_NEWNY =DATE_FORMAT(LD_NEWMONTH, '%Y%m');

      -- JCFX_DATA_QYYHZ
      BEGIN
        SELECT COUNT(*) INTO LN_CNT FROM JCFX_DATA_QYYHZ T WHERE T.DJXH=BJTS_CUR_NSR_DJXH_001 AND T.NY=LC_NY;
        IF LN_CNT = 0 THEN
          INSERT INTO JCFX_DATA_QYYHZ(DJXH,NY,NSRSBH,SHXYDM)
          VALUES(BJTS_CUR_NSR_DJXH_001,LC_NY,BJTS_CUR_NSR_NSRSBH_001,BJTS_CUR_NSR_SHXYDM_001);
          COMMIT;
        END IF;

        SELECT COUNT(*) INTO LN_CNT FROM JCFX_DATA_QYYHZ T WHERE T.DJXH=BJTS_CUR_NSR_DJXH_001 AND T.NY=LC_NY AND IFNULL(T.BJTS_ZT, 'N') <> 'Y';
        -- 本地BJTS抽取
        IF LN_CNT > 0 THEN
          -- LN_CK_SB_XSEMY,LN_CK_SB_XSERMB,LN_CK_SB_JSJE,LN_CK_SB_JHCB
          BEGIN
  DECLARE BJTS_SQLCODE_006 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_006 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_006 = MYSQL_ERRNO, BJTS_SQLERRM_006 = MESSAGE_TEXT;
              SET LN_CK_SB_XSEMY =0;
              SET LN_CK_SB_XSERMB =0;
              SET LN_CK_SB_JSJE =0;
              SET LN_CK_SB_JHCB =0;

  END;
SELECT IFNULL(SUM(XSEMY), 0),IFNULL(SUM(XSERMB), 0),IFNULL(SUM(JSJE), 0),IFNULL(SUM(JHCB), 0)
              INTO LN_CK_SB_XSEMY, LN_CK_SB_XSERMB, LN_CK_SB_JSJE, LN_CK_SB_JHCB
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY, SUM(T.RMBLAJ) AS XSERMB, SUM(T.RMBLAJ) AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.YSFWYYEMY) AS XSEMY, SUM(T.YSFWYYERMB) AS XSERMB, SUM(T.YSFWYYERMB) AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_YFSJ T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.YSFWYYEMY) AS XSEMY, SUM(T.YSFWYYERMB) AS XSERMB, SUM(T.YSFWYYERMB) AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_GJYS T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY, SUM(T.MYLAJ * R.RMBLAJ / R.MYLAJ) AS XSERMB, 0 AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     INNER JOIN CKTS_WBSJ_HG_BGD R ON R.DJXH=BJTS_CUR_NSR_DJXH_001 AND R.CKBGDH=T.CKBGDH
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT 0 AS XSEMY, 0 AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_JHMX T ON T.LCSLID_SB=S.LCSLID_SB AND T.SZ='V'
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.SKJEMY) AS XSEMY, SUM(T.BQQRYSFWYYSRRMBJE) AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_YSFW T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY, SUM(T.MYLAJ * R.RMBLAJ / R.MYLAJ) AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     INNER JOIN CKTS_WBSJ_HG_BGD R ON R.DJXH=BJTS_CUR_NSR_DJXH_001 AND R.CKBGDH=T.CKBGDH
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(R.MYLAJ) AS XSEMY, SUM(R.RMBLAJ) AS XSERMB, SUM(T.SBZYJZ) AS JSJE, SUM(T.SBZYJZ * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_YS_SBMX T ON T.LCSLID=S.LCSLID_SB
                     INNER JOIN CKTS_WBSJ_HG_BGD R ON R.DJXH=BJTS_CUR_NSR_DJXH_001 AND R.CKBGDH=T.CKBGDH
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0303001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT 0 AS XSEMY, 0 AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_GJ_SBMX T ON T.LCSLID=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0304001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL) TT;
          END;

          -- LN_CK_SB_TSE,LN_CK_SB_MDE
          SELECT IFNULL(SUM(S.SB_ZZSTSE+S.SB_XFSTSE), 0),IFNULL(SUM(S.SB_MDSE), 0)
            INTO LN_CK_SB_TSE,LN_CK_SB_MDE
            FROM CKTS_LC_SBXX S
           WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001
             AND ((S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY) OR ( S.SBYWB_DM<>'A0305001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH))
             AND S.ZFBZ IS NULL;

          -- LN_CK_HZ_TSE,LN_CK_HZ_MDE
          SELECT IFNULL(SUM(S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE), 0),IFNULL(SUM(S.SEHZ_MDSE), 0)
            INTO LN_CK_HZ_TSE,LN_CK_HZ_MDE
            FROM CKTS_LC_SEHZXX S
           WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SEHZRQ>=LD_DEALMONTH AND S.SEHZRQ<LD_NEXTMONTH;

          -- LN_CK_BL_TSE
          SELECT IFNULL(SUM(S.SE), 0)
            INTO LN_CK_BL_TSE
            FROM CKTS_ZS_SRTHS S
           WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.THRQ_1>=LD_DEALMONTH AND S.THRQ_1<LD_NEXTMONTH AND S.TTSJLX_DM='01' AND S.TZLX_DM IN ('1','4');

          -- LN_CK_BL_MDE
          SELECT IFNULL(SUM(S.JE), 0)
            INTO LN_CK_BL_MDE
            FROM CKTS_ZS_TKGZ S
           WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.GKGZRQ>=LD_DEALMONTH AND S.GKGZRQ<LD_NEXTMONTH AND S.TZSLY='3' AND S.TZLX_DM='1' AND S.GZBZ='Y';

          -- LN_CK_XZSP_CKE             --出口_新增商品出口额
          BEGIN
  DECLARE BJTS_SQLCODE_005 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_005 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_005 = MYSQL_ERRNO, BJTS_SQLERRM_005 = MESSAGE_TEXT;
              SET LN_CK_XZSP_CKE =0;

  END;
SELECT IFNULL(SUM(XSEMY), 0)
              INTO LN_CK_XZSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_MDT_CKMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=BJTS_CUR_NSR_DJXH_001 AND S1.SBYWB_DM='A0305001' AND S1.SSQ>=LC_NEWNY AND S1.SSQ<LC_NY AND S1.ZFBZ IS NULL
                                          AND T1.CKSP_DM LIKE ORA_CONCAT(SUBSTR(T.CKSP_DM,1,4), '%'))
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_MTS_CKMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=BJTS_CUR_NSR_DJXH_001 AND S1.SBYWB_DM='A0301001' AND S1.SBRQ>=LD_NEWMONTH AND S1.SBRQ<LD_DEALMONTH AND S1.ZFBZ IS NULL
                                          AND T1.CKSP_DM LIKE ORA_CONCAT(SUBSTR(T.CKSP_DM,1,4), '%'))
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_WZF_CKMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=BJTS_CUR_NSR_DJXH_001 AND S1.SBYWB_DM='A0310001' AND S1.SBRQ>=LD_NEWMONTH AND S1.SBRQ<LD_DEALMONTH AND S1.ZFBZ IS NULL
                                          AND T1.CKSP_DM LIKE ORA_CONCAT(SUBSTR(T.CKSP_DM,1,4), '%')
                                          AND T1.WTDBTSSCQYNSRSBH=T.WTDBTSSCQYNSRSBH) ) TT;
          END;

          -- LN_CK_XZGHS_JSJE           --出口_新增供应商计税金额
          BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_004 = MYSQL_ERRNO, BJTS_SQLERRM_004 = MESSAGE_TEXT;
              SET LN_CK_XZGHS_JSJE =0;

  END;
SELECT IFNULL(SUM(JSJE), 0)
              INTO LN_CK_XZGHS_JSJE
              FROM (SELECT SUM(T.JSJE) AS JSJE
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_JHMX T ON T.LCSLID_SB=S.LCSLID_SB AND T.SZ='V'
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_MTS_JHMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=BJTS_CUR_NSR_DJXH_001 AND S1.SBYWB_DM='A0301001' AND S1.SBRQ>=LD_NEWMONTH AND S1.SBRQ<LD_DEALMONTH AND S1.ZFBZ IS NULL
                                          AND T1.GHFNSRSBH_1=T.GHFNSRSBH_1) ) TT;
          END;

          -- LN_CK_TSSP_CKE             --出口_特殊商品出口额
          BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
              SET LN_CK_TSSP_CKE =0;

  END;
SELECT IFNULL(SUM(XSEMY), 0)
              INTO LN_CK_TSSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_TSSP R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_TSSP R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_TSSP R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001) ) TT;
          END;

          -- LN_CK_MGSP_CKE             --出口_敏感商品出口额
          BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
              SET LN_CK_MGSP_CKE =0;

  END;
SELECT IFNULL(SUM(XSEMY), 0)
              INTO LN_CK_MGSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_MGSP R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_MGSP R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_MGSP R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001) ) TT;
          END;

          -- LN_CK_MGKA_CKE             --出口_敏感口岸出口额
          BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
              SET LN_CK_MGSP_CKE =0;

  END;
SELECT IFNULL(SUM(XSEMY), 0)
              INTO LN_CK_MGSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND T.HGCODE IN (SELECT R.HGGQKA_DM FROM JCFX_CS_MGKA R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.HGCODE IN (SELECT R.HGGQKA_DM FROM JCFX_CS_MGKA R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.HGCODE IN (SELECT R.HGGQKA_DM FROM JCFX_CS_MGKA R WHERE R.SWJGDM=BJTS_CUR_NSR_SWJGDM_001) ) TT;
          END;

          UPDATE JCFX_DATA_QYYHZ AS A
             SET CK_SB_XSEMY=LN_CK_SB_XSEMY,
    CK_SB_XSERMB=LN_CK_SB_XSERMB,
    CK_SB_JSJE=LN_CK_SB_JSJE,
    CK_SB_JHCB=LN_CK_SB_JHCB,
    CK_SB_TSE=LN_CK_SB_TSE,
    CK_SB_MDE=LN_CK_SB_MDE,
    CK_HZ_TSE=LN_CK_HZ_TSE,
    CK_HZ_MDE=LN_CK_HZ_MDE,
    CK_BL_TSE=LN_CK_BL_TSE,
    CK_BL_MDE=LN_CK_BL_MDE,
    CK_XZSP_CKE=LN_CK_XZSP_CKE,
    CK_XZGHS_JSJE=LN_CK_XZGHS_JSJE,
    CK_TSSP_CKE=LN_CK_TSSP_CKE,
    CK_MGSP_CKE=LN_CK_MGSP_CKE,
    CK_MGKA_CKE=LN_CK_MGKA_CKE,
    BJTS_ZT='Y',
    BJTS_SJ=CURRENT_TIMESTAMP,
    SJGXSJ=CURRENT_TIMESTAMP
          WHERE DJXH=BJTS_CUR_NSR_DJXH_001 AND NY=LC_NY;
          COMMIT;

        END IF;
      END;

      SET LD_DEALMONTH =LD_NEXTMONTH;
    END LOOP BJTS_LOOP_001;

    UPDATE JCFX_NSR_BADJ_TOHZ SET JCFXSJ = CURRENT_TIMESTAMP WHERE DJXH=BJTS_CUR_NSR_DJXH_001;
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  DO '检测分析初始化完成';
  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DEAL_JCFX_DATA_QYYHZ_INIT.sql

-- ======================================================================
-- [012/146] BEGIN SOURCE: PRO_DEAL_JCFX_DATA_TSSBMX.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_JCFX_DATA_TSSBMX$$

CREATE PROCEDURE PRO_DEAL_JCFX_DATA_TSSBMX()
routine_body: BEGIN
  DECLARE V_BEGINDATE      DATETIME;
  DECLARE V_RMBLAJ         DECIMAL(18,2);
  DECLARE V_GHFNSRSBH      VARCHAR(30);
  DECLARE V_HYDXZQH_DM     VARCHAR(10);
  DECLARE LN_ROWS          BIGINT;
  DECLARE LC_SBYY          VARCHAR(2000);

  SET @BJTS_DYNAMIC_SQL_001 = 'ALTER TABLE JCFX_DATA_TSSBMX ENABLE ROW MOVEMENT';
PREPARE BJTS_DYNAMIC_STMT_001 FROM @BJTS_DYNAMIC_SQL_001;
EXECUTE BJTS_DYNAMIC_STMT_001;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_001;

  SELECT ORA_DATE_ADD(DATE(MAX(T.SJGXSJ)), -(1))
    INTO V_BEGINDATE
    FROM JCFX_DATA_TSSBMX T;

  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_SB_MDT_CKMX S
   WHERE S.SJTB_SJ>=V_BEGINDATE
     AND IFNULL(S.BYBLBZ, 'N')='N';

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('CKTS_SB_MDT_CKMX-->JCFX_DATA_TSSBMX开始运行，记录总数：', LN_ROWS));
  COMMIT;

  -- 免抵退税
  BEGIN
  DECLARE BJTS_SQLCODE_008 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_008 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_008 = MYSQL_ERRNO, BJTS_SQLERRM_008 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_008;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MDT_CKMX-->JCFX_DATA_TSSBMX失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE JCFX_DATA_TSSBMX AS A
JOIN (
SELECT S.UUID,S.TSSWJG_DM,S.DJXH,IFNULL(TRIM(S.DLCKHWZMHM), S.CKBGDH) AS CKBGDH,DATE_FORMAT(S.SBRQ, '%Y%m') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'1' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.RMBLAJ,S.TSL,S.MDTSE
                  FROM CKTS_SB_MDT_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND IFNULL(S.BYBLBZ, 'N')='N'
                   AND IFNULL(TRIM(S.DLCKHWZMHM), S.CKBGDH) IS NOT NULL
) AS B
ON A.UUID=B.UUID
SET TSSWJG_DM = B.TSSWJG_DM, DJXH = B.DJXH, CKBGDH = B.CKBGDH, NY = B.NY, SBRQ = B.SBRQ, CKRQ = B.CKRQ_1, CKSP_DM = B.CKSP_DM, HGGQKA_DM = B.HGCODE, MYGDQSZ_DM = B.GBCODE, JGFS_DM = B.TDCODE, HZDWDQ_DM = B.HZDWDQDM, SJGXSJ = CURRENT_TIMESTAMP, SBYWLX = B.SBYWLX, LCSLID = B.LCSLID_SB, MYLAJ = B.MYLAJ, RMBLAJ = B.RMBLAJ, JSJE = B.RMBLAJ, TSL = B.TSL, TMSE = B.MDTSE, CKSL = B.CKSL;
INSERT INTO JCFX_DATA_TSSBMX (UUID,TSSWJG_DM,DJXH,CKBGDH,NY,SBRQ,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,SJGXSJ,SBYWLX,LCSLID,MYLAJ,RMBLAJ,JSJE,TSL,TMSE,CKSL)
SELECT B.UUID,B.TSSWJG_DM,B.DJXH,B.CKBGDH,B.NY,B.SBRQ,B.CKRQ_1,B.CKSP_DM,B.HGCODE,B.GBCODE,B.TDCODE,B.HZDWDQDM,CURRENT_TIMESTAMP,B.SBYWLX,B.LCSLID_SB,B.MYLAJ,B.RMBLAJ,B.RMBLAJ,B.TSL,B.MDTSE,B.CKSL
FROM (
SELECT S.UUID,S.TSSWJG_DM,S.DJXH,IFNULL(TRIM(S.DLCKHWZMHM), S.CKBGDH) AS CKBGDH,DATE_FORMAT(S.SBRQ, '%Y%m') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'1' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.RMBLAJ,S.TSL,S.MDTSE
                  FROM CKTS_SB_MDT_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND IFNULL(S.BYBLBZ, 'N')='N'
                   AND IFNULL(TRIM(S.DLCKHWZMHM), S.CKBGDH) IS NOT NULL
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JCFX_DATA_TSSBMX AS A WHERE A.UUID=B.UUID
);
    COMMIT;
    -- 不需要补充GHFNSRSBH,HYDXZQH_DM
  END;

  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_SB_MTS_CKMX S
   WHERE S.SJTB_SJ>=V_BEGINDATE
     AND IFNULL(S.BYBLBZ, 'N')='N';

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('CKTS_SB_MTS_CKMX-->JCFX_DATA_TSSBMX开始运行，记录总数：', LN_ROWS));
  COMMIT;

  -- 免退税
  BEGIN
  DECLARE BJTS_SQLCODE_007 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_007 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_007 = MYSQL_ERRNO, BJTS_SQLERRM_007 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_007;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MTS_CKMX-->JCFX_DATA_TSSBMX失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE JCFX_DATA_TSSBMX AS A
JOIN (
SELECT S.UUID,S.TSSWJG_DM,S.DJXH,IFNULL(TRIM(S.DLCKHWZMHM), S.CKBGDH) AS CKBGDH,DATE_FORMAT(S.SBRQ, '%Y%m') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'2' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.GLH,S.JSJE,S.TSL,S.TSE
                  FROM CKTS_SB_MTS_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND IFNULL(S.BYBLBZ, 'N')='N'
) AS B
ON A.UUID=B.UUID
SET TSSWJG_DM = B.TSSWJG_DM, DJXH = B.DJXH, CKBGDH = B.CKBGDH, NY = B.NY, SBRQ = B.SBRQ, CKRQ = B.CKRQ_1, CKSP_DM = B.CKSP_DM, HGGQKA_DM = B.HGCODE, MYGDQSZ_DM = B.GBCODE, JGFS_DM = B.TDCODE, HZDWDQ_DM = B.HZDWDQDM, SJGXSJ = CURRENT_TIMESTAMP, SBYWLX = B.SBYWLX, LCSLID = B.LCSLID_SB, MYLAJ = B.MYLAJ, GLH = B.GLH, JSJE = B.JSJE, TSL = B.TSL, TMSE = B.TSE, CKSL = B.CKSL;
INSERT INTO JCFX_DATA_TSSBMX (UUID,TSSWJG_DM,DJXH,CKBGDH,NY,SBRQ,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,SJGXSJ,SBYWLX,LCSLID,MYLAJ,GLH,JSJE,TSL,TMSE,CKSL)
SELECT B.UUID,B.TSSWJG_DM,B.DJXH,B.CKBGDH,B.NY,B.SBRQ,B.CKRQ_1,B.CKSP_DM,B.HGCODE,B.GBCODE,B.TDCODE,B.HZDWDQDM,CURRENT_TIMESTAMP,B.SBYWLX,B.LCSLID_SB,B.MYLAJ,B.GLH,B.JSJE,B.TSL,B.TSE,B.CKSL
FROM (
SELECT S.UUID,S.TSSWJG_DM,S.DJXH,IFNULL(TRIM(S.DLCKHWZMHM), S.CKBGDH) AS CKBGDH,DATE_FORMAT(S.SBRQ, '%Y%m') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'2' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.GLH,S.JSJE,S.TSL,S.TSE
                  FROM CKTS_SB_MTS_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND IFNULL(S.BYBLBZ, 'N')='N'
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JCFX_DATA_TSSBMX AS A WHERE A.UUID=B.UUID
);
    COMMIT;
  END;

  BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';
    -- 补充RMBLAJ,GHFNSRSBH,HYDXZQH_DM

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_004 = MYSQL_ERRNO, BJTS_SQLERRM_004 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_004;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('JCFX_DATA_TSSBMX补充RMBLAJ,GHFNSRSBH,HYDXZQH_DM失败！', LC_SBYY);
      COMMIT;

  END;
BEGIN
  DECLARE BJTS_CURSOR_DONE_006 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TSSB_UUID_006 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_DJXH_006 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_CKBGDH_006 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_CKSP_DM_006 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_GLH_006 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_MYLAJ_006 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_CKNY_006 LONGTEXT;
  DECLARE BJTS_CURSOR_006 CURSOR FOR
SELECT T.UUID,T.DJXH,T.CKBGDH,T.CKSP_DM,GLH,MYLAJ,DATE_FORMAT(T.CKRQ, '%Y%m') AS CKNY FROM JCFX_DATA_TSSBMX T WHERE T.SJGXSJ>=DATE(CURRENT_TIMESTAMP) AND T.SBYWLX='2';
  OPEN BJTS_CURSOR_006;
  BJTS_CURSOR_LOOP_006: LOOP
    SET BJTS_CURSOR_DONE_006 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_006 = TRUE;
      FETCH BJTS_CURSOR_006 INTO BJTS_CUR_TSSB_UUID_006, BJTS_CUR_TSSB_DJXH_006, BJTS_CUR_TSSB_CKBGDH_006, BJTS_CUR_TSSB_CKSP_DM_006, BJTS_CUR_TSSB_GLH_006, BJTS_CUR_TSSB_MYLAJ_006, BJTS_CUR_TSSB_CKNY_006;
    END;
    IF BJTS_CURSOR_DONE_006 THEN
      LEAVE BJTS_CURSOR_LOOP_006;
    END IF;
      BEGIN
  DECLARE BJTS_SQLCODE_006 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_006 TEXT DEFAULT '';
        -- 防止部分申报

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_006 = MYSQL_ERRNO, BJTS_SQLERRM_006 = MESSAGE_TEXT;
          SET V_RMBLAJ = NULL;

  END;
SELECT BJTS_CUR_TSSB_MYLAJ_006 * S.RMBLAJ / S.MYLAJ
          INTO V_RMBLAJ
          FROM CKTS_WBSJ_HG_BGD S
         WHERE S.DJXH=BJTS_CUR_TSSB_DJXH_006 AND S.CKBGDH=BJTS_CUR_TSSB_CKBGDH_006;
      END;

      IF V_RMBLAJ IS NULL THEN
        SELECT BJTS_CUR_TSSB_MYLAJ_006 * S.HL_RMB / 100
          INTO V_RMBLAJ
          FROM GS_HBZL_HLV S
         WHERE S.CODE='USD' AND S.HL_YM=BJTS_CUR_TSSB_CKNY_006 AND 1=1
LIMIT 1;
      END IF;

      BEGIN
  DECLARE BJTS_SQLCODE_005 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_005 TEXT DEFAULT '';
        -- 主要供货商

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_005 = MYSQL_ERRNO, BJTS_SQLERRM_005 = MESSAGE_TEXT;
          SET V_GHFNSRSBH =NULL;
          SET V_HYDXZQH_DM =NULL;

  END;
SELECT GHFNSRSBH_1, CASE WHEN SUBSTR(GHFNSRSBH_1,1,2)='91' THEN SUBSTR(GHFNSRSBH_1,3,4) ELSE SUBSTR(GHFNSRSBH_1,1,4) END
          INTO V_GHFNSRSBH, V_HYDXZQH_DM
          FROM (SELECT S.GHFNSRSBH_1, SUM(S.TSE) AS TSE
                  FROM CKTS_SB_MTS_JHMX S
                 WHERE S.DJXH=BJTS_CUR_TSSB_DJXH_006 AND S.GLH=BJTS_CUR_TSSB_GLH_006 AND S.CKSP_DM=BJTS_CUR_TSSB_CKSP_DM_006
                 GROUP BY S.GHFNSRSBH_1
                 ORDER BY SUM(S.TSE) DESC) TT
         WHERE 1=1
LIMIT 1;
      END;

      UPDATE JCFX_DATA_TSSBMX AS S
         SET RMBLAJ = V_RMBLAJ,
    GHFNSRSBH = V_GHFNSRSBH,
    HYDXZQH_DM = V_HYDXZQH_DM
       WHERE S.UUID=BJTS_CUR_TSSB_UUID_006;
      COMMIT;

  END LOOP BJTS_CURSOR_LOOP_006;
  CLOSE BJTS_CURSOR_006;
END;
  END;

  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_SB_WZF_CKMX S
   WHERE S.SJTB_SJ>=V_BEGINDATE
     AND IFNULL(S.BYBLBZ, 'N')='N';

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES (ORA_CONCAT('CKTS_SB_WZF_CKMX-->JCFX_DATA_TSSBMX开始运行，记录总数：', LN_ROWS));
  COMMIT;

  -- 代办退税
  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_003;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_WZF_CKMX-->JCFX_DATA_TSSBMX失败！', LC_SBYY);
      COMMIT;

  END;
UPDATE JCFX_DATA_TSSBMX AS A
JOIN (
SELECT S.UUID,S.TSSWJG_DM,S.DJXH,S.CKBGDH,DATE_FORMAT(S.SBRQ, '%Y%m') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'3' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.JSJE,S.TSL,S.TSE,S.WTDBTSSCQYNSRSBH,
                       CASE WHEN SUBSTR(S.WTDBTSSCQYNSRSBH,1,2)='91' THEN SUBSTR(S.WTDBTSSCQYNSRSBH,3,4) ELSE SUBSTR(S.WTDBTSSCQYNSRSBH,1,4) END AS HYDXZQH_DM
                  FROM CKTS_SB_WZF_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND IFNULL(S.BYBLBZ, 'N')='N'
) AS B
ON A.UUID=B.UUID
SET TSSWJG_DM = B.TSSWJG_DM, DJXH = B.DJXH, CKBGDH = B.CKBGDH, NY = B.NY, SBRQ = B.SBRQ, CKRQ = B.CKRQ_1, CKSP_DM = B.CKSP_DM, HGGQKA_DM = B.HGCODE, MYGDQSZ_DM = B.GBCODE, JGFS_DM = B.TDCODE, HZDWDQ_DM = B.HZDWDQDM, SJGXSJ = CURRENT_TIMESTAMP, SBYWLX = B.SBYWLX, LCSLID = B.LCSLID_SB, MYLAJ = B.MYLAJ, JSJE = B.JSJE, TSL = B.TSL, TMSE = B.TSE, CKSL = B.CKSL, GHFNSRSBH = B.WTDBTSSCQYNSRSBH, HYDXZQH_DM = B.HYDXZQH_DM;
INSERT INTO JCFX_DATA_TSSBMX (UUID,TSSWJG_DM,DJXH,CKBGDH,NY,SBRQ,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,SJGXSJ,SBYWLX,LCSLID,MYLAJ,JSJE,TSL,TMSE,CKSL,GHFNSRSBH,HYDXZQH_DM)
SELECT B.UUID,B.TSSWJG_DM,B.DJXH,B.CKBGDH,B.NY,B.SBRQ,B.CKRQ_1,B.CKSP_DM,B.HGCODE,B.GBCODE,B.TDCODE,B.HZDWDQDM,CURRENT_TIMESTAMP,B.SBYWLX,B.LCSLID_SB,B.MYLAJ,B.JSJE,B.TSL,B.TSE,B.CKSL,B.WTDBTSSCQYNSRSBH,B.HYDXZQH_DM
FROM (
SELECT S.UUID,S.TSSWJG_DM,S.DJXH,S.CKBGDH,DATE_FORMAT(S.SBRQ, '%Y%m') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'3' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.JSJE,S.TSL,S.TSE,S.WTDBTSSCQYNSRSBH,
                       CASE WHEN SUBSTR(S.WTDBTSSCQYNSRSBH,1,2)='91' THEN SUBSTR(S.WTDBTSSCQYNSRSBH,3,4) ELSE SUBSTR(S.WTDBTSSCQYNSRSBH,1,4) END AS HYDXZQH_DM
                  FROM CKTS_SB_WZF_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND IFNULL(S.BYBLBZ, 'N')='N'
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JCFX_DATA_TSSBMX AS A WHERE A.UUID=B.UUID
);
    COMMIT;
  END;

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';
    -- 补充RMBLAJ

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET LC_SBYY =BJTS_SQLERRM_001;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('JCFX_DATA_TSSBMX补充RMBLAJ失败！', LC_SBYY);
      COMMIT;

  END;
BEGIN
  DECLARE BJTS_CURSOR_DONE_005 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_TSSB_UUID_005 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_DJXH_005 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_CKBGDH_005 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_MYLAJ_005 LONGTEXT;
  DECLARE BJTS_CUR_TSSB_NY_005 LONGTEXT;
  DECLARE BJTS_CURSOR_005 CURSOR FOR
SELECT T.UUID,T.DJXH,T.CKBGDH,MYLAJ,T.NY FROM JCFX_DATA_TSSBMX T WHERE T.SJGXSJ>=DATE(CURRENT_TIMESTAMP) AND T.SBYWLX='3';
  OPEN BJTS_CURSOR_005;
  BJTS_CURSOR_LOOP_005: LOOP
    SET BJTS_CURSOR_DONE_005 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_005 = TRUE;
      FETCH BJTS_CURSOR_005 INTO BJTS_CUR_TSSB_UUID_005, BJTS_CUR_TSSB_DJXH_005, BJTS_CUR_TSSB_CKBGDH_005, BJTS_CUR_TSSB_MYLAJ_005, BJTS_CUR_TSSB_NY_005;
    END;
    IF BJTS_CURSOR_DONE_005 THEN
      LEAVE BJTS_CURSOR_LOOP_005;
    END IF;
      BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
          SET V_RMBLAJ = NULL;

  END;
SELECT S.RMBLAJ * BJTS_CUR_TSSB_MYLAJ_005 / S.MYLAJ  -- 防止部分申报
          INTO V_RMBLAJ
          FROM CKTS_WBSJ_HG_BGD S
         WHERE S.DJXH=BJTS_CUR_TSSB_DJXH_005 AND S.CKBGDH=BJTS_CUR_TSSB_CKBGDH_005;
      END;

      IF V_RMBLAJ IS NULL THEN
        SELECT BJTS_CUR_TSSB_MYLAJ_005 * S.HL_RMB / 100
          INTO V_RMBLAJ
          FROM GS_HBZL_HLV S
         WHERE S.CODE='USD' AND S.HL_YM=BJTS_CUR_TSSB_NY_005 AND 1=1
LIMIT 1;
      END IF;

      UPDATE JCFX_DATA_TSSBMX AS S
         SET RMBLAJ = V_RMBLAJ
       WHERE S.UUID=BJTS_CUR_TSSB_UUID_005;
      COMMIT;

  END LOOP BJTS_CURSOR_LOOP_005;
  CLOSE BJTS_CURSOR_005;
END;
  END;

  SET @BJTS_DYNAMIC_SQL_002 = 'ALTER TABLE JCFX_DATA_TSSBMX DISABLE ROW MOVEMENT';
PREPARE BJTS_DYNAMIC_STMT_002 FROM @BJTS_DYNAMIC_SQL_002;
EXECUTE BJTS_DYNAMIC_STMT_002;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_002;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('JCFX_DATA_TSSBMX 开始运行，清除作废流程和不予办理数据...');
  COMMIT;

  BEGIN
    -- 根据明细变更情况，删除不予办理数据
    BEGIN
  DECLARE BJTS_CURSOR_DONE_004 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BYBL_UUID_004 LONGTEXT;
  DECLARE BJTS_CURSOR_004 CURSOR FOR
SELECT T.UUID FROM CKTS_SB_MDT_CKMX T WHERE T.XGRQ>=V_BEGINDATE AND T.BYBLBZ='Y';
  OPEN BJTS_CURSOR_004;
  BJTS_CURSOR_LOOP_004: LOOP
    SET BJTS_CURSOR_DONE_004 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_004 = TRUE;
      FETCH BJTS_CURSOR_004 INTO BJTS_CUR_BYBL_UUID_004;
    END;
    IF BJTS_CURSOR_DONE_004 THEN
      LEAVE BJTS_CURSOR_LOOP_004;
    END IF;
      DELETE FROM JCFX_DATA_TSSBMX AS S WHERE S.UUID=BJTS_CUR_BYBL_UUID_004;

  END LOOP BJTS_CURSOR_LOOP_004;
  CLOSE BJTS_CURSOR_004;
END;
    COMMIT;

    BEGIN
  DECLARE BJTS_CURSOR_DONE_003 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BYBL_UUID_003 LONGTEXT;
  DECLARE BJTS_CURSOR_003 CURSOR FOR
SELECT T.UUID FROM CKTS_SB_MTS_CKMX T WHERE T.XGRQ>=V_BEGINDATE AND T.BYBLBZ='Y';
  OPEN BJTS_CURSOR_003;
  BJTS_CURSOR_LOOP_003: LOOP
    SET BJTS_CURSOR_DONE_003 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_003 = TRUE;
      FETCH BJTS_CURSOR_003 INTO BJTS_CUR_BYBL_UUID_003;
    END;
    IF BJTS_CURSOR_DONE_003 THEN
      LEAVE BJTS_CURSOR_LOOP_003;
    END IF;
      DELETE FROM JCFX_DATA_TSSBMX AS S WHERE S.UUID=BJTS_CUR_BYBL_UUID_003;

  END LOOP BJTS_CURSOR_LOOP_003;
  CLOSE BJTS_CURSOR_003;
END;
    COMMIT;

    BEGIN
  DECLARE BJTS_CURSOR_DONE_002 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BYBL_UUID_002 LONGTEXT;
  DECLARE BJTS_CURSOR_002 CURSOR FOR
SELECT T.UUID FROM CKTS_SB_WZF_CKMX T WHERE T.XGRQ>=V_BEGINDATE AND T.BYBLBZ='Y';
  OPEN BJTS_CURSOR_002;
  BJTS_CURSOR_LOOP_002: LOOP
    SET BJTS_CURSOR_DONE_002 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_002 = TRUE;
      FETCH BJTS_CURSOR_002 INTO BJTS_CUR_BYBL_UUID_002;
    END;
    IF BJTS_CURSOR_DONE_002 THEN
      LEAVE BJTS_CURSOR_LOOP_002;
    END IF;
      DELETE FROM JCFX_DATA_TSSBMX AS S WHERE S.UUID=BJTS_CUR_BYBL_UUID_002;

  END LOOP BJTS_CURSOR_LOOP_002;
  CLOSE BJTS_CURSOR_002;
END;
    COMMIT;

    -- 根据流程信息作废情况，删除作废数据
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_ZFLC_LCSLID_SB_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.LCSLID_SB FROM CKTS_LC_SBXX T WHERE T.ZFRQ>=V_BEGINDATE;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_ZFLC_LCSLID_SB_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      DELETE FROM JCFX_DATA_TSSBMX AS S WHERE S.LCSLID=BJTS_CUR_ZFLC_LCSLID_SB_001;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
    COMMIT;

    DELETE FROM JCFX_DATA_TSSBMX AS T
     WHERE T.SJGXSJ>=DATE_ADD(DATE(CURRENT_TIMESTAMP), INTERVAL -1 MONTH) AND T.SBYWLX='1'
       AND NOT EXISTS (SELECT 1 FROM CKTS_SB_MDT_CKMX S WHERE S.UUID=T.UUID);
    COMMIT;

    DELETE FROM JCFX_DATA_TSSBMX AS T
     WHERE T.SJGXSJ>=DATE_ADD(DATE(CURRENT_TIMESTAMP), INTERVAL -1 MONTH) AND T.SBYWLX='2'
       AND NOT EXISTS (SELECT 1 FROM CKTS_SB_MTS_CKMX S WHERE S.UUID=T.UUID);
    COMMIT;

    DELETE FROM JCFX_DATA_TSSBMX AS T
     WHERE T.SJGXSJ>=DATE_ADD(DATE(CURRENT_TIMESTAMP), INTERVAL -1 MONTH) AND T.SBYWLX='3'
       AND NOT EXISTS (SELECT 1 FROM CKTS_SB_WZF_CKMX S WHERE S.UUID=T.UUID);
    COMMIT;

  END;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('JCFX_DATA_TSSBMX 处理结束！');
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

