-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_JCFX_NSR_BADJ$$

CREATE PROCEDURE PRO_DEAL_JCFX_NSR_BADJ()
routine_body: BEGIN
  DECLARE LD_DEALDATA      DATETIME;          -- 用于基础数据处理的提前量

  BEGIN
    UPDATE JCFX_NSR_BADJ AS A
JOIN (
SELECT T.DJXH_JS,T.NSRDJNO,T.SHXYNO,T.NSRMC,T.QYHGDM,T.QYLX,T.FLGLCD,T.DJZCLX_JS,T.HYDM,T.NSRZT_JS,T.NSRLX_JS,T.SQ_DATE,IFNULL(T.ZX_FLAG, 'N') AS ZX_FLAG,T.ZX_DATE,T.SWJGDM,T.ZGSWSKFJ_DM,T.JDXZ_DM
                  FROM GLXT_BB_SHXT_DJXX T
) AS B
ON A.DJXH=B.DJXH_JS
SET NSRSBH = B.NSRDJNO, SHXYDM = B.SHXYNO, NSRMC = B.NSRMC, QYHGDM = B.QYHGDM, CKQYLX = B.QYLX, FLGLCD = B.FLGLCD, DJZCLX = B.DJZCLX_JS, HY = B.HYDM, NSRZT = B.NSRZT_JS, NSRLB = B.NSRLX_JS, SQ_DATE = B.SQ_DATE, BACHBZ = B.ZX_FLAG, BACHSJ = B.ZX_DATE, SWJGDM = B.SWJGDM, KSSWJG_DM = B.ZGSWSKFJ_DM, JDXZ_DM = B.JDXZ_DM;
INSERT INTO JCFX_NSR_BADJ (DJXH,NSRSBH,SHXYDM,NSRMC,QYHGDM,CKQYLX,FLGLCD,DJZCLX,HY,NSRZT,NSRLB,SQ_DATE,BACHBZ,BACHSJ,SWJGDM,KSSWJG_DM,JDXZ_DM)
SELECT B.DJXH_JS,B.NSRDJNO,B.SHXYNO,B.NSRMC,B.QYHGDM,B.QYLX,B.FLGLCD,B.DJZCLX_JS,B.HYDM,B.NSRZT_JS,B.NSRLX_JS,B.SQ_DATE,B.ZX_FLAG,B.ZX_DATE,B.SWJGDM,B.ZGSWSKFJ_DM,B.JDXZ_DM
FROM (
SELECT T.DJXH_JS,T.NSRDJNO,T.SHXYNO,T.NSRMC,T.QYHGDM,T.QYLX,T.FLGLCD,T.DJZCLX_JS,T.HYDM,T.NSRZT_JS,T.NSRLX_JS,T.SQ_DATE,IFNULL(T.ZX_FLAG, 'N') AS ZX_FLAG,T.ZX_DATE,T.SWJGDM,T.ZGSWSKFJ_DM,T.JDXZ_DM
                  FROM GLXT_BB_SHXT_DJXX T
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JCFX_NSR_BADJ AS A WHERE A.DJXH=B.DJXH_JS
);
    COMMIT;

    -- QYFZ,NSRDZDAH
  END;

  SELECT ORA_DATE_ADD(MAX(JLXZSJ), -(7)) INTO LD_DEALDATA FROM JCFX_NSR_BADJ_TOHZ;

  BEGIN
    -- 后续增量数据1：新备案出口企业
    INSERT INTO JCFX_NSR_BADJ_TOHZ(DJXH,NSRSBH,SHXYDM,JLXZSJ,BACHSJ,SWJGDM)
         SELECT T.DJXH_JS,T.NSRDJNO,T.SHXYNO,DATE(LEAST(CURRENT_TIMESTAMP,T.SQ_DATE)),T.ZX_DATE,T.SWJGDM
           FROM GLXT_BB_SHXT_DJXX T
          WHERE T.SQ_DATE>=LD_DEALDATA
            AND NOT EXISTS (SELECT 1 FROM JCFX_NSR_BADJ_TOHZ S WHERE S.DJXH=T.DJXH_JS);
    COMMIT;

    -- 后续增量数据2：老备案企业，2019年1月1日以来首次申报出口退免税
    INSERT INTO JCFX_NSR_BADJ_TOHZ(DJXH,NSRSBH,SHXYDM,JLXZSJ,BACHSJ,SWJGDM)
         SELECT T.DJXH_JS,T.NSRDJNO,T.SHXYNO,DATE(CURRENT_TIMESTAMP),T.ZX_DATE,T.SWJGDM
           FROM GLXT_BB_SHXT_DJXX T
          WHERE EXISTS (SELECT 1 FROM CKTS_LC_SBXX S WHERE S.DJXH=T.DJXH_JS AND S.SBRQ>=LD_DEALDATA)
            AND NOT EXISTS (SELECT 1 FROM JCFX_NSR_BADJ_TOHZ S WHERE S.DJXH=T.DJXH_JS);
    COMMIT;

  -- 后续注销企业
    UPDATE JCFX_NSR_BADJ_TOHZ AS T
       SET BACHSJ=(SELECT S.ZX_DATE FROM GLXT_BB_SHXT_DJXX S WHERE S.DJXH_JS=T.DJXH)
     WHERE EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX S WHERE S.DJXH_JS=T.DJXH AND S.ZX_DATE>=LD_DEALDATA);
    COMMIT;
  END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DEAL_JCFX_NSR_BADJ.sql

-- ======================================================================
-- [014/146] BEGIN SOURCE: PRO_DEAL_JCFX_NSR_BADJ_BLV.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_JCFX_NSR_BADJ_BLV$$

CREATE PROCEDURE PRO_DEAL_JCFX_NSR_BADJ_BLV
(
  IN V_YEAR VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LN_QBXSE         DECIMAL(18,2);
  DECLARE LN_CKXSE         DECIMAL(18,2);
  DECLARE LN_CKGM          DECIMAL(18,2);
  DECLARE LN_SBMDE         DECIMAL(18,2);
  DECLARE LN_SBMDTSE       DECIMAL(18,2);
  DECLARE LN_SBSF          DECIMAL(18,2);
  DECLARE LN_CKBLV         DECIMAL(10,6);
  DECLARE LN_MDBLV         DECIMAL(10,6);
  DECLARE LN_SFBLV         DECIMAL(10,6);
  DECLARE LC_CKBLV         VARCHAR(1);
  DECLARE LC_CKGM          VARCHAR(1);
  DECLARE LC_MDBLV         VARCHAR(1);
  DECLARE LC_SFBLV         VARCHAR(1);

  IF V_YEAR IS NULL THEN
    LEAVE routine_body;
  END IF;

  -- 根据审核信息设置LCTJJC
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_NSR_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.DJXH
                    FROM JCFX_NSR_BADJ T;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_NSR_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    SELECT IFNULL(SUM(S.ZZS_QBXSSR), 0), IFNULL(SUM(S.CK_SB_XSERMB), 0), IFNULL(SUM(S.CK_SB_XSEMY), 0), IFNULL(SUM(S.CK_SB_MDE), 0), IFNULL(SUM(S.CK_SB_TSE+S.CK_SB_MDE), 0), IFNULL(SUM(S.ZZS_YNSE+S.CK_SB_MDE), 0)
      INTO LN_QBXSE, LN_CKXSE, LN_CKGM, LN_SBMDE, LN_SBMDTSE, LN_SBSF
      FROM JCFX_DATA_QYYHZ S
     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_001 AND S.NY LIKE ORA_CONCAT(V_YEAR, '%');

    IF LN_QBXSE<=0 THEN
      IF LN_CKXSE<=0 THEN
        SET LN_CKBLV = 0;
      ELSE
        SET LN_CKBLV = 100;
      END IF;
    ELSE
      -- LN_QBXSE>0
      IF LN_CKXSE> LN_QBXSE THEN
        SET LN_CKBLV = 100;
      ELSEIF LN_CKXSE<0 THEN
        SET LN_CKBLV = 0;
      ELSE
        SET LN_CKBLV = 100 * LN_CKXSE / LN_QBXSE;
      END IF;
    END IF;

    IF LN_SBMDTSE<=0 OR LN_SBMDE<=0 THEN
      SET LN_MDBLV = 0;
    ELSEIF LN_SBMDE>LN_SBMDTSE THEN
      SET LN_MDBLV = 100;
    ELSE
      SET LN_MDBLV = 100 * LN_SBMDE / LN_SBMDTSE;
    END IF;

    IF LN_QBXSE<=0 OR LN_SBSF<=0 THEN
      SET LN_SFBLV = 0;
    ELSEIF LN_SBSF>LN_QBXSE THEN
      SET LN_SFBLV = 100;
    ELSE
      SET LN_SFBLV = 100 * LN_SBSF / LN_QBXSE;
    END IF;


    SET LC_CKBLV = CASE WHEN LN_CKBLV>=80 THEN 'A' WHEN LN_CKBLV>=60 THEN 'B' WHEN LN_CKBLV>=40 THEN 'C' WHEN LN_CKBLV>=20 THEN 'D' ELSE 'E' END;
    SET LC_CKGM = CASE WHEN LN_CKGM>=100000000 THEN 'A' WHEN LN_CKGM>=50000000 THEN 'B' WHEN LN_CKGM>=10000000 THEN 'C' WHEN LN_CKGM>=1000000 THEN 'D' ELSE 'E' END;
    SET LC_MDBLV = CASE WHEN LN_MDBLV>=40 THEN 'A' WHEN LN_MDBLV>=30 THEN 'B' WHEN LN_MDBLV>=20 THEN 'C' WHEN LN_MDBLV>=10 THEN 'D' ELSE 'E' END;
    SET LC_SFBLV = CASE WHEN LN_SFBLV>=20 THEN 'A' WHEN LN_SFBLV>=15 THEN 'B' WHEN LN_SFBLV>=10 THEN 'C' WHEN LN_SFBLV>=5 THEN 'D' ELSE 'E' END;

    UPDATE JCFX_NSR_BADJ AS A
       SET CKBLV=LN_CKBLV,
    CKBLV_DM=LC_CKBLV,
    CKGM=LN_CKGM,
    CKGM_DM=LC_CKGM,
    MDBLV=LN_MDBLV,
    MDBLV_DM=LC_MDBLV,
    SFLV=LN_SFBLV,
    SFLV_DM=LC_SFBLV
     WHERE A.DJXH=BJTS_CUR_NSR_DJXH_001;
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DEAL_JCFX_NSR_BADJ_BLV.sql

-- ======================================================================
-- [015/146] BEGIN SOURCE: PRO_DEAL_JCFX_NSR_BLV.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DEAL_JCFX_NSR_BLV$$

CREATE PROCEDURE PRO_DEAL_JCFX_NSR_BLV()
routine_body: BEGIN
  DECLARE LN_CKBGDFS       BIGINT;
  DECLARE LN_CKMYLAJ       DECIMAL(18,2);
  DECLARE LN_SBMYLAJ       DECIMAL(18,2);
  DECLARE LN_SBTMSE         DECIMAL(18,2);
  DECLARE LN_SBMDE         DECIMAL(18,2);
  DECLARE LC_CKGM          VARCHAR(1);
  DECLARE LN_MDBLV         DECIMAL(10,6);
  DECLARE LC_MDBLV         VARCHAR(1);

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_NSR_DJXH_JS_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.DJXH_JS FROM GLXT_BB_SHXT_DJXX T;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_NSR_DJXH_JS_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    SELECT COUNT(DISTINCT SUBSTR(S.CKBGDH,1,18)), IFNULL(SUM(S.MYLAJ), 0)
      INTO LN_CKBGDFS, LN_CKMYLAJ
      FROM CKTS_WBSJ_HG_BGD S
     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_JS_001
       AND S.CKRQ_1>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -12 MONTH)
       AND S.CKRQ_1< MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1);

    SELECT IFNULL(SUM(S.USD_AMT), 0), IFNULL(SUM(S.SB_TS_AMT), 0)+ IFNULL(SUM(S.SB_MD_AMT), 0), IFNULL(SUM(S.SB_MD_AMT), 0)
      INTO LN_SBMYLAJ, LN_SBTMSE, LN_SBMDE
      FROM GLXT_BB_SHXT_LCXX S
     WHERE S.DJXH=BJTS_CUR_NSR_DJXH_JS_001
       AND IFNULL(S.SL_DATE, S.SB_DATE)>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -12 MONTH)
       AND IFNULL(S.SL_DATE, S.SB_DATE)< MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1);

    SET LC_CKGM = CASE WHEN LN_SBMYLAJ>=100000000 THEN 'A'
                    WHEN LN_SBMYLAJ>=50000000 THEN 'B'
                    WHEN LN_SBMYLAJ>=10000000 THEN 'C'
                    WHEN LN_SBMYLAJ>=1000000 THEN 'D'
                    ELSE 'E' END;

    IF LN_SBMDE<=0 THEN
      SET LN_MDBLV = 0;
    ELSEIF LN_SBTMSE<0 THEN
      SET LN_MDBLV = 100;
    ELSE
      SET LN_MDBLV = 100 * LN_SBMDE / LN_SBTMSE;
    END IF;
    SET LC_MDBLV = CASE WHEN LN_MDBLV>=40 THEN 'A'
                     WHEN LN_MDBLV>=30 THEN 'B'
                     WHEN LN_MDBLV>=20 THEN 'C'
                     WHEN LN_MDBLV>=10 THEN 'D'
                     ELSE 'E' END;

    UPDATE GLXT_BB_SHXT_DJXX AS A
       SET CK_BGDFS = LN_CKBGDFS,
    CK_MYLAJ = LN_CKMYLAJ,
    CKGM     = LN_SBMYLAJ,
    SB_TMSE  = LN_SBTMSE,
    SB_MDE   = LN_SBMDE,
    MDBLV    = LN_MDBLV,
    CKGM_DM  = LC_CKGM,
    MDBLV_DM = LC_MDBLV
     WHERE A.DJXH_JS=BJTS_CUR_NSR_DJXH_JS_001;
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DEAL_JCFX_NSR_BLV.sql

-- ======================================================================
-- [016/146] BEGIN SOURCE: PRO_DXTX_JJYQ.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_DXTX_JJYQ$$

CREATE PROCEDURE PRO_DXTX_JJYQ()
/*
 * 20260515，根据杭州市局王薇意见，每年4月申报期增加卷烟免税核销的提醒
 */
routine_body: BEGIN
  DECLARE LL_JJR        BIGINT;
  DECLARE LL_TSSB       BIGINT;
  DECLARE LL_FUH        BIGINT;
  DECLARE LL_FUHCL      BIGINT;
  DECLARE LL_SDHC       BIGINT;
  DECLARE LL_FXCK       BIGINT;
  DECLARE LL_NKSQTX     BIGINT;
  DECLARE LL_NKSHJD     BIGINT;
  DECLARE LL_MSZMHX     BIGINT;
  DECLARE LC_SWJGDM     VARCHAR(11);
  DECLARE LC_MSG        VARCHAR(200);

  SELECT COUNT(1)
    INTO LL_JJR
    FROM PUB_JJR T
   WHERE T.JJR_DATE=DATE(CURRENT_TIMESTAMP);

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_USER_ID_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_JOB_TYPE_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_PHONE_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_SWJG_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_SWJG_MC_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_USERNAME_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_JJYQ_TSSB_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_JJYQ_FUH_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_JJYQ_FUHCL_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_JJYQ_SDHC_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_FXCK_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_NKSQTX_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_NKSHJD_001 LONGTEXT;
  DECLARE BJTS_CUR_USER_JJRTXBZ_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.ID,T.JOB_TYPE,T.PHONE,T.SWJG_DM,T.SWJG_MC,T.USERNAME,
                          T.JJYQ_TSSB,T.JJYQ_FUH,T.JJYQ_FUHCL,T.JJYQ_SDHC,T.FXCK,T.NKSQTX,T.NKSHJD,T.JJRTXBZ
                    FROM MSG_PUSH_USER T
                   WHERE T.QYBZ='Y';
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_USER_ID_001, BJTS_CUR_USER_JOB_TYPE_001, BJTS_CUR_USER_PHONE_001, BJTS_CUR_USER_SWJG_DM_001, BJTS_CUR_USER_SWJG_MC_001, BJTS_CUR_USER_USERNAME_001, BJTS_CUR_USER_JJYQ_TSSB_001, BJTS_CUR_USER_JJYQ_FUH_001, BJTS_CUR_USER_JJYQ_FUHCL_001, BJTS_CUR_USER_JJYQ_SDHC_001, BJTS_CUR_USER_FXCK_001, BJTS_CUR_USER_NKSQTX_001, BJTS_CUR_USER_NKSHJD_001, BJTS_CUR_USER_JJRTXBZ_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    IF BJTS_CUR_USER_JJRTXBZ_001='N' AND LL_JJR>0 THEN
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;
    IF BJTS_CUR_USER_JOB_TYPE_001 IN ('1','2') THEN -- 区县局
      BEGIN
        IF BJTS_CUR_USER_JJYQ_TSSB_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_TSSB
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='退税办理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_TSSB>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，有'), LL_TSSB), '笔出口退(免)税业务即将超期，请及时办理。谢谢！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-01'),
                          BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
;
              COMMIT;
            END IF;
          END;
        END IF;

        IF BJTS_CUR_USER_JJYQ_FUH_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_FUH
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='函调复函' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_FUH>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，'), S.YWBZ), '的函调业务即将超期，请及时办理。谢谢！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-02-'), S.BIZKEY),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
                     FROM MSG_PUSH_DATA S
                    WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='函调复函' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
              COMMIT;
            END IF;
          END;
        END IF;

        IF BJTS_CUR_USER_JJYQ_FUHCL_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_FUHCL
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='函调处理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_FUHCL>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，'), S.YWBZ), '已于'), DATE_FORMAT(QDSJ, '%Y-%m-%d')), '回函，请及时办理。谢谢！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-05-'), S.BIZKEY),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
                     FROM MSG_PUSH_DATA S
                    WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='函调处理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
              COMMIT;
            END IF;
          END;
        END IF;

        IF BJTS_CUR_USER_JJYQ_SDHC_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_SDHC
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='容缺办理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_SDHC>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，税号['), S.NSRSBH), ']的容缺办理退税业务，实地核查即将超期，请及时办理。谢谢！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-03-'), S.BIZKEY),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
                     FROM MSG_PUSH_DATA S
                    WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='容缺办理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
              COMMIT;
            END IF;
          END;
        END IF;

        IF BJTS_CUR_USER_FXCK_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_FXCK
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='风险出口电子信息' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_FXCK>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，您部门扫描到['), LL_FXCK), ']笔风险出口电子信息，请加强监管。详情请到便捷退税管理系统的短信关联业务查询！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-04'),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
;
              COMMIT;
            END IF;
          END;
        END IF;

        IF BJTS_CUR_USER_NKSQTX_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_NKSQTX
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='内控提醒' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_NKSQTX>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，您部门扫描到['), LL_FXCK), ']笔内控风险事前提醒业务，请及时处理。详情请到便捷退税管理系统的内控管理——内控风险处理——事前提醒信息管理查询！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-04'),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
;
              COMMIT;
            END IF;
          END;
        END IF;

        IF BJTS_CUR_USER_NKSHJD_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_NKSHJD
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='内控监督' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_NKSHJD>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，您部门扫描到['), LL_FXCK), ']笔内控风险事后监督业务，请及时处理。详情请到便捷退税管理系统的内控管理——内控风险处理——事后风险信息管理查询！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-04'),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
;
              COMMIT;
            END IF;
          END;
        END IF;

        IF BJTS_CUR_USER_JJYQ_TSSB_001='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_MSZMHX
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=BJTS_CUR_USER_SWJG_DM_001 AND S.BIZTYPE='免税核销' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP);
            IF LL_MSZMHX>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,
                          ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，您部门扫描到['), LL_FXCK), ']笔企业（出口卷烟/来料加工证明）未免税核销的提醒，请提醒企业及时核销。详情请到便捷退税管理系统的内控管理——内控风险处理——事后风险信息管理查询！'),
                          '0',BJTS_CUR_USER_PHONE_001,CURRENT_TIMESTAMP,'0','Y',ORA_CONCAT(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'), '-04'),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
;
              COMMIT;
            END IF;
          END;
        END IF;

      END;
    ELSE
      BEGIN
        IF BJTS_CUR_USER_JOB_TYPE_001 = '3' THEN
          SET LC_SWJGDM =ORA_CONCAT(SUBSTR(BJTS_CUR_USER_SWJG_DM_001, 1, 5), '%');
        ELSE
          SET LC_SWJGDM =ORA_CONCAT(SUBSTR(BJTS_CUR_USER_SWJG_DM_001, 1, 3), '%');
        END IF;
        SELECT COUNT(1)
          INTO LL_TSSB
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='退税办理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP)
           AND BJTS_CUR_USER_JJYQ_TSSB_001='Y';
        SELECT COUNT(1)
          INTO LL_FUH
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='函调复函' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP)
           AND BJTS_CUR_USER_JJYQ_FUH_001='Y';
        SELECT COUNT(1)
          INTO LL_FUHCL
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='函调处理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP)
           AND BJTS_CUR_USER_JJYQ_FUHCL_001='Y';
        SELECT COUNT(1)
          INTO LL_SDHC
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='容缺办理' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP)
           AND BJTS_CUR_USER_JJYQ_SDHC_001='Y';
        SELECT COUNT(1)
          INTO LL_MSZMHX
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='免税核销' AND S.SJTBSJ>=DATE(CURRENT_TIMESTAMP)
           AND BJTS_CUR_USER_JJYQ_TSSB_001='Y';
        IF (LL_TSSB + LL_FUH + LL_FUHCL + LL_SDHC + LL_MSZMHX) >0 THEN
          SET LC_MSG = ORA_CONCAT(ORA_CONCAT('温馨提醒：[', BJTS_CUR_USER_SWJG_MC_001), ']，下属各局共有');
          IF LL_TSSB > 0 THEN
            SET LC_MSG = ORA_CONCAT(ORA_CONCAT(LC_MSG, LL_TSSB), '笔出口退(免)税业务，');
          END IF;
          IF LL_FUH > 0 THEN
            SET LC_MSG = ORA_CONCAT(ORA_CONCAT(LC_MSG, LL_FUH), '笔函调复函业务，');
          END IF;
          IF LL_FUHCL > 0 THEN
            SET LC_MSG = ORA_CONCAT(ORA_CONCAT(LC_MSG, LL_FUHCL), '笔复函处理业务，');
          END IF;
          IF LL_SDHC > 0 THEN
            SET LC_MSG = ORA_CONCAT(ORA_CONCAT(LC_MSG, LL_SDHC), '笔容缺办理的实地核查业务，');
          END IF;
          IF LL_MSZMHX > 0 THEN
            SET LC_MSG = ORA_CONCAT(ORA_CONCAT(LC_MSG, LL_MSZMHX), '笔企业免税核销提醒，');
          END IF;
          SET LC_MSG = ORA_CONCAT(LC_MSG, '即将超期，请督促办理。谢谢！');
          INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
               SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_PLAN'),BJTS_CUR_USER_ID_001,LC_MSG,'0',BJTS_CUR_USER_PHONE_001,
                      CURRENT_TIMESTAMP,'0','Y',DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-%d'),BJTS_CUR_USER_SWJG_DM_001,BJTS_CUR_USER_USERNAME_001
;
          COMMIT;
        END IF;
      END;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_DXTX_JJYQ.sql

-- ======================================================================
-- [017/146] BEGIN SOURCE: PRO_FXGL_ATFX_CKFP.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_ATFX_CKFP$$

CREATE PROCEDURE PRO_FXGL_ATFX_CKFP
/*
 * 风险管理——案头分析——出口电子信息补充发票号码、境外收货人信息
 */
(
  IN P_DJXH VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LC_CKFP        VARCHAR(30);
  DECLARE LN_FGF         BIGINT;
  DECLARE LC_WSMC        VARCHAR(300);

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CK_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_CK_CKBGDH_001 LONGTEXT;
  DECLARE BJTS_CUR_CK_DLCKHWZMHM_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT CK.DJXH,CK.CKBGDH,CK.DLCKHWZMHM
                   FROM ATFX_CK_YS_CKDZXX CK
                  WHERE CK.DJXH=P_DJXH
                    AND CK.CYTSSBJL IS NOT NULL AND CK.CKFPHM IS NULL;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CK_DJXH_001, BJTS_CUR_CK_CKBGDH_001, BJTS_CUR_CK_DLCKHWZMHM_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
        SET LC_CKFP = NULL;

  END;
IF BJTS_CUR_CK_DLCKHWZMHM_001 IS NULL THEN
        SELECT CKFPH
          INTO LC_CKFP
          FROM (SELECT MTS.CKFPH
                  FROM ATFX_TS_YS_CKMXSBB MTS
                 WHERE MTS.DJXH=BJTS_CUR_CK_DJXH_001
                   AND MTS.CKBGDH=BJTS_CUR_CK_CKBGDH_001
                 UNION ALL
                SELECT MDT.CKFPH
                  FROM ATFX_TS_YS_MDTSSBB MDT
                 WHERE MDT.DJXH=BJTS_CUR_CK_DJXH_001
                   AND MDT.CKBGDH=BJTS_CUR_CK_CKBGDH_001) AS BJTS_DERIVED_001
         WHERE 1=1
LIMIT 1;
      ELSE
        SELECT CKFPH
          INTO LC_CKFP
          FROM (SELECT MTS.CKFPH
                  FROM ATFX_TS_YS_CKMXSBB MTS
                 WHERE MTS.DJXH=BJTS_CUR_CK_DJXH_001
                   AND MTS.DLZMH=BJTS_CUR_CK_DLCKHWZMHM_001
                 UNION ALL
                SELECT MDT.CKFPH
                  FROM ATFX_TS_YS_MDTSSBB MDT
                 WHERE MDT.DJXH=BJTS_CUR_CK_DJXH_001
                   AND MDT.DLCKHWZMHM=BJTS_CUR_CK_DLCKHWZMHM_001) AS BJTS_DERIVED_002
         WHERE 1=1
LIMIT 1;
      END IF;
    END;

    IF LC_CKFP IS NOT NULL THEN
      SET LN_FGF = INSTR(LC_CKFP,',');
      IF LN_FGF>0 THEN
        SET LC_CKFP = SUBSTR(LC_CKFP,1,LN_FGF-1);
      END IF;
      SET LN_FGF = INSTR(LC_CKFP,'-');
      IF LN_FGF>0 THEN
        SET LC_CKFP = SUBSTR(LC_CKFP,1,LN_FGF-1);
      END IF;
      BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
          SET LC_WSMC = NULL;

  END;
IF LENGTH(LC_CKFP) IN (18,20) THEN
          SELECT FP.GMFMC
            INTO LC_WSMC
            FROM ATFX_FP_YS_XSFPXX FP
           WHERE FP.DJXH=BJTS_CUR_CK_DJXH_001
             AND FP.FPHM=LC_CKFP
             AND 1=1
LIMIT 1;
        ELSE
          SELECT FP.GMFMC
            INTO LC_WSMC
            FROM ATFX_FP_YS_XSFPXX FP
           WHERE FP.DJXH=BJTS_CUR_CK_DJXH_001
             AND FP.FPHM LIKE ORA_CONCAT('%', LC_CKFP)
             AND 1=1
LIMIT 1;
        END IF;
      END;

      UPDATE ATFX_CK_YS_CKDZXX AS T
         SET CKFPHM = LC_CKFP,
    JWSHR = LC_WSMC
       WHERE T.DJXH = BJTS_CUR_CK_DJXH_001
         AND T.CKBGDH = BJTS_CUR_CK_CKBGDH_001;
      COMMIT;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_ATFX_CKFP.sql

-- ======================================================================
-- [018/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C01001.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C01001$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C01001
/*
 * 新办企业出口异常模型
 * 需要从金三同步CKTS_BA_BABGQK_JGB表中变更退税机关记录
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_MYLAJ_LX3M    DECIMAL(18,2);    -- 预警参数：连续3个月内美元出口额
  DECLARE V_MONTHS_ZDCK   DECIMAL(18,2);    -- 预警参数：中断出口后复出口的企业中断期
  DECLARE V_MONTHS_SCSB   DECIMAL(18,2);    -- 预警参数：新办类企业首次申报以后有效期
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);
  DECLARE V_MYLAJ         DECIMAL(18,2);    -- 统计结果：连续3个月内美元出口额

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_YJJG';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MYLAJ_LX3M
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MYLAJ_LX3M';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_ZDCK
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_ZDCK';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_SCSB
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_SCSB';
  SET V_PARAMS =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG), '|连续3个月内美元出口额阈值='), V_MYLAJ_LX3M), '|中断后复出口间隔周期='), V_MONTHS_ZDCK), '|首次申报后检查有效期='), V_MONTHS_SCSB);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C01001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 首次申报不足V_MONTHS_SCSB个月的出口企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_003 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_003 LONGTEXT;
  DECLARE BJTS_CUR_CKQY_SCSBRQ_003 LONGTEXT;
  DECLARE BJTS_CURSOR_003 CURSOR FOR
SELECT T.DJXH,DATE(MIN(T.QDSJ)) AS SCSBRQ
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_SCSB MONTH) -- 检查24个月内的申报流程
                      AND NOT EXISTS (SELECT 1 -- 不存在更早的申报流程
                                        FROM CKTS_LC_SBXX A
                                       WHERE A.DJXH = T.DJXH
                                         AND IFNULL(A.ZFBZ, 'N') = 'N'
                                         AND A.QDSJ < T.QDSJ)
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C01001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')))
                    GROUP BY T.DJXH;
  OPEN BJTS_CURSOR_003;
  BJTS_CURSOR_LOOP_003: LOOP
    SET BJTS_CURSOR_DONE_003 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_003 = TRUE;
      FETCH BJTS_CURSOR_003 INTO BJTS_CUR_CKQY_DJXH_003, BJTS_CUR_CKQY_SCSBRQ_003;
    END;
    IF BJTS_CURSOR_DONE_003 THEN
      LEAVE BJTS_CURSOR_LOOP_003;
    END IF;
    -- 统计连续三个月美元出口额，不包含当月数据
    SELECT IFNULL(SUM(MYLAJ), 0)
      INTO V_MYLAJ
      FROM CKTS_WBSJ_HG_BGD
     WHERE DJXH=BJTS_CUR_CKQY_DJXH_003
       AND CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
       AND CKRQ_1<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND ZMTBZ='T';
    -- 如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),TT.SWJGDM,TT.DJXH_JS,IFNULL(TT.SHXYNO, TT.NSRDJNO),TT.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C01001',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]出口企业首次申报日期=', DATE_FORMAT(BJTS_CUR_CKQY_SCSBRQ_003, '%Y%m%d')), '|最近三个月美元出口额='), V_MYLAJ)
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=BJTS_CUR_CKQY_DJXH_003;
      COMMIT;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_003;
  CLOSE BJTS_CURSOR_003;
END;

  -- 中断后复出口不足V_MONTHS_SCSB个月的出口企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_002 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_002 LONGTEXT;
  DECLARE BJTS_CUR_CKQY_SCSBRQ_002 LONGTEXT;
  DECLARE BJTS_CURSOR_002 CURSOR FOR
SELECT T.DJXH,DATE(MIN(T.QDSJ)) AS SCSBRQ
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_SCSB MONTH) -- 检查24个月内的申报流程
                      AND NOT EXISTS (SELECT 1 -- 不存在中断周期后更早的申报流程
                                        FROM CKTS_LC_SBXX A
                                       WHERE A.DJXH = T.DJXH
                                         AND IFNULL(A.ZFBZ, 'N') = 'N'
                                         AND A.QDSJ < T.QDSJ
                                         AND A.QDSJ >= DATE_ADD(T.QDSJ, INTERVAL (-1) * V_MONTHS_ZDCK MONTH))
                      AND EXISTS (SELECT 1 -- 存在中断周期前更早的申报流程
                                    FROM CKTS_LC_SBXX B
                                   WHERE B.DJXH = T.DJXH
                                     AND IFNULL(B.ZFBZ, 'N') = 'N'
                                     AND B.QDSJ < DATE_ADD(T.QDSJ, INTERVAL (-1) * V_MONTHS_ZDCK MONTH))
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C01001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')))
                    GROUP BY T.DJXH;
  OPEN BJTS_CURSOR_002;
  BJTS_CURSOR_LOOP_002: LOOP
    SET BJTS_CURSOR_DONE_002 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_002 = TRUE;
      FETCH BJTS_CURSOR_002 INTO BJTS_CUR_CKQY_DJXH_002, BJTS_CUR_CKQY_SCSBRQ_002;
    END;
    IF BJTS_CURSOR_DONE_002 THEN
      LEAVE BJTS_CURSOR_LOOP_002;
    END IF;
    -- 统计连续三个月美元出口额，不包含当月数据
    SELECT IFNULL(SUM(MYLAJ), 0)
      INTO V_MYLAJ
      FROM CKTS_WBSJ_HG_BGD
     WHERE DJXH=BJTS_CUR_CKQY_DJXH_002
       AND CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
       AND CKRQ_1<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND ZMTBZ='T';
    -- 如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),TT.SWJGDM,TT.DJXH_JS,IFNULL(TT.SHXYNO, TT.NSRDJNO),TT.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C01001',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]中断后复出口申报日期=', DATE_FORMAT(BJTS_CUR_CKQY_SCSBRQ_002, '%Y%m%d')), '|最近三个月美元出口额='), V_MYLAJ)
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=BJTS_CUR_CKQY_DJXH_002;
      COMMIT;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_002;
  CLOSE BJTS_CURSOR_002;
END;

  -- 迁移后不足V_MONTHS_SCSB个月的外贸企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_CKQY_SCSBRQ_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.DJXH,DATE(MIN(T.QDSJ)) AS SCSBRQ
                     FROM CKTS_LC_SBXX T
                    INNER JOIN (SELECT DJXH,MAX(LRRQ) AS QYRQ -- 最近24个月内最后一次迁移
                                  FROM CKTS_BA_BABGQK_JGB
                                 WHERE BABGZD_DM='TSSWJG_DM_1'
                                   AND LRRQ>=DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_SCSB MONTH)
                                 GROUP BY DJXH) R ON R.DJXH=T.DJXH
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= R.QYRQ -- 检查迁移以后的申报流程
                      AND T.SBYWB_DM='A0301001'
                      AND NOT EXISTS (SELECT 1 -- 不存在迁移以后更早的申报流程
                                        FROM CKTS_LC_SBXX A
                                       WHERE A.DJXH = T.DJXH
                                         AND IFNULL(A.ZFBZ, 'N') = 'N'
                                         AND A.QDSJ < T.QDSJ
                                         AND A.QDSJ >= R.QYRQ)
                      AND EXISTS (SELECT 1 -- 存在迁移以前更早的申报流程
                                    FROM CKTS_LC_SBXX B
                                   WHERE B.DJXH = T.DJXH
                                     AND IFNULL(B.ZFBZ, 'N') = 'N'
                                     AND B.QDSJ < R.QYRQ)
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C01001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')))
                    GROUP BY T.DJXH;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001, BJTS_CUR_CKQY_SCSBRQ_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    -- 统计连续三个月美元出口额，不包含当月数据
    SELECT IFNULL(SUM(MYLAJ), 0)
      INTO V_MYLAJ
      FROM CKTS_WBSJ_HG_BGD
     WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
       AND CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
       AND CKRQ_1<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND ZMTBZ='T';
    -- 如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),TT.SWJGDM,TT.DJXH_JS,IFNULL(TT.SHXYNO, TT.NSRDJNO),TT.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C01001',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]外贸迁移后首次申报日期=', DATE_FORMAT(BJTS_CUR_CKQY_SCSBRQ_001, '%Y%m%d')), '|最近三个月美元出口额='), V_MYLAJ)
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=BJTS_CUR_CKQY_DJXH_001;
      COMMIT;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C01001.sql

-- ======================================================================
-- [019/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C02001.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C02001$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C02001
/*
 * 货物出口日期早于供货企业开业登记日期
 * 需要从金三同步DJ_NSRXX表中KZZTDJLX=1110，KQCCSZTDJBZ=N的名单
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 * 20250829，原来根据上月申报的流程进行扫描，调整为对上月有申报的企业，自上一次相同指标扫描日期（没有扫描日期按系统日期前推一年）之后申报的数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02001_MONTHS_YJJG';
  SET V_PARAMS =ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C02001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 上月以来有申报的外贸企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND T.SBYWB_DM='A0301001'
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C02001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),DJ.SWJGDM,DJ.DJXH_JS,IFNULL(DJ.SHXYNO, DJ.NSRDJNO),DJ.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C02001',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]所属期批次=', YC.SSQPC), '|供货方纳税人='), YC.GHFNSRSBH_1), '|登记日期='), DATE_FORMAT(YC.DJRQ, '%Y%m%d')), '|出口日期范围='), DATE_FORMAT(YC.MIN_CKRQ, '%Y%m%d')), '-'), DATE_FORMAT(YC.MAX_CKRQ, '%Y%m%d')), '|涉及退税额='), TSE)
             FROM (SELECT DJXH,SSQPC,GHFNSRSBH_1,DJRQ,MIN(CKRQ_1) AS MIN_CKRQ,MAX(CKRQ_1) AS MAX_CKRQ,SUM(TSE) AS TSE
                     FROM (SELECT DJXH,ORA_CONCAT(SSQ, SBPC) AS SSQPC,GHFNSRSBH_1,CKRQ_1,TSE,
                                  (SELECT MIN(GH.DJRQ)
                                     FROM CKTS_DJ_NSRXX GH
                                    WHERE GH.NSRSBH=SB.GHFNSRSBH_1
                                      AND GH.NSRZT_DM NOT IN ('09','10')
                                      AND IFNULL(GH.ZXRQ, CURRENT_TIMESTAMP)>SB.KPRQ) AS DJRQ
                             FROM CKTS_SB_MTS_JHMX SB
                             LEFT JOIN (SELECT MAX(SMRQ) AS SMRQ
                                          FROM FXGL_DATA_ZXZB
                                         WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
                                           AND ZBID='C02001'
                                           AND IFNULL(HSRY, '1')!='SYSTEM') HS
                               ON 1=1
                            WHERE SB.DJXH=BJTS_CUR_CKQY_DJXH_001
                              AND SB.SBRQ > IFNULL(HS.SMRQ, DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -24 MONTH))
                              AND CKRQ_1>CAST('1900-01-01' AS DATE) -- CKRQ_1是etl后置存储过程处理的，需要剔除还没赋值的情况
                              AND TSE>0) TT  -- 检查正数申报，红字冲减的去掉
                    WHERE CKRQ_1<DATE(DJRQ)
                    GROUP BY DJXH,SSQPC,GHFNSRSBH_1,DJRQ) YC
            INNER JOIN GLXT_BB_SHXT_DJXX DJ ON DJ.DJXH_JS=YC.DJXH;
      COMMIT;
    END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C02001.sql

-- ======================================================================
-- [020/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C02002.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C02002$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C02002
/*
 * 已申报退税但发票状态非正常
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02002_MONTHS_YJJG';
  SET V_PARAMS =ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C02002'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
       SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),T.TSSWJG_DM,T.DJXH,T.GFNSRSBH,T.GHFMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C02002',
              V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]进货凭证号=', T.JHPZH), '|供货方纳税人='), T.XFNSRSBH), '|原始发票计税金额='), T.JE), '|红字冲减计税金额='), T.HZCJJSJE), '|申报退税计税金额='), T.SBFPJSJE), '|红字冲减日期='), DATE_FORMAT(T.HZCJRQ, '%Y%m%d'))
         FROM FXGL_DATA_YCFP T
        WHERE T.TSSWJG_DM LIKE V_SWJGDM
          AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
          AND T.JE + T.HZCJJSJE < T.SBFPJSJE - 0.1
          AND NOT EXISTS
              (SELECT 1 -- 如果存在未处理的相同进货凭证号，就不再重复插入
                 FROM FXGL_DATA_ZXZB A
                WHERE A.ZBID='C02002'
                  AND A.DJXH=T.DJXH
                  AND REGEXP_LIKE(A.SMJG,T.JHPZH)
                  AND A.HSJGLX='0')
          AND NOT EXISTS
              (SELECT 1 -- 如果存在已处理的相同进货凭证号，预警周期内就不再重复插入
                 FROM FXGL_DATA_ZXZB B
                WHERE B.ZBID='C02002'
                  AND B.DJXH=T.DJXH
                  AND REGEXP_LIKE(B.SMJG,T.JHPZH)
                  AND B.HSJGLX='1'
                  AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                  AND B.HSRY!='SYSTEM');
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C02002.sql

-- ======================================================================
-- [021/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C02003.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C02003$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C02003
/*
 * 供货企业存在复函异常情形
 * 需要从金三同步函调异常数据到TL_ADMIN.YJ_CS_YCHD_JS表中
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_MONTHS_YCFUH  DECIMAL(18,2);    -- 预警参数：异常复函情形起监控周期
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02003_MONTHS_YJJG';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YCFUH
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02003_MONTHS_YCFUH';
  SET V_PARAMS =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG), '|异常复函情形起监控周期='), V_MONTHS_YCFUH);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C02003'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 上月以来有申报的外贸企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_CKQY_LCSLID_SB_001 LONGTEXT;
  DECLARE BJTS_CUR_CKQY_QDSJ_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.DJXH,T.LCSLID_SB,T.QDSJ
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND T.SBYWB_DM='A0301001'
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C02003'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001, BJTS_CUR_CKQY_LCSLID_SB_001, BJTS_CUR_CKQY_QDSJ_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),DJ.SWJGDM,DJ.DJXH_JS,IFNULL(DJ.SHXYNO, DJ.NSRDJNO),DJ.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C02003',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]所属期批次=', YC.SSQPC), '|供货方纳税人='), YC.GHFNSRSBH_1), '|退税额合计='), YC.TSE), '|风险情况=供货企业存在复函异常情形')
             FROM (SELECT SB.DJXH,ORA_CONCAT(SB.SSQ, SB.SBPC) AS SSQPC,SB.GHFNSRSBH_1,SUM(TSE) AS TSE
                     FROM CKTS_SB_MTS_JHMX SB
                    WHERE LCSLID_SB=BJTS_CUR_CKQY_LCSLID_SB_001
                      AND EXISTS (SELECT 1
                                    FROM YJ_CS_YCHD_JS HD
                                   WHERE HD.GHQYNSRSBH_1=SB.GHFNSRSBH_1
                                     AND HD.FUHLX_DM='2'
                                     AND DATE_ADD(HD.FUHQFRQ, INTERVAL V_MONTHS_YCFUH MONTH)>BJTS_CUR_CKQY_QDSJ_001)
                    GROUP BY SB.DJXH,SB.SSQ,SB.SBPC,SB.GHFNSRSBH_1
                   HAVING SUM(SB.TSE)>0) YC
            INNER JOIN GLXT_BB_SHXT_DJXX DJ ON DJ.DJXH_JS=YC.DJXH;
      COMMIT;
    END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C02003.sql

-- ======================================================================
-- [022/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C02004.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C02004$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C02004
/*
 * 连续3个月内供货企业数量变动异常
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_SL_GHQY_LX3M  DECIMAL(18,2);    -- 预警参数：连续3个月内供货企业数量
  DECLARE V_SL_ZB_XZGHQY  DECIMAL(18,2);    -- 预警参数：新增供货企业的数量占比
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);
  DECLARE V_NUM_GHS       BIGINT; --  退税_供货商个数
  DECLARE V_NUM_NEWGHS    BIGINT; --  退税_新增供货商个数

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02004_MONTHS_YJJG';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO v_SL_GHQY_LX3M
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02004_SL_GHQY_LX3M';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_SL_ZB_XZGHQY
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02004_SL_ZB_XZGHQY';
  SET V_PARAMS =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG), '|连续3个月内供货企业数量阈值='), v_SL_GHQY_LX3M), '|新增供货企业的数量占比阈值='), V_SL_ZB_XZGHQY);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX='1' THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C02004'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;


  -- 上月以来有申报的外贸企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND T.SBYWB_DM='A0301001'
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C02004'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
      SELECT COUNT(DISTINCT SB.GHFNSRSBH_1)
        INTO V_NUM_GHS
        FROM CKTS_SB_MTS_JHMX SB
       WHERE SB.DJXH=BJTS_CUR_CKQY_DJXH_001
         AND SB.SBRQ>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH);
      SELECT COUNT(DISTINCT SB.GHFNSRSBH_1)
        INTO V_NUM_NEWGHS
        FROM CKTS_SB_MTS_JHMX SB
       WHERE SB.DJXH=BJTS_CUR_CKQY_DJXH_001
         AND SB.SBRQ>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
         AND NOT EXISTS (SELECT 1
                           FROM CKTS_SB_MTS_JHMX HIS
                          WHERE HIS.DJXH=SB.DJXH
                            AND HIS.GHFNSRSBH_1=SB.GHFNSRSBH_1
                            AND HIS.SBRQ>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -24 MONTH)
                            AND HIS.SBRQ<DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH));
      IF (V_NUM_GHS>=V_SL_GHQY_LX3M AND V_NUM_NEWGHS>=V_SL_ZB_XZGHQY * V_NUM_GHS) THEN
        INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
             SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),DJ.SWJGDM,DJ.DJXH_JS,IFNULL(DJ.SHXYNO, DJ.NSRDJNO),DJ.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C02004',
                    V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]供货商个数=', V_NUM_GHS), '|新增供货商个数='), V_NUM_NEWGHS)
             FROM GLXT_BB_SHXT_DJXX DJ
            WHERE DJ.DJXH_JS=BJTS_CUR_CKQY_DJXH_001;
        COMMIT;
      END IF;
    END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C02004.sql

-- ======================================================================
-- [023/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C02005.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C02005$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C02005
/*
 * 小规模期间供货开13%票
 * 20250912，从金三取数增加首次认定一般纳税人有效期起，模型增加小规模期间出口征税率大于3数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C02005_MONTHS_YJJG';
  SET V_PARAMS =ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C02005'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 上月以来有申报的外贸企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND T.SBYWB_DM='A0301001'
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C02005'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),DJ.SWJGDM,DJ.DJXH_JS,IFNULL(DJ.SHXYNO, DJ.NSRDJNO),DJ.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C02005',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]所属期批次=', YC.SSQPC), '|供货方纳税人='), YC.GHFNSRSBH_1), '|登记日期='), DATE_FORMAT(YC.DJRQ, '%Y%m%d')), '|出口日期范围='), DATE_FORMAT(YC.MIN_CKRQ, '%Y%m%d')), '-'), DATE_FORMAT(YC.MAX_CKRQ, '%Y%m%d')), '|一般纳税人有效期起='), DATE_FORMAT(YC.YBNSRRDRQ, '%Y%m%d')), '发票征税税率='), ZSSL)
             FROM (SELECT DJXH,SSQPC,GHFNSRSBH_1,DJRQ,YBNSRRDRQ,ZSSL,MIN(CKRQ_1) AS MIN_CKRQ,MAX(CKRQ_1) AS MAX_CKRQ,SUM(TSE) AS TSE
                     FROM (SELECT DJXH,ORA_CONCAT(SSQ, SBPC) AS SSQPC,GHFNSRSBH_1,CKRQ_1,ZSSL,TSE,
                                  (SELECT MIN(GH.DJRQ)
                                     FROM CKTS_DJ_NSRXX GH
                                    WHERE GH.NSRSBH=SB.GHFNSRSBH_1
                                      AND GH.NSRZT_DM NOT IN ('09','10')
                                      AND IFNULL(GH.ZXRQ, CURRENT_TIMESTAMP)>SB.KPRQ) AS DJRQ,
                                  (SELECT MIN(GH.YBNSRRDRQ)
                                     FROM CKTS_DJ_NSRXX GH
                                    WHERE GH.NSRSBH=SB.GHFNSRSBH_1
                                      AND GH.NSRZT_DM NOT IN ('09','10')
                                      AND IFNULL(GH.ZXRQ, CURRENT_TIMESTAMP)>SB.KPRQ) AS YBNSRRDRQ
                             FROM CKTS_SB_MTS_JHMX SB
                             LEFT JOIN (SELECT MAX(SMRQ) AS SMRQ
                                          FROM FXGL_DATA_ZXZB
                                         WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
                                           AND ZBID='C02005'
                                           AND IFNULL(HSRY, '1')!='SYSTEM') HS
                               ON 1=1
                            WHERE SB.DJXH=BJTS_CUR_CKQY_DJXH_001
                              AND SB.SBRQ > IFNULL(HS.SMRQ, DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -12 MONTH))
                              AND CKRQ_1>CAST('1900-01-01' AS DATE) -- CKRQ_1是etl后置存储过程处理的，需要剔除还没赋值的情况
                              AND TSE>0) TT  -- 检查正数申报，红字冲减的去掉
                    WHERE CKRQ_1>=DATE(DJRQ)
                      AND CKRQ_1<DATE(YBNSRRDRQ)
                      AND ZSSL>3
                    GROUP BY DJXH,SSQPC,GHFNSRSBH_1,DJRQ,YBNSRRDRQ,ZSSL) YC
            INNER JOIN GLXT_BB_SHXT_DJXX DJ ON DJ.DJXH_JS=YC.DJXH;
      COMMIT;
    END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C02005.sql

-- ======================================================================
-- [024/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C03001.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C03001$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C03001
/*
 * 农产品出口异常模型
 * 农产品列表，在FXGL_SZ_SPFXCK中定义，规则名称为“农产品_”
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_MYLAJ_LX3M    DECIMAL(18,2);    -- 预警参数：连续3个月内美元出口额
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);
  DECLARE V_MYLAJ         DECIMAL(18,2);    -- 统计结果：连续3个月内美元出口额
  DECLARE V_CKSP          VARCHAR(200);
  DECLARE V_CKSPDM        VARCHAR(200);

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C03001_MONTHS_YJJG';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MYLAJ_LX3M
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C03001_MYLAJ_LX3M';
  SET V_PARAMS =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG), '|连续3个月内美元出口额阈值='), V_MYLAJ_LX3M);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C03001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;


  -- 农产品列表
  SELECT CAST(REPLACE(GROUP_CONCAT(T.GZ_SPDM SEPARATOR ','),',','|') AS CHAR)
    INTO V_CKSP
    FROM FXGL_SZ_SPFXCK T
   WHERE T.GZ_MC LIKE '农产品%';

  -- 上月以来有申报的外贸企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND T.SBYWB_DM='A0301001'
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C03001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    -- 统计连续三个月农产品美元出口额，不包含当月数据
    SELECT IFNULL(SUM(MYLAJ), 0), CAST(GROUP_CONCAT(CKSP_DM SEPARATOR ',') AS CHAR)
      INTO V_MYLAJ, V_CKSPDM
      FROM (SELECT CKSP_DM, SUM(MYLAJ) AS MYLAJ
              FROM CKTS_WBSJ_HG_BGD
             WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
               AND CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
               AND CKRQ_1<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
               AND ZMTBZ='T'
               AND REGEXP_LIKE(CKSP_DM,V_CKSP)
             GROUP BY CKSP_DM) AS BJTS_DERIVED_001;
    -- 如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),TT.SWJGDM,TT.DJXH_JS,IFNULL(TT.SHXYNO, TT.NSRDJNO),TT.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C03001',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]连续三个月农产品美元出口额=', V_MYLAJ), '，主要出口商品代码：'), V_CKSPDM)
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=BJTS_CUR_CKQY_DJXH_001;
      COMMIT;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C03001.sql

-- ======================================================================
-- [025/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C04001.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C04001$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C04001
/*
 * 电子产品出口异常模型
 * 电子产品列表，在FXGL_SZ_SPFXCK中定义，规则名称为“电子产品_”
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_MYLAJ_LX3M    DECIMAL(18,2);    -- 预警参数：连续3个月内美元出口额
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);
  DECLARE V_MYLAJ         DECIMAL(18,2);    -- 统计结果：连续3个月内美元出口额
  DECLARE V_CKSP          VARCHAR(200);
  DECLARE V_CKSPDM        VARCHAR(200);

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C04001_MONTHS_YJJG';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MYLAJ_LX3M
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C04001_MYLAJ_LX3M';
  SET V_PARAMS =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG), '|连续3个月内美元出口额阈值='), V_MYLAJ_LX3M);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C04001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 电子产品列表
  SELECT CAST(REPLACE(GROUP_CONCAT(T.GZ_SPDM SEPARATOR ','),',','|') AS CHAR)
    INTO V_CKSP
    FROM FXGL_SZ_SPFXCK T
   WHERE T.GZ_MC LIKE '电子类产品%';

  -- 上月以来有申报的出口企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C04001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    -- 统计连续三个月电子产品美元出口额，不包含当月数据
    SELECT IFNULL(SUM(MYLAJ), 0), CAST(GROUP_CONCAT(CKSP_DM SEPARATOR ',') AS CHAR)
      INTO V_MYLAJ, V_CKSPDM
      FROM (SELECT CKSP_DM, SUM(MYLAJ) AS MYLAJ
              FROM CKTS_WBSJ_HG_BGD
             WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
               AND CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
               AND CKRQ_1<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
               AND ZMTBZ='T'
               AND REGEXP_LIKE(CKSP_DM,V_CKSP)
             GROUP BY CKSP_DM) AS BJTS_DERIVED_001;
    -- 如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),TT.SWJGDM,TT.DJXH_JS,IFNULL(TT.SHXYNO, TT.NSRDJNO),TT.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C04001',
                  V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]连续三个月电子产品美元出口额=', V_MYLAJ), '，主要出口商品代码：'), V_CKSPDM)
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=BJTS_CUR_CKQY_DJXH_001;
      COMMIT;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C04001.sql

-- ======================================================================
-- [026/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C05001.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C05001$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C05001
/*
 * 外贸企业出口增长异常
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_HBZCE_MYLAJ   DECIMAL(18,2);    -- 预警参数：连续3个月内供货企业数量
  DECLARE V_HBZCL_MYLAJ   DECIMAL(18,2);    -- 预警参数：新增供货企业的数量占比
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);
  DECLARE V_MYLAJ_PRE     DECIMAL(18,2); --  前3个月美元
  DECLARE V_MYLAJ_NOW     DECIMAL(18,2); --  现3个月美元
  DECLARE V_MYLAJ_HB      DECIMAL(18,2); --  现3个月美元

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C05001_MONTHS_YJJG';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO v_HBZCE_MYLAJ
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C05001_HBZCE_MYLAJ';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_HBZCL_MYLAJ
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C05001_HBZCL_MYLAJ';
  SET V_PARAMS =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG), '|连续3个月出口额环比增长额阈值='), v_HBZCE_MYLAJ), '|连续3个月出口额环比增长率阈值='), V_HBZCL_MYLAJ);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C05001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 上月以来有申报的外贸企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND T.SBYWB_DM='A0301001'
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C05001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
      -- 统计连续三个月美元出口额，不包含当月数据
      SELECT IFNULL(SUM(MYLAJ), 0)
        INTO V_MYLAJ_NOW
        FROM CKTS_WBSJ_HG_BGD
       WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
         AND CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
         AND CKRQ_1<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
         AND ZMTBZ='T';
      -- 统计环比三个月美元出口额
      SELECT IFNULL(SUM(MYLAJ), 0)
        INTO V_MYLAJ_PRE
        FROM CKTS_WBSJ_HG_BGD
       WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
         AND CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -6 MONTH)
         AND CKRQ_1<DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -3 MONTH)
         AND ZMTBZ='T';
      SET V_MYLAJ_HB = V_MYLAJ_NOW-V_MYLAJ_PRE;
      IF (V_MYLAJ_HB>=V_HBZCE_MYLAJ AND V_MYLAJ_HB>=V_HBZCL_MYLAJ * V_MYLAJ_PRE) THEN
        INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
             SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),DJ.SWJGDM,DJ.DJXH_JS,IFNULL(DJ.SHXYNO, DJ.NSRDJNO),DJ.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C05001',
                    V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]当前3个月出口额=', V_MYLAJ_NOW), '|环比3个月出口额='), V_MYLAJ_PRE), '|环比增长额='), V_MYLAJ_HB)
             FROM GLXT_BB_SHXT_DJXX DJ
            WHERE DJ.DJXH_JS=BJTS_CUR_CKQY_DJXH_001;
        COMMIT;
      END IF;
    END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C05001.sql

-- ======================================================================
-- [027/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C06001.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C06001$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C06001
/*
 * 生产企业生产能力异常
 * 20250605，根据台州反馈，增加上季度报告期电费数据未提取的判断
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 * 20260327，自动扫描条件改为不存在6个月以内已人工核实的数据，因税务人员调整参数自动核实的数据不算
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MONTHS_YJJG   DECIMAL(18,2);    -- 预警参数：预警间隔周期
  DECLARE V_MYLAJ_LX3M    DECIMAL(18,2);    -- 预警参数：连续3个月内美元出口额
  DECLARE V_HBZCL_MYLAJ   DECIMAL(18,2);    -- 预警参数：连续3个月出口额环比增长率
  DECLARE V_HBZCL_DIANFEI DECIMAL(18,2);    -- 预警参数：连续3个月电费环比增长率
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);
  DECLARE V_MYLAJ_PRE     DECIMAL(18,2); --  前3个月美元
  DECLARE V_MYLAJ_NOW     DECIMAL(18,2); --  现3个月美元
  DECLARE V_MYLAJ_HB      DECIMAL(18,2); --  美元环比
  DECLARE V_DIANF_PRE     DECIMAL(18,2); --  前3个月电费
  DECLARE V_DIANF_NOW     DECIMAL(18,2); --  现3个月电费
  DECLARE V_DIANF_HB      DECIMAL(18,2); --  电费环比
  DECLARE V_BGQ_Q         DATETIME;
  DECLARE V_BGQ_Z         DATETIME;

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C06001_MONTHS_YJJG';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO v_MYLAJ_LX3M
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C06001_MYLAJ_LX3M';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_HBZCL_MYLAJ
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C06001_HBZCL_MYLAJ';
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_HBZCL_DIANFEI
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C06001_HBZCL_DIANFEI';
  -- 取上季度起止日期
  SELECT DATE_ADD(DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL ((QUARTER(CURRENT_TIMESTAMP) - 1) * 3) MONTH), INTERVAL -3 MONTH),ORA_DATE_ADD(DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL ((QUARTER(CURRENT_TIMESTAMP) - 1) * 3) MONTH), -(1))
    INTO V_BGQ_Q,V_BGQ_Z
;
  SET V_PARAMS =ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]预警间隔周期=', V_MONTHS_YJJG), '|连续3个月出口额阈值='), v_MYLAJ_LX3M), '|连续3个月出口额环比增长率阈值='), V_HBZCL_MYLAJ), '|连续3个月电费环比增长率阈值='), V_HBZCL_DIANFEI);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C06001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 上月以来有申报的生产企业
  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKQY_DJXH_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) -- 是否单个企业扫描
                      AND IFNULL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -1 MONTH)
                      AND T.SBYWB_DM='A0305001'
                      AND (  (IFNULL(P_SMLX, '0')='1')
                          OR (IFNULL(P_SMLX, '0')='0'
                         AND NOT EXISTS (SELECT 1 -- 预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C06001'
                                            AND B.HSRQ>DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * V_MONTHS_YJJG MONTH)
                                            AND B.HSRY!='SYSTEM')))
                      AND EXISTS (SELECT 1 -- 上季度报告期底账数据已提取
                                    FROM JKGL_DATA_BGQ A
                                   WHERE A.DJXH=T.DJXH
                                     AND A.BGQ_Q=V_BGQ_Q AND A.BGQ_Z=V_BGQ_Z
                                     AND A.DZDZ_ZT='Y');
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKQY_DJXH_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
      -- 取上季度出口额
      SELECT IFNULL(SUM(MYLAJ), 0)
        INTO V_MYLAJ_NOW
        FROM CKTS_WBSJ_HG_BGD
       WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
         AND CKRQ_1>=V_BGQ_Q AND CKRQ_1<=V_BGQ_Z;
      -- 取上季度电费
      SELECT IFNULL(SUM(DZ_DFJE_ZC-DZ_DFJE_SR), 0)
        INTO V_DIANF_NOW
        FROM JKGL_DATA_BGQ BGQ
       INNER JOIN JKGL_DATA_TJ_ZBU ZBU ON ZBU.BGQID=BGQ.BGQID
       WHERE BGQ.DJXH=BJTS_CUR_CKQY_DJXH_001
         AND BGQ.BGQ_Q=V_BGQ_Q AND BGQ.BGQ_Z=V_BGQ_Z
         AND 1=1
LIMIT 1;

      -- 取上上季度出口额
      SELECT IFNULL(SUM(MYLAJ), 0)
        INTO V_MYLAJ_PRE
        FROM CKTS_WBSJ_HG_BGD
       WHERE DJXH=BJTS_CUR_CKQY_DJXH_001
         AND CKRQ_1>=DATE_ADD(V_BGQ_Q, INTERVAL -3 MONTH) AND CKRQ_1<=ORA_DATE_ADD(V_BGQ_Q, -(1));
      -- 取上上季度电费
      SELECT IFNULL(SUM(DZ_DFJE_ZC-DZ_DFJE_SR), 0)
        INTO V_DIANF_PRE
        FROM JKGL_DATA_BGQ BGQ
       INNER JOIN JKGL_DATA_TJ_ZBU ZBU ON ZBU.BGQID=BGQ.BGQID
       WHERE BGQ.DJXH=BJTS_CUR_CKQY_DJXH_001
         AND BGQ.BGQ_Q=DATE_ADD(V_BGQ_Q, INTERVAL -3 MONTH) AND BGQ.BGQ_Z=ORA_DATE_ADD(V_BGQ_Q, -(1))
         AND 1=1
LIMIT 1;

      SET V_MYLAJ_HB = V_MYLAJ_NOW-V_MYLAJ_PRE;
      SET V_DIANF_HB = V_DIANF_NOW-V_DIANF_PRE;
      IF (V_MYLAJ_NOW>=V_MYLAJ_LX3M AND
         (V_MYLAJ_HB>=V_HBZCL_MYLAJ * V_MYLAJ_PRE) AND
         (V_DIANF_HB<V_HBZCL_DIANFEI * V_DIANF_PRE)) THEN
        INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
             SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),DJ.SWJGDM,DJ.DJXH_JS,IFNULL(DJ.SHXYNO, DJ.NSRDJNO),DJ.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C06001',
                    V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]上季度(', DATE_FORMAT(V_BGQ_Q, '%Y%m%d')), '-'), DATE_FORMAT(V_BGQ_Z, '%Y%m%d')), ')出口额='), V_MYLAJ_NOW), '|环比3个月出口额='), V_MYLAJ_PRE), '|出口环比增长额='), V_MYLAJ_HB), '|上季度电费='), V_DIANF_NOW), '|环比3个月电费='), V_DIANF_PRE), '|电费环比增长额='), V_DIANF_HB)
             FROM GLXT_BB_SHXT_DJXX DJ
            WHERE DJ.DJXH_JS=BJTS_CUR_CKQY_DJXH_001;
        COMMIT;
      END IF;
    END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C06001.sql

-- ======================================================================
-- [028/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_C07001.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_C07001$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_C07001
/*
 * 生产企业货源地异常模型
 * 货源地不在本地市，免抵退明细未申报视同自产
 * 数据量有点大，全省202508月申报的类似数据有6512条
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 可空，空默认全省，前台手工刷新需传入
  IN P_DJXH VARCHAR(4000), -- 可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  IN P_SMLX VARCHAR(4000) -- 可空，空默认自动扫描，前台人工扫描输入1
)
routine_body: BEGIN
  DECLARE V_MYLAJ_MIN     DECIMAL(18,2);    -- 预警参数：连续3个月内美元出口额
  DECLARE V_PARAMS        VARCHAR(4000);
  DECLARE V_SWJGDM        VARCHAR(11);

  -- 取本次风险扫描的参数
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO V_MYLAJ_MIN
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C07001_MYLAJ_MIN';
  SET V_PARAMS =ORA_CONCAT('[d]报关单最低货值（美元）=', V_MYLAJ_MIN);

  -- 取本次风险扫描的税务机关范围
  IF IFNULL(P_SWJGDM, '13300000000')='13300000000' THEN
    SET V_SWJGDM ='133%';
  ELSEIF SUBSTR(P_SWJGDM,6)='000000' THEN
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,5), '%');
  ELSE
    SET V_SWJGDM =ORA_CONCAT(SUBSTR(P_SWJGDM,1,7), '%');
  END IF;

  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB AS T
       SET HSJGLX='1',
    HSRQ=CURRENT_TIMESTAMP,
    HSRY='SYSTEM',
    HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C07001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND CAST(DATE_FORMAT(T.SMRQ, '%Y-%m-01') AS DATETIME)=CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
       AND T.HSJGLX='0';
    COMMIT;
  END IF;

  -- 上月申报的免抵退数据
  BEGIN
    INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
         SELECT SEQ_NEXTVAL('SEQ_FXGL_DATA_ZXZB'),CK.TSSWJG_DM,CK.DJXH,IFNULL(DJ.SHXYNO, DJ.NSRDJNO),DJ.NSRMC,IFNULL(P_SMLX, '0'),CURRENT_TIMESTAMP,'C07001',
                V_PARAMS,ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报关单或代理证明号=', IFNULL(CK.CKBGDH, CK.DLCKHWZMHM)), '|美元离岸价='), CK.MYLAJ), '|货源地='), CK.HZDWDQDM), '('), IFNULL(DM.HGHYD_MC, CK.HZDWDQDM)), ')|出口退免税业务类型 = '), IFNULL(CK.CKTMSYWLXDMJH, ' '))
         FROM CKTS_SB_MDT_CKMX CK
        INNER JOIN GLXT_BB_SHXT_DJXX DJ
           ON DJ.DJXH_JS=CK.DJXH
         LEFT JOIN DM_HGHYD DM
           ON DM.HGHYD_DM=CK.HZDWDQDM
        WHERE CK.TSSWJG_DM LIKE V_SWJGDM -- 税务机关范围扫描
          AND CK.SBRQ>=CAST(DATE_FORMAT(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -1 MONTH), '%Y-%m-01') AS DATETIME)
          AND CK.SBRQ<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME) -- 上月申报免抵退，所属期为当前月份-2
          AND (P_DJXH IS NULL OR CK.DJXH=P_DJXH) -- 是否单个企业扫描
          AND CK.MYLAJ>=V_MYLAJ_MIN -- 报关单最低货值
          AND IFNULL(DM.XZQH_DM, CK.HZDWDQDM) <> SUBSTR(CK.TSSWJG_DM,2,4)
          AND NOT REGEXP_LIKE(IFNULL(CK.CKTMSYWLXDMJH, ' '),'ST')
          AND NOT EXISTS (SELECT 1 -- 去重处理
                            FROM FXGL_DATA_ZXZB ZB
                           WHERE ZB.DJXH=CK.DJXH
                             AND ZB.ZBID='C07001'
                             AND REGEXP_LIKE(ZB.SMJG,IFNULL(CK.CKBGDH, CK.DLCKHWZMHM))
                             AND ZB.HSJGLX='0');
    COMMIT;
  END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_C07001.sql

-- ======================================================================
-- [029/146] BEGIN SOURCE: PRO_FXGL_COMPUTE_MAIN.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_COMPUTE_MAIN$$

CREATE PROCEDURE PRO_FXGL_COMPUTE_MAIN()
/*
 * 态势感知平台——风险管理——日常监管指标
 * 自动扫描主程序
 */
routine_body: BEGIN

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_LSF_SWJG_SWJG_DM_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1' AND QYBZ='Y' AND YXWS=7 ORDER BY SWJG_DM;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_LSF_SWJG_SWJG_DM_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    CALL PRO_FXGL_COMPUTE_C01001(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C02001(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C02002(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C02003(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C02004(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C02005(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C03001(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C04001(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C05001(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);
    CALL PRO_FXGL_COMPUTE_C06001(BJTS_LSF_SWJG_SWJG_DM_001,NULL,NULL);

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

   CALL PRO_FXGL_COMPUTE_C07001('13310000000',NULL,NULL);
   CALL PRO_FXGL_COMPUTE_C07001('13307000000',NULL,NULL);

END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_COMPUTE_MAIN.sql

-- ======================================================================
-- [030/146] BEGIN SOURCE: PRO_FXGL_DATA_FZPCKQY.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_DATA_FZPCKQY$$

CREATE PROCEDURE PRO_FXGL_DATA_FZPCKQY()
/*
 * 纺织品出口企业风险指标提取过程
 */
routine_body: BEGIN

  -- 1、先运行zj_bjts用户下的PRO_DEAL_FXGL_DATA_FZPCKQY存储过程，获取FXGL_DATA_FZPCKQY企业信息
  -- 2、调用ETL抽取进销项发票数据到FXGL_DATA_FZPCKQY_FPXX表中
  -- 数据抽取逻辑如下
/*
  INSERT INTO FXGL_DATA_FZPCKQY_FPXX
         (FPHM,XH,KPRQ,XSFNSRSBH,XSFMC,XHFDJXH,GMFNSRSBH,GMFMC,GMFDJXH,SPHFWSSFLHBBM,SPFWJC,XMMC,GGXH,DW,FPSPDJ,FPSPSL,JE,SL_1,SE,SPBM5,SL)
  SELECT HW.FPHM,HW.XH,HW.KPRQ,
         FP.XSFNSRSBH,FP.XSFMC,FP.XHFDJXH,
         FP.GMFNSRSBH,FP.GMFMC,FP.GMFDJXH,
         HW.SPHFWSSFLHBBM,HW.SPFWJC,HW.XMMC,HW.GGXH,
         UPPER(HW.DW),
         HW.FPSPDJ,HW.FPSPSL,HW.JE,HW.SL_1,HW.SE,
         SUBSTR(HW.SPHFWSSFLHBBM,1,5),TO_NUMBER(HW.FPSPSL)
    FROM DZFP_KPYW_FPJCXXB FP
   INNER JOIN DZFP_KPYW_FPMXXXB HW
      ON HW.FPHM=FP.FPHM
   WHERE FP.KPRQ >= LD_FXRQQ AND FP.KPRQ < LD_FXRQZ
     AND (FP.XSFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_FZPCKQY) OR
         FP.GMFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_FZPCKQY));
  COMMIT;
*/

  SET @BJTS_DYNAMIC_SQL_001 = 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_JXMX';
PREPARE BJTS_DYNAMIC_STMT_001 FROM @BJTS_DYNAMIC_SQL_001;
EXECUTE BJTS_DYNAMIC_STMT_001;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_001;
  COMMIT;

  -- 进项发票（采购原材料）按商品大类、名称分组
  INSERT INTO FXGL_DATA_FZPCKQY_JXMX
         (DJXH,SPBM5,XMMC,DW,SL,JE,SE)
  SELECT FP.GMFDJXH,FP.SPBM5,FP.XMMC,FP.DW,SUM(CAST(FP.FPSPSL AS DECIMAL(65,30))),SUM(FP.JE),SUM(FP.SE)
    FROM FXGL_DATA_FZPCKQY_FPXX FP
   WHERE FP.GMFDJXH IS NOT NULL
     AND FP.SPBM5 IN ('10401', '10704')
     AND FP.SE <> 0 -- 出口单证不算
     AND (FP.DW NOT IN ('T', '吨', 'KM', '千米') OR
         (FP.DW IN ('T', '吨', 'KM', '千米') AND CAST(FP.FPSPDJ AS DECIMAL(65,30))>100))  -- 单价过低的吨和千米，应该是发票开错，应为公斤或米，不参与计算
   GROUP BY FP.GMFDJXH,FP.SPBM5,FP.XMMC,FP.DW;
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_002 = 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_JXXX';
PREPARE BJTS_DYNAMIC_STMT_002 FROM @BJTS_DYNAMIC_SQL_002;
EXECUTE BJTS_DYNAMIC_STMT_002;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_002;
  COMMIT;

  -- 进项发票（采购原材料）按商品大类、名称分组统计
  INSERT INTO FXGL_DATA_FZPCKQY_JXXX
         (DJXH,SPBM5,JH_SL_KG,JH_JE_KG,JH_DJ_KG,JH_DJ_KG_PJ,JH_SL_M,JH_JE_M,JH_DJ_M,JH_DJ_M_PJ,JH_JE_NOTKG,JH_GJ_M)
  WITH
  MD AS (
  SELECT DJXH, IFNULL(CK_GJ_M, CK_GJ_M_PJ) AS JH_GJ_M, '10401' AS SPBM5
    FROM FXGL_DATA_FZPCKQY
   UNION
  SELECT DJXH, IFNULL(CK_GJ_M, CK_GJ_M_PJ) AS JH_GJ_M, '10704' AS SPBM5
    FROM FXGL_DATA_FZPCKQY
  ),
  JX_KG AS ( -- 重量单位计算
  SELECT DJXH,
         SPBM5,
         SUM(CASE
               WHEN DW IN ('T', '吨') THEN SL * 1000
               WHEN DW IN ('KG', '公斤', '千克') THEN SL
               ELSE 0
             END) AS JX_SL_KG,
         SUM(JE) AS JX_JE_KG,
         CASE
           WHEN SUM(ABS(JE)) =0
             OR SUM(ABS(JE)) IS NULL
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)=0
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END) IS NULL
           THEN NULL
           ELSE SUM(ABS(JE)) /
                SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)
         END  AS JX_DJ_KG
    FROM FXGL_DATA_FZPCKQY_JXMX
   WHERE DW IN ('T', '吨', 'KG', '公斤', '千克')
   GROUP BY DJXH,SPBM5
  ),
  DJALL_KG AS (
  SELECT SPBM5,
         SUM(ABS(JX_JE_KG)) / SUM(ABS(JX_SL_KG)) AS JX_DJ_KG_PJ
    FROM JX_KG
   GROUP BY SPBM5
  ),
  JX_M AS ( -- 长度单位计算
  SELECT DJXH,
         SPBM5,
         SUM(CASE
               WHEN DW IN ('KM', '千米') THEN SL*1000
               WHEN DW IN ('百米') THEN SL*100
               WHEN DW IN ('M', '米') THEN SL
               WHEN DW IN ('码') THEN SL*0.9144
               ELSE 0
             END) AS JX_SL_M,
         SUM(JE) AS JX_JE_M,
         CASE
           WHEN SUM(ABS(JE)) =0
             OR SUM(ABS(JE)) IS NULL
             OR SUM(CASE
                      WHEN DW IN ('KM', '千米') THEN ABS(SL)*1000
                      WHEN DW IN ('百米') THEN ABS(SL)*100
                      WHEN DW IN ('M', '米') THEN ABS(SL)
                      WHEN DW IN ('码') THEN ABS(SL)*0.9144
                      ELSE 0
                    END)=0
             OR SUM(CASE
                      WHEN DW IN ('KM', '千米') THEN ABS(SL)*1000
                      WHEN DW IN ('百米') THEN ABS(SL)*100
                      WHEN DW IN ('M', '米') THEN ABS(SL)
                      WHEN DW IN ('码') THEN ABS(SL)*0.9144
                      ELSE 0
                    END) IS NULL
           THEN NULL
           ELSE SUM(ABS(JE)) /
                SUM(CASE
                      WHEN DW IN ('KM', '千米') THEN ABS(SL)*1000
                      WHEN DW IN ('百米') THEN ABS(SL)*100
                      WHEN DW IN ('M', '米') THEN ABS(SL)
                      WHEN DW IN ('码') THEN ABS(SL)*0.9144
                      ELSE 0
                    END)
         END AS JX_DJ_M
    FROM FXGL_DATA_FZPCKQY_JXMX
   WHERE DW IN ('KM', '千米', '百米', 'M', '米', '码')
     AND XMMC NOT LIKE '%带'
     AND XMMC NOT LIKE '%线'
   GROUP BY DJXH, SPBM5
  ),
  DJALL_M AS (
  SELECT SPBM5,
         SUM(ABS(JX_JE_M)) / SUM(ABS(JX_SL_M)) AS JX_DJ_M_PJ
    FROM JX_M
   GROUP BY SPBM5
  ),
  JX_NOTKG AS ( -- 非重量计，非长度计部分采购，从金额算重量
  SELECT DJXH, SPBM5, SUM(JE) AS JX_JE_NOTKG
    FROM FXGL_DATA_FZPCKQY_JXMX
   WHERE DW NOT IN ('T', '吨', 'KG', '公斤', '千克', 'KM', '千米', '百米', 'M', '米', '码')
   GROUP BY DJXH, SPBM5
  )
  SELECT MD.DJXH,
         MD.SPBM5,
         IFNULL(JX_KG.JX_SL_KG, 0),
         IFNULL(JX_KG.JX_JE_KG, 0),
         IFNULL(JX_KG.JX_DJ_KG, DJALL_KG.JX_DJ_KG_PJ),
         DJALL_KG.JX_DJ_KG_PJ,
         IFNULL(JX_M.JX_SL_M, 0),
         IFNULL(JX_M.JX_JE_M, 0),
         IFNULL(JX_M.JX_DJ_M, DJALL_M.JX_DJ_M_PJ),
         DJALL_M.JX_DJ_M_PJ,
         IFNULL(JX_NOTKG.JX_JE_NOTKG, 0),
         MD.JH_GJ_M
    FROM MD
    LEFT JOIN JX_KG ON JX_KG.DJXH=MD.DJXH AND JX_KG.SPBM5=MD.SPBM5
    LEFT JOIN DJALL_KG ON DJALL_KG.SPBM5=MD.SPBM5
    LEFT JOIN JX_M ON JX_M.DJXH=MD.DJXH AND JX_M.SPBM5=MD.SPBM5
    LEFT JOIN DJALL_M ON DJALL_M.SPBM5=MD.SPBM5
    LEFT JOIN JX_NOTKG ON JX_NOTKG.DJXH=MD.DJXH AND JX_NOTKG.SPBM5=MD.SPBM5;
  COMMIT;

  -- 更新原材料采购指标
  UPDATE FXGL_DATA_FZPCKQY AS T
     SET JH_ZZL = (SELECT SUM(S.JH_SL_KG + S.JH_SL_M * S.JH_GJ_M + S.JH_JE_NOTKG / S.JH_DJ_KG)
FROM FXGL_DATA_FZPCKQY_JXXX S
   WHERE S.DJXH=T.DJXH),
    JH_ZJE = (SELECT SUM(S.JH_JE_KG + S.JH_JE_M + S.JH_JE_NOTKG)
FROM FXGL_DATA_FZPCKQY_JXXX S
   WHERE S.DJXH=T.DJXH),
    JH_DJ_GJ = (SELECT AVG(S.JH_DJ_KG)
FROM FXGL_DATA_FZPCKQY_JXXX S
   WHERE S.DJXH=T.DJXH),
    JH_DJ_GJ_PJ = (SELECT AVG(S.JH_DJ_KG_PJ)
FROM FXGL_DATA_FZPCKQY_JXXX S
   WHERE S.DJXH=T.DJXH),
    JH_DJ_M = (SELECT AVG(S.JH_DJ_M)
FROM FXGL_DATA_FZPCKQY_JXXX S
   WHERE S.DJXH=T.DJXH),
    JH_DJ_M_PJ = (SELECT AVG(S.JH_DJ_M_PJ)
FROM FXGL_DATA_FZPCKQY_JXXX S
   WHERE S.DJXH=T.DJXH);
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_003 = 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_NXMX';
PREPARE BJTS_DYNAMIC_STMT_003 FROM @BJTS_DYNAMIC_SQL_003;
EXECUTE BJTS_DYNAMIC_STMT_003;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_003;
  COMMIT;

  -- 内销发票按商品大类、名称分组
  INSERT INTO FXGL_DATA_FZPCKQY_NXMX
         (DJXH,SPBM5,XMMC,DW,SL,JE,SE)
  SELECT FP.XHFDJXH,FP.SPBM5,FP.XMMC,FP.DW,SUM(CAST(FP.FPSPSL AS DECIMAL(65,30))),SUM(FP.JE),SUM(FP.SE)
    FROM FXGL_DATA_FZPCKQY_FPXX FP
   WHERE FP.XHFDJXH IS NOT NULL
     AND FP.SPBM5 IN ('10401', '10402', '10704')
     AND FP.SE <> 0 -- 出口单证不算
     AND (FP.DW NOT IN ('T', '吨', 'KM', '千米') OR
         (FP.DW IN ('T', '吨', 'KM', '千米') AND CAST(FP.FPSPDJ AS DECIMAL(65,30))>100))  -- 单价过低的吨和千米，应该是发票开错，应为公斤或米，不参与计算
   GROUP BY FP.XHFDJXH,FP.SPBM5,FP.XMMC,FP.DW;
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_004 = 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_NXXX';
PREPARE BJTS_DYNAMIC_STMT_004 FROM @BJTS_DYNAMIC_SQL_004;
EXECUTE BJTS_DYNAMIC_STMT_004;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_004;
  COMMIT;

  -- 内销发票按商品大类、名称分组统计
  INSERT INTO FXGL_DATA_FZPCKQY_NXXX
         (DJXH,SPBM5,NX_SL_KG,NX_JE_KG,NX_DJ_KG,NX_DJ_KG_PJ,NX_JE_NOTKG)
  WITH
  MD AS (
  SELECT DJXH, SPBM5
    FROM FXGL_DATA_FZPCKQY_NXMX
   GROUP BY DJXH, SPBM5
  ),
  NX_KG AS ( -- 重量单位计算
  SELECT DJXH,
         SPBM5,
         SUM(CASE
               WHEN DW IN ('T', '吨') THEN SL * 1000
               WHEN DW IN ('KG', '公斤', '千克') THEN SL
               ELSE 0
             END) AS NX_SL_KG,
         SUM(JE) AS NX_JE_KG,
         CASE
           WHEN SUM(ABS(JE)) =0
             OR SUM(ABS(JE)) IS NULL
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)=0
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END) IS NULL
           THEN NULL
           ELSE SUM(ABS(JE)) /
                SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)
         END  AS NX_DJ_KG
    FROM FXGL_DATA_FZPCKQY_NXMX
   WHERE DW IN ('T', '吨', 'KG', '公斤', '千克')
   GROUP BY DJXH,SPBM5
  ),
  DJALL_KG AS (
  SELECT SPBM5,
         SUM(ABS(NX_JE_KG)) / SUM(ABS(NX_SL_KG)) AS NX_DJ_KG_PJ
    FROM NX_KG
   GROUP BY SPBM5
  ),
  NX_NOTKG AS ( -- 非重量计，从金额算重量
  SELECT DJXH, SPBM5, SUM(JE) AS NX_JE_NOTKG
    FROM FXGL_DATA_FZPCKQY_NXMX
   WHERE DW NOT IN ('T', '吨', 'KG', '公斤', '千克')
   GROUP BY DJXH, SPBM5
  )
  SELECT MD.DJXH,
         MD.SPBM5,
         IFNULL(NX_KG.NX_SL_KG, 0),
         IFNULL(NX_KG.NX_JE_KG, 0),
         IFNULL(NX_KG.NX_DJ_KG, DJALL_KG.NX_DJ_KG_PJ),
         DJALL_KG.NX_DJ_KG_PJ,
         IFNULL(NX_NOTKG.NX_JE_NOTKG, 0)
    FROM MD
    LEFT JOIN NX_KG ON NX_KG.DJXH=MD.DJXH AND NX_KG.SPBM5=MD.SPBM5
    LEFT JOIN DJALL_KG ON DJALL_KG.SPBM5=MD.SPBM5
    LEFT JOIN NX_NOTKG ON NX_NOTKG.DJXH=MD.DJXH AND NX_NOTKG.SPBM5=MD.SPBM5;
  COMMIT;

  -- 更新内销指标
  UPDATE FXGL_DATA_FZPCKQY AS T
     SET NX_ZZL = (SELECT SUM(S.NX_SL_KG + S.NX_JE_NOTKG / S.NX_DJ_KG_PJ)
FROM FXGL_DATA_FZPCKQY_NXXX S
   WHERE S.DJXH=T.DJXH),
    NX_ZJE = (SELECT SUM(S.NX_JE_KG + S.NX_JE_NOTKG)
FROM FXGL_DATA_FZPCKQY_NXXX S
   WHERE S.DJXH=T.DJXH);
  COMMIT;

  -- 更新耗电指标
  UPDATE FXGL_DATA_FZPCKQY AS T
     SET DL_JE = (
  SELECT SUM(S.JE)
    FROM FXGL_DATA_FZPCKQY_FPXX S
   WHERE (S.XHFDJXH = T.DJXH OR
          S.GMFDJXH = T.DJXH)
     AND ((REGEXP_LIKE(S.SPHFWSSFLHBBM,'^110010102') AND REGEXP_LIKE(S.XMMC,'电')) OR
          REGEXP_LIKE(S.XMMC,'电能耗|电( )*[费量价补能谷峰购]|[水风售份耗谷峰]电|([水风用月季年份发供耗]电|能耗|空调费|力)(费|收入)?[0-9A-Z [:punct:]]*$|电.*月'))
     AND S.SPFWJC = '供电' );
  COMMIT;

END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_DATA_FZPCKQY.sql

-- ======================================================================
-- [031/146] BEGIN SOURCE: PRO_FXGL_DATA_STZCANDGJSB.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_DATA_STZCANDGJSB$$

CREATE PROCEDURE PRO_FXGL_DATA_STZCANDGJSB()
/*
 * 生产企业出口外购货物风险模型、购进设备开1%3%普票风险模型
 */
routine_body: BEGIN

  -- 1、先运行zj_bjts用户下的PRO_DEAL_FXGL_STZCANDGJSB存储过程，获取FXGL_DATA_STZC企业信息
  -- 2、提取sbtscke>100000的数据到本地，目前有29961户
  -- 3、调用ETL抽取进销项发票数据到FXGL_DATA_STZC_FPXX表中
  -- 数据抽取逻辑如下
/*
  INSERT INTO FXGL_DATA_STZC_FPXX
         (FPHM,XH,KPRQ,XSFNSRSBH,XHFDJXH,GMFNSRSBH,GMFDJXH,SPHFWSSFLHBBM,XMMC,FPSPDJ,FPSPSL,JE,SL_1,SE,BZ)
  SELECT HW.FPHM,HW.XH,HW.KPRQ,
         FP.XSFNSRSBH,FP.XHFDJXH,
         FP.GMFNSRSBH,FP.GMFDJXH,
         HW.SPHFWSSFLHBBM,HW.XMMC,
         HW.FPSPDJ,HW.FPSPSL,HW.JE,HW.SL_1,HW.SE,
         FP.BZ
    FROM DZFP_KPYW_FPJCXXB FP
   INNER JOIN DZFP_KPYW_FPMXXXB HW
      ON HW.FPHM=FP.FPHM
   WHERE FP.KPRQ >= DATE'2024-01-01' AND FP.KPRQ < DATE'2026-01-01'
     --AND FP.FPZT_DM<>'2'
     AND NOT REGEXP_LIKE(HW.XMMC, '原价合计|折扣额合计'
     AND (FP.XSFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_STZC) OR
         FP.GMFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_STZC));
  COMMIT;
*/
  -- 4、调用ETL抽取采购设备的进项发票（包括数电、专票、普票）数据到FXGL_DATA_STZC_FPXX_GJ表中
  -- 数据抽取逻辑如下
/*
  INSERT INTO FXGL_DATA_STZC_FPXX_GJ
         (FPHM,XH,KPRQ,XSFNSRSBH,XHFDJXH,GMFNSRSBH,GMFDJXH,SPHFWSSFLHBBM,XMMC,FPSPDJ,FPSPSL,JE,SL_1,SE,BZ,FPLB)
  SELECT HW.FPHM,HW.XH,HW.KPRQ,
         FP.XSFNSRSBH,FP.XHFDJXH,
         FP.GMFNSRSBH,FP.GMFDJXH,
         HW.SPHFWSSFLHBBM,HW.XMMC,
         HW.FPSPDJ,HW.FPSPSL,HW.JE,HW.SL_1,HW.SE,
         FP.BZ,FPLB -- 底帐库根据专票、普票的对应表设置，数电票需要根据发票的某个字段区分，分别设置为“专票、普票”
    FROM DZFP_KPYW_FPJCXXB FP
   INNER JOIN DZFP_KPYW_FPMXXXB HW
      ON HW.FPHM=FP.FPHM
   WHERE FP.GMFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_STZC)
     --AND FP.FPZT_DM<>'2'
     AND FP.SPHFWSSFLHBBM LIKE '109%' -- 购进设备
     AND (CASE WHEN NVL(HW.FPSPDJ,'0')='0' OR UPPER(HW.FPSPDJ)='NULL' THEN HW.JE ELSE TO_NUMBER(HW.FPSPDJ) END)>5000; -- 单价5000以上
  COMMIT;
*/

  SET @BJTS_DYNAMIC_SQL_001 = 'TRUNCATE TABLE FXGL_DATA_STZC_CKMX';
PREPARE BJTS_DYNAMIC_STMT_001 FROM @BJTS_DYNAMIC_SQL_001;
EXECUTE BJTS_DYNAMIC_STMT_001;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_001;
  COMMIT;

  -- 出口发票按商品编码、名称分组
  INSERT INTO FXGL_DATA_STZC_CKMX(DJXH,SPHFWSSFLHBBM,XMMC,JE)
  SELECT FP.XHFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC,SUM(FP.JE)
    FROM FXGL_DATA_STZC_FPXX FP
   WHERE FP.XHFDJXH IS NOT NULL
     AND FP.SE = 0 -- 出口业务，全省除绍兴，其他大部分开免税，因此用税额判断
     AND REGEXP_LIKE(FP.BZ,'出口业务')
   GROUP BY FP.XHFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC;
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_002 = 'TRUNCATE TABLE FXGL_DATA_STZC_JXMX';
PREPARE BJTS_DYNAMIC_STMT_002 FROM @BJTS_DYNAMIC_SQL_002;
EXECUTE BJTS_DYNAMIC_STMT_002;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_002;
  COMMIT;

  -- 进货发票按商品编码、名称分组
  INSERT INTO FXGL_DATA_STZC_CKMX(DJXH,SPHFWSSFLHBBM,XMMC,JE)
  SELECT FP.GMFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC,SUM(FP.JE)
    FROM FXGL_DATA_STZC_FPXX FP
   WHERE FP.GMFDJXH IS NOT NULL
   GROUP BY FP.GMFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC;
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_003 = 'TRUNCATE TABLE FXGL_DATA_STZC_YSWG_BM';
PREPARE BJTS_DYNAMIC_STMT_003 FROM @BJTS_DYNAMIC_SQL_003;
EXECUTE BJTS_DYNAMIC_STMT_003;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_003;
  COMMIT;

  -- 按商品编码分组疑似外购比较
  INSERT INTO FXGL_DATA_STZC_YSWG_BM(DJXH,SPHFWSSFLHBBM,CKJE,JHJE,YSWG_BFB,YSWG_CKJE)
  SELECT A.DJXH,A.SPHFWSSFLHBBM,A.CKJE,B.JHJE,
         CASE
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN 100
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN ROUND(B.JHJE*100/A.CKJE,2)
           ELSE 0
         END AS YSWG_BFB,
         CASE
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN A.CKJE
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN B.JHJE
           ELSE 0
         END AS YSWG_CKJE
    FROM (SELECT DJXH,SPHFWSSFLHBBM,SUM(JE) AS CKJE FROM FXGL_DATA_STZC_CKMX GROUP BY DJXH,SPHFWSSFLHBBM) A
   INNER JOIN (SELECT DJXH,SPHFWSSFLHBBM,SUM(JE) AS JHJE FROM FXGL_DATA_STZC_JXMX GROUP BY DJXH,SPHFWSSFLHBBM) B
      ON A.DJXH=B.DJXH AND A.SPHFWSSFLHBBM=B.SPHFWSSFLHBBM;
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_004 = 'TRUNCATE TABLE FXGL_DATA_STZC_YSWG_MC';
PREPARE BJTS_DYNAMIC_STMT_004 FROM @BJTS_DYNAMIC_SQL_004;
EXECUTE BJTS_DYNAMIC_STMT_004;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_004;
  COMMIT;

  -- 按商品编码、名称分组疑似外购比较
  INSERT INTO FXGL_DATA_STZC_YSWG_MC(DJXH,SPHFWSSFLHBBM,XMMC,CKJE,JHJE,YSWG_BFB,YSWG_CKJE)
  SELECT A.DJXH,A.SPHFWSSFLHBBM,A.XMMC,A.CKJE,B.JHJE,
         CASE
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN 100
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN ROUND(B.JHJE*100/A.CKJE,2)
           ELSE 0
         END AS YSWG_BFB,
         CASE
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN A.CKJE
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN B.JHJE
           ELSE 0
         END AS YSWG_CKJE
    FROM (SELECT DJXH,SPHFWSSFLHBBM,XMMC,SUM(JE) AS CKJE FROM FXGL_DATA_STZC_CKMX GROUP BY DJXH,SPHFWSSFLHBBM,XMMC) A
   INNER JOIN (SELECT DJXH,SPHFWSSFLHBBM,XMMC,SUM(JE) AS JHJE FROM FXGL_DATA_STZC_JXMX GROUP BY DJXH,SPHFWSSFLHBBM,XMMC) B
      ON A.DJXH=B.DJXH AND A.SPHFWSSFLHBBM=B.SPHFWSSFLHBBM AND A.XMMC=B.XMMC;
  COMMIT;

  UPDATE FXGL_DATA_STZC AS T
     SET FP_CKE=(
         SELECT SUM(FP.JE)
           FROM FXGL_DATA_STZC_FPXX FP
          WHERE FP.XHFDJXH=T.DJXH
            AND FP.SE = 0 -- 出口业务，全省除绍兴，其他大部分开免税，因此用税额判断
            AND REGEXP_LIKE(FP.BZ,'出口业务')),
    FP_GJE=(
         SELECT SUM(FP.JE)
           FROM FXGL_DATA_STZC_FPXX FP
          WHERE FP.GMFDJXH=T.DJXH),
    YSWG_CKJE_BM=(
         SELECT SUM(YSWG_CKJE)
           FROM FXGL_DATA_STZC_YSWG_BM BM
          WHERE BM.DJXH=T.DJXH),
    YSWG_CKJE_MC=(
         SELECT SUM(YSWG_CKJE)
           FROM FXGL_DATA_STZC_YSWG_MC MC
          WHERE MC.DJXH=T.DJXH)
   WHERE T.ETL_BZ='1';
  COMMIT;

  UPDATE FXGL_DATA_STZC AS T
     SET YSWG_CKZB_BM = ROUND(100* T.YSWG_CKJE_BM/T.FP_CKE,2),
    YSWG_CKZB_MC = ROUND(100* T.YSWG_CKJE_MC/T.FP_CKE,2)
   WHERE T.ETL_BZ='1'
     AND T.FP_CKE>0;
  COMMIT;

  UPDATE FXGL_DATA_STZC AS T
     SET GJSB_MINKPRQ = (SELECT MIN(FP.KPRQ)
FROM FXGL_DATA_STZC_FPXX_GJ FP
          WHERE FP.GMFDJXH=T.DJXH),
    GJSB_ZJE = (SELECT SUM(FP.JE)
FROM FXGL_DATA_STZC_FPXX_GJ FP
          WHERE FP.GMFDJXH=T.DJXH),
    GJSB_XGM_PP = (SELECT SUM(CASE WHEN FP.SL_1<=0.03 AND FP.FPLB='普票' THEN FP.JE ELSE 0 END)
FROM FXGL_DATA_STZC_FPXX_GJ FP
          WHERE FP.GMFDJXH=T.DJXH),
    GJSB_XGM_ZP = (SELECT SUM(CASE WHEN FP.SL_1<=0.03 AND FP.FPLB='专票' THEN FP.JE ELSE 0 END)
FROM FXGL_DATA_STZC_FPXX_GJ FP
          WHERE FP.GMFDJXH=T.DJXH)
   WHERE T.ETL_BZ='1';
  COMMIT;

  UPDATE FXGL_DATA_STZC AS T
     SET GJSB_ZB_PP = ROUND(100* T.GJSB_XGM_PP/T.GJSB_ZJE,2)
   WHERE T.ETL_BZ='1'
     AND T.GJSB_ZJE>0;
  COMMIT;

  UPDATE FXGL_DATA_STZC AS T
     SET ETL_BZ='2'
   WHERE T.ETL_BZ='1';
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_005 = 'TRUNCATE TABLE FXGL_DATA_STZC_FPXX';
PREPARE BJTS_DYNAMIC_STMT_005 FROM @BJTS_DYNAMIC_SQL_005;
EXECUTE BJTS_DYNAMIC_STMT_005;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_005;
  COMMIT;

  SET @BJTS_DYNAMIC_SQL_006 = 'TRUNCATE TABLE FXGL_DATA_STZC_FPXX_GJ';
PREPARE BJTS_DYNAMIC_STMT_006 FROM @BJTS_DYNAMIC_SQL_006;
EXECUTE BJTS_DYNAMIC_STMT_006;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_006;
  COMMIT;

  -- 输出生产企业出口外购货物风险模型企业清单
/*
  SELECT A.DJXH,
         A.NSRSBH  纳税人识别号,
         A.NSRMC  纳税人名称,
         A.ZGSWJ_DM  主管税务机关编码,
         A.ZGSWJ_MC  主管税务机关名称,
         A.HY_DM  行业代码,
         A.HY_MC  行业名称,
         TO_CHAR(A.BARQ,'yyyy-mm-dd')  退税备案日期,
         A.FP_CKE  出口发票总金额,
         A.FP_GJE  购进发票总金额,
         A.SBTS_CKE  申报退税出口额,
         A.SBTS_WGCKE  申报退税外购出口额,
         A.YSWG_CKJE_BM  疑似外购出口金额_编码,
         A.YSWG_CKZB_BM  疑似外购出口占比_编码,
         A.YSWG_CKJE_MC  疑似外购出口金额_品名,
         A.YSWG_CKZB_MC  疑似外购出口占比_品名
    FROM FXGL_DATA_STZC A
   WHERE A.FP_CKE>0
     AND A.YSWG_CKZB_BM>30
     AND A.YSWG_CKJE_MC>100000;
*/
  -- 输出生产企业购进设备开1%3%普票风险模型企业清单
/*
  SELECT A.DJXH,
         A.NSRSBH  纳税人识别号,
         A.NSRMC  纳税人名称,
         A.ZGSWJ_DM  主管税务机关编码,
         A.ZGSWJ_MC  主管税务机关名称,
         A.HY_DM  行业代码,
         A.HY_MC  行业名称,
         TO_CHAR(A.BARQ,'yyyy-mm-dd')  退税备案日期,
         TO_CHAR(A.GJSB_MINKPRQ,'yyyy-mm-dd')  购进设备统计期起,
         A.GJSB_ZJE  购进设备总金额,
         A.GJSB_XGM_PP  其中开具小规模普票金额,
         A.GJSB_XGM_ZP  其中开具小规模专票金额,
         A.GJSB_ZB_PP  开具小规模普票占比
    FROM FXGL_DATA_STZC A
   WHERE A.GJSB_ZJE>0
     AND A.GJSB_XGM_PP>100000;
*/
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_DATA_STZCANDGJSB.sql

-- ======================================================================
-- [032/146] BEGIN SOURCE: PRO_FXGL_FXSPCK_DZXX.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_FXSPCK_DZXX$$

CREATE PROCEDURE PRO_FXGL_FXSPCK_DZXX()
/*
 * 风险商品出口电子信息提取
 * 20250331，根据省局李裕军局长意见，对市场采购业务不做风险商品出口短信提醒
 */
routine_body: BEGIN
  DECLARE LD_BEGINDATE      DATETIME;

  SELECT ORA_DATE_ADD(MAX(T.SJTB_SJ), -(3)) INTO LD_BEGINDATE FROM CKTS_WBSJ_HG_BGD T;

  BEGIN
  DECLARE BJTS_CURSOR_DONE_002 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_FXGZ_GZ_MC_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_FXMS_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_FW_SWJG_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_SPDM_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_SPMC_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_GGXH_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_CKKA_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_CKGB_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_HYD_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_DJQ_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_DJZ_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_ZJQ_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_ZJZ_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_YXQZ_002 LONGTEXT;
  DECLARE BJTS_CUR_FXGZ_GZ_DXTXBZ_002 LONGTEXT;
  DECLARE BJTS_CURSOR_002 CURSOR FOR
SELECT GZ_MC,GZ_FXMS,GZ_FW_SWJG,GZ_SPDM,GZ_SPMC,GZ_GGXH,GZ_CKKA,GZ_CKGB,GZ_HYD,GZ_DJQ,GZ_DJZ,GZ_ZJQ,GZ_ZJZ,GZ_YXQZ,GZ_DXTXBZ
                     FROM FXGL_SZ_SPFXCK
                    WHERE GZ_FW_DATA IN ('1','3') -- 规则适用业务范围：1出口电子信息+3同时适用
                      AND QYBJ='Y' -- 规则启用标记：Y
                      AND IFNULL(GZ_YXQZ, CAST('2100-12-31' AS DATE))>CURRENT_TIMESTAMP; -- 规则有效期止：NULL或大于当前日期
  OPEN BJTS_CURSOR_002;
  BJTS_CURSOR_LOOP_002: LOOP
    SET BJTS_CURSOR_DONE_002 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_002 = TRUE;
      FETCH BJTS_CURSOR_002 INTO BJTS_CUR_FXGZ_GZ_MC_002, BJTS_CUR_FXGZ_GZ_FXMS_002, BJTS_CUR_FXGZ_GZ_FW_SWJG_002, BJTS_CUR_FXGZ_GZ_SPDM_002, BJTS_CUR_FXGZ_GZ_SPMC_002, BJTS_CUR_FXGZ_GZ_GGXH_002, BJTS_CUR_FXGZ_GZ_CKKA_002, BJTS_CUR_FXGZ_GZ_CKGB_002, BJTS_CUR_FXGZ_GZ_HYD_002, BJTS_CUR_FXGZ_GZ_DJQ_002, BJTS_CUR_FXGZ_GZ_DJZ_002, BJTS_CUR_FXGZ_GZ_ZJQ_002, BJTS_CUR_FXGZ_GZ_ZJZ_002, BJTS_CUR_FXGZ_GZ_YXQZ_002, BJTS_CUR_FXGZ_GZ_DXTXBZ_002;
    END;
    IF BJTS_CURSOR_DONE_002 THEN
      LEAVE BJTS_CURSOR_LOOP_002;
    END IF;
    BEGIN
      -- 规则中所有设置为空，无效规则挑过
      IF BJTS_CUR_FXGZ_GZ_SPDM_002 IS NULL AND BJTS_CUR_FXGZ_GZ_SPMC_002 IS NULL AND BJTS_CUR_FXGZ_GZ_GGXH_002 IS NULL
         AND BJTS_CUR_FXGZ_GZ_CKKA_002 IS NULL AND BJTS_CUR_FXGZ_GZ_CKGB_002 IS NULL AND BJTS_CUR_FXGZ_GZ_HYD_002 IS NULL
         AND BJTS_CUR_FXGZ_GZ_DJQ_002 IS NULL AND BJTS_CUR_FXGZ_GZ_DJZ_002 IS NULL AND BJTS_CUR_FXGZ_GZ_ZJQ_002 IS NULL AND BJTS_CUR_FXGZ_GZ_ZJZ_002 IS NULL THEN
        ITERATE BJTS_CURSOR_LOOP_002;
      END IF;

      -- 根据风险规则扫描出口电子信息
      BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_FXSJ_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_CKBGDH_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_MYLAJ_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_CKNY_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_CKSP_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_CKRQ_1_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_CKBGD18_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_HGSPMC_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_NSRDZDAH_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_SWJG_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_NSRSBH_001 LONGTEXT;
  DECLARE BJTS_CUR_FXSJ_NSRMC_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.DJXH,T.CKBGDH,T.MYLAJ,T.CKNY,T.CKSP_DM,T.CKRQ_1,SUBSTR(T.CKBGDH,1,18) AS CKBGD18,T.HGSPMC,
                              S.NSRDZDAH,S.SWJG_DM,IFNULL(S.SHXYNO, S.NSRDJNO) AS NSRSBH,S.NSRMC
                         FROM CKTS_WBSJ_HG_BGD T
                        INNER JOIN GS_DJ_CKTMSDAB S ON S.CPCODE=T.DJXH
                        WHERE T.JGFS_DM<>'1039'
                          AND T.SJTB_SJ>=LD_BEGINDATE
                          AND (T.TSSWJG_DM_1 LIKE ORA_CONCAT(BJTS_CUR_FXGZ_GZ_FW_SWJG_002, '%'))
                          AND (BJTS_CUR_FXGZ_GZ_SPDM_002 IS NULL OR
                              (SUBSTR(BJTS_CUR_FXGZ_GZ_SPDM_002,1,1)='!' AND NOT REGEXP_LIKE(T.CKSP_DM,SUBSTR(BJTS_CUR_FXGZ_GZ_SPDM_002,2))) OR
                              (SUBSTR(BJTS_CUR_FXGZ_GZ_SPDM_002,1,1)<>'!' AND REGEXP_LIKE(T.CKSP_DM,BJTS_CUR_FXGZ_GZ_SPDM_002)))
                          AND (BJTS_CUR_FXGZ_GZ_SPMC_002 IS NULL OR REGEXP_LIKE(T.HGSPMC,BJTS_CUR_FXGZ_GZ_SPMC_002))
                          AND (BJTS_CUR_FXGZ_GZ_GGXH_002 IS NULL OR REGEXP_LIKE(T.GGXH,BJTS_CUR_FXGZ_GZ_GGXH_002))
                          AND (BJTS_CUR_FXGZ_GZ_CKKA_002 IS NULL OR REGEXP_LIKE(T.HGGQKA_DM,BJTS_CUR_FXGZ_GZ_CKKA_002))
                          AND (BJTS_CUR_FXGZ_GZ_CKGB_002 IS NULL OR REGEXP_LIKE(T.MYGDQSZ_DM,BJTS_CUR_FXGZ_GZ_CKGB_002))
                          AND (BJTS_CUR_FXGZ_GZ_HYD_002 IS NULL OR
                              (SUBSTR(BJTS_CUR_FXGZ_GZ_HYD_002,1,1)='!' AND NOT REGEXP_LIKE(T.HZDWDQ_DM,SUBSTR(BJTS_CUR_FXGZ_GZ_HYD_002,2))) OR
                              (SUBSTR(BJTS_CUR_FXGZ_GZ_HYD_002,1,1)<>'!' AND REGEXP_LIKE(T.HZDWDQ_DM,BJTS_CUR_FXGZ_GZ_HYD_002)))
                          AND (BJTS_CUR_FXGZ_GZ_DJQ_002 IS NULL OR (CASE T.CKSL WHEN 0 THEN 0 ELSE T.MYLAJ/T.CKSL END)>BJTS_CUR_FXGZ_GZ_DJQ_002)
                          AND (BJTS_CUR_FXGZ_GZ_DJZ_002 IS NULL OR (CASE T.CKSL WHEN 0 THEN 0 ELSE T.MYLAJ/T.CKSL END)<BJTS_CUR_FXGZ_GZ_DJZ_002)
                          AND (BJTS_CUR_FXGZ_GZ_ZJQ_002 IS NULL OR T.MYLAJ>BJTS_CUR_FXGZ_GZ_ZJQ_002)
                          AND (BJTS_CUR_FXGZ_GZ_ZJZ_002 IS NULL OR T.MYLAJ<BJTS_CUR_FXGZ_GZ_ZJZ_002);
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_FXSJ_DJXH_001, BJTS_CUR_FXSJ_CKBGDH_001, BJTS_CUR_FXSJ_MYLAJ_001, BJTS_CUR_FXSJ_CKNY_001, BJTS_CUR_FXSJ_CKSP_DM_001, BJTS_CUR_FXSJ_CKRQ_1_001, BJTS_CUR_FXSJ_CKBGD18_001, BJTS_CUR_FXSJ_HGSPMC_001, BJTS_CUR_FXSJ_NSRDZDAH_001, BJTS_CUR_FXSJ_SWJG_DM_001, BJTS_CUR_FXSJ_NSRSBH_001, BJTS_CUR_FXSJ_NSRMC_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
        BEGIN
          -- TL_ADMIN.YJ_DATA_YJXX，态势感知风险管理，所有风险数据往这张表写数据
          INSERT INTO YJ_DATA_YJXX(
                      TBPC,ID,SBID,NSRDZDAH,CJ_DATE,YJCODE,ZBCODE,YJ_OBJECT,YJ_COUNT,YJ_AMT,YJ_RECORD,YJ_MSG,SBYM,SWFLAG,QYFLAG,BMDFLAG)
               SELECT 0,SEQ_NEXTVAL('SEQ_YJ_DATA_YJXX'),0,BJTS_CUR_FXSJ_NSRDZDAH_001,CURRENT_TIMESTAMP,'140','14001',BJTS_CUR_FXSJ_CKSP_DM_001,1,BJTS_CUR_FXSJ_MYLAJ_001,BJTS_CUR_FXSJ_CKBGDH_001,
                      ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('风险商品出口(规则：', IFNULL(BJTS_CUR_FXGZ_GZ_MC_002, BJTS_CUR_FXGZ_GZ_FXMS_002)), ')，报关单号('), BJTS_CUR_FXSJ_CKBGDH_001), ')，商品代码('), BJTS_CUR_FXSJ_CKSP_DM_001), ')，商品名称('), BJTS_CUR_FXSJ_CKSP_DM_001), ')，出口美元金额'), BJTS_CUR_FXSJ_MYLAJ_001), ')'),
                      BJTS_CUR_FXSJ_CKNY_001,1,0,0

                WHERE NOT EXISTS (SELECT 1
                                    FROM YJ_DATA_YJXX A
                                   WHERE A.SBID=0 AND A.NSRDZDAH=BJTS_CUR_FXSJ_NSRDZDAH_001
                                     AND A.YJCODE='140' AND A.ZBCODE='14001'
                                     AND A.YJ_RECORD=BJTS_CUR_FXSJ_CKBGDH_001)
                  AND NOT EXISTS (SELECT 1
                                      FROM YJ_CS_BMD B
                                      LEFT JOIN YJ_CS_BMD_SUB C ON C.BMDID=B.ID
                                     WHERE B.NSRDZDAH=BJTS_CUR_FXSJ_NSRDZDAH_001
                                       AND B.YJCODE='140'
                                       AND (B.OBJFLAG='0' OR C.YJ_OBJECT=BJTS_CUR_FXGZ_GZ_MC_002));
          -- TL_TSSH.JKGL_GY_FXSM_HGCK，原三三智检风险出口数据，待迁移
          INSERT INTO JKGL_GY_FXSM_HGCK(DJXH,CKBGDH,SMRQ,FXGZ)
               SELECT BJTS_CUR_FXSJ_DJXH_001,BJTS_CUR_FXSJ_CKBGDH_001,CURRENT_TIMESTAMP,BJTS_CUR_FXGZ_GZ_MC_002

                WHERE NOT EXISTS (SELECT 1
                                    FROM JKGL_GY_FXSM_HGCK A
                                   WHERE A.DJXH=BJTS_CUR_FXSJ_DJXH_001
                                     AND A.CKBGDH=BJTS_CUR_FXSJ_CKBGDH_001)
                  AND NOT EXISTS (SELECT 1
                                      FROM YJ_CS_BMD B
                                      LEFT JOIN YJ_CS_BMD_SUB C ON C.BMDID=B.ID
                                     WHERE B.NSRDZDAH=BJTS_CUR_FXSJ_NSRDZDAH_001
                                       AND B.YJCODE='140'
                                       AND (B.OBJFLAG='0' OR C.YJ_OBJECT=BJTS_CUR_FXGZ_GZ_MC_002));
          -- TL_TSSH.MSG_PUSH_DATA，风险出口数据的短信提醒
          -- 从原PRO_JKGL_FXCKSP存储过程迁移到这来，原biztype为“风险出口”，现改为“风险出口电子信息”
          IF BJTS_CUR_FXGZ_GZ_DXTXBZ_002='Y' THEN
            -- 20240819，插入风险出口的短信提醒信息，
            -- 风险出口短信提醒按18位报关单号汇总
            INSERT INTO MSG_PUSH_DATA(ID,SWJG_DM,NSRSBH,NSRMC,BIZTYPE,BIZKEY,QDSJ,JZSJ,YWBZ,SJTBSJ,IDLY)
                 SELECT SEQ_NEXTVAL('SEQ_MSG_PUSH_DATA'),BJTS_CUR_FXSJ_SWJG_DM_001,BJTS_CUR_FXSJ_NSRSBH_001,BJTS_CUR_FXSJ_NSRMC_001,'风险出口电子信息',
                        BJTS_CUR_FXSJ_CKBGD18_001,BJTS_CUR_FXSJ_CKRQ_1_001,NULL,BJTS_CUR_FXGZ_GZ_MC_002,CURRENT_TIMESTAMP,'1'

                  WHERE NOT EXISTS (SELECT 1
                                      FROM MSG_PUSH_DATA A
                                     WHERE A.BIZTYPE='风险出口电子信息'
                                       AND A.BIZKEY=BJTS_CUR_FXSJ_CKBGD18_001)
                    AND NOT EXISTS (SELECT 1
                                      FROM YJ_CS_BMD B
                                      LEFT JOIN YJ_CS_BMD_SUB C ON C.BMDID=B.ID
                                     WHERE B.NSRDZDAH=BJTS_CUR_FXSJ_NSRDZDAH_001
                                       AND B.YJCODE='140'
                                       AND (B.OBJFLAG='0' OR C.YJ_OBJECT=BJTS_CUR_FXGZ_GZ_MC_002));
          END IF;
          COMMIT;
        END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
    END;

  END LOOP BJTS_CURSOR_LOOP_002;
  CLOSE BJTS_CURSOR_002;
END;

  INSERT INTO FXGL_SZ_SPFXJH (ID,TSSWJG_DM,TSSWJG_MC,TBR,TBRQ,GZ_FW_SWJG,GZ_FW_DATA,GZ_MC,GZ_FXMS,GZ_GHQYSH,GZ_GHQYMC,GZ_DXTXBZ,QYBJ,FHXXBUUID)
SELECT SEQ_NEXTVAL('SEQ_FXGL_SZ_SPFXJH'),'13300000000','浙江省税务局','SYSTEM',CURRENT_TIMESTAMP,'133','2',B.GZ_MC,B.GZ_FXMS,B.GHQYNSRSBH_1,B.GHFQYMC_1,'N','Y',B.FHXXBUUID
FROM (
SELECT T.FHXXBUUID,T.FUHQFRQ,T.GHQYNSRSBH_1,T.GHFQYMC_1,'一年以上未回函' AS GZ_MC,
                     ORA_CONCAT(ORA_CONCAT(T.FAHDSWJGMC, DATE_FORMAT(T.FAHQFRQ, '%Y-%m-%d')), '发函，至今尚无明确回函意见') AS GZ_FXMS
                FROM YJ_CS_YCHD_JS T
               WHERE T.FUHLX_DM IS NULL AND ORA_DATE_DIFF(CURRENT_TIMESTAMP, T.FAHQFRQ)>365
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM FXGL_SZ_SPFXJH AS A WHERE B.FHXXBUUID=A.FHXXBUUID AND B.GZ_MC=A.GZ_MC
);
  COMMIT;
  INSERT INTO FXGL_SZ_SPFXJH (ID,TSSWJG_DM,TSSWJG_MC,TBR,TBRQ,GZ_FW_SWJG,GZ_FW_DATA,GZ_MC,GZ_FXMS,GZ_GHQYSH,GZ_GHQYMC,GZ_DXTXBZ,QYBJ,FHXXBUUID,GZ_YXQZ)
SELECT SEQ_NEXTVAL('SEQ_FXGL_SZ_SPFXJH'),'13300000000','浙江省税务局','SYSTEM',CURRENT_TIMESTAMP,'133','2',B.GZ_MC,B.GZ_FXMS,B.GHQYNSRSBH_1,B.GHFQYMC_1,'N','Y',B.FHXXBUUID,DATE_ADD(B.FUHQFRQ, INTERVAL 12 MONTH)
FROM (
SELECT T.FHXXBUUID,T.FUHQFRQ,T.GHQYNSRSBH_1,T.GHFQYMC_1,'回函存在异常业务' AS GZ_MC,
                     ORA_CONCAT(ORA_CONCAT(T.FAHDSWJGMC, DATE_FORMAT(T.FAHQFRQ, '%Y-%m-%d')), '发函，对方税务机关回函存在异常业务') AS GZ_FXMS
                FROM YJ_CS_YCHD_JS T
               WHERE T.FUHLX_DM='2'
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM FXGL_SZ_SPFXJH AS A WHERE B.FHXXBUUID=A.FHXXBUUID AND B.GZ_MC=A.GZ_MC
);
  COMMIT;
  /*MERGE INTO FXGL_SZ_SPFXJH A
       USING (SELECT T.FHXXBUUID,T.FUHQFRQ,T.GHQYNSRSBH_1,T.GHFQYMC_1,'回函正常其他情况不予退税' AS GZ_MC,
                     T.FAHDSWJGMC||TO_CHAR(T.FAHQFRQ,'yyyy-mm-dd')||'发函，对方税务机关回函正常，经核查其他情况不予退税' AS GZ_FXMS
                FROM TL_ADMIN.YJ_CS_YCHD_JS T
               WHERE T.FUHLX_DM<>'2' AND T.FUHCLYJ_DM='3') B
          ON (B.FHXXBUUID=A.FHXXBUUID AND B.GZ_MC=A.GZ_MC)
        WHEN NOT MATCHED THEN
          INSERT (ID,TSSWJG_DM,TSSWJG_MC,TBR,TBRQ,GZ_FW_SWJG,GZ_FW_DATA,GZ_MC,GZ_FXMS,GZ_GHQYSH,GZ_GHQYMC,GZ_DXTXBZ,QYBJ,FHXXBUUID,GZ_YXQZ)
          VALUES (SEQ_FXGL_SZ_SPFXJH.NEXTVAL,'13300000000','浙江省税务局','SYSTEM',SYSDATE,'133','2',B.GZ_MC,B.GZ_FXMS,B.GHQYNSRSBH_1,B.GHFQYMC_1,'N','Y',B.FHXXBUUID,ADD_MONTHS(B.FUHQFRQ,12));
  COMMIT;*/
  UPDATE FXGL_SZ_SPFXJH AS A
     SET GZ_YXQZ=(SELECT FUHQFRQ FROM YJ_CS_YCHD_JS B WHERE B.FHXXBUUID=A.FHXXBUUID)
   WHERE A.FHXXBUUID IS NOT NULL AND A.GZ_MC='一年以上未回函';
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_FXSPCK_DZXX.sql

-- ======================================================================
-- [033/146] BEGIN SOURCE: PRO_FXGL_SZYJ_CKSPDJ_PERM.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_SZYJ_CKSPDJ_PERM$$

CREATE PROCEDURE PRO_FXGL_SZYJ_CKSPDJ_PERM()
/*
 * 风险管理——事中预警——出口商品平均单价模型刷新（每月）
 */
routine_body: BEGIN

  delete from YJ_CS_QSPJDJ_WM;
  commit;

  insert into YJ_CS_QSPJDJ_WM(spdm,qnt,amt,dj,qyhs,ywbs,spmc,sbspmc)
  with
  tj as (
  select a.cksp_dm,
         sum(case when a.sz='V' then a.sl else 0 end) as qnt,
         sum(a.jsje) as amt,
         count(distinct a.djxh) as qyhs,
         count(distinct ORA_CONCAT(a.djxh, a.glh)) as ywbs
    from CKTS_SB_MTS_JHMX a
   where a.sbrq>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -12 MONTH) and a.sbrq<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
     and a.sl>0
   group by a.cksp_dm
  ),
  zymc as (
  select a.cksp_dm,a.sbhgspmc,sum(a.jsje) as amt,
         row_number() over (partition by a.cksp_dm order by sum(a.jsje) desc) as pm
    from CKTS_SB_MTS_JHMX a
   where a.sbrq>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -12 MONTH) and a.sbrq<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
   group by a.cksp_dm,a.sbhgspmc
  ),
  wkmc as (
  select tj.cksp_dm,wk.ckspmc,row_number() over (partition by tj.cksp_dm order by wk.yxqq desc) as pm
    from tj
    left join CKTS_DM_TSLVWK wk on wk.cksp_dm=tj.cksp_dm
  )
  select tj.cksp_dm,tj.qnt,tj.amt,round(tj.amt/tj.qnt,2),tj.qyhs,tj.ywbs,wkmc.ckspmc,zymc.sbhgspmc
    from tj
   inner join zymc on zymc.cksp_dm=tj.cksp_dm and zymc.pm=1
   inner join wkmc on wkmc.cksp_dm=tj.cksp_dm and wkmc.pm=1
  ;
  commit;

  delete from YJ_CS_QSPJDJ_SC;
  commit;

  insert into YJ_CS_QSPJDJ_SC(spdm,qnt,amt,dj,qyhs,ywbs,spmc,sbspmc)
  with
  tj as (
  select a.cksp_dm,
         sum(a.cksl) as qnt,
         sum(a.mylaj) as amt,
         count(distinct a.djxh) as qyhs,
         count(distinct IFNULL(a.ckbgdh, a.dlckhwzmhm)) as ywbs
    from CKTS_SB_MDT_CKMX a
   where a.sbrq>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -12 MONTH) and a.sbrq<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
     and a.cksl>0
   group by a.cksp_dm
  ),
  zymc as (
  select a.cksp_dm,a.sbhgspmc,sum(a.mylaj) as amt,
         row_number() over (partition by a.cksp_dm order by sum(a.mylaj) desc) as pm
    from CKTS_SB_MDT_CKMX a
   where a.sbrq>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -12 MONTH) and a.sbrq<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
   group by a.cksp_dm,a.sbhgspmc
  ),
  wkmc as (
  select tj.cksp_dm,wk.ckspmc,row_number() over (partition by tj.cksp_dm order by wk.yxqq desc) as pm
    from tj
    left join CKTS_DM_TSLVWK wk on wk.cksp_dm=tj.cksp_dm
  )
  select tj.cksp_dm,tj.qnt,tj.amt,round(tj.amt/tj.qnt,2),tj.qyhs,tj.ywbs,wkmc.ckspmc,zymc.sbhgspmc
    from tj
   inner join zymc on zymc.cksp_dm=tj.cksp_dm and zymc.pm=1
   inner join wkmc on wkmc.cksp_dm=tj.cksp_dm and wkmc.pm=1
  ;
  commit;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_SZYJ_CKSPDJ_PERM.sql

-- ======================================================================
-- [034/146] BEGIN SOURCE: PRO_FXGL_SZYJ_MMYLRL_PERM.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_SZYJ_MMYLRL_PERM$$

CREATE PROCEDURE PRO_FXGL_SZYJ_MMYLRL_PERM()
/*
 * 风险管理——事中预警——外贸企业每美元利润率刷新（每月）
 */
routine_body: BEGIN

  delete from YJ_CS_WMQYMMYLRL;
  delete from YJ_CS_WMQYMMYLRL_FQY;
  commit;

  insert into YJ_CS_WMQYMMYLRL_FQY(swjg_dm,djxh,sbywbs,mmylrl_max,mmylrl_min,mmylrl_mid,mmylrl_avg,mmylrl_std,mylaj,rmblaj,jhcb,mmylrl_yjx)
  with
  jh as (
  select a.djxh,a.glh,sum(a.jsje*(100+a.zssl-a.tsl)/100) as jhcb
    from CKTS_SB_MTS_JHMX a
   where a.sbrq>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -12 MONTH) and a.sbrq<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
   group by a.djxh,a.glh
  )
  ,mx as (
  select b.tsswjg_dm,b.djxh,b.ckbgdh,b.mylaj,round(c.rmblaj*b.mylaj/c.mylaj,2) as rmblaj,jh.jhcb,
         round((round(c.rmblaj*b.mylaj/c.mylaj,2)-jh.jhcb)/b.mylaj,2) as mmylrl
    from CKTS_SB_MTS_CKMX b
   inner join jh on jh.djxh=b.djxh and jh.glh=b.glh
   inner join CKTS_WBSJ_HG_BGD c on c.ckbgdh=b.ckbgdh and c.djxh=b.djxh
   where b.sbrq>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -12 MONTH) and b.sbrq<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
     and b.ckbgdh is not null
     and c.mylaj>0 and b.mylaj>0
   union all
  select b.tsswjg_dm,b.djxh,b.dlckhwzmhm as ckbgdh,b.mylaj,round(c.rmblaj*b.mylaj/c.mylaj,2) as rmblaj,jh.jhcb,
         round((round(c.rmblaj*b.mylaj/c.mylaj,2)-jh.jhcb)/b.mylaj,2) as mmylrl
    from CKTS_SB_MTS_CKMX b
   inner join jh on jh.djxh=b.djxh and jh.glh=b.glh
   inner join CKTS_WBSJ_ZJ_DLCKHWZM c on c.dlckhwzmhm=b.dlckhwzmhm and c.djxh=b.djxh
   where b.sbrq>=DATE_ADD(CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME), INTERVAL -12 MONTH) and b.sbrq<CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME)
     and b.ckbgdh is null
     and c.mylaj>0 and b.mylaj>0
  )
  select tsswjg_dm,djxh,
         count(distinct ckbgdh) as sbywbs,max(mmylrl) as mmylrl_max,min(mmylrl) as mmylrl_min,
         ORA_MEDIAN(JSON_ARRAYAGG(mmylrl)) as mmylrl_mid,avg(mmylrl) as mmylrl_avg,stddev(mmylrl) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from mx
   group by tsswjg_dm,djxh
  ;
  commit;

  insert into YJ_CS_WMQYMMYLRL(swjg_dm,sbqyhs,sbywbs,mmylrl_max,mmylrl_min,mmylrl_mid,mmylrl_avg,mmylrl_std,mylaj,rmblaj,jhcb,mmylrl_yjx)
  select swjg_dm,
         count(distinct djxh) as sbqyhs,sum(sbywbs) as sbywbs,
         max(mmylrl_yjx) as mmylrl_max,min(mmylrl_yjx) as mmylrl_min,
         ORA_MEDIAN(JSON_ARRAYAGG(mmylrl_yjx)) as mmylrl_mid,avg(mmylrl_yjx) as mmylrl_avg,stddev(mmylrl_yjx) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from YJ_CS_WMQYMMYLRL_FQY
   group by swjg_dm
   union all
  select ORA_CONCAT(substr(swjg_dm,1,5), '000000'),
         count(distinct djxh) as sbqyhs,sum(sbywbs) as sbywbs,
         max(mmylrl_yjx) as mmylrl_max,min(mmylrl_yjx) as mmylrl_min,
         ORA_MEDIAN(JSON_ARRAYAGG(mmylrl_yjx)) as mmylrl_mid,avg(mmylrl_yjx) as mmylrl_avg,stddev(mmylrl_yjx) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from YJ_CS_WMQYMMYLRL_FQY
   group by substr(swjg_dm,1,5)
   union all
  select '13300000000',
         count(distinct djxh) as sbqyhs,sum(sbywbs) as sbywbs,
         max(mmylrl_yjx) as mmylrl_max,min(mmylrl_yjx) as mmylrl_min,
         ORA_MEDIAN(JSON_ARRAYAGG(mmylrl_yjx)) as mmylrl_mid,avg(mmylrl_yjx) as mmylrl_avg,stddev(mmylrl_yjx) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from YJ_CS_WMQYMMYLRL_FQY
  ;
  commit;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_SZYJ_MMYLRL_PERM.sql

-- ======================================================================
-- [035/146] BEGIN SOURCE: PRO_FXGL_SZYJ_WLXX.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_SZYJ_WLXX$$

CREATE PROCEDURE PRO_FXGL_SZYJ_WLXX()
/*
 * 从出口发票备注或申报明细备注提取物流信息（车牌号、起运日期、起运地、快递单号）
 * LN_WLBZ : 初始NULL，
 *           备注（发票+出口）空白99，
 *           从发票备注提取到车牌号，初始10；日期大于出口日期+1；大于系统日期+2；日期空+3；地址空+5
 *           从发票备注提取到快递信息20
 *           从出口明细备注提取到车牌号，初始30；日期大于出口日期+1；大于系统日期+2；日期空+3；地址空+5
 *           从出口明细备注提取到快递信息40
 *           备注非空白，未提取到物流98
 */
routine_body: BEGIN
  DECLARE LC_WLXX    VARCHAR(1000);
  DECLARE LN_WLBZ    BIGINT;
  DECLARE LC_WLDM    CHAR(1);
  DECLARE LC_CPH     VARCHAR(500);
  DECLARE LD_QYR     DATETIME;
  DECLARE LC_QYD     VARCHAR(500);
  DECLARE LN_ADDR    BIGINT;
  DECLARE LC_PATTERN VARCHAR(500);

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGD_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_BGDHGBH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKFPBZ_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKMXBZ_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_WLXXLY_DM_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CPH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_QYRQ_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_QYD_001 LONGTEXT;
  DECLARE BJTS_CUR_BGD_CKRQ_1_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DJXH,BGDHGBH,CKFPBZ,CKMXBZ,WLXXLY_DM,CPH,QYRQ,QYD,CKRQ_1
                    FROM CKLLFX_DATA_BGDWL
                   WHERE WLXXLY_BZ IS NULL
                   ORDER BY SJGXSJ;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_BGD_DJXH_001, BJTS_CUR_BGD_BGDHGBH_001, BJTS_CUR_BGD_CKFPBZ_001, BJTS_CUR_BGD_CKMXBZ_001, BJTS_CUR_BGD_WLXXLY_DM_001, BJTS_CUR_BGD_CPH_001, BJTS_CUR_BGD_QYRQ_001, BJTS_CUR_BGD_QYD_001, BJTS_CUR_BGD_CKRQ_1_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    SET LN_WLBZ = NULL;
    SET LC_WLDM = NULL;
    SET LC_CPH = NULL;
    SET LD_QYR = NULL;
    SET LC_QYD = NULL;

    -- 1、发票备注+出口明细备注 为空
    IF (TRIM(BJTS_CUR_BGD_CKFPBZ_001) IS NULL) AND (TRIM(BJTS_CUR_BGD_CKMXBZ_001) IS NULL) THEN
      SET LN_WLBZ = 99;
      SET LC_WLDM = '0';
      UPDATE CKLLFX_DATA_BGDWL AS T
         SET WLXXLY_BZ=LN_WLBZ,
    WLXXLY_DM=LC_WLDM,
    CPH=LC_CPH,
    QYRQ=LD_QYR,
    QYD=LC_QYD
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.BGDHGBH=BJTS_CUR_BGD_BGDHGBH_001;
      COMMIT;
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;

    -- 2、发票备注提取到车牌号
    CALL F_WLGL_EXTRACT_PLATE(BJTS_CUR_BGD_CKFPBZ_001,LN_ADDR, LC_CPH);
    IF LC_CPH IS NOT NULL THEN
      -- 2.1、从车牌号以后备注内容提取起运日、起运地信息，剔除前面的干扰因素
      SET LC_WLXX = SUBSTR(BJTS_CUR_BGD_CKFPBZ_001,LN_ADDR);
      SET LD_QYR = F_WLGL_EXTRACT_DATE(LC_WLXX,BJTS_CUR_BGD_CKRQ_1_001);
      SET LC_QYD = F_WLGL_EXTRACT_FROM(LC_WLXX);

      -- 2.2、起运日或起运地为空，提取物流关键字位置，从关键字位置以后再提取一次
      SET LC_PATTERN = '车牌|车号|车辆|起运|起始|起送|起至运|启运|始运|始发|出发|出运|出货|发车|发货|装车|装货|装柜|装箱|装运|送货|拉货|货源地|托运';
      SET LN_ADDR = REGEXP_INSTR(BJTS_CUR_BGD_CKFPBZ_001,LC_PATTERN,1);
      IF LN_ADDR > 0 THEN
        SET LC_WLXX = SUBSTR(BJTS_CUR_BGD_CKFPBZ_001,LN_ADDR);
        IF LD_QYR IS NULL THEN
          SET LD_QYR = F_WLGL_EXTRACT_DATE(LC_WLXX,BJTS_CUR_BGD_CKRQ_1_001);
        END IF;
        IF LC_QYD IS NULL THEN
          SET LC_QYD = F_WLGL_EXTRACT_FROM(LC_WLXX);
        END IF;
      END IF;

      -- 2.3、如果起运日或起运地还是为空，从完整备注中再提取一次
      IF LD_QYR IS NULL THEN
        SET LD_QYR = F_WLGL_EXTRACT_DATE(BJTS_CUR_BGD_CKFPBZ_001,BJTS_CUR_BGD_CKRQ_1_001);
      END IF;
      IF LC_QYD IS NULL THEN
        SET LC_QYD = F_WLGL_EXTRACT_FROM(BJTS_CUR_BGD_CKFPBZ_001);
      END IF;

      -- 2.4、根据起运日或起运地是否为空，记录不同结果
      SET LC_WLDM = '1';
      SET LN_WLBZ = 10;
      IF LD_QYR IS NULL THEN
        SET LN_WLBZ = LN_WLBZ + 3;
      ELSEIF LD_QYR>=CURRENT_TIMESTAMP THEN
        SET LN_WLBZ = LN_WLBZ + 2;
      ELSEIF LD_QYR>=BJTS_CUR_BGD_CKRQ_1_001 THEN
        SET LN_WLBZ = LN_WLBZ + 1;
      END IF;
      IF LC_QYD IS NULL THEN
        SET LN_WLBZ = LN_WLBZ + 5;
      END IF;
      UPDATE CKLLFX_DATA_BGDWL AS T
         SET WLXXLY_BZ=LN_WLBZ,
    WLXXLY_DM=LC_WLDM,
    CPH=LC_CPH,
    QYRQ=LD_QYR,
    QYD=LC_QYD
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.BGDHGBH=BJTS_CUR_BGD_BGDHGBH_001;
      COMMIT;
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;

    -- 2、发票备注未提取到车牌号，但提取到快递信息
    SET LC_CPH = F_WLGL_EXTRACT_PARCEL(BJTS_CUR_BGD_CKFPBZ_001);
    IF LC_CPH IS NOT NULL THEN
      SET LN_WLBZ = 20;
      SET LC_WLDM = '1';
      UPDATE CKLLFX_DATA_BGDWL AS T
         SET WLXXLY_BZ=LN_WLBZ,
    WLXXLY_DM=LC_WLDM,
    CPH=LC_CPH,
    QYRQ=LD_QYR,
    QYD=LC_QYD
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.BGDHGBH=BJTS_CUR_BGD_BGDHGBH_001;
      COMMIT;
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;

    -- 3、出口明细备注提取到车牌号
    CALL F_WLGL_EXTRACT_PLATE(BJTS_CUR_BGD_CKMXBZ_001,LN_ADDR, LC_CPH);
    IF LC_CPH IS NOT NULL THEN
      SET LN_WLBZ = 30;
      SET LC_WLDM = '2';
      SET LD_QYR = F_WLGL_EXTRACT_DATE(BJTS_CUR_BGD_CKMXBZ_001,BJTS_CUR_BGD_CKRQ_1_001);
      IF LD_QYR IS NULL THEN
        SET LN_WLBZ = LN_WLBZ + 3;
      ELSEIF LD_QYR>=CURRENT_TIMESTAMP THEN
        SET LN_WLBZ = LN_WLBZ + 2;
      ELSEIF LD_QYR>=BJTS_CUR_BGD_CKRQ_1_001 THEN
        SET LN_WLBZ = LN_WLBZ + 1;
      END IF;
      SET LC_QYD = F_WLGL_EXTRACT_FROM(BJTS_CUR_BGD_CKMXBZ_001);
      IF LC_QYD IS NULL THEN
        SET LN_WLBZ = LN_WLBZ + 5;
      END IF;
      UPDATE CKLLFX_DATA_BGDWL AS T
         SET WLXXLY_BZ=LN_WLBZ,
    WLXXLY_DM=LC_WLDM,
    CPH=LC_CPH,
    QYRQ=LD_QYR,
    QYD=LC_QYD
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.BGDHGBH=BJTS_CUR_BGD_BGDHGBH_001;
      COMMIT;
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;

    -- 4、出口明细备注未提取到车牌号，但提取到快递信息
    SET LC_CPH = F_WLGL_EXTRACT_PARCEL(BJTS_CUR_BGD_CKMXBZ_001);
    IF LC_CPH IS NOT NULL THEN
      SET LN_WLBZ = 40;
      SET LC_WLDM = '2';
      UPDATE CKLLFX_DATA_BGDWL AS T
         SET WLXXLY_BZ=LN_WLBZ,
    WLXXLY_DM=LC_WLDM,
    CPH=LC_CPH,
    QYRQ=LD_QYR,
    QYD=LC_QYD
       WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.BGDHGBH=BJTS_CUR_BGD_BGDHGBH_001;
      COMMIT;
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;

    -- 5、发票备注+出口明细备注 不包含物流关键字
    SET LN_WLBZ = 98;
    UPDATE CKLLFX_DATA_BGDWL AS T
       SET WLXXLY_BZ=LN_WLBZ,
    WLXXLY_DM=LC_WLDM,
    CPH=LC_CPH,
    QYRQ=LD_QYR,
    QYD=LC_QYD
     WHERE T.DJXH=BJTS_CUR_BGD_DJXH_001 AND T.BGDHGBH=BJTS_CUR_BGD_BGDHGBH_001;
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_SZYJ_WLXX.sql

-- ======================================================================
-- [036/146] BEGIN SOURCE: PRO_FXGL_SZYJ_WMQYCKLL_DQ_PERY.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_SZYJ_WMQYCKLL_DQ_PERY$$

CREATE PROCEDURE PRO_FXGL_SZYJ_WMQYCKLL_DQ_PERY()
/*
 * 风险管理——事中预警——外贸企业出口链路统计（每年）
 */
routine_body: BEGIN

  delete from CKLLFX_CS_WMQYLSLL_DQ AS t;
  commit;

  insert into CKLLFX_CS_WMQYLSLL_DQ(
         ysfs_dm,spdl_dm,qycode_hyd,qycode_hg,qycode_mdg,
         qyhs_all,qyzb_all,bgdfs_all,bgdzb_all,mylaj_all,myzb_all,
         qyhs_sx,qyzb_sx,bgdfs_sx,bgdzb_sx,mylaj_sx,myzb_sx)
  with
  zygys as (
  -- 按关联号统计主要供应地区（供货金额最大）
  select a.djxh,a.glh,
         case
           -- 进口缴款书货源地按口岸提取2位行政区划
           when a.cktmspzlx_dm='04'
             then substr(ka.xzqh_dm,1,2)
           -- 未提取到销售方地市税务机关代码的，从供货方税号提取2位行政区划
           when length(a.xsfdsswjgdm)=4
             then substr(a.xsfdsswjgdm,1,2)
           -- 提取到销售方地市税务机关代码的，从地市税务机关代码提取2位行政区划
           when length(a.xsfdsswjgdm)=5
             then substr(a.xsfdsswjgdm,2,2)
         end as ghdz,
         row_number() over (partition by a.djxh,a.glh order by sum(a.jsje) desc) as pm
    from CKTS_SB_MTS_JHMX a
    -- 对进口缴款书，关联口岸代码表提取关区对应行政区划（省级）
    left join DM_HGCODE ka on ka.hgcode=ORA_CONCAT(substr(a.jhpzh,1,2), '00')
   where a.sbrq>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -24 MONTH) and a.sbrq<MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1)
   group by a.djxh,a.glh,
         case
           when a.cktmspzlx_dm='04'
             then substr(ka.xzqh_dm,1,2)
           when length(a.xsfdsswjgdm)=4
             then substr(a.xsfdsswjgdm,1,2)
           when length(a.xsfdsswjgdm)=5
             then substr(a.xsfdsswjgdm,2,2)
         end
  ),
  mx as (
  -- 按关联号提取出口链路明细
  select s.djxh,
         s.ckbgdh,
         s.mylaj,
         s.ysfs_dm,
         substr(s.cksp_dm,1,2) as spdl_dm,
         hyd.qycode as qycode_hyd,
         hg.qycode as qycode_hg,
         mdg.qycode as qycode_mdg
    from CKTS_SB_MTS_CKMX t
   inner join zygys on zygys.djxh=t.djxh and zygys.glh=t.glh and pm=1
   inner join CKTS_WBSJ_HG_BGD s on s.ckbgdh=t.ckbgdh and s.djxh=t.djxh
    left join DM_XZQH_DQ hyd on hyd.dm=zygys.ghdz
    -- 启运港报关单从报关单号提取报关关区，否则取离境关区
    left join DM_HGCODE ka on ka.hgcode=ORA_CONCAT((case when s.qygbz='Y' then substr(s.ckbgdh,1,2) else substr(s.hggqka_dm,1,2) end), '00')
    left join DM_XZQH_DQ hg on hg.dm=ka.xzqh_dm
    left join DM_GBCODE mdg on mdg.gb_code=s.zzmdgdqsz_dm
   where t.sbrq>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -24 MONTH) and t.sbrq<MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1)
     and t.ckbgdh is not null
   union all
  select s.djxh,
         s.dlckhwzmhm as ckbgdh,
         s.mylaj,
         s.ysfs_dm,
         substr(s.cksp_dm,1,2) as spdl_dm,
         hyd.qycode as qycode_hyd,
         hg.qycode as qycode_hg,
         mdg.qycode as qycode_mdg
    from CKTS_SB_MTS_CKMX t
   inner join zygys on zygys.djxh=t.djxh and zygys.glh=t.glh and pm=1
   inner join CKTS_WBSJ_ZJ_DLCKHWZM s on s.dlckhwzmhm=t.dlckhwzmhm and s.djxh=t.djxh
    left join DM_XZQH_DQ hyd on hyd.dm=zygys.ghdz
    left join DM_HGCODE ka on ka.hgcode=ORA_CONCAT(substr(s.hggqka_dm,1,2), '00')
    left join DM_XZQH_DQ hg on hg.dm=ka.xzqh_dm
    left join DM_GBCODE mdg on mdg.gb_code=s.zzmdgdqsz_dm
   where t.sbrq>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -24 MONTH) and t.sbrq<MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1)
     and t.ckbgdh is null
  ),
  tj1 as (
  -- 相同运输方式、商品大类、供货区域、目的区域总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,
         count(distinct djxh) as qyhs_tj1,
         count(distinct ckbgdh) as bgdfs_tj1,
         sum(mylaj) as mylaj_tj1
    from mx
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg
  ),
  tj2 as (
  -- 相同运输方式、商品大类、供货区域、目的区域大额报关单总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,
         count(distinct djxh) as qyhs_tj2,
         count(distinct ckbgdh) as bgdfs_tj2,
         sum(mylaj) as mylaj_tj2
    from mx
   where mylaj>=30000
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg
  ),
  tj3 as (
  -- 相同运输方式、商品大类、供货区域、目的区域大额报关单总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,qycode_hg,
         count(distinct djxh) as qyhs_all,
         count(distinct ckbgdh) as bgdfs_all,
         sum(mylaj) as mylaj_all,
         count(distinct case when mylaj>=30000 then djxh else null end) as qyhs_sx,
         count(distinct case when mylaj>=30000 then ckbgdh else null end) as bgdfs_sx,
         sum(case when mylaj>=30000 then mylaj else 0 end) as mylaj_sx
    from mx
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,qycode_hg
  )
  select tj3.ysfs_dm,tj3.spdl_dm,tj3.qycode_hyd,tj3.qycode_hg,tj3.qycode_mdg,
         tj3.qyhs_all,case when IFNULL(tj1.qyhs_tj1, 0)<=tj3.qyhs_all then 100.00 else round(100*tj3.qyhs_all/tj1.qyhs_tj1,2) end as qyzb_all,
         tj3.bgdfs_all,case when IFNULL(tj1.bgdfs_tj1, 0)<=tj3.bgdfs_all then 100.00 else round(100*tj3.bgdfs_all/tj1.bgdfs_tj1,2) end as bgdzb_all,
         tj3.mylaj_all,case when IFNULL(tj1.mylaj_tj1, 0)<=tj3.mylaj_all then 100.00 else round(100*tj3.mylaj_all/tj1.mylaj_tj1,2) end as myzb_all,
         tj3.qyhs_sx,case when IFNULL(tj2.qyhs_tj2, 0)<=tj3.qyhs_sx then 100.00 else round(100*tj3.qyhs_sx/tj2.qyhs_tj2,2) end as qyzb_sx,
         tj3.bgdfs_sx,case when IFNULL(tj2.bgdfs_tj2, 0)<=tj3.bgdfs_sx then 100.00 else round(100*tj3.bgdfs_sx/tj2.bgdfs_tj2,2) end as bgdzb_sx,
         tj3.mylaj_sx,case when IFNULL(tj2.mylaj_tj2, 0)<=tj3.mylaj_sx then 100.00 else round(100*tj3.mylaj_sx/tj2.mylaj_tj2,2) end as myzb_sx
    from tj3
    left join tj1
      on tj1.ysfs_dm=tj3.ysfs_dm
     and tj1.spdl_dm=tj3.spdl_dm
     and tj1.qycode_hyd=tj3.qycode_hyd
     and tj1.qycode_mdg=tj3.qycode_mdg
    left join tj2
      on tj2.ysfs_dm=tj3.ysfs_dm
     and tj2.spdl_dm=tj3.spdl_dm
     and tj2.qycode_hyd=tj3.qycode_hyd
     and tj2.qycode_mdg=tj3.qycode_mdg
  ;
  commit;

  update CKLLFX_CS_WMQYLSLL_DQ AS t
     set fxdj_zhfxzs= t.qyzb_all * 0.1 + t.bgdzb_all * 0.2 + t.myzb_all * 0.2
                      + t.qyzb_sx  * 0.1 + t.bgdzb_sx  * 0.2 + t.myzb_sx  * 0.2;
  commit;
  -- 根据风险指数设置风险等级，对浙沪出口或货源地与出口地区域一致的降一级风险等级
  update CKLLFX_CS_WMQYLSLL_DQ AS t
     set fxdj_dm= case when t.fxdj_zhfxzs<=5
                         then (case when t.qycode_hg='08' or t.qycode_hyd=t.qycode_hg then '3' else '4' end)
                         when t.fxdj_zhfxzs<=10
                         then (case when t.qycode_hg='08' or t.qycode_hyd=t.qycode_hg then '2' else '3' end)
                         when t.fxdj_zhfxzs<=20
                         then (case when t.qycode_hg='08' or t.qycode_hyd=t.qycode_hg then '1' else '2' end)
                         else '1'
                    end;
  commit;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_SZYJ_WMQYCKLL_DQ_PERY.sql

-- ======================================================================
-- [037/146] BEGIN SOURCE: PRO_FXGL_SZYJ_WMQYCKLL_SF_PERY.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_SZYJ_WMQYCKLL_SF_PERY$$

CREATE PROCEDURE PRO_FXGL_SZYJ_WMQYCKLL_SF_PERY()
/*
 * 风险管理——事中预警——外贸企业出口链路统计（每年）
 */
routine_body: BEGIN

  delete from CKLLFX_CS_WMQYLSLL_SF AS t;
  commit;

  insert into CKLLFX_CS_WMQYLSLL_SF(
         ysfs_dm,spdl_dm,qycode_hyd,qycode_hg,qycode_mdg,
         qyhs_all,qyzb_all,bgdfs_all,bgdzb_all,mylaj_all,myzb_all,
         qyhs_sx,qyzb_sx,bgdfs_sx,bgdzb_sx,mylaj_sx,myzb_sx)
  with
  zygys as (
  -- 按关联号统计主要供应地区（供货金额最大）
  select a.djxh,a.glh,
         case
           -- 进口缴款书货源地按口岸提取2位行政区划
           when a.cktmspzlx_dm='04'
             then substr(ka.xzqh_dm,1,2)
           -- 未提取到销售方地市税务机关代码的，从供货方税号提取2位行政区划
           when length(a.xsfdsswjgdm)=4
             then substr(a.xsfdsswjgdm,1,2)
           -- 提取到销售方地市税务机关代码的，从地市税务机关代码提取2位行政区划
           when length(a.xsfdsswjgdm)=5
             then substr(a.xsfdsswjgdm,2,2)
         end as ghdz,
         row_number() over (partition by a.djxh,a.glh order by sum(a.jsje) desc) as pm
    from CKTS_SB_MTS_JHMX a
    -- 对进口缴款书，关联口岸代码表提取关区对应行政区划（省级）
    left join DM_HGCODE ka on ka.hgcode=ORA_CONCAT(substr(a.jhpzh,1,2), '00')
   where a.sbrq>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -24 MONTH) and a.sbrq<MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1)
   group by a.djxh,a.glh,
         case
           when a.cktmspzlx_dm='04'
             then substr(ka.xzqh_dm,1,2)
           when length(a.xsfdsswjgdm)=4
             then substr(a.xsfdsswjgdm,1,2)
           when length(a.xsfdsswjgdm)=5
             then substr(a.xsfdsswjgdm,2,2)
         end
  ),
  mx as (
  -- 按关联号提取出口链路明细
  select s.djxh,
         s.ckbgdh,
         s.mylaj,
         s.ysfs_dm,
         substr(s.cksp_dm,1,2) as spdl_dm,
         hyd.qycode as qycode_hyd,
         hg.qycode as qycode_hg,
         mdg.qycode as qycode_mdg
    from CKTS_SB_MTS_CKMX t
   inner join zygys on zygys.djxh=t.djxh and zygys.glh=t.glh and pm=1
   inner join CKTS_WBSJ_HG_BGD s on s.ckbgdh=t.ckbgdh and s.djxh=t.djxh
    left join DM_XZQH_SF hyd on hyd.dm=zygys.ghdz
    -- 启运港报关单从报关单号提取报关关区，否则取离境关区
    left join DM_HGCODE ka on ka.hgcode=ORA_CONCAT((case when s.qygbz='Y' then substr(s.ckbgdh,1,2) else substr(s.hggqka_dm,1,2) end), '00')
    left join DM_XZQH_SF hg on hg.dm=ka.xzqh_dm
    left join DM_GBCODE mdg on mdg.gb_code=s.zzmdgdqsz_dm
   where t.sbrq>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -24 MONTH) and t.sbrq<MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1)
     and t.ckbgdh is not null
   union all
  select s.djxh,
         s.dlckhwzmhm as ckbgdh,
         s.mylaj,
         s.ysfs_dm,
         substr(s.cksp_dm,1,2) as spdl_dm,
         hyd.qycode as qycode_hyd,
         hg.qycode as qycode_hg,
         mdg.qycode as qycode_mdg
    from CKTS_SB_MTS_CKMX t
   inner join zygys on zygys.djxh=t.djxh and zygys.glh=t.glh and pm=1
   inner join CKTS_WBSJ_ZJ_DLCKHWZM s on s.dlckhwzmhm=t.dlckhwzmhm and s.djxh=t.djxh
    left join DM_XZQH_SF hyd on hyd.dm=zygys.ghdz
    left join DM_HGCODE ka on ka.hgcode=ORA_CONCAT(substr(s.hggqka_dm,1,2), '00')
    left join DM_XZQH_SF hg on hg.dm=ka.xzqh_dm
    left join DM_GBCODE mdg on mdg.gb_code=s.zzmdgdqsz_dm
   where t.sbrq>=DATE_ADD(MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1), INTERVAL -24 MONTH) and t.sbrq<MAKEDATE(YEAR(CURRENT_TIMESTAMP), 1)
     and t.ckbgdh is null
  ),
  tj1 as (
  -- 相同运输方式、商品大类、供货区域、目的区域总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,
         count(distinct djxh) as qyhs_tj1,
         count(distinct ckbgdh) as bgdfs_tj1,
         sum(mylaj) as mylaj_tj1
    from mx
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg
  ),
  tj2 as (
  -- 相同运输方式、商品大类、供货区域、目的区域大额报关单总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,
         count(distinct djxh) as qyhs_tj2,
         count(distinct ckbgdh) as bgdfs_tj2,
         sum(mylaj) as mylaj_tj2
    from mx
   where mylaj>=30000
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg
  ),
  tj3 as (
  -- 相同运输方式、商品大类、供货区域、目的区域大额报关单总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,qycode_hg,
         count(distinct djxh) as qyhs_all,
         count(distinct ckbgdh) as bgdfs_all,
         sum(mylaj) as mylaj_all,
         count(distinct case when mylaj>=30000 then djxh else null end) as qyhs_sx,
         count(distinct case when mylaj>=30000 then ckbgdh else null end) as bgdfs_sx,
         sum(case when mylaj>=30000 then mylaj else 0 end) as mylaj_sx
    from mx
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,qycode_hg
  )
  select tj3.ysfs_dm,tj3.spdl_dm,tj3.qycode_hyd,tj3.qycode_hg,tj3.qycode_mdg,
         tj3.qyhs_all,case when IFNULL(tj1.qyhs_tj1, 0)<=tj3.qyhs_all then 100.00 else round(100*tj3.qyhs_all/tj1.qyhs_tj1,2) end as qyzb_all,
         tj3.bgdfs_all,case when IFNULL(tj1.bgdfs_tj1, 0)<=tj3.bgdfs_all then 100.00 else round(100*tj3.bgdfs_all/tj1.bgdfs_tj1,2) end as bgdzb_all,
         tj3.mylaj_all,case when IFNULL(tj1.mylaj_tj1, 0)<=tj3.mylaj_all then 100.00 else round(100*tj3.mylaj_all/tj1.mylaj_tj1,2) end as myzb_all,
         tj3.qyhs_sx,case when IFNULL(tj2.qyhs_tj2, 0)<=tj3.qyhs_sx then 100.00 else round(100*tj3.qyhs_sx/tj2.qyhs_tj2,2) end as qyzb_sx,
         tj3.bgdfs_sx,case when IFNULL(tj2.bgdfs_tj2, 0)<=tj3.bgdfs_sx then 100.00 else round(100*tj3.bgdfs_sx/tj2.bgdfs_tj2,2) end as bgdzb_sx,
         tj3.mylaj_sx,case when IFNULL(tj2.mylaj_tj2, 0)<=tj3.mylaj_sx then 100.00 else round(100*tj3.mylaj_sx/tj2.mylaj_tj2,2) end as myzb_sx
    from tj3
    left join tj1
      on tj1.ysfs_dm=tj3.ysfs_dm
     and tj1.spdl_dm=tj3.spdl_dm
     and tj1.qycode_hyd=tj3.qycode_hyd
     and tj1.qycode_mdg=tj3.qycode_mdg
    left join tj2
      on tj2.ysfs_dm=tj3.ysfs_dm
     and tj2.spdl_dm=tj3.spdl_dm
     and tj2.qycode_hyd=tj3.qycode_hyd
     and tj2.qycode_mdg=tj3.qycode_mdg
  ;
  commit;

  update CKLLFX_CS_WMQYLSLL_SF AS t
     set fxdj_zhfxzs= t.qyzb_all * 0.1 + t.bgdzb_all * 0.2 + t.myzb_all * 0.2
                      + t.qyzb_sx  * 0.1 + t.bgdzb_sx  * 0.2 + t.myzb_sx  * 0.2;
  commit;
  -- 根据风险指数设置风险等级，对浙江、上海出口或货源地与出口地区域一致的降一级风险等级
  update CKLLFX_CS_WMQYLSLL_SF AS t
     set fxdj_dm= case when t.fxdj_zhfxzs<=5
                         then (case when t.qycode_hg in ('31','33') or t.qycode_hyd=t.qycode_hg then '3' else '4' end)
                         when t.fxdj_zhfxzs<=10
                         then (case when t.qycode_hg in ('31','33') or t.qycode_hyd=t.qycode_hg then '2' else '3' end)
                         when t.fxdj_zhfxzs<=20
                         then (case when t.qycode_hg in ('31','33') or t.qycode_hyd=t.qycode_hg then '1' else '2' end)
                         else '1'
                    end;
  commit;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_SZYJ_WMQYCKLL_SF_PERY.sql

-- ======================================================================
-- [038/146] BEGIN SOURCE: PRO_FXGL_SZYJ_XBLQY.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_FXGL_SZYJ_XBLQY$$

CREATE PROCEDURE PRO_FXGL_SZYJ_XBLQY
/*
 * 风险管理——事中预警——新办类企业
 */
(
  IN P_SWJGDM VARCHAR(4000), -- 非空，通审核助手获取当前流程的退税机关代码并传入
  IN P_DJXH VARCHAR(4000), -- 非空，通审核助手获取当前流程的企业登记序号并传入
  OUT P_OUTMSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LN_MONTHS_ZDCK   DECIMAL(18,2);
  DECLARE LN_MONTHS_SCSB   DECIMAL(18,2);
  DECLARE LD_PRE_MAXRQ     DATETIME;
  DECLARE LD_NOW_MINRQ     DATETIME;
  DECLARE LD_BG_TSJWRQ     DATETIME;

  -- 预警参数：新办类企业首次申报以后有效期
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO LN_MONTHS_SCSB
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S
      ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_SCSB';
  -- 预警参数：中断出口后复出口的企业中断期
  SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
    INTO LN_MONTHS_ZDCK
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S
      ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_ZDCK';
  -- LN_MONTHS_SCSB个月前最后一次申报时间
  SELECT DATE(MAX(T.QDSJ))
    INTO LD_PRE_MAXRQ
    FROM CKTS_LC_SBXX T
   WHERE T.DJXH = P_DJXH
     AND IFNULL(T.ZFBZ, 'N') = 'N'
     AND T.QDSJ <= DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * LN_MONTHS_SCSB MONTH);
  -- LN_MONTHS_SCSB个月内最早一次申报时间
  SELECT DATE(MIN(T.QDSJ))
    INTO LD_NOW_MINRQ
    FROM CKTS_LC_SBXX T
   WHERE T.DJXH = P_DJXH
     AND IFNULL(T.ZFBZ, 'N') = 'N'
     AND T.QDSJ > DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * LN_MONTHS_SCSB MONTH);
  -- 外贸企业LN_MONTHS_SCSB个月内最后一次迁移
  SELECT DATE(MAX(T.LRRQ))
    INTO LD_BG_TSJWRQ
    FROM CKTS_BA_BABGQK_JGB T
   INNER JOIN GLXT_BB_SHXT_DJXX S
      ON S.DJXH_JS=T.DJXH
     AND S.JSMODE='2'
   WHERE T.DJXH = P_DJXH
     AND BABGZD_DM='TSSWJG_DM_1'
     AND T.LRRQ > DATE_ADD(CURRENT_TIMESTAMP, INTERVAL (-1) * LN_MONTHS_SCSB MONTH);
  IF LD_PRE_MAXRQ IS NULL THEN
    SET P_OUTMSG = ORA_CONCAT(ORA_CONCAT('01-新办类企业，出口企业首次申报不足', LN_MONTHS_SCSB), '个月，请加强审核！');
    LEAVE routine_body;
  END IF;
  IF IFNULL(LD_NOW_MINRQ, CURRENT_TIMESTAMP) >= DATE_ADD(LD_PRE_MAXRQ, INTERVAL LN_MONTHS_ZDCK MONTH) THEN
    SET P_OUTMSG = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('02-新办类企业，出口企业中断申报', LN_MONTHS_ZDCK), '个月后复出口申报不足'), LN_MONTHS_SCSB), '个月，请加强审核！');
    LEAVE routine_body;
  END IF;
  IF LD_BG_TSJWRQ IS NOT NULL THEN
    SET P_OUTMSG = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('03-新办类企业，外贸企业于', DATE_FORMAT(LD_BG_TSJWRQ, '%Y-%m-%d')), '迁移后首次申报不足'), LN_MONTHS_SCSB), '个月，请加强审核！');
    LEAVE routine_body;
  END IF;
  SET P_OUTMSG = '00';

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_FXGL_SZYJ_XBLQY.sql

-- ======================================================================
-- [039/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_S10101.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_S10101$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_S10101
/*
 * 企业经营稳定性
 * ZB_VAL：最后一次变更法人代表时间（未变更按税务登记时间）至报告期止月数
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10),
  IN P_BGQ_Z DATETIME
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT ROUND(TIMESTAMPDIFF(MONTH, MAX(CAST(DATE_FORMAT(IFNULL(S.LRRQ, T.SWDJ_DATE), '%Y-%m-01') AS DATETIME)), P_BGQ_Z)),
           ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报告期截止日期=', DATE_FORMAT(P_BGQ_Z, '%Y%m%d')), '|税务登记日期='), DATE_FORMAT(MAX(T.SWDJ_DATE), '%Y%m%d')), '|最近变更法人代表日期='), DATE_FORMAT(MAX(S.LRRQ), '%Y%m%d'))
      INTO V_ZB_VAL, V_PARAMS
      FROM GLXT_BB_SHXT_DJXX T
      LEFT JOIN CKTS_DJ_BGDJMX S ON S.DJXH=T.DJXH_JS AND S.BGQNR<>S.BGHNR AND S.LRRQ<=P_BGQ_Z
     WHERE T.DJXH_JS=P_DJXH;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10101' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10101',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10101';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_S10101.sql

-- ======================================================================
-- [040/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_S10102.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_S10102$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_S10102
/*
 * 出口企业法定代表人是否为企业实际控制人
 * ZB_VAL：出口企业填报JKGL_ZLCJ_JGB，以填报结果为准，一致为0，不一致为1
 *         出口企业未填报JKGL_ZLCJ_JGB，查看股东占股比例，小于10%为1，否则为0
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_THIS_DATA  DECIMAL(18,6);
  DECLARE V_PARAMS     VARCHAR(1000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT CASE WHEN T.FDDBR_XM=T.SJJYR_XM THEN 0 ELSE 1 END,
           ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]法定代表人=', T.FDDBR_XM), '|实际控制人='), T.SJJYR_XM)
      INTO V_ZB_VAL, V_PARAMS
      FROM JKGL_ZLCJ_JGB T
     WHERE T.DJXH=P_DJXH;
  END;

  IF V_ZB_VAL IS NULL THEN
    SELECT IFNULL(T.FDDBR_CGBL, 0),
           ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]法定代表人=', T.FDDBRMC), '|持股比例='), IFNULL(T.FDDBR_CGBL, 0)), '%')
      INTO V_THIS_DATA, V_PARAMS
      FROM GS_DJ_CKTMSDAB T
     WHERE T.CPCODE=CAST(P_DJXH AS CHAR);
    IF V_THIS_DATA<10 THEN
      SET V_ZB_VAL = 1;
    ELSE
      SET V_ZB_VAL = 0;
    END IF;
  END IF;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10102' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10102',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10102';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_S10102.sql

-- ======================================================================
-- [041/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_S10103.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_S10103$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_S10103
/*
 * 出口企业法定代表人是否来自骗税高风险地区
 * ZB_VAL：否0，是1，非身份证的返回0
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_ZJLX       VARCHAR(50);
  DECLARE V_ZJHM       VARCHAR(50);
  DECLARE V_PARAMS     VARCHAR(1000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT FRDB_ZJLX, FRDB_ZJHM, ORA_CONCAT('[d]法定代表人证件号码=', FRDB_ZJHM)
      INTO V_ZJLX, V_ZJHM, V_PARAMS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.DJXH_JS=P_DJXH;

    IF V_ZJLX='201' AND LENGTH(V_ZJHM) IN (15,18) THEN
      SELECT LEAST(COUNT(1),1)
        INTO V_ZB_VAL
        FROM JKGL_GY_FXDQ_SWJG S
       WHERE (S.XZQH_DM=SUBSTR(V_ZJHM,1,6) OR S.XZQH_DM=SUBSTR(V_ZJHM,1,4))
         AND S.QYBZ='Y';
    ELSE
      SET V_ZB_VAL = NULL;
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10103' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10103',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10103';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

