-- ======================================================================
-- [042/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_S10104.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_S10104$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_S10104
/*
 * 出口企业出口企业法定代表人年龄是否异常
 * ZB_VAL：法定代表人年龄小于19周岁；企业经营期未满三年且法人代表年龄大于65周岁，返回1
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10),
  IN P_BGQ_Z DATETIME,
  IN P_SWJGDM VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_ZJLX       VARCHAR(50);
  DECLARE V_ZJHM       VARCHAR(50);
  DECLARE V_THIS_DATA  DECIMAL(18,2);
  DECLARE V_LAST_DATA  DECIMAL(18,2);
  DECLARE VAL1         DECIMAL(18,2);    -- 参数1
  DECLARE VAL2         DECIMAL(18,2);    -- 参数2
  DECLARE V_PARAMS     VARCHAR(1000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
      INTO VAL1
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_S10104_AGE_LOWER';
    SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
      INTO VAL2
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_S10104_AGE_UPPER';

    SELECT FRDB_ZJLX, FRDB_ZJHM
      INTO V_ZJLX, V_ZJHM
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.DJXH_JS=P_DJXH;

    IF V_ZJLX='201' AND LENGTH(V_ZJHM)=15 THEN
      SET V_THIS_DATA = EXTRACT(YEAR FROM P_BGQ_Z) - CAST(ORA_CONCAT('19', SUBSTR(V_ZJHM,7,2)) AS DECIMAL(65,30));
    ELSEIF V_ZJLX='201' AND LENGTH(V_ZJHM)=18 THEN
      SET V_THIS_DATA = EXTRACT(YEAR FROM P_BGQ_Z) - CAST(SUBSTR(V_ZJHM,7,4) AS DECIMAL(65,30));
    ELSE
      SET V_THIS_DATA = 0;
    END IF;

    SELECT FLOOR(TIMESTAMPDIFF(MONTH, MAX(IFNULL(S.LRRQ, T.SWDJ_DATE)), P_BGQ_Z))
      INTO V_LAST_DATA
      FROM GLXT_BB_SHXT_DJXX T
      LEFT JOIN CKTS_DJ_BGDJMX S ON S.DJXH=T.DJXH_JS AND S.LRRQ<=P_BGQ_Z
     WHERE T.DJXH_JS=P_DJXH;

    IF V_THIS_DATA<=0 THEN
      SET V_ZB_VAL = NULL;
    ELSEIF V_THIS_DATA<VAL1 THEN
      SET V_ZB_VAL = 1;
    ELSEIF V_THIS_DATA>VAL2 AND V_LAST_DATA<36 THEN
      SET V_ZB_VAL = 1;
    ELSE
      SET V_ZB_VAL = 0;
    END IF;

    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]法定代表人证件号码=', V_ZJHM), '|经营期限='), V_LAST_DATA), '个月');
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10104' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10104',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10104';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_S10104.sql

-- ======================================================================
-- [043/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_S10105.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_S10105$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_S10105
/*
 * 财务负责人是否兼职
 * ZB_VAL：财务负责人兼职的企业合计户数
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_ZJHM       VARCHAR(50);
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT T.CWFZRSFZJHM,
           ORA_CONCAT('[d]财务负责人证件号码=', T.CWFZRSFZJHM)
      INTO V_ZJHM, V_PARAMS
      FROM GS_DJ_CKTMSDAB T
     WHERE T.CPCODE=CAST(P_DJXH AS CHAR)
       AND 1=1
LIMIT 1;

    SET V_ZB_VAL = 0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SPDM_NSRSBH_001 LONGTEXT;
  DECLARE BJTS_CUR_SPDM_NSRMC_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.NSRSBH, T.NSRMC
                       FROM GS_DJ_CKTMSDAB T
                      WHERE T.CWFZRSFZJHM = V_ZJHM
                         OR T.FRZJHM = V_ZJHM;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_SPDM_NSRSBH_001, BJTS_CUR_SPDM_NSRMC_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      SET V_ZB_VAL = V_ZB_VAL +1;
      IF V_ZB_VAL<=20 THEN
        SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|财务负责人所在单位税号='), BJTS_CUR_SPDM_NSRSBH_001), '，名称='), BJTS_CUR_SPDM_NSRMC_001);
      END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
    IF V_ZB_VAL>20 THEN
      SET V_PARAMS = ORA_CONCAT(V_PARAMS, '|...');
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10105' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10105',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10105';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_S10105.sql

