-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_S10203$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_S10203
/*
 * 销售额与电费支出变动趋势，取统计期往前一年与前前一年的数据
 * ZB_VAL：销售额(扣除委托加工费)升降趋势与电费升降趋势不一致返回1，否则0
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_JQID DECIMAL(38,10)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_THIS_DATA  DECIMAL(18,2);
  DECLARE V_LAST_DATA  DECIMAL(18,2);
  DECLARE V_THIS_AMT   DECIMAL(18,2);
  DECLARE V_LAST_AMT   DECIMAL(18,2);
  DECLARE V_PARAMS     VARCHAR(1000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT S.ZZS_XSE_QB - S.DZ_WTJG, S.DZ_DFJE_ZC - S.DZ_DFJE_SR
      INTO V_THIS_DATA, V_THIS_AMT
      FROM JKGL_DATA_TJ_ZBU S
     WHERE S.BGQID=P_BGQID;

    SELECT S.ZZS_XSE_QB - S.DZ_WTJG, S.DZ_DFJE_ZC - S.DZ_DFJE_SR
      INTO V_LAST_DATA, V_LAST_AMT
      FROM JKGL_DATA_TJ_ZBU S
     WHERE S.BGQID=P_JQID;

    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报告期销售额(扣除委托加工费)=', V_THIS_DATA), '|报告期电费='), V_THIS_AMT), '|基期销售额(扣除委托加工费)='), V_LAST_DATA), '|基期电费='), V_LAST_AMT);
    IF V_THIS_DATA>0 AND V_THIS_AMT>=0 AND V_LAST_DATA>0 AND V_LAST_AMT>=0 THEN
      IF (V_THIS_DATA - V_LAST_DATA) * (V_THIS_AMT - V_LAST_AMT) < 0 THEN
        SET V_ZB_VAL = 1;
      ELSE
        SET V_ZB_VAL = 0;
      END IF;
    ELSE
      SET V_ZB_VAL = NULL;
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10203' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10203',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10203';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

