       WHERE S.BGQID=P_BGQID;
      SELECT S.CK_CKEUSD
        INTO V_LAST_DATA
        FROM JKGL_DATA_TJ_ZBU S
       WHERE S.BGQID=P_JQID;

      SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报告期出口销售额=', V_THIS_DATA), '|基期出口销售额='), V_LAST_DATA);
      IF V_LAST_DATA>0 THEN
        IF V_THIS_DATA>=VAL2 AND V_THIS_DATA>=V_LAST_DATA * VAL1 THEN
          SET V_ZB_VAL = 1;
        ELSE
          SET V_ZB_VAL = 0;
        END IF;
        SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|环比='), ROUND(100 * V_THIS_DATA / V_LAST_DATA,2)), '%');
      ELSE
        SET V_ZB_VAL = NULL;
      END IF;
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S30103' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S30103',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S30103';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

