-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W10101$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W10101
/*
 * 企业经营稳定性
 * ZB_VAL：最后一次变更法人代表时间（未变更按税务登记时间）至报告期止月数
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10),
  IN P_BGQ_Z DATETIME
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT ROUND(TIMESTAMPDIFF(MONTH, MAX(CAST(DATE_FORMAT(IFNULL(S.LRRQ, T.SWDJ_DATE), '%Y-%m-01') AS DATETIME)), P_BGQ_Z)),
           ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报告期截止日期=', DATE_FORMAT(P_BGQ_Z, '%Y%m%d')), '|税务登记日期='), DATE_FORMAT(MAX(T.SWDJ_DATE), '%Y%m%d')), '|最近变更法人代表日期='), DATE_FORMAT(MAX(S.LRRQ), '%Y%m%d'))
      INTO V_ZB_VAL, V_PARAMS
      FROM GLXT_BB_SHXT_DJXX T
      LEFT JOIN CKTS_DJ_BGDJMX S ON S.DJXH=T.DJXH_JS AND S.BGQNR<>S.BGHNR AND S.LRRQ<=P_BGQ_Z
     WHERE T.DJXH_JS=P_DJXH;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10101' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W10101',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10101';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W10101.sql

-- ======================================================================
-- [080/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W10102.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W10102$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W10102
/*
 * 布尔，报告期内是否变更法人代表
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10),
  IN P_BGQ_Q DATETIME,
  IN P_BGQ_Z DATETIME
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = 0;

  END;
SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]变更日期=', DATE_FORMAT(LRRQ, '%Y%m%d')), '|变更前内容='), BGQNR), '|变更后内容='), BGHNR)
      INTO V_PARAMS
      FROM (SELECT *
              FROM CKTS_DJ_BGDJMX T
             WHERE T.DJXH=P_DJXH AND T.LRRQ>=P_BGQ_Q AND T.LRRQ<ORA_DATE_ADD(P_BGQ_Z, 1)
               AND T.BGQNR<>T.BGHNR
             ORDER BY T.LRRQ DESC) AS BJTS_DERIVED_001
     WHERE 1=1
LIMIT 1;
     IF V_PARAMS IS NOT NULL THEN
       SET V_ZB_VAL =1;
     ELSE
       SET V_ZB_VAL =0;
     END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10102' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W10102',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10102';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W10102.sql

-- ======================================================================
-- [081/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W10201.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W10201$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W10201
/*
 * 是否存在多个企业共用一个经营地址的情况
 * ZB_VAL：出口企业经营地址登记企业数量
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_ADDRESS    VARCHAR(1000);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT S.ADDRESS_JY,
           ORA_CONCAT(ORA_CONCAT('[d]企业经营地址=', S.ADDRESS_JY), '，该地址登记企业：')
      INTO V_ADDRESS, V_PARAMS
      FROM GLXT_BB_SHXT_DJXX S
     WHERE S.DJXH_JS=P_DJXH
       AND 1=1
LIMIT 1;

    SET V_ZB_VAL = 0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SPDM_NSRDJNO_001 LONGTEXT;
  DECLARE BJTS_CUR_SPDM_NSRMC_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.NSRDJNO, T.NSRMC
                       FROM GLXT_BB_SHXT_DJXX T
                      WHERE T.ADDRESS_JY = V_ADDRESS;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_SPDM_NSRDJNO_001, BJTS_CUR_SPDM_NSRMC_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      SET V_ZB_VAL = V_ZB_VAL +1;
      IF V_ZB_VAL<=20 THEN
        SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|税号='), BJTS_CUR_SPDM_NSRDJNO_001), '，名称='), BJTS_CUR_SPDM_NSRMC_001) ;
      END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
    IF V_ZB_VAL>20 THEN
