-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W10304$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W10304
/*
 * 出口企业是否经常变更法定代表人
 * ZB_VAL：变更次数
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10),
  IN P_BGQ_Z DATETIME
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SET V_ZB_VAL = 0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SPDM_LRRQ_001 LONGTEXT;
  DECLARE BJTS_CUR_SPDM_BGQNR_001 LONGTEXT;
  DECLARE BJTS_CUR_SPDM_BGHNR_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DATE_FORMAT(LRRQ, '%Y%m%d') AS LRRQ, BGQNR, BGHNR
                       FROM CKTS_DJ_BGDJMX T
                      WHERE T.DJXH=P_DJXH AND T.BGQNR<>T.BGHNR AND T.LRRQ<ORA_DATE_ADD(P_BGQ_Z, 1)
                      ORDER BY T.LRRQ DESC;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_SPDM_LRRQ_001, BJTS_CUR_SPDM_BGQNR_001, BJTS_CUR_SPDM_BGHNR_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      SET V_ZB_VAL = V_ZB_VAL +1;
      IF V_ZB_VAL=1 THEN
        SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]变更日期=', BJTS_CUR_SPDM_LRRQ_001), '，变更前内容='), BJTS_CUR_SPDM_BGQNR_001), '，变更后内容='), BJTS_CUR_SPDM_BGHNR_001);
      ELSEIF V_ZB_VAL<=20 THEN
        SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|变更日期='), BJTS_CUR_SPDM_LRRQ_001), '，变更前内容='), BJTS_CUR_SPDM_BGQNR_001), '，变更后内容='), BJTS_CUR_SPDM_BGHNR_001);
      END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
    IF V_ZB_VAL>20 THEN
      SET V_PARAMS = ORA_CONCAT(V_PARAMS, '|...');
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10304' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W10304',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10304';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W10304.sql

-- ======================================================================
-- [087/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W10401.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W10401$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W10401
/*
 * 企业四员是否来自敏感地区
 * ZB_VAL：存在来自敏感地区的成员，返回1
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_FRDBRZJHM  VARCHAR(100);
  DECLARE V_CWFZRZJHM  VARCHAR(100);
  DECLARE V_BSYZJHM    VARCHAR(100);
  DECLARE V_PARAMS     VARCHAR(1000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT FRDB_ZJHM, ORA_CONCAT('[d]法定代表人证件号码=', FRDB_ZJHM)
      INTO V_FRDBRZJHM, V_PARAMS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.DJXH_JS=P_DJXH;

    SELECT T1.CWFZRSFZJHM
      INTO V_CWFZRZJHM
      FROM GS_DJ_CKTMSDAB T1
     WHERE T1.CPCODE=CAST(P_DJXH AS CHAR);
    SELECT COUNT(1)
      INTO V_ROWS
      FROM JKGL_GY_FXDQ_SWJG S1
     WHERE (S1.XZQH_DM=SUBSTR(V_CWFZRZJHM,1,6) OR S1.XZQH_DM=SUBSTR(V_CWFZRZJHM,1,4))
       AND S1.QYBZ='Y'
       AND LENGTH(V_CWFZRZJHM) IN (15,18);
    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|财务负责人证件号码='), V_CWFZRZJHM);
    IF V_ROWS>0 THEN
      SET V_PARAMS = ORA_CONCAT(V_PARAMS, '，是');
    ELSE
      SET V_PARAMS = ORA_CONCAT(V_PARAMS, '，否');
    END IF;

    SELECT T1.BSRSFZJHM
      INTO V_BSYZJHM
      FROM GS_DJ_CKTMSDAB T1
     WHERE T1.CPCODE=CAST(P_DJXH AS CHAR);
    SELECT COUNT(1)
      INTO V_ZB_VAL
      FROM JKGL_GY_FXDQ_SWJG S1
     WHERE (S1.XZQH_DM=SUBSTR(V_BSYZJHM,1,6) OR S1.XZQH_DM=SUBSTR(V_BSYZJHM,1,4))
       AND S1.QYBZ='Y'
       AND LENGTH(V_BSYZJHM) IN (15,18);
    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|办税员证件号码='), V_BSYZJHM);
    IF V_ZB_VAL>0 THEN
      SET V_PARAMS = ORA_CONCAT(V_PARAMS, '，是');
    ELSE
      SET V_PARAMS = ORA_CONCAT(V_PARAMS, '，否');
    END IF;

    IF (V_ZB_VAL>0 AND V_FRDBRZJHM<>V_BSYZJHM) OR (V_ROWS>0 AND V_FRDBRZJHM<>V_CWFZRZJHM) THEN
      SET V_ZB_VAL = 1;
    ELSE
      SET V_ZB_VAL =0;
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10401' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W10401',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10401';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W10401.sql

-- ======================================================================
-- [088/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W10403.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W10403$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W10403
/*
 * 法人兼营多家企业
 * ZB_VAL：企业法人兼营的企业户数，目前未计算股东兼营情况
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_ZJHM       VARCHAR(50);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT T.FRDB_ZJHM,
           ORA_CONCAT(ORA_CONCAT('[d]企业法人证件号码=', T.FRDB_ZJHM), '，法人兼营企业列表：')
      INTO V_ZJHM, V_PARAMS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.DJXH_JS=P_DJXH
       AND 1=1
LIMIT 1;

    SET V_ZB_VAL = 0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SPDM_NSRSBH_001 LONGTEXT;
  DECLARE BJTS_CUR_SPDM_NSRMC_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.NSRSBH, T.NSRMC
                       FROM CKTS_DJ_NSRXX T
                      WHERE T.FDDBRSFZJHM = V_ZJHM
                        AND T.NSRZT_DM NOT IN ('07','13')
                        AND LENGTH(T.NSRSBH)=18
                        AND SUBSTR(T.NSRSBH,1,1)<>'L'
                        AND T.NSRMC NOT LIKE '%车购税%';
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_SPDM_NSRSBH_001, BJTS_CUR_SPDM_NSRMC_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      SET V_ZB_VAL = V_ZB_VAL +1;
      IF V_ZB_VAL<=20 THEN
        SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|税号='), BJTS_CUR_SPDM_NSRSBH_001), '，名称='), BJTS_CUR_SPDM_NSRMC_001);
      END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
    IF V_ZB_VAL>20 THEN
      SET V_PARAMS = ORA_CONCAT(V_PARAMS, '|...');
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10403' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W10403',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10403';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W10403.sql

-- ======================================================================
-- [089/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W10501.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W10501$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W10501
/*
 * 出口企业分类管理登记
 * ZB_VAL：A-1,B-2,C-3,D-4，无类别返回5
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10),
  IN P_BGQ_Z DATETIME
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_PARAMS     VARCHAR(1000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT (CASE B.KZXX WHEN 'A' THEN 1 WHEN 'B' THEN 2 WHEN 'C' THEN 3 WHEN 'D' THEN 4 ELSE 5 END),
           ORA_CONCAT('[d]出口企业分类管理等级=', B.KZXX)
      INTO V_ZB_VAL, V_PARAMS
      FROM GS_DJ_CKTMSDAB A
     INNER JOIN GS_DJ_CKTMSDAB_KZ B ON A.NSRDZDAH=B.NSRDZDAH AND B.KZLX='FLGLCD' AND (P_BGQ_Z BETWEEN B.ST_DATE AND B.END_DATE)
     WHERE A.CPCODE=CAST(P_DJXH AS CHAR)
       AND 1=1
LIMIT 1;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10501' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W10501',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W10501';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W10501.sql

-- ======================================================================
-- [090/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W20101.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W20101$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W20101
/*
 * 跨大类商品退税额
 * ZB_VAL：跨大类商品退税额>XX AND 跨大类商品退税额/报告期_退税额>YY%，返回1
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_JQID DECIMAL(38,10),
  IN P_SWJGDM VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_THIS_DATA  DECIMAL(18,2);
  DECLARE V_LAST_DATA  DECIMAL(18,2);
  DECLARE VAL1         DECIMAL(18,2);    -- 参数1
  DECLARE VAL2         DECIMAL(18,2);    -- 参数2
  DECLARE V_PARAMS     VARCHAR(4000);
  DECLARE V_PARAM2     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
      INTO VAL1
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20101_KDLSP_TSE';
    SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
      INTO VAL2
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20101_KDLSP_ZB';

    SELECT T.TS_TSE_SB+T.TS_MDE_SB
      INTO V_THIS_DATA
      FROM JKGL_DATA_TJ_ZBU T
     WHERE T.BGQID=P_BGQID;

    SET V_ROWS = 0;
    SET V_PARAM2 = '';
    SET V_LAST_DATA =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SPDM_SP_DL_001 LONGTEXT;
  DECLARE BJTS_CUR_SPDM_CKSP_MC_001 LONGTEXT;
  DECLARE BJTS_CUR_SPDM_SBTMSE_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.SP_DL, DM.CKSP_MC, SUM(T.SBTMSE) AS SBTMSE
                       FROM JKGL_DATA_TJ_ZBU_TSSP T
                       LEFT JOIN JCFX_DM_CKSPTREE DM ON DM.CKSP_DM=T.SP_DL AND DM.CKSP_JC='2'
                      WHERE T.BGQID=P_BGQID
                        AND NOT EXISTS (SELECT 1
                                          FROM JKGL_DATA_TJ_ZBU_TSSP S
                                         WHERE S.BGQID=P_JQID
                                           AND S.SP_DL=T.SP_DL)
                      GROUP BY T.SP_DL, DM.CKSP_MC;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_SPDM_SP_DL_001, BJTS_CUR_SPDM_CKSP_MC_001, BJTS_CUR_SPDM_SBTMSE_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      SET V_ROWS = V_ROWS +1;
      SET V_LAST_DATA = V_LAST_DATA + BJTS_CUR_SPDM_SBTMSE_001;
      IF V_ROWS<=20 THEN
        SET V_PARAM2 = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAM2, '|跨大类商品代码='), BJTS_CUR_SPDM_SP_DL_001), '（'), BJTS_CUR_SPDM_CKSP_MC_001), '），申报退免税额='), BJTS_CUR_SPDM_SBTMSE_001);
      END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
    IF V_ROWS>20 THEN
      SET V_PARAM2 = ORA_CONCAT(V_PARAM2, '|...');
    END IF;

    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报告期申报退(免)税额=', V_THIS_DATA), '|其中跨大类商品申报退(免)税额='), V_LAST_DATA);
    IF V_THIS_DATA>0 AND V_LAST_DATA>0 THEN
      IF V_LAST_DATA>=VAL2 AND V_LAST_DATA>=V_THIS_DATA * VAL1 THEN
        SET V_ZB_VAL = 1;
      ELSE
        SET V_ZB_VAL = 0;
      END IF;
      SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|占比='), ROUND(100 * V_LAST_DATA / V_THIS_DATA,2)), '%');
    ELSE
      SET V_ZB_VAL = 0;
    END IF;
    SET V_PARAMS = ORA_CONCAT(V_PARAMS, V_PARAM2);
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20101' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W20101',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20101';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W20101.sql

-- ======================================================================
-- [091/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W20103.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W20103$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W20103
/*
 * 退税额增长，取统计期往前一季的数据与上一季的比较
 * ZB_VAL：季度环比大于50%且退税额大于50万元，返回1
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_JQID DECIMAL(38,10),
  IN P_SWJGDM VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_THIS_DATA  DECIMAL(18,2);
  DECLARE V_LAST_DATA  DECIMAL(18,2);
  DECLARE VAL1         DECIMAL(18,2);    -- 参数1
  DECLARE VAL2         DECIMAL(18,2);    -- 参数2
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
      INTO VAL1
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20103_TSE_JE';
    SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) / (CASE T.CSTYPE WHEN '百分比' THEN 100 ELSE 1 END)
      INTO VAL2
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20103_TSE_HB';

    SELECT S.TS_MDE_SB + S.TS_TSE_SB
      INTO V_THIS_DATA
      FROM JKGL_DATA_TJ_ZBU S
     WHERE S.BGQID=P_BGQID;

    SELECT S.TS_MDE_SB + S.TS_TSE_SB
      INTO V_LAST_DATA
      FROM JKGL_DATA_TJ_ZBU S
     WHERE S.BGQID=P_JQID;

    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报告期申报退(免)税额=', V_THIS_DATA), '|基期申报退(免)税额='), V_LAST_DATA);
    IF V_THIS_DATA>0 AND V_LAST_DATA>0 THEN
      IF V_THIS_DATA>=VAL1 AND V_THIS_DATA>=VAL2*V_LAST_DATA THEN
        SET V_ZB_VAL = 1;
      ELSE
        SET V_ZB_VAL = 0;
      END IF;
    ELSE
      SET V_ZB_VAL = NULL;
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20103' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W20103',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB AS T
       SET ZB_VAL=V_ZB_VAL,
    BADPOINT=V_BADPOINT,
    PARAMS=V_PARAMS,
    UPTIME=CURRENT_TIMESTAMP
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20103';
  END IF;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_W20103.sql

-- ======================================================================
-- [092/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_W20201.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_W20201$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_W20201
/*
 * (报关单每单的每美元利润<本企业每美元利润中位数*下限%
 * or 报关单每单的每美元利润>本企业每美元利润中位数*上限%）的出口额合计/报告期_出口额>80%
 * ZB_VAL：
 */
(
  IN P_BGQID DECIMAL(38,10),
  IN P_DJXH DECIMAL(38,10),
  IN P_BGQ_Q DATETIME,
  IN P_BGQ_Z DATETIME
)
routine_body: BEGIN
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_ROWS       BIGINT;
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE V_THIS_DATA  DECIMAL(18,2);
  DECLARE V_LAST_DATA  DECIMAL(18,2);
  DECLARE V_MEDIAN     DECIMAL(18,3);
  DECLARE V_MAX        DECIMAL(18,3);
  DECLARE V_MIN        DECIMAL(18,3);
  DECLARE V_PARAMS     VARCHAR(4000);

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ZB_VAL = NULL;

  END;
SELECT SUM(CKEUSD), ORA_MEDIAN(JSON_ARRAYAGG(MMYLR)), MAX(MMYLR), MIN(MMYLR)
      INTO V_THIS_DATA, V_MEDIAN, V_MAX, V_MIN
      FROM (SELECT SUBSTR(T.CKBGDH,1,18) AS CKBGDH, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB, SUM(T.JSJE) AS JHJE,
                   CASE WHEN SUM(T.MYLAJ)<=0 THEN 0 ELSE ROUND((SUM(T.RMBLAJ) - SUM(T.JSJE)) / SUM(T.MYLAJ),2) END AS MMYLR
              FROM JCFX_DATA_TSSBMX T
             WHERE T.DJXH=P_DJXH
               AND T.SBRQ>=P_BGQ_Q AND T.SBRQ<ORA_DATE_ADD(P_BGQ_Z, 1)
             GROUP BY SUBSTR(T.CKBGDH,1,18)) TT;

    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('[d]报告期出口额=', V_THIS_DATA), '|本企业每美元利润中位数='), V_MEDIAN), '|本企业每美元利润最大值='), V_MAX), '|本企业每美元利润最小值='), V_MIN);
    SET V_MAX = (V_MAX + V_MEDIAN) /2;
    SET V_MIN = (V_MIN + V_MEDIAN) /2;
    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|按大于上限='), V_MAX), '|或小于下限='), V_MIN);

    SELECT SUM(CKEUSD)
      INTO V_LAST_DATA
      FROM (SELECT SUBSTR(T.CKBGDH,1,18) AS CKBGDH, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB, SUM(T.JSJE) AS JHJE,
                   CASE WHEN SUM(T.MYLAJ)<=0 THEN 0 ELSE ROUND((SUM(T.RMBLAJ) - SUM(T.JSJE)) / SUM(T.MYLAJ),2) END AS MMYLR
              FROM JCFX_DATA_TSSBMX T
             WHERE T.DJXH=P_DJXH
               AND T.SBRQ>=P_BGQ_Q AND T.SBRQ<ORA_DATE_ADD(P_BGQ_Z, 1)
             GROUP BY SUBSTR(T.CKBGDH,1,18)) TT
     WHERE MMYLR>V_MAX OR MMYLR<V_MIN;
    SET V_PARAMS = ORA_CONCAT(ORA_CONCAT(V_PARAMS, '|与中位数偏离较大的出口额='), V_LAST_DATA);

    IF V_THIS_DATA<=0 OR V_LAST_DATA<0 THEN
      SET V_ZB_VAL = NULL;
    ELSE
      SET V_ZB_VAL =ROUND(100 * V_LAST_DATA / V_THIS_DATA, 2);
    END IF;
  END;

  IF V_ZB_VAL IS NULL THEN
    SET V_BADPOINT = 'Y';
  ELSE
    SET V_BADPOINT = 'N';
  END IF;

  SELECT LEAST(COUNT(1), 1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20201' AND 1=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
