     WHERE T.CSBM='ZC_W40103_GHQY_SL_HB';

    SELECT T.TS_GHS_NUM
      INTO V_THIS_DATA
      FROM JKGL_DATA_TJ_ZBU T
     WHERE T.BGQID=P_BGQID;

    SELECT T.TS_GHS_NUM
      INTO V_LAST_DATA
      FROM JKGL_DATA_TJ_ZBU T
     WHERE T.BGQID=P_JQID;

