-- ======================================================================
-- [131/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_ZB.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_ZB$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_ZB
/*
 * 指标计算总入口
 * P_ZBYEAR: 指标年度，空的时候默认为最新的企业年度报告期，否则按YYYY格式
 * P_SWJGDM: 税务机关范围，空的时候默认为133（全省），否则按省级前3位，地市级传前5位，区县级传前7位
 * P_QYLX: 企业类型范围，空的时候默认为全部，否则按生产1外贸2
 * P_DJXH：企业登记序号，空的时候默认为全部，否则单个企业刷新
 * P_ZB_ID：指标标识，可空，空默认为全部指标
 * P_ERROR：输出参数，0执行成功，其他执行失败
 * P_MSG：  输出参数，执行失败时的错误信息
 */
(
  IN P_ZBYEAR VARCHAR(4000),
  IN P_SWJGDM VARCHAR(4000),
  IN P_QYLX VARCHAR(4000),
  IN P_DJXH DECIMAL(38,10),
  IN P_ZB_ID VARCHAR(4000),
  OUT P_ERROR DECIMAL(38,10),
  OUT P_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE V_ZBYEAR  VARCHAR(4);
  DECLARE V_SWJGDM  VARCHAR(12);
  DECLARE V_NDJQID  DECIMAL(20,0);     -- 年度基期ID
  DECLARE V_JDBGQID DECIMAL(20,0);     -- 季度报告期ID
  DECLARE V_JDJQID  DECIMAL(20,0);     -- 季度基期ID
  DECLARE V_QSPJID  DECIMAL(20,0);     -- 全省平均报告期ID
  DECLARE V_JDBGQQ  DATETIME;           -- 季度报告期起
  DECLARE V_JDBGQZ  DATETIME;           -- 季度报告期止
  DECLARE V_NDBGQQ  DATETIME;           -- 年度报告期起
  DECLARE V_NDBGQZ  DATETIME;           -- 年度报告期止

  SET P_ERROR =0;
  SET P_MSG = ' ';

  IF TRIM(P_ZBYEAR) IS NULL THEN
    SET V_ZBYEAR = DATE_FORMAT(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -4 MONTH), '%Y');
  ELSEIF LENGTH(TRIM(P_ZBYEAR))=4 AND P_ZBYEAR>='2019' AND P_ZBYEAR<=DATE_FORMAT(DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -4 MONTH), '%Y') THEN
    SET V_ZBYEAR = TRIM(P_ZBYEAR);
  ELSE
    SET P_ERROR = -1;
    SET P_MSG = '参数（指标年度）请按YYYY格式输入！';
    LEAVE routine_body;
  END IF;
  IF TRIM(P_SWJGDM) IS NULL THEN
    SET V_SWJGDM = '133%';
  ELSEIF LENGTH(TRIM(P_SWJGDM)) IN (3,5,7) THEN
    SET V_SWJGDM = ORA_CONCAT(TRIM(P_SWJGDM), '%');
  ELSE
    SET P_ERROR = -2;
    SET P_MSG = '参数（税务机关代码）请按省级前3位，地市级传前5位，区县级传前7位输入！';
    LEAVE routine_body;
  END IF;
  IF TRIM(P_QYLX) IS NOT NULL AND TRIM(P_QYLX)!='1' AND TRIM(P_QYLX)!='2' THEN
    SET P_ERROR = -3;
    SET P_MSG = '参数（企业类型）请按生产1外贸2输入！';
    LEAVE routine_body;
  END IF;

  SET V_NDBGQQ = STR_TO_DATE(ORA_CONCAT(V_ZBYEAR, '-01-01'), '%Y-%m-%d');
  SET V_NDBGQZ = STR_TO_DATE(ORA_CONCAT(V_ZBYEAR, '-12-31'), '%Y-%m-%d');

  DELETE FROM CKTS_DJ_BGDJMX AS T
  WHERE T.BGQNR=T.BGHNR;
  COMMIT;
  DELETE FROM CKTS_DJ_BGDJMX AS T
  WHERE LENGTH(T.BGQNR)=15 AND LENGTH(T.BGHNR)=18
  AND T.BGQNR=ORA_CONCAT(SUBSTR(T.BGHNR,1,6), SUBSTR(T.BGHNR,9,9));
  COMMIT;
  DELETE FROM CKTS_DJ_BGDJMX AS T
  WHERE LENGTH(T.BGHNR)=15 AND LENGTH(T.BGQNR)=18
  AND T.BGHNR=ORA_CONCAT(SUBSTR(T.BGQNR,1,6), SUBSTR(T.BGQNR,9,9));
  COMMIT;

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CURSOR_SKIP_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGQ_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQID_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_SWJGDM_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_JSMODE_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT S.DJXH, S.BGQID, T.SWJGDM, T.JSMODE
                    FROM GLXT_BB_SHXT_DJXX T
                   INNER JOIN JKGL_DATA_BGQ S ON S.DJXH=T.DJXH_JS
                   WHERE T.SWJGDM LIKE V_SWJGDM
                     AND ((TRIM(P_QYLX) IS NULL) OR ((CASE T.JSMODE WHEN '1' THEN '1' ELSE '2' END) = TRIM(P_QYLX)))
                     AND ((P_DJXH IS NULL) OR (T.DJXH_JS=P_DJXH))
                     AND S.BGQ_Q=V_NDBGQQ AND S.BGQ_Z=V_NDBGQZ
                     AND S.SXZT='2';
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_BGQ_DJXH_001, BJTS_CUR_BGQ_BGQID_001, BJTS_CUR_BGQ_SWJGDM_001, BJTS_CUR_BGQ_JSMODE_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    SET BJTS_CURSOR_SKIP_001 = FALSE;
    -- 年度报告期ID : CUR_BGQ.BGQID
    -- 年度基期ID
    BEGIN
  DECLARE BJTS_SQLCODE_006 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_006 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_006 = MYSQL_ERRNO, BJTS_SQLERRM_006 = MESSAGE_TEXT;
        SET V_NDJQID =0;

  END;
SELECT T.BGQID
        INTO V_NDJQID
        FROM JKGL_DATA_BGQ T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T.BGQ_Q=DATE_ADD(V_NDBGQQ, INTERVAL -12 MONTH) AND T.BGQ_Z=ORA_DATE_ADD(V_NDBGQQ, -(1))
         AND T.SXZT='2';
    END;
    -- 季度报告期ID
    BEGIN
  DECLARE BJTS_SQLCODE_005 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_005 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_005 = MYSQL_ERRNO, BJTS_SQLERRM_005 = MESSAGE_TEXT;
        SET V_JDBGQID =0;

  END;
SELECT BGQID, BGQ_Q, BGQ_Z
        INTO V_JDBGQID, V_JDBGQQ, V_JDBGQZ
        FROM (SELECT *
                FROM JKGL_DATA_BGQ T
               WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T.BGQ_Q>=V_NDBGQQ AND T.BGQ_Q<V_NDBGQZ
                 AND T.ZQLX='季' AND T.SXZT='3'
               ORDER BY T.BGQ_Q DESC) TT
       WHERE 1=1
LIMIT 1;
    END;
    -- 季度基期ID
    BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_004 = MYSQL_ERRNO, BJTS_SQLERRM_004 = MESSAGE_TEXT;
        SET V_JDJQID =0;

  END;
SELECT T.BGQID
        INTO V_JDJQID
        FROM JKGL_DATA_BGQ T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T.BGQ_Q>=DATE_ADD(V_JDBGQQ, INTERVAL -3 MONTH) AND T.BGQ_Z=ORA_DATE_ADD(V_JDBGQQ, -(1))
         AND T.SXZT='3';
    END;
    -- 全省平均报告期ID
    BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
        SET V_QSPJID =0;

  END;
SELECT T.BGQID
        INTO V_QSPJID
        FROM JKGL_DATA_BGQ_QSPJ T
       WHERE T.QYLX=(CASE BJTS_CUR_BGQ_JSMODE_001 WHEN '1' THEN '1' ELSE '2' END)
         AND T.BGQ_Q=V_NDBGQQ AND T.BGQ_Z=V_NDBGQZ;
    END;

    IF BJTS_CUR_BGQ_JSMODE_001='1' THEN
      BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
          SET BJTS_CURSOR_SKIP_001 = TRUE;

  END;
IF IFNULL(P_ZB_ID, 'S10101')='S10101' THEN -- 数量，最后一次变更法人代表时间（未变更按税务登记时间）至报告期止月数
          CALL PRO_JKGL_COMPUTE_S10101(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_JDBGQZ);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10102')='S10102' THEN -- 布尔，出口企业填报采集表，以填报结果为准，一致为0，不一致为1, 未填报查看股东占股比例，小于10%为1，否则为0
          CALL PRO_JKGL_COMPUTE_S10102(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10103')='S10103' THEN -- 布尔，法定代表人身份证行政区划是否来自敏感地区，是返回1
          CALL PRO_JKGL_COMPUTE_S10103(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10104')='S10104' THEN -- 布尔，法定代表人年龄小于19周岁；企业经营期未满三年且法人代表年龄大于65周岁，返回1
          CALL PRO_JKGL_COMPUTE_S10104(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_JDBGQZ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10105')='S10105' THEN -- 数量，财务负责人是否兼职(兼任其他企业财务负责人或法人)，返回兼职企业数量
          CALL PRO_JKGL_COMPUTE_S10105(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10107')='S10107' THEN -- 数量，出口企业分类管理等级，返回A-1,B-2,C-3,D-4，无类别返回5
          CALL PRO_JKGL_COMPUTE_S10107(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_JDBGQZ);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10108')='S10108' THEN -- 布尔，报告期内是否变更法人代表
          CALL PRO_JKGL_COMPUTE_S10108(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,V_JDBGQZ);
        END IF;

        IF IFNULL(P_ZB_ID, 'S10201')='S10201' THEN -- 数量，返回增值税全部销售额/固定资产期初期末平均数
          CALL PRO_JKGL_COMPUTE_S10201(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10202')='S10202' THEN -- 数量，平均生产面积销售额，未填报采集表返回坏点标志
          CALL PRO_JKGL_COMPUTE_S10202(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10203')='S10203' THEN -- 布尔，销售额(扣除委托加工费)升降趋势与电费升降趋势不一致返回1，否则0
          CALL PRO_JKGL_COMPUTE_S10203(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;
        IF IFNULL(P_ZB_ID, 'S10204')='S10204' THEN -- 布尔，报告期内电费支出小于等于5万元且外销收入减委托加工费用大于700W
          CALL PRO_JKGL_COMPUTE_S10204(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'S20101')='S20101' THEN -- 布尔，出口销售额占全部销售额比例90%以下但应退税额占免抵退税额比例达90%以上。
          CALL PRO_JKGL_COMPUTE_S20101(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S20102')='S20102' THEN -- 布尔，环比大于150%且退税额大于50万元。
          CALL PRO_JKGL_COMPUTE_S20102(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S20103')='S20103' THEN -- 布尔，跨大类商品退税额>100W AND 跨大类商品退税额/报告期_退税额>50%
          CALL PRO_JKGL_COMPUTE_S20103(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'S30101')='S30101' THEN -- 百分比，出口额变动率异常，取消
          CALL PRO_JKGL_COMPUTE_S30101(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30102')='S30102' THEN -- 布尔，出口_大额报关单出口额USD / 出口_出口额USD > 80%
          CALL PRO_JKGL_COMPUTE_S30102(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30103')='S30103' THEN -- 布尔，首笔出口满一年 and  出口_出口额USD>100万美元 and  出口_出口额USD环比>150%
          CALL PRO_JKGL_COMPUTE_S30103(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30104')='S30104' THEN -- 布尔，首笔出口未满一年企业,季度出口额达100万美元且环比超150%。
          CALL PRO_JKGL_COMPUTE_S30104(BJTS_CUR_BGQ_BGQID_001,V_JDBGQID,V_JDJQID,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30105')='S30105' THEN -- 布尔，首笔出口未满一年企业,出口额超1000万美元。
          CALL PRO_JKGL_COMPUTE_S30105(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'S30201')='S30201' THEN -- 数量，商品出口额超1WUSD且商品_出口额USD环比>150% 的商品数量
          CALL PRO_JKGL_COMPUTE_S30201(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30202')='S30202' THEN -- 百分比，商品_新增出口额USD/商品_出口额USD
          CALL PRO_JKGL_COMPUTE_S30202(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30203')='S30203' THEN -- 数量，商品出口额超1WUSD且单价环比>150% 的商品个数
          CALL PRO_JKGL_COMPUTE_S30203(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30204')='S30204' THEN -- 数量，商品出口额超1WUSD且出口单价与全省平均差异超50%的商品个数
          CALL PRO_JKGL_COMPUTE_S30204(BJTS_CUR_BGQ_BGQID_001,V_QSPJID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30205')='S30205' THEN -- 数量，商品出口额超1WUSD且商品_出口额USD环比>150% 的敏感商品数量
          CALL PRO_JKGL_COMPUTE_S30205(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30206')='S30206' THEN -- 数量，生产企业跨大类(基期不存在该大类)数
          CALL PRO_JKGL_COMPUTE_S30206(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30207')='S30207' THEN  -- 百分比，出口跨大类商品金额占比，取消
          CALL PRO_JKGL_COMPUTE_S30207(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;

        IF IFNULL(P_ZB_ID, 'S30301')='S30301' THEN -- 数量，出口额环比超150%的口岸个数
          CALL PRO_JKGL_COMPUTE_S30301(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        -- IF NVL(P_ZB_ID,'S30302')='S30302' THEN -- 转关出口额占比，取消
        IF IFNULL(P_ZB_ID, 'S30303')='S30303' THEN -- 数量，敏感口岸数量
          CALL PRO_JKGL_COMPUTE_S30303(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30304')='S30304' THEN -- 数量，国别_口岸数量>5 的国别数量
          CALL PRO_JKGL_COMPUTE_S30304(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'S30401')='S30401' THEN -- 百分比，出口目的国数量变动，取消
          CALL PRO_JKGL_COMPUTE_S30401(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30402')='S30402' THEN -- 百分比，出口到香港商品占比
          CALL PRO_JKGL_COMPUTE_S30402(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30403')='S30403' THEN -- 布尔，出口国别（地区）数大于10个且增幅超50%。
          CALL PRO_JKGL_COMPUTE_S30403(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        -- IF NVL(P_ZB_ID,'S30501')='S30501' THEN -- 两高两不符，取消

        IF IFNULL(P_ZB_ID, 'S30601')='S30601' THEN  -- 布尔，报告期出口额大于100万美元但运费小于500元。
          CALL PRO_JKGL_COMPUTE_S30601(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S30602')='S30602' THEN  -- 数量，出口同一国别（地区）货代（申报单位）数量超5个。
          CALL PRO_JKGL_COMPUTE_S30602(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        -- IF NVL(P_ZB_ID,'S30603')='S30603' THEN -- 数量，返回二异报关USD出口额

        -- IF NVL(P_ZB_ID,'S40101')='S40101' THEN -- 百分比，非视同自产且货源地行政区划<>企业所在地的申报出口MY占比。
        -- IF NVL(P_ZB_ID,'S40102')='S40102' THEN -- 底账_商品名称 与退税_出口商品名称相同 且 退税_视同自产出口额=0，的底账_该商品进项金额合计/底账_进项总金额
        IF IFNULL(P_ZB_ID, 'S40103')='S40103' THEN -- 百分比，退税_视同自产出口额RMB/退税_出口额RMB
          CALL PRO_JKGL_COMPUTE_S40103(BJTS_CUR_BGQ_BGQID_001);
        END IF;

        -- IF NVL(P_ZB_ID,'S40201')='S40201' THEN -- 底账_供货企业 涉及贵金属的数量
        IF IFNULL(P_ZB_ID, 'S40202')='S40202' THEN -- 百分比，增值税_农产品进项税额/增值税_全部进项税额
          CALL PRO_JKGL_COMPUTE_S40202(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S40203')='S40203' THEN -- 百分比，(底账_农产品进项税额-底账_农产品进项税额[基期])/底账_农产品进项税额[基期])
          CALL PRO_JKGL_COMPUTE_S40203(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;

        -- IF NVL(P_ZB_ID,'S40301')='S40301' THEN -- 退税_退税额>100万 且 (底账_供货企业汇总中涉及非正常户的税额合计>100万 或 底账_供货企业汇总中涉及非正常户的税额合计/底账_总进项税额>15%)
        -- IF NVL(P_ZB_ID,'S40302')='S40302' THEN -- 底账_供货企业汇总中涉及非正常户的户数合计>=3  且 底账_供货企业汇总中涉及非正常户的户数合计/底账_供货企业总数>10%

        IF IFNULL(P_ZB_ID, 'S50101')='S50101' THEN -- 百分比，(增值税_免抵销售+增值税_免税销售)/增值税_全部销售
          CALL PRO_JKGL_COMPUTE_S50101(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S50201')='S50201' THEN -- 百分比，(资产_期末存货-资产_期末存货[基期])/资产_期末存货[基期]
          CALL PRO_JKGL_COMPUTE_S50201(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'S50301')='S50301' THEN -- 百分比，还原税负率
          CALL PRO_JKGL_COMPUTE_S50301(BJTS_CUR_BGQ_BGQID_001);
        END IF;

        -- IF NVL(P_ZB_ID,'S60101')='S60101' THEN -- 同一业务员备案3个以上非关联外贸公司的出口企业。
      END;
    ELSE
      BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
          SET BJTS_CURSOR_SKIP_001 = TRUE;

  END;
IF IFNULL(P_ZB_ID, 'W10101')='W10101' THEN -- 数量，最后一次变更法人代表时间（未变更按税务登记时间）至报告期止月数
          CALL PRO_JKGL_COMPUTE_W10101(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_JDBGQZ);
        END IF;
        IF IFNULL(P_ZB_ID, 'W10102')='W10102' THEN -- 布尔，报告期内是否变更法人代表
          CALL PRO_JKGL_COMPUTE_W10102(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,V_JDBGQZ);
        END IF;

        IF IFNULL(P_ZB_ID, 'W10201')='W10201' THEN -- 数量，是否存在多个企业共用一个经营地址的情况，出口企业范围内经营地址相同的企业数量
          CALL PRO_JKGL_COMPUTE_W10201(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W10202')='W10202' THEN -- 布尔，企业基础登记信息中注册地址与生产经营地址不一致，则返回1
          CALL PRO_JKGL_COMPUTE_W10202(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W10301')='W10301' THEN -- 布尔，法定代表人年龄小于19周岁；企业经营期未满三年且法人代表年龄大于65周岁，返回1
          CALL PRO_JKGL_COMPUTE_W10301(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_JDBGQZ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W10302')='W10302' THEN -- 布尔，法定代表人是否来自敏感地区
          CALL PRO_JKGL_COMPUTE_W10302(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W10303')='W10303' THEN -- 布尔，法定代表人与实际经营人的一致性
          CALL PRO_JKGL_COMPUTE_W10303(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W10304')='W10304' THEN -- 数量，企业是否经常变更法定代表人
          CALL PRO_JKGL_COMPUTE_W10304(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_JDBGQZ);
        END IF;

        IF IFNULL(P_ZB_ID, 'W10401')='W10401' THEN -- 布尔，企业四员是否来自敏感地区
          CALL PRO_JKGL_COMPUTE_W10401(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;
        -- IF NVL(P_ZB_ID,'W10402')='W10402' THEN -- 业务员是否缴纳社保
        IF IFNULL(P_ZB_ID, 'W10403')='W10403' THEN -- 数量，法人是否同时兼营多家企业（含内销企业）
          CALL PRO_JKGL_COMPUTE_W10403(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W10501')='W10501' THEN -- 数量，出口企业分类管理等级
          CALL PRO_JKGL_COMPUTE_W10501(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_JDBGQZ);
        END IF;

        IF IFNULL(P_ZB_ID, 'W20101')='W20101' THEN -- 布尔，跨大类商品退税额>XX AND 跨大类商品退税额/报告期_退税额>YY%
          CALL PRO_JKGL_COMPUTE_W20101(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        -- IF NVL(P_ZB_ID,'W20102')='W20102' THEN -- 百分比，超期申报的报关单/报告期申报报关数量，参考W20202
        IF IFNULL(P_ZB_ID, 'W20103')='W20103' THEN -- 布尔，季度环比大于150%且退税额大于50万元。
          CALL PRO_JKGL_COMPUTE_W20103(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W20201')='W20201' THEN -- (报关单每单的每美元利润<本企业每美元利润中位数*下限% or 报关单每单的每美元利润>本企业每美元利润中位数*上限%）的出口额合计/报告期_出口额>
          CALL PRO_JKGL_COMPUTE_W20201(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,V_JDBGQZ);
        END IF;
        IF IFNULL(P_ZB_ID, 'W20202')='W20202' THEN -- 布尔，超期申报报关单数量>XX and 超期申报出口额/报告期出口额>YY%
          CALL PRO_JKGL_COMPUTE_W20202(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W20203')='W20203' THEN -- 数值，综合换汇成本异常=申报退税的总计税金额/申报退税的报关单人民币出口额
          CALL PRO_JKGL_COMPUTE_W20203(BJTS_CUR_BGQ_BGQID_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W30101')='W30101' THEN -- 数值，涉及四同出口的报关单数量
          CALL PRO_JKGL_COMPUTE_W30101(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,V_JDBGQZ);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30102')='W30102' THEN -- 美元，出口货物单笔货柜值较高
          CALL PRO_JKGL_COMPUTE_W30102(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,V_JDBGQZ);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30103')='W30103' THEN -- 百分比，出口_大额报关单出口额USD / 出口_出口额USD*100%
          CALL PRO_JKGL_COMPUTE_W30103(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30104')='W30104' THEN -- 百分比，拼箱报关单份数/总份数*100%
          CALL PRO_JKGL_COMPUTE_W30104(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30105')='W30105' THEN -- 美元，出口_出口额USD/出口_报关单数量
          CALL PRO_JKGL_COMPUTE_W30105(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30106')='W30106' THEN -- 布尔，出口_申报单位数量/出口_报关单数量>XX% and 出口_报关单数量>YY
          CALL PRO_JKGL_COMPUTE_W30106(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30107')='W30107' THEN -- 数量，统计(国别_口岸数量>5)的国别个数
          CALL PRO_JKGL_COMPUTE_W30107(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30108')='W30108' THEN -- 数量，敏感口岸数量
          CALL PRO_JKGL_COMPUTE_W30108(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        -- IF NVL(P_ZB_ID,'W30109')='W30109' THEN -- 二异出口（舍近求远）
        IF IFNULL(P_ZB_ID, 'W30110')='W30110' THEN -- 数量，(国别_运输方式数量>2 and 国别代码 not in ('142'))的国别数量
          CALL PRO_JKGL_COMPUTE_W30110(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W30201')='W30201' THEN -- 布尔，首笔出口满一年企业,出口额USD>100万美元,年度报告期增幅>50%
          CALL PRO_JKGL_COMPUTE_W30201(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30202')='W30202' THEN -- 布尔，首笔出口未满一年,出口额USD>100万美元,季度报告期增幅>50%
          CALL PRO_JKGL_COMPUTE_W30202(BJTS_CUR_BGQ_BGQID_001,V_JDBGQID,V_JDJQID,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30203')='W30203' THEN -- 布尔，首笔出口未满一年企业,出口额超1000万美元。
          CALL PRO_JKGL_COMPUTE_W30203(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        -- IF NVL(P_ZB_ID,'W30204')='W30204' THEN -- 出口额异常（重复？）
        IF IFNULL(P_ZB_ID, 'W30205')='W30205' THEN -- 布尔，僵尸企业出口额增长异常
          CALL PRO_JKGL_COMPUTE_W30205(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_DJXH_001,V_NDBGQQ,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30206')='W30206' THEN -- 布尔，报告期_出口额>100W and (基期_出口额<>0) and (报告期_出口额>1.5*基期_出口额)
          CALL PRO_JKGL_COMPUTE_W30206(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W30301')='W30301' THEN -- 布尔，出口目的国数量>10,出口目的国数量增幅>50%
          CALL PRO_JKGL_COMPUTE_W30301(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W30401')='W30401' THEN -- 数量，商品出口额超1WUSD且商品_出口额USD环比>150% 的敏感商品数量
          CALL PRO_JKGL_COMPUTE_W30401(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30402')='W30402' THEN -- 数量，商品出口额超1WUSD且出口单价与全省平均差异超50%的商品个数
          CALL PRO_JKGL_COMPUTE_W30402(BJTS_CUR_BGQ_BGQID_001,V_QSPJID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        -- IF NVL(P_ZB_ID,'W30403')='W30403' THEN -- 单位重量的商品单价与同行业相比偏离较大
        IF IFNULL(P_ZB_ID, 'W30404')='W30404' THEN -- 数量，外贸企业跨大类数大于10个
          CALL PRO_JKGL_COMPUTE_W30404(BJTS_CUR_BGQ_BGQID_001,V_NDJQID);
        END IF;

        IF IFNULL(P_ZB_ID, 'W30501')='W30501' THEN  -- 布尔，报告期出口额大于100万美元但运费小于500元。
          CALL PRO_JKGL_COMPUTE_W30501(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W30502')='W30502' THEN  -- 数量，同一口岸货代预警，口岸_申报单位数量>5
          CALL PRO_JKGL_COMPUTE_W30502(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        -- IF NVL(P_ZB_ID,'W30601')='W30601' THEN  -- 两高两不符

        IF IFNULL(P_ZB_ID, 'W40101')='W40101' THEN -- 布尔，供货企业是否来自预警地区(退税_计税金额>50W AND 风险地区供货企业数量>50%)
          CALL PRO_JKGL_COMPUTE_W40101(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W40102')='W40102' THEN -- 百分比，报告期_省外进货金额/报告期_进货金额
          CALL PRO_JKGL_COMPUTE_W40102(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W40103')='W40103' THEN -- 布尔，退税_供货商个数>=20 and (退税_供货商个数 - 退税_供货商个数[基期])/退税_供货商个数[基期]>50%
          CALL PRO_JKGL_COMPUTE_W40103(BJTS_CUR_BGQ_BGQID_001,V_NDJQID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W40104')='W40104' THEN -- 布尔，非正常企业供货退税额合计>100万元 or 非正常企业供货退税额合计/报告期_退免税额>15%
          CALL PRO_JKGL_COMPUTE_W40104(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W40105')='W40105' THEN -- 布尔，非正常企业供货户数合计>3 or 非正常企业供货户数合计/报告期_供货企业户数>10%
          CALL PRO_JKGL_COMPUTE_W40105(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W40201')='W40201' THEN -- 布尔，退税_超期1发票金额>XX元 or 退税_超期1发票金额/退税_进项金额>XX% or 退税_超期1发票份数>XX份
          CALL PRO_JKGL_COMPUTE_W40201(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        -- IF NVL(P_ZB_ID,'W40202')='W40202' THEN -- 与W40201合并成一个指标，取消
        IF IFNULL(P_ZB_ID, 'W40203')='W40203' THEN -- 布尔，退税_顶格开票总金额>XX元 and 退税_顶格开票总金额/退税_发票总金额>YY%
          CALL PRO_JKGL_COMPUTE_W40203(BJTS_CUR_BGQ_BGQID_001,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        -- IF NVL(P_ZB_ID,'W40204')='W40204' THEN -- 发票ip及mac地址

        IF IFNULL(P_ZB_ID, 'W40301')='W40301' THEN -- 数量，上游供货企业涉及贵金属，取消
          CALL PRO_JKGL_COMPUTE_W40301(BJTS_CUR_BGQ_BGQID_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W50101')='W50101' THEN -- 数量，毛利率与同行业相比偏离较大的商品数量
          CALL PRO_JKGL_COMPUTE_W50101(BJTS_CUR_BGQ_BGQID_001,V_QSPJID,BJTS_CUR_BGQ_SWJGDM_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W50102')='W50102' THEN -- 百分比，总体毛利率与同行业相比偏离较大
          CALL PRO_JKGL_COMPUTE_W50102(BJTS_CUR_BGQ_BGQID_001,V_QSPJID);
        END IF;

        -- IF NVL(P_ZB_ID,'W50201')='W50201' THEN -- 出口企业税负率与同行业平均值相比偏离是否较大
        IF IFNULL(P_ZB_ID, 'W50202')='W50202' THEN -- 百分比，企业还原税负率与同行业平均值相比偏离是否较大
          CALL PRO_JKGL_COMPUTE_W50202(BJTS_CUR_BGQ_BGQID_001);
        END IF;

        IF IFNULL(P_ZB_ID, 'W50301')='W50301' THEN -- 百分比，应收账款周转率
          CALL PRO_JKGL_COMPUTE_W50301(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W50302')='W50302' THEN -- 百分比，应收账款占营业收入比重
          CALL PRO_JKGL_COMPUTE_W50302(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W50303')='W50303' THEN -- 百分比，应付账款周转率
          CALL PRO_JKGL_COMPUTE_W50303(BJTS_CUR_BGQ_BGQID_001);
        END IF;
        IF IFNULL(P_ZB_ID, 'W50304')='W50304' THEN -- 百分比，应付账款占营业成本比重
          CALL PRO_JKGL_COMPUTE_W50304(BJTS_CUR_BGQ_BGQID_001);
        END IF;

        -- IF NVL(P_ZB_ID,'W50401')='W50401' THEN -- 企业是否按规定缴纳社保
        -- IF NVL(P_ZB_ID,'W50402')='W50402' THEN -- 企业缴纳社保的人员与企业实际人员是否匹配

        IF IFNULL(P_ZB_ID, 'W50501')='W50501' THEN -- 百分比，企业销售费用与企业营业收入的比值是否异常
          CALL PRO_JKGL_COMPUTE_W50501(BJTS_CUR_BGQ_BGQID_001);
        END IF;

        -- IF NVL(P_ZB_ID,'W60101')='W60101' THEN -- 业务员挂靠企业户数
        -- IF NVL(P_ZB_ID,'W60102')='W60102' THEN -- 业务员出口额变动率
        -- IF NVL(P_ZB_ID,'W60103')='W60103' THEN -- 业务员商品出口数量变动
        -- IF NVL(P_ZB_ID,'W60104')='W60104' THEN -- 业务员商品出口额变动率
        -- IF NVL(P_ZB_ID,'W60105')='W60105' THEN -- 业务员出口目的国数量
        -- IF NVL(P_ZB_ID,'W60106')='W60106' THEN -- 业务员出口目的国出口额变动率
        -- IF NVL(P_ZB_ID,'W60107')='W60107' THEN -- 业务员供货企业户数
        -- IF NVL(P_ZB_ID,'W60108')='W60108' THEN -- 业务员供货金额变动率

        -- IF NVL(P_ZB_ID,'W60201')='W60201' THEN -- 是否被公安海关外管税务稽查等部门查处
        -- IF NVL(P_ZB_ID,'W60202')='W60202' THEN -- 存在各类企业异常信息

        -- IF NVL(P_ZB_ID,'W60301')='W60301' THEN -- 是否存在外管部门反馈的异常外汇数据
      END;
    END IF;
    IF BJTS_CURSOR_SKIP_001 THEN
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;
  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_ZB.sql

-- ======================================================================
-- [132/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_ZBU_JD.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_ZBU_JD$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_ZBU_JD()
/*
 * 季度指标元刷新算法
 * 202309，增加判断是否新开业的出口企业
 * 202309，增加代理出口统计
 * 20250919，调整拼箱与整柜报关单的计算口径
 */
routine_body: BEGIN
  DECLARE V_CK_BGDSL        BIGINT; --  出口_报关单数量
  DECLARE V_CK_CKEUSD       DECIMAL(18,2); --  出口_出口额USD
  DECLARE V_CK_CKERMB       DECIMAL(18,2); --  出口_出口额
  DECLARE V_CK_SBDW_SL      BIGINT; --  出口_申报单位数量
  DECLARE V_CK_GB_SL        BIGINT; --  出口_目的国数量
  DECLARE V_CK_BGDSL_DE     BIGINT; --  出口_大额报关单数量
  DECLARE V_CK_CKEUSD_DE    DECIMAL(18,2); --  出口_大额报关单出口额USD
  DECLARE V_CK_BGDSL_ST     BIGINT; --  出口_四同报关单数量
  DECLARE V_CK_PXBGDSL      BIGINT; --  出口_拼箱报关单数量
  DECLARE V_CK_ZXBGDSL      DECIMAL(18,2); --  出口_整箱报关单数量
  DECLARE V_CK_PJDBHGZ      DECIMAL(18,2); --  出口_平均单笔货柜值
  DECLARE V_CK_CKEUSD_LASTYEAR	DECIMAL(18,2); --	出口_最近12个月出口额USD
  DECLARE V_TS_BGDSL        BIGINT; --  退税_报关单数量
  DECLARE V_TS_CKEUSD       DECIMAL(18,2); --  退税_出口额USD
  DECLARE V_TS_CKERMB       DECIMAL(18,2); --  退税_出口额RMB
  DECLARE V_TS_MTSCKE       DECIMAL(18,2); --  退税_出口额RMB（免退税）
  DECLARE V_TS_JSJE         DECIMAL(18,2); --  退税_计税金额（免退税）
  DECLARE V_TS_HHCB         DECIMAL(18,2); --  退税_换汇成本（免退税）
  DECLARE V_TS_BGDSL_CQ     BIGINT; --  退税_报关单数量_超期申报
  DECLARE V_TS_CKEUSD_CQ    DECIMAL(18,2); --  退税_出口额USD_超期申报
  DECLARE V_TS_TSE_SB       DECIMAL(18,2); --  退税_退税额_申报
  DECLARE V_TS_MDE_SB       DECIMAL(18,2); --  退税_免抵额_申报
  DECLARE V_TS_TSE_HZ       DECIMAL(18,2); --  退税_退税_核准
  DECLARE V_TS_MDE_HZ       DECIMAL(18,2); --  退税_免抵_核准
  DECLARE V_TS_TSE_BL       DECIMAL(18,2); --  退税_退税_办理
  DECLARE V_TS_MDE_BL       DECIMAL(18,2); --  退税_免抵_办理
  DECLARE V_TS_CKERMB_STZC  DECIMAL(18,2); --  退税_视同自产出口额
  DECLARE V_TS_JHFP_JE      DECIMAL(18,2); --  退税_发票总金额
  DECLARE V_TS_JHFP_FS      BIGINT; --  退税_发票总份数
  DECLARE V_TS_JHFP_JE_CQ1  DECIMAL(18,2); --  退税_超期1发票金额
  DECLARE V_TS_JHFP_FS_CQ1  BIGINT; --  退税_超期1发票份数
  DECLARE V_TS_JHFP_JE_CQ2  DECIMAL(18,2); --  退税_超期2发票金额
  DECLARE V_TS_JHFP_FS_CQ2  BIGINT; --  退税_超期2发票份数
  DECLARE V_TS_GHS_NUM      BIGINT; --  退税_供货商个数
  DECLARE V_BGQ_Q           DATETIME;

  DECLARE V_ROWS            BIGINT;  -- 待更新表中是否存在目标记录


  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGQ_BGQID_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_NSRDJNO_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_SHXYNO_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_ZQLX_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Q_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Z_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_YF_Q_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_YF_Z_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_SQ_DATE_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.BGQID, T.DJXH, S.NSRDJNO, S.SHXYNO, T.ZQLX,
                         T.BGQ_Q, T.BGQ_Z, DATE_FORMAT(T.BGQ_Q, '%Y%m') AS YF_Q, DATE_FORMAT(T.BGQ_Z, '%Y%m') AS YF_Z,
                         S.SQ_DATE
                    FROM JKGL_DATA_BGQ T
                   INNER JOIN GLXT_BB_SHXT_DJXX S ON S.DJXH_JS=T.DJXH
                   WHERE T.ZQLX='季' AND T.SXZT='0' AND T.TQBZ IS NULL;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_BGQ_BGQID_001, BJTS_CUR_BGQ_DJXH_001, BJTS_CUR_BGQ_NSRDJNO_001, BJTS_CUR_BGQ_SHXYNO_001, BJTS_CUR_BGQ_ZQLX_001, BJTS_CUR_BGQ_BGQ_Q_001, BJTS_CUR_BGQ_BGQ_Z_001, BJTS_CUR_BGQ_YF_Q_001, BJTS_CUR_BGQ_YF_Z_001, BJTS_CUR_BGQ_SQ_DATE_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    -- 锁定正在处理的报告期
    UPDATE JKGL_DATA_BGQ AS T
       SET TQBZ=REPLACE(UUID(), '-', ''),
    TQSJ=CURRENT_TIMESTAMP,
    SXZT='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 检查报告期ZBU记录是否存在
    SELECT LEAST(COUNT(1), 1)
      INTO V_ROWS
      FROM JKGL_DATA_TJ_ZBU T
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001 AND 1=1;
    IF V_ROWS=0 THEN
      INSERT INTO JKGL_DATA_TJ_ZBU(BGQID) VALUES (BJTS_CUR_BGQ_BGQID_001);
      COMMIT;
    END IF;

    -- 判断是否新开业的出口企业
    IF BJTS_CUR_BGQ_SQ_DATE_001>=BJTS_CUR_BGQ_BGQ_Q_001 AND BJTS_CUR_BGQ_SQ_DATE_001<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1) THEN
      -- 当年新办的出口企业，首次报告期统计范围从当年年初开始，防止先出口后备案，并与年度报告期分类统计一致
      SET V_BGQ_Q = MAKEDATE(YEAR(BJTS_CUR_BGQ_BGQ_Q_001), 1);
    ELSE
      SET V_BGQ_Q = BJTS_CUR_BGQ_BGQ_Q_001;
    END IF;

    --  V_CK_
    BEGIN
      --  V_CK_BGDSL  NUMBER(10)  出口_报关单数量
      --  V_CK_CKEUSD NUMBER(18,2)  出口_出口额USD
      --  V_CK_CKERMB NUMBER(18,2)  出口_出口额
      --  V_CK_SBDW_SL  NUMBER(10)  出口_申报单位数量
      --  V_CK_GB_SL  NUMBER(10)  出口_目的国数量
      SELECT COUNT(DISTINCT SUBSTR(CKBGDH,1,18)), IFNULL(SUM(MYLAJ), 0), IFNULL(SUM(RMBLAJ), 0),
             COUNT(DISTINCT SBDWDM), COUNT(DISTINCT MYGDQSZ_DM)
        INTO V_CK_BGDSL, V_CK_CKEUSD, V_CK_CKERMB, V_CK_SBDW_SL, V_CK_GB_SL
        FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM
                FROM CKTS_WBSJ_HG_BGD T
               WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                 AND T.CKRQ_1>=V_BGQ_Q AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                 AND T.JGFS_DM<>'1039'
               UNION ALL
              SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM
                FROM CKTS_WBSJ_ZJ_DLCKHWZM S
               WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                 AND S.CKRQ_1>=V_BGQ_Q AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                 AND S.JGFS_DM<>'1039'
             ) TT;

      --  V_CK_BGDSL_DE NUMBER(10)  出口_大额报关单数量
      --  V_CK_CKEUSD_DE  NUMBER(18,2)  出口_大额报关单出口额USD
      --  每单超10W美金算大额报关单
      SELECT COUNT(1), IFNULL(SUM(MYLAJ18), 0)
        INTO V_CK_BGDSL_DE, V_CK_CKEUSD_DE
        FROM (SELECT SUBSTR(TT.CKBGDH,1,18) AS BGD18, SUM(TT.MYLAJ) AS MYLAJ18
                FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM
                        FROM CKTS_WBSJ_HG_BGD T
                       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                         AND T.CKRQ_1>=V_BGQ_Q AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                         AND T.JGFS_DM<>'1039'
                       UNION ALL
                      SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM
                        FROM CKTS_WBSJ_ZJ_DLCKHWZM S
                       WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                         AND S.CKRQ_1>=V_BGQ_Q AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                         AND S.JGFS_DM<>'1039'
                     ) TT
               GROUP BY SUBSTR(TT.CKBGDH,1,18)
              HAVING SUM(TT.MYLAJ)>100000
             ) T2;

      --  V_CK_BGDSL_ST NUMBER(10)  出口_四同报关单数量
      SELECT COUNT(1)
        INTO V_CK_BGDSL_ST
        FROM (SELECT T.HGCKHWBGDSBRQ,T.HGGQKA_DM,T.CKSP_DM,T.MYGDQSZ_DM, COUNT(DISTINCT SUBSTR(T.CKBGDH,1,18)) AS STNUM
                FROM CKTS_WBSJ_HG_BGD T
               WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                 AND T.HGCKHWBGDSBRQ>=V_BGQ_Q AND T.HGCKHWBGDSBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                 AND T.JGFS_DM<>'1039'
               GROUP BY T.HGCKHWBGDSBRQ,T.HGGQKA_DM,T.CKSP_DM,T.MYGDQSZ_DM) AS BJTS_DERIVED_001
       WHERE STNUM>=3;

      --  V_CK_PXBGDSL  NUMBER(10)  出口_拼箱报关单数量
      SELECT COUNT(DISTINCT T.BGDHGBH)
        INTO V_CK_PXBGDSL
        FROM CKTS_WBSJ_HG_BGD204 T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.CKRQ_1>=V_BGQ_Q AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND T.JZXH<>'无'
         AND (T.BJMMJBZ LIKE '%拼箱%' OR
             EXISTS (SELECT 1
                       FROM CKTS_WBSJ_HG_BGD204 S
                      WHERE S.JZXH=T.JZXH AND S.CKRQ_1=T.CKRQ_1 AND S.DJXH<>T.DJXH));

      --  V_CK_ZXBGDSL  NUMBER(18,2)  出口_整箱报关单数量
      --  V_CK_PJDBHGZ  NUMBER(18,2)  出口_平均单笔货柜值
      WITH JZXHXX AS (SELECT T2.BGDHGBH, COUNT(DISTINCT T2.JZXH) AS JZXSL
                        FROM CKTS_WBSJ_HG_BGD204 T2
                       WHERE T2.DJXH=BJTS_CUR_BGQ_DJXH_001
                         AND T2.CKRQ_1>=V_BGQ_Q AND T2.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                         AND T2.JZXH<>'无'
                         AND T2.BJMMJBZ NOT LIKE '%拼箱%'
                         AND NOT EXISTS (SELECT 1
                                           FROM CKTS_WBSJ_HG_BGD204 T3
                                          WHERE T3.JZXH=T2.JZXH AND T3.CKRQ_1=T2.CKRQ_1 AND T3.DJXH<>T2.DJXH)
                       GROUP BY T2.BGDHGBH),
           CKBGXX AS (SELECT SUBSTR(T.CKBGDH,1,18) AS BGDHGBH, SUM(T.MYLAJ) AS TOTALMY
                        FROM CKTS_WBSJ_HG_BGD T
                       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                         AND T.CKRQ_1>=V_BGQ_Q AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                         AND T.JGFS_DM<>'1039'
                       GROUP BY SUBSTR(T.CKBGDH,1,18))
      SELECT COUNT(DISTINCT JZXHXX.BGDHGBH),
             IFNULL((CASE WHEN SUM(JZXHXX.JZXSL)=0 THEN 0 ELSE SUM(CKBGXX.TOTALMY)/SUM(JZXHXX.JZXSL) END), 0)
        INTO V_CK_ZXBGDSL, V_CK_PJDBHGZ
        FROM JZXHXX
       INNER JOIN CKBGXX ON JZXHXX.BGDHGBH=CKBGXX.BGDHGBH;

      --  V_CK_CKEUSD_LASTYEAR	NUMBER(18,2); --	出口_最近12个月出口额USD
      SELECT IFNULL(SUM(MYLAJ), 0)
        INTO V_CK_CKEUSD_LASTYEAR
        FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM
                FROM CKTS_WBSJ_HG_BGD T
               WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                 AND T.CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_001, '%Y-%m-01') AS DATETIME), INTERVAL -11 MONTH) AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                 AND T.JGFS_DM<>'1039'
               UNION ALL
              SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM
                FROM CKTS_WBSJ_ZJ_DLCKHWZM S
               WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                 AND S.CKRQ_1>=DATE_ADD(CAST(DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_001, '%Y-%m-01') AS DATETIME), INTERVAL -11 MONTH) AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                 AND S.JGFS_DM<>'1039'
             ) TT;

      UPDATE JKGL_DATA_TJ_ZBU
         SET CK_BGDSL=V_CK_BGDSL,
    CK_CKEUSD=V_CK_CKEUSD,
    CK_CKERMB=V_CK_CKERMB,
    CK_SBDW_SL=V_CK_SBDW_SL,
    CK_GB_SL=V_CK_GB_SL,
    CK_BGDSL_DE=V_CK_BGDSL_DE,
    CK_CKEUSD_DE=V_CK_CKEUSD_DE,
    CK_BGDSL_ST=V_CK_BGDSL_ST,
    CK_PXBGDSL=V_CK_PXBGDSL,
    CK_ZXBGDSL=V_CK_ZXBGDSL,
    CK_PJDBHGZ=V_CK_PJDBHGZ,
    CK_CKEUSD_LASTYEAR=V_CK_CKEUSD_LASTYEAR
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;
    END;

    --  V_TS_
    BEGIN
      --  V_TS_BGDSL NUMBER(10) 退税_报关单数量
      --  V_TS_CKEUSD NUMBER(18,2)  退税_出口额USD
      --  V_TS_CKERMB NUMBER(18,2)  退税_出口额RMB
      --  V_TS_MTSCKE NUMBER(18,2)  退税_出口额RMB（免退税）
      --  V_TS_JSJE NUMBER(18,2)  退税_计税金额（免退税）
      --  V_TS_BGDSL_CQ NUMBER(10) 退税_报关单数量_超期申报
      --  V_TS_CKEUSD_CQ NUMBER(18,2)  退税_出口额USD_超期申报
      SELECT COUNT(DISTINCT SUBSTR(T.CKBGDH,1,18)), IFNULL(SUM(T.MYLAJ), 0), IFNULL(SUM(T.RMBLAJ), 0),
             IFNULL(SUM(CASE WHEN T.SBYWLX='1' THEN 0 ELSE T.RMBLAJ END), 0),
             IFNULL(SUM(CASE WHEN T.SBYWLX='1' THEN 0 ELSE T.JSJE END), 0),
             COUNT(DISTINCT CASE WHEN T.SBRQ>STR_TO_DATE(ORA_CONCAT(DATE_FORMAT(DATE_ADD(T.CKRQ, INTERVAL 12 MONTH), '%Y'), '0420'), '%Y%m%d') AND T.MYLAJ>0 THEN SUBSTR(T.CKBGDH,1,18) ELSE NULL END),
             IFNULL(SUM(CASE WHEN T.SBRQ>STR_TO_DATE(ORA_CONCAT(DATE_FORMAT(DATE_ADD(T.CKRQ, INTERVAL 12 MONTH), '%Y'), '0420'), '%Y%m%d') AND T.MYLAJ>0 THEN T.MYLAJ ELSE NULL END), 0)
        INTO V_TS_BGDSL, V_TS_CKEUSD, V_TS_CKERMB, V_TS_MTSCKE, V_TS_JSJE, V_TS_BGDSL_CQ, V_TS_CKEUSD_CQ
        FROM JCFX_DATA_TSSBMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=V_BGQ_Q AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1);

      --  V_TS_HHCB NUMBER(18,2)  退税_换汇成本（免退税）
      SET V_TS_HHCB = CASE WHEN V_TS_MTSCKE>0 AND V_TS_JSJE>0 THEN ROUND(100*V_TS_JSJE/V_TS_MTSCKE,2) ELSE NULL END;

      --  V_TS_TSE_SB NUMBER(18,2)  退税_退税额_申报
      --  V_TS_MDE_SB NUMBER(18,2)  退税_免抵额_申报
      --  CKTS_LC_SBXX.SBRQ为便捷退税申报日期，部分数据没有，改用流程启动时间
      SELECT IFNULL(SUM(T.SB_ZZSTSE+T.SB_XFSTSE), 0), IFNULL(SUM(T.SB_MDSE), 0)
        INTO V_TS_TSE_SB, V_TS_MDE_SB
        FROM CKTS_LC_SBXX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.QDSJ>=V_BGQ_Q AND T.QDSJ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND IFNULL(T.ZFBZ, 'N')='N';

      --  V_TS_TSE_HZ NUMBER(18,2)  退税_退税_核准
      --  V_TS_MDE_HZ NUMBER(18,2)  退税_免抵_核准
      SELECT IFNULL(SUM(S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE), 0), IFNULL(SUM(S.SEHZ_MDSE), 0)
        INTO V_TS_TSE_HZ, V_TS_MDE_HZ
        FROM CKTS_LC_SEHZXX S
       WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND S.SEHZRQ>=V_BGQ_Q AND S.SEHZRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1);

      --  V_TS_TSE_BL NUMBER(18,2)  退税_退税_办理
      SELECT IFNULL(SUM(S.SE), 0)
        INTO V_TS_TSE_BL
        FROM CKTS_ZS_SRTHS S
       WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND S.THRQ_1>=V_BGQ_Q AND S.THRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND S.TTSJLX_DM='01' AND S.TZLX_DM IN ('1','4');

      --  V_TS_MDE_BL NUMBER(18,2)  退税_免抵_办理
      SELECT IFNULL(SUM(S.JE), 0)
        INTO V_TS_MDE_BL
        FROM CKTS_ZS_TKGZ S
       WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND S.GKGZRQ>=V_BGQ_Q AND S.GKGZRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND S.TZSLY='3' AND S.TZLX_DM='1' AND S.GZBZ='Y';

      --  V_TS_CKERMB_STZC  NUMBER(18,2)  退税_视同自产出口额
      SELECT IFNULL(SUM(MYLAJ), 0)
        INTO V_TS_CKERMB_STZC
        FROM CKTS_SB_MDT_CKMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=V_BGQ_Q AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND T.CKTMSYWLXDMJH LIKE '%STZC%';

      --  V_TS_JHFP_JE  NUMBER(18,2)  退税_发票总金额
      --  V_TS_JHFP_FS  NUMBER(10)  退税_发票总份数
      --  V_TS_GHS_NUM  NUMBER(10)  退税_供货商个数
      SELECT COUNT(DISTINCT T.JHPZH), IFNULL(SUM(T.JSJE), 0), COUNT(DISTINCT T.GHFNSRSBH_1)
        INTO V_TS_JHFP_FS, V_TS_JHFP_JE, V_TS_GHS_NUM
        FROM CKTS_SB_MTS_JHMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=V_BGQ_Q AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND T.SZ='V' AND IFNULL(T.BYBLBZ, 'N')='N';

      --  V_TS_JHFP_FS_CQ1  NUMBER(10)  退税_超期1发票份数
      --  V_TS_JHFP_JE_CQ1  NUMBER(18,2)  退税_超期1发票金额
      SELECT COUNT(DISTINCT T.JHPZH), IFNULL(SUM(T.JSJE), 0)
        INTO V_TS_JHFP_FS_CQ1, V_TS_JHFP_JE_CQ1
        FROM CKTS_SB_MTS_JHMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=V_BGQ_Q AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND ORA_DATE_DIFF(T.KPRQ, T.CKRQ_1) >= 60
         AND T.SZ='V' AND IFNULL(T.BYBLBZ, 'N')='N';

      --  V_TS_JHFP_FS_CQ2  NUMBER(10)  退税_超期2发票份数
      --  V_TS_JHFP_JE_CQ2  NUMBER(18,2)  退税_超期2发票金额
      SELECT COUNT(DISTINCT T.JHPZH), IFNULL(SUM(T.JSJE), 0)
        INTO V_TS_JHFP_FS_CQ2, V_TS_JHFP_JE_CQ2
        FROM CKTS_SB_MTS_JHMX T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
         AND T.SBRQ>=V_BGQ_Q AND T.SBRQ<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
         AND ORA_DATE_DIFF(T.KPRQ, T.CKRQ_1) >= 90
         AND T.SZ='V' AND IFNULL(T.BYBLBZ, 'N')='N';

      UPDATE JKGL_DATA_TJ_ZBU
         SET TS_BGDSL=V_TS_BGDSL,
    TS_CKEUSD=V_TS_CKEUSD,
    TS_CKERMB=V_TS_CKERMB,
    TS_MTSCKE=V_TS_MTSCKE,
    TS_JSJE=V_TS_JSJE,
    TS_HHCB=V_TS_HHCB,
    TS_BGDSL_CQ=V_TS_BGDSL_CQ,
    TS_CKEUSD_CQ=V_TS_CKEUSD_CQ,
    TS_TSE_SB=V_TS_TSE_SB,
    TS_MDE_SB=V_TS_MDE_SB,
    TS_TSE_HZ=V_TS_TSE_HZ,
    TS_MDE_HZ=V_TS_MDE_HZ,
    TS_TSE_BL=V_TS_TSE_BL,
    TS_MDE_BL=V_TS_MDE_BL,
    TS_CKERMB_STZC=V_TS_CKERMB_STZC,
    TS_JHFP_JE=V_TS_JHFP_JE,
    TS_JHFP_FS=V_TS_JHFP_FS,
    TS_GHS_NUM=V_TS_GHS_NUM,
    TS_JHFP_FS_CQ1=V_TS_JHFP_FS_CQ1,
    TS_JHFP_JE_CQ1=V_TS_JHFP_JE_CQ1,
    TS_JHFP_FS_CQ2=V_TS_JHFP_FS_CQ2,
    TS_JHFP_JE_CQ2=V_TS_JHFP_JE_CQ2
       WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
      COMMIT;
    END;

    -- 解锁处理完成的报告期
    UPDATE JKGL_DATA_BGQ AS T
       SET TQBZ=NULL,
    WCSJ=CURRENT_TIMESTAMP,
    SXZT='3',
    ZBU_DZSPXX_ZT='Y',
    ZBU_DZSPJX_ZT='Y',
    ZBU_DZXF_ZT='Y',
    ZBU_DZGF_ZT='Y'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 后续需要通过ETL抽取的数据
    --  V_ZZS_，其中退税发票的顶格开具指标元，农产品指标元，在此处实现
    --  V_ZC_
    --  V_LR_
    --  V_DZ_


  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_ZBU_JD.sql

-- ======================================================================
-- [133/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_ZBU_ND.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_ZBU_ND$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_ZBU_ND()
/*
 * 年度指标元刷新算法
 * 202309，增加代理出口统计
 * 20260714，根据龙泉税局反馈，修正年度报表财务期初数据取数口径
 */
routine_body: BEGIN
  DECLARE V_CK_BGDSL        BIGINT; --  出口_报关单数量
  DECLARE V_CK_CKEUSD       DECIMAL(18,2); --  出口_出口额USD
  DECLARE V_CK_CKERMB       DECIMAL(18,2); --  出口_出口额
  DECLARE V_CK_SBDW_SL      BIGINT; --  出口_申报单位数量
  DECLARE V_CK_GB_SL        BIGINT; --  出口_目的国数量
  DECLARE V_CK_BGDSL_DE     BIGINT; --  出口_大额报关单数量
  DECLARE V_CK_CKEUSD_DE    DECIMAL(18,2); --  出口_大额报关单出口额USD
  DECLARE V_CK_BGDSL_ST     BIGINT; --  出口_四同报关单数量
  DECLARE V_CK_PXBGDSL      BIGINT; --  出口_拼箱报关单数量
  DECLARE V_CK_ZXBGDSL      DECIMAL(18,2); --  出口_整箱报关单数量
  DECLARE V_CK_PJDBHGZ      DECIMAL(18,2); --  出口_平均单笔货柜值
  DECLARE V_CK_CKEUSD_LASTYEAR	DECIMAL(18,2); --	出口_最近12个月出口额USD
  DECLARE V_TS_BGDSL        BIGINT; --  退税_报关单数量
  DECLARE V_TS_CKEUSD       DECIMAL(18,2); --  退税_出口额USD
  DECLARE V_TS_CKERMB       DECIMAL(18,2); --  退税_出口额RMB
  DECLARE V_TS_MTSCKE       DECIMAL(18,2); --  退税_出口额RMB（免退税）
  DECLARE V_TS_JSJE         DECIMAL(18,2); --  退税_计税金额（免退税）
  DECLARE V_TS_HHCB         DECIMAL(18,2); --  退税_换汇成本（免退税）
  DECLARE V_TS_BGDSL_CQ     BIGINT; --  退税_报关单数量_超期申报
  DECLARE V_TS_CKEUSD_CQ    DECIMAL(18,2); --  退税_出口额USD_超期申报
  DECLARE V_TS_TSE_SB       DECIMAL(18,2); --  退税_退税额_申报
  DECLARE V_TS_MDE_SB       DECIMAL(18,2); --  退税_免抵额_申报
  DECLARE V_TS_TSE_HZ       DECIMAL(18,2); --  退税_退税_核准
  DECLARE V_TS_MDE_HZ       DECIMAL(18,2); --  退税_免抵_核准
  DECLARE V_TS_TSE_BL       DECIMAL(18,2); --  退税_退税_办理
  DECLARE V_TS_MDE_BL       DECIMAL(18,2); --  退税_免抵_办理
  DECLARE V_TS_CKERMB_STZC  DECIMAL(18,2); --  退税_视同自产出口额
  DECLARE V_TS_JHFP_JE_DG   DECIMAL(18,2); --  退税_顶格开票金额
  DECLARE V_TS_JHFP_FS_DG   BIGINT; --  退税_顶格开票份数
  DECLARE V_TS_JHFP_JE      DECIMAL(18,2); --  退税_发票总金额
  DECLARE V_TS_JHFP_FS      BIGINT; --  退税_发票总份数
  DECLARE V_TS_JHFP_JE_CQ1  DECIMAL(18,2); --  退税_超期1发票金额
  DECLARE V_TS_JHFP_FS_CQ1  BIGINT; --  退税_超期1发票份数
  DECLARE V_TS_JHFP_JE_CQ2  DECIMAL(18,2); --  退税_超期2发票金额
  DECLARE V_TS_JHFP_FS_CQ2  BIGINT; --  退税_超期2发票份数
  DECLARE V_TS_GHS_NUM      BIGINT; --  退税_供货商个数
  DECLARE V_ZZS_XSE_QB      DECIMAL(18,2); --  增值税_全部销售
  DECLARE V_ZZS_XSE_MDT     DECIMAL(18,2); --  增值税_免抵退出口销售
  DECLARE V_ZZS_XSE_MS      DECIMAL(18,2); --  增值税_免税销售
  DECLARE V_ZZS_XXSE        DECIMAL(18,2); --  增值税_销项税额
  DECLARE V_ZZS_JXSE        DECIMAL(18,2); --  增值税_进项税额
  DECLARE V_ZZS_JXSEZC      DECIMAL(18,2); --  增值税_进项税额转出
  DECLARE V_ZZS_MDTBDDKJXSE DECIMAL(18,2); --  增值税_免抵退不得抵扣进项税额
  DECLARE V_ZZS_YNSE        DECIMAL(18,2); --  增值税_应纳税额
  DECLARE V_DZ_XXFS_QB      BIGINT; --  底账_销项份数_全部
  DECLARE V_DZ_XXJE_QB      DECIMAL(18,2); --  底账_销项金额_全部
  DECLARE V_DZ_XXSE_QB      DECIMAL(18,2); --  底账_销项税额_全部
  DECLARE V_DZ_XXFS_ZY      BIGINT; --  底账_销项份数_专票
  DECLARE V_DZ_XXJE_ZY      DECIMAL(18,2); --  底账_销项金额_专票
  DECLARE V_DZ_XXSE_ZY      DECIMAL(18,2); --  底账_销项税额_专票
  DECLARE V_DZ_XXFS_PT      BIGINT; --  底账_销项份数_普票
  DECLARE V_DZ_XXJE_PT      DECIMAL(18,2); --  底账_销项金额_普票
  DECLARE V_DZ_XXSE_PT      DECIMAL(18,2); --  底账_销项税额_普票
  DECLARE V_DZ_XXFS_CK      BIGINT; --  底账_销项份数_出口
  DECLARE V_DZ_XXJE_CK      DECIMAL(18,2); --  底账_销项金额_出口
  DECLARE V_DZ_JXFS_QB      BIGINT; --  底账_全部进项份数
  DECLARE V_DZ_JXJE_QB      DECIMAL(18,2); --  底账_全部进项金额
  DECLARE V_DZ_JXSE_QB      DECIMAL(18,2); --  底账_全部进项税额
  DECLARE V_DZ_JXFS_ZY      BIGINT; --  底账_进项份数_专票
  DECLARE V_DZ_JXJE_ZY      DECIMAL(18,2); --  底账_进项金额_专票
  DECLARE V_DZ_JXSE_ZY      DECIMAL(18,2); --  底账_进项税额_专票
  DECLARE V_DZ_JXFS_PT      BIGINT; --  底账_进项份数_普票
  DECLARE V_DZ_JXJE_PT      DECIMAL(18,2); --  底账_进项金额_普票
  DECLARE V_DZ_JXSE_PT      DECIMAL(18,2); --  底账_进项税额_普票
  DECLARE V_DZ_JXFS_DGKJ    BIGINT; --  底账_进项份数_专票顶格开具
  DECLARE V_DZ_JXJE_DGKJ    DECIMAL(18,2); --  底账_进项金额_专票顶格开具
  DECLARE V_DZ_JXSE_DGKJ    DECIMAL(18,2); --  底账_进项税额_专票顶格开具
  DECLARE V_DZ_JXSE_JKS     DECIMAL(18,2); --  底账_进项税额_缴款书
  DECLARE V_DZ_JXJE_NCP     DECIMAL(18,2); --  底账_进项金额_农产品
  DECLARE V_DZ_JXSE_NCP     DECIMAL(18,2); --  底账_进项税额_农产品
  DECLARE V_DZ_DFJE_SR      DECIMAL(18,2); --  底账_电费收入（销项）
  DECLARE V_DZ_DFJE_ZC      DECIMAL(18,2); --  底账_电费支出（进项）
  DECLARE V_DZ_WTJG         DECIMAL(18,2); --  底账_委托加工费支出
  DECLARE V_DZ_YFJE         DECIMAL(18,2); --  底账_运费支出
  DECLARE V_DZ_JXJE_SN      DECIMAL(18,2); --  底账_进项金额_省内
  DECLARE V_DZ_JXJE_SW      DECIMAL(18,2); --  底账_进项金额_省外
  DECLARE V_ZC_YSZK_QC      DECIMAL(18,2); --  资产_应收账款_期初
  DECLARE V_ZC_YSZK_QM      DECIMAL(18,2); --  资产_应收账款_期末
  DECLARE V_ZC_YFZK_QC      DECIMAL(18,2); --  资产_应付账款_期初
  DECLARE V_ZC_YFZK_QM      DECIMAL(18,2); --  资产_应付账款_期末
  DECLARE V_ZC_GDZC_QC      DECIMAL(18,2); --  资产_固定资产_期初
  DECLARE V_ZC_GDZC_QM      DECIMAL(18,2); --  资产_固定资产_期末
  DECLARE V_ZC_CH_QC        DECIMAL(18,2); --  资产_存货_期初
  DECLARE V_ZC_CH_QM        DECIMAL(18,2); --  资产_存货_期末
  DECLARE V_ZC_ZCZE_QC      DECIMAL(18,2); --  资产_资产总额_期初
  DECLARE V_ZC_ZCZE_QM      DECIMAL(18,2); --  资产_资产总额_期末
  DECLARE V_ZC_FZZE_QC      DECIMAL(18,2); --  资产_负债总额_期初
  DECLARE V_ZC_FZZE_QM      DECIMAL(18,2); --  资产_负债总额_期末
  DECLARE V_ZC_SYZQY_QC     DECIMAL(18,2); --  资产_所有者权益_期初
  DECLARE V_ZC_SYZQY_QM     DECIMAL(18,2); --  资产_所有者权益_期末
  DECLARE V_ZC_SSGDQY_QC    DECIMAL(18,2); --  资产_少数股东权益_期初
  DECLARE V_ZC_SSGDQY_QM    DECIMAL(18,2); --  资产_少数股东权益_期末
  DECLARE V_ZC_LDZC_QC      DECIMAL(18,2); --  资产_流动资产_期初
  DECLARE V_ZC_LDZC_QM      DECIMAL(18,2); --  资产_流动资产_期末
  DECLARE V_ZC_YUSZK_QC     DECIMAL(18,2); --  资产_预收账款_期初
  DECLARE V_ZC_YUSZK_QM     DECIMAL(18,2); --  资产_预收账款_期末
  DECLARE V_ZC_YUFZK_QC     DECIMAL(18,2); --  资产_预付账款_期初
  DECLARE V_ZC_YUFZK_QM     DECIMAL(18,2); --  资产_预付账款_期末
  DECLARE V_ZC_LDFZZE_QC    DECIMAL(18,2); --  资产_流动负债总额_期初
  DECLARE V_ZC_LDFZZE_QM    DECIMAL(18,2); --  资产_流动负债总额_期末

  DECLARE V_LR_YYSR         DECIMAL(18,2); --  利润_营业收入
  DECLARE V_LR_YYCB         DECIMAL(18,2); --  利润_营业成本
  DECLARE V_LR_XSFY         DECIMAL(18,2); --  利润_销售费用
  DECLARE V_LR_GLFY         DECIMAL(18,2); --  利润_管理费用
  DECLARE V_LR_LXZC         DECIMAL(18,2); --  利润_利息支出
  DECLARE V_LR_YYLR         DECIMAL(18,2); --  利润_营业利润
  DECLARE V_LR_LRZE         DECIMAL(18,2); --  利润_利润总额
  DECLARE V_LR_QTSR         DECIMAL(18,2); --  利润_其它收入
  DECLARE V_LR_SJJFJ        DECIMAL(18,2); --  利润_税金及附加
  DECLARE V_LR_CWFY         DECIMAL(18,2); --  利润_财务费用
  DECLARE V_LR_JLR          DECIMAL(18,2); --  利润_净利润
  DECLARE V_LR_SDS          DECIMAL(18,2); --  利润_所得税

  DECLARE V_ROWS            BIGINT;  -- 待更新表中是否存在目标记录
  DECLARE V_JDNUM           BIGINT;  -- 年度内季度报告期数量
  DECLARE V_BGQ_Z           DATETIME;
  DECLARE V_NDJQID          DECIMAL(20,0);  -- 年度基期ID

  BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGQ_BGQID_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_ZQLX_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Q_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Z_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_YF_Q_001 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_YF_Z_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.BGQID, T.ZQLX, T.DJXH,
                         T.BGQ_Q, T.BGQ_Z, DATE_FORMAT(T.BGQ_Q, '%Y%m') AS YF_Q, DATE_FORMAT(T.BGQ_Z, '%Y%m') AS YF_Z
                    FROM JKGL_DATA_BGQ T
                   WHERE T.ZQLX='年' AND T.SXZT='0' AND T.TQBZ IS NULL
                     AND NOT EXISTS (SELECT 1
                                       FROM JKGL_DATA_BGQ T1
                                      WHERE T1.DJXH=T.DJXH AND T1.BGQ_Q>=T.BGQ_Q AND T1.BGQ_Z<=T.BGQ_Z
                                        AND T1.ZQLX='季'
                                        AND (T1.SXZT<>'3' OR T1.ZZS_ZT='N' OR T1.DZDZ_ZT='N' OR T1.DZSP_ZT='N'));
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_BGQ_BGQID_001, BJTS_CUR_BGQ_ZQLX_001, BJTS_CUR_BGQ_DJXH_001, BJTS_CUR_BGQ_BGQ_Q_001, BJTS_CUR_BGQ_BGQ_Z_001, BJTS_CUR_BGQ_YF_Q_001, BJTS_CUR_BGQ_YF_Z_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    -- 检查该企业该年度内季度报告期数量
    SELECT COUNT(1), MAX(T1.BGQ_Z)
      INTO V_JDNUM, V_BGQ_Z
      FROM JKGL_DATA_BGQ T1
     WHERE T1.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T1.BGQ_Q>=BJTS_CUR_BGQ_BGQ_Q_001 AND T1.BGQ_Z<=BJTS_CUR_BGQ_BGQ_Z_001
       AND T1.ZQLX='季'
       AND T1.SXZT='3' AND T1.ZZS_ZT='Y' AND T1.DZDZ_ZT='Y' AND T1.DZSP_ZT='Y';
    IF V_JDNUM=0 THEN
      ITERATE BJTS_CURSOR_LOOP_001;
    ELSEIF V_JDNUM>4 THEN
      ITERATE BJTS_CURSOR_LOOP_001;
    END IF;

    -- 锁定正在处理的报告期
    UPDATE JKGL_DATA_BGQ AS T
       SET TQBZ=REPLACE(UUID(), '-', ''),
    TQSJ=CURRENT_TIMESTAMP,
    SXZT='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU.BGQID
    SELECT LEAST(COUNT(1), 1)
      INTO V_ROWS
      FROM JKGL_DATA_TJ_ZBU T
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001 AND 1=1;
    IF V_ROWS=0 THEN
      INSERT INTO JKGL_DATA_TJ_ZBU(BGQID) VALUES (BJTS_CUR_BGQ_BGQID_001);
      COMMIT;
    END IF;

    SELECT SUM(T2.CK_BGDSL), SUM(T2.CK_CKEUSD), SUM(T2.CK_CKERMB),
           SUM(T2.CK_BGDSL_DE), SUM(T2.CK_CKEUSD_DE), SUM(T2.CK_BGDSL_ST),
           SUM(T2.CK_PXBGDSL), SUM(T2.CK_ZXBGDSL),
           CASE WHEN SUM(T2.CK_ZXBGDSL)=0 THEN 0 ELSE SUM(T2.CK_PJDBHGZ * T2.CK_ZXBGDSL) / SUM(T2.CK_ZXBGDSL) END,
           SUM(T2.TS_BGDSL), SUM(T2.TS_CKEUSD), SUM(T2.TS_CKERMB), SUM(T2.TS_MTSCKE), SUM(T2.TS_JSJE),
           SUM(T2.TS_BGDSL_CQ), SUM(T2.TS_CKEUSD_CQ),
           SUM(T2.TS_TSE_SB), SUM(T2.TS_MDE_SB),
           SUM(T2.TS_TSE_HZ), SUM(T2.TS_MDE_HZ),
           SUM(T2.TS_TSE_BL), SUM(T2.TS_MDE_BL),
           SUM(T2.TS_CKERMB_STZC),
           SUM(T2.TS_JHFP_FS), SUM(T2.TS_JHFP_JE),
           SUM(T2.TS_JHFP_FS_CQ1), SUM(T2.TS_JHFP_JE_CQ1),
           SUM(T2.TS_JHFP_FS_CQ2), SUM(T2.TS_JHFP_JE_CQ2),
           SUM(T2.TS_JHFP_FS_DG), SUM(T2.TS_JHFP_JE_DG),
           SUM(T2.ZZS_XSE_QB), SUM(T2.ZZS_XSE_MDT), SUM(T2.ZZS_XSE_MS),
           SUM(T2.ZZS_XXSE), SUM(T2.ZZS_JXSE), SUM(T2.ZZS_JXSEZC), SUM(T2.ZZS_MDTBDDKJXSE), SUM(T2.ZZS_YNSE),
           SUM(T2.DZ_XXFS_ZY), SUM(T2.DZ_XXJE_ZY), SUM(T2.DZ_XXSE_ZY),
           SUM(T2.DZ_XXFS_PT), SUM(T2.DZ_XXJE_PT), SUM(T2.DZ_XXSE_PT),
           SUM(T2.DZ_XXFS_QB), SUM(T2.DZ_XXJE_QB), SUM(T2.DZ_XXSE_QB),
           SUM(T2.DZ_XXFS_CK), SUM(T2.DZ_XXJE_CK),
           SUM(T2.DZ_JXFS_ZY), SUM(T2.DZ_JXJE_ZY), SUM(T2.DZ_JXSE_ZY),
           SUM(T2.DZ_JXFS_PT), SUM(T2.DZ_JXJE_PT), SUM(T2.DZ_JXSE_PT),
           SUM(T2.DZ_JXFS_QB), SUM(T2.DZ_JXJE_QB), SUM(T2.DZ_JXSE_QB),
           SUM(T2.DZ_JXFS_DGKJ), SUM(T2.DZ_JXJE_DGKJ), SUM(T2.DZ_JXSE_DGKJ),
           SUM(T2.DZ_JXSE_JKS), SUM(T2.DZ_JXJE_NCP), SUM(T2.DZ_JXSE_NCP),
           SUM(T2.DZ_DFJE_SR), SUM(T2.DZ_DFJE_ZC), SUM(T2.DZ_WTJG), SUM(T2.DZ_YFJE),
           SUM(T2.DZ_JXJE_SN), SUM(T2.DZ_JXJE_SW),
           SUM(T2.LR_YYSR), SUM(T2.LR_YYCB), SUM(T2.LR_XSFY), SUM(T2.LR_GLFY), SUM(T2.LR_LRZE), SUM(T2.LR_YYLR),
           SUM(T2.LR_QTSR), SUM(T2.LR_SJJFJ), SUM(T2.LR_CWFY), SUM(T2.LR_JLR), SUM(T2.LR_SDS), SUM(T2.LR_LXZC)
      INTO V_CK_BGDSL, V_CK_CKEUSD, V_CK_CKERMB,
           V_CK_BGDSL_DE, V_CK_CKEUSD_DE, V_CK_BGDSL_ST,
           V_CK_PXBGDSL, V_CK_ZXBGDSL,
           V_CK_PJDBHGZ,
           V_TS_BGDSL, V_TS_CKEUSD, V_TS_CKERMB, V_TS_MTSCKE, V_TS_JSJE,
           V_TS_BGDSL_CQ, V_TS_CKEUSD_CQ,
           V_TS_TSE_SB, V_TS_MDE_SB,
           V_TS_TSE_HZ, V_TS_MDE_HZ,
           V_TS_TSE_BL, V_TS_MDE_BL,
           V_TS_CKERMB_STZC,
           V_TS_JHFP_FS, V_TS_JHFP_JE,
           V_TS_JHFP_FS_CQ1, V_TS_JHFP_JE_CQ1,
           V_TS_JHFP_FS_CQ2, V_TS_JHFP_JE_CQ2,
           V_TS_JHFP_FS_DG, V_TS_JHFP_JE_DG,
           V_ZZS_XSE_QB, V_ZZS_XSE_MDT, V_ZZS_XSE_MS,
           V_ZZS_XXSE, V_ZZS_JXSE, V_ZZS_JXSEZC, V_ZZS_MDTBDDKJXSE, V_ZZS_YNSE,
           V_DZ_XXFS_ZY, V_DZ_XXJE_ZY, V_DZ_XXSE_ZY,
           V_DZ_XXFS_PT, V_DZ_XXJE_PT, V_DZ_XXSE_PT,
           V_DZ_XXFS_QB, V_DZ_XXJE_QB, V_DZ_XXSE_QB,
           V_DZ_XXFS_CK, V_DZ_XXJE_CK,
           V_DZ_JXFS_ZY, V_DZ_JXJE_ZY, V_DZ_JXSE_ZY,
           V_DZ_JXFS_PT, V_DZ_JXJE_PT, V_DZ_JXSE_PT,
           V_DZ_JXFS_QB, V_DZ_JXJE_QB, V_DZ_JXSE_QB,
           V_DZ_JXFS_DGKJ, V_DZ_JXJE_DGKJ, V_DZ_JXSE_DGKJ,
           V_DZ_JXSE_JKS, V_DZ_JXJE_NCP, V_DZ_JXSE_NCP,
           V_DZ_DFJE_SR, V_DZ_DFJE_ZC, V_DZ_WTJG, V_DZ_YFJE,
           V_DZ_JXJE_SN, V_DZ_JXJE_SW,
           V_LR_YYSR, V_LR_YYCB, V_LR_XSFY, V_LR_GLFY, V_LR_LRZE, V_LR_YYLR,
           V_LR_QTSR, V_LR_SJJFJ, V_LR_CWFY, V_LR_JLR, V_LR_SDS, V_LR_LXZC
      FROM JKGL_DATA_BGQ T1
     INNER JOIN JKGL_DATA_TJ_ZBU T2 ON T2.BGQID=T1.BGQID
     WHERE T1.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T1.BGQ_Q>=BJTS_CUR_BGQ_BGQ_Q_001 AND T1.BGQ_Z<=V_BGQ_Z
       AND T1.ZQLX='季';

    SELECT COUNT(DISTINCT SBDWDM), COUNT(DISTINCT MYGDQSZ_DM)
      INTO V_CK_SBDW_SL, V_CK_GB_SL
      FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM
              FROM CKTS_WBSJ_HG_BGD T
             WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
               AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
               AND T.JGFS_DM<>'1039'
             UNION ALL
            SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM
              FROM CKTS_WBSJ_ZJ_DLCKHWZM S
             WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
               AND S.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
               AND S.JGFS_DM<>'1039'
           ) TT;

    SELECT CK_CKEUSD_LASTYEAR,
           ZC_YSZK_QM, ZC_YFZK_QM, ZC_GDZC_QM, ZC_CH_QM, ZC_ZCZE_QM, ZC_FZZE_QM,
           ZC_SYZQY_QM, ZC_SSGDQY_QM, ZC_LDZC_QM, ZC_YUSZK_QM, ZC_YUFZK_QM, ZC_LDFZZE_QM
      INTO V_CK_CKEUSD_LASTYEAR,
           V_ZC_YSZK_QM, V_ZC_YFZK_QM, V_ZC_GDZC_QM, V_ZC_CH_QM, V_ZC_ZCZE_QM, V_ZC_FZZE_QM,
           V_ZC_SYZQY_QM, V_ZC_SSGDQY_QM, V_ZC_LDZC_QM, V_ZC_YUSZK_QM, V_ZC_YUFZK_QM, V_ZC_LDFZZE_QM
      FROM (SELECT T2.*, T1.BGQ_Z
              FROM JKGL_DATA_BGQ T1
             INNER JOIN JKGL_DATA_TJ_ZBU T2 ON T2.BGQID=T1.BGQID
             WHERE T1.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T1.BGQ_Q>=BJTS_CUR_BGQ_BGQ_Q_001 AND T1.BGQ_Z<=V_BGQ_Z
               AND T1.ZQLX='季'
             ORDER BY T1.BGQ_Z DESC) AS BJTS_DERIVED_001
     WHERE 1=1
LIMIT 1;

    SELECT ZC_YSZK_QC, ZC_YFZK_QC, ZC_GDZC_QC, ZC_CH_QC, ZC_ZCZE_QC, ZC_FZZE_QC,
           ZC_SYZQY_QC, ZC_SSGDQY_QC, ZC_LDZC_QC, ZC_YUSZK_QC, ZC_YUFZK_QC, ZC_LDFZZE_QC
      INTO V_ZC_YSZK_QC, V_ZC_YFZK_QC, V_ZC_GDZC_QC, V_ZC_CH_QC, V_ZC_ZCZE_QC, V_ZC_FZZE_QC,
           V_ZC_SYZQY_QC, V_ZC_SSGDQY_QC, V_ZC_LDZC_QC, V_ZC_YUSZK_QC, V_ZC_YUFZK_QC, V_ZC_LDFZZE_QC
      FROM (SELECT T2.*, T1.BGQ_Z
              FROM JKGL_DATA_BGQ T1
             INNER JOIN JKGL_DATA_TJ_ZBU T2 ON T2.BGQID=T1.BGQID
             WHERE T1.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T1.BGQ_Q>=BJTS_CUR_BGQ_BGQ_Q_001 AND T1.BGQ_Z<=V_BGQ_Z
               AND T1.ZQLX='季'
             ORDER BY T1.BGQ_Z ASC) AS BJTS_DERIVED_002
     WHERE 1=1
LIMIT 1;

    SET V_TS_HHCB = CASE WHEN V_TS_MTSCKE>0 AND V_TS_JSJE>0 THEN ROUND(100*V_TS_JSJE/V_TS_MTSCKE,2) ELSE NULL END;

    SELECT COUNT(DISTINCT T.GHFNSRSBH_1)
      INTO V_TS_GHS_NUM
      FROM CKTS_SB_MTS_JHMX T
     WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
       AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
       AND T.SZ='V' AND IFNULL(T.BYBLBZ, 'N')='N';

    UPDATE JKGL_DATA_TJ_ZBU
       SET CK_BGDSL=V_CK_BGDSL,
    CK_CKEUSD=V_CK_CKEUSD,
    CK_CKERMB=V_CK_CKERMB,
    CK_BGDSL_DE=V_CK_BGDSL_DE,
    CK_CKEUSD_DE=V_CK_CKEUSD_DE,
    CK_BGDSL_ST=V_CK_BGDSL_ST,
    CK_PXBGDSL=V_CK_PXBGDSL,
    CK_ZXBGDSL=V_CK_ZXBGDSL,
    CK_PJDBHGZ=V_CK_PJDBHGZ,
    CK_SBDW_SL=V_CK_SBDW_SL,
    CK_GB_SL=V_CK_GB_SL,
    CK_CKEUSD_LASTYEAR=V_CK_CKEUSD_LASTYEAR,
    TS_BGDSL=V_TS_BGDSL,
    TS_CKEUSD=V_TS_CKEUSD,
    TS_CKERMB=V_TS_CKERMB,
    TS_MTSCKE=V_TS_MTSCKE,
    TS_JSJE=V_TS_JSJE,
    TS_HHCB=V_TS_HHCB,
    TS_BGDSL_CQ=V_TS_BGDSL_CQ,
    TS_CKEUSD_CQ=V_TS_CKEUSD_CQ,
    TS_TSE_SB=V_TS_TSE_SB,
    TS_MDE_SB=V_TS_MDE_SB,
    TS_TSE_HZ=V_TS_TSE_HZ,
    TS_MDE_HZ=V_TS_MDE_HZ,
    TS_TSE_BL=V_TS_TSE_BL,
    TS_MDE_BL=V_TS_MDE_BL,
    TS_CKERMB_STZC=V_TS_CKERMB_STZC,
    TS_JHFP_JE_DG=V_TS_JHFP_JE_DG,
    TS_JHFP_FS_DG=V_TS_JHFP_FS_DG,
    TS_JHFP_JE=V_TS_JHFP_JE,
    TS_JHFP_FS=V_TS_JHFP_FS,
    TS_GHS_NUM=V_TS_GHS_NUM,
    TS_JHFP_FS_CQ1=V_TS_JHFP_FS_CQ1,
    TS_JHFP_JE_CQ1=V_TS_JHFP_JE_CQ1,
    TS_JHFP_FS_CQ2=V_TS_JHFP_FS_CQ2,
    TS_JHFP_JE_CQ2=V_TS_JHFP_JE_CQ2,
    ZZS_XSE_QB=V_ZZS_XSE_QB,
    ZZS_XSE_MDT=V_ZZS_XSE_MDT,
    ZZS_XSE_MS=V_ZZS_XSE_MS,
    ZZS_XXSE=V_ZZS_XXSE,
    ZZS_JXSE=V_ZZS_JXSE,
    ZZS_JXSEZC=V_ZZS_JXSEZC,
    ZZS_YNSE=V_ZZS_YNSE,
    ZZS_MDTBDDKJXSE=V_ZZS_MDTBDDKJXSE,
    DZ_XXFS_ZY=V_DZ_XXFS_ZY,
    DZ_XXJE_ZY=V_DZ_XXJE_ZY,
    DZ_XXSE_ZY=V_DZ_XXSE_ZY,
    DZ_XXFS_PT=V_DZ_XXFS_PT,
    DZ_XXJE_PT=V_DZ_XXJE_PT,
    DZ_XXSE_PT=V_DZ_XXSE_PT,
    DZ_XXFS_QB=V_DZ_XXFS_QB,
    DZ_XXJE_QB=V_DZ_XXJE_QB,
    DZ_XXSE_QB=V_DZ_XXSE_QB,
    DZ_XXFS_CK=V_DZ_XXFS_CK,
    DZ_XXJE_CK=V_DZ_XXJE_CK,
    DZ_JXFS_ZY=V_DZ_JXFS_ZY,
    DZ_JXJE_ZY=V_DZ_JXJE_ZY,
    DZ_JXSE_ZY=V_DZ_JXSE_ZY,
    DZ_JXFS_PT=V_DZ_JXFS_PT,
    DZ_JXJE_PT=V_DZ_JXJE_PT,
    DZ_JXSE_PT=V_DZ_JXSE_PT,
    DZ_JXFS_QB=V_DZ_JXFS_QB,
    DZ_JXJE_QB=V_DZ_JXJE_QB,
    DZ_JXSE_QB=V_DZ_JXSE_QB,
    DZ_JXFS_DGKJ=V_DZ_JXFS_DGKJ,
    DZ_JXJE_DGKJ=V_DZ_JXJE_DGKJ,
    DZ_JXSE_DGKJ=V_DZ_JXSE_DGKJ,
    DZ_JXSE_JKS=V_DZ_JXSE_JKS,
    DZ_JXJE_NCP=V_DZ_JXJE_NCP,
    DZ_JXSE_NCP=V_DZ_JXSE_NCP,
    DZ_DFJE_SR=V_DZ_DFJE_SR,
    DZ_DFJE_ZC=V_DZ_DFJE_ZC,
    DZ_WTJG=V_DZ_WTJG,
    DZ_YFJE=V_DZ_YFJE,
    DZ_JXJE_SN=V_DZ_JXJE_SN,
    DZ_JXJE_SW=V_DZ_JXJE_SW,
    ZC_YSZK_QC=V_ZC_YSZK_QC,
    ZC_YFZK_QC=V_ZC_YFZK_QC,
    ZC_GDZC_QC=V_ZC_GDZC_QC,
    ZC_CH_QC=V_ZC_CH_QC,
    ZC_ZCZE_QC=V_ZC_ZCZE_QC,
    ZC_FZZE_QC=V_ZC_FZZE_QC,
    ZC_SYZQY_QC=V_ZC_SYZQY_QC,
    ZC_SSGDQY_QC=V_ZC_SSGDQY_QC,
    ZC_LDZC_QC=V_ZC_LDZC_QC,
    ZC_YUSZK_QC=V_ZC_YUSZK_QC,
    ZC_YUFZK_QC=V_ZC_YUFZK_QC,
    ZC_LDFZZE_QC=V_ZC_LDFZZE_QC,
    ZC_YSZK_QM=V_ZC_YSZK_QM,
    ZC_YFZK_QM=V_ZC_YFZK_QM,
    ZC_GDZC_QM=V_ZC_GDZC_QM,
    ZC_CH_QM=V_ZC_CH_QM,
    ZC_ZCZE_QM=V_ZC_ZCZE_QM,
    ZC_FZZE_QM=V_ZC_FZZE_QM,
    ZC_SYZQY_QM=V_ZC_SYZQY_QM,
    ZC_SSGDQY_QM=V_ZC_SSGDQY_QM,
    ZC_LDZC_QM=V_ZC_LDZC_QM,
    ZC_YUSZK_QM=V_ZC_YUSZK_QM,
    ZC_YUFZK_QM=V_ZC_YUFZK_QM,
    ZC_LDFZZE_QM=V_ZC_LDFZZE_QM,
    LR_YYSR=V_LR_YYSR,
    LR_YYCB=V_LR_YYCB,
    LR_XSFY=V_LR_XSFY,
    LR_GLFY=V_LR_GLFY,
    LR_LRZE=V_LR_LRZE,
    LR_YYLR=V_LR_YYLR,
    LR_QTSR=V_LR_QTSR,
    LR_SJJFJ=V_LR_SJJFJ,
    LR_CWFY=V_LR_CWFY,
    LR_JLR=V_LR_JLR,
    LR_SDS=V_LR_SDS,
    LR_LXZC=V_LR_LXZC
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 年度基期ID
    BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
        SET V_NDJQID =0;

  END;
SELECT T.BGQID
        INTO V_NDJQID
        FROM JKGL_DATA_BGQ T
       WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001 AND T.BGQ_Q=DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, INTERVAL -12 MONTH) AND T.BGQ_Z=ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Q_001, -(1))
         AND T.SXZT='2';
    END;

    -- 计算 JKGL_DATA_TJ_ZBU_KZ.BGQID
    SELECT LEAST(COUNT(1), 1)
      INTO V_ROWS
      FROM JKGL_DATA_TJ_ZBU_KZ T
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001 AND 1=1;
    IF V_ROWS=0 THEN
      INSERT INTO JKGL_DATA_TJ_ZBU_KZ(BGQID) VALUES (BJTS_CUR_BGQ_BGQID_001);
      COMMIT;
    END IF;

    UPDATE JKGL_DATA_TJ_ZBU_KZ AS T
       SET CW_MLL = (SELECT -- 毛利率=100%*（主营业务收入-主营业务成本）/主营业务收入
           CASE WHEN (LR_YYSR IS NOT NULL) AND (LR_YYSR<>0)
                THEN LEAST(GREATEST(ROUND(100*(LR_YYSR-LR_YYCB)/LR_YYSR,2),-900),100)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_HYSFL = (SELECT -- 行业税负率=100%*（0.13*（增值税全部销售额+期末存货-期初存货）-进项税额+进项税额转出）/增值税全部销售额
           CASE WHEN (ZZS_XSE_QB IS NOT NULL) AND (ZZS_XSE_QB<>0)
                THEN LEAST(GREATEST(ROUND(100*(0.13*(ZZS_XSE_QB+ZC_CH_QM-ZC_CH_QC)-ZZS_JXSE+ZZS_JXSEZC)/ZZS_XSE_QB,2),-100),100)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_YYLRL = (SELECT -- 营业利润率=100%*营业利润/全部收入=100%*营业利润/（主营业务收入+其它收入）
           CASE WHEN (LR_YYSR IS NOT NULL) AND (LR_QTSR IS NOT NULL) AND (LR_YYSR+LR_QTSR<>0)
                THEN LEAST(GREATEST(ROUND(100*LR_YYLR/(LR_YYSR+LR_QTSR),2),-900),100)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_CBFYLRL = (SELECT -- 成本费用利润率=100%*利润总额/成本费用总额=100%*利润总额/（主营业务成本+税金及附加+销售费用+管理费用+财务费用）
           CASE WHEN (LR_YYCB IS NOT NULL) AND (LR_SJJFJ IS NOT NULL) AND (LR_XSFY IS NOT NULL) AND (LR_GLFY IS NOT NULL)
                     AND (LR_CWFY IS NOT NULL) AND (LR_YYCB+LR_SJJFJ+LR_XSFY+LR_GLFY+LR_CWFY<>0)
                THEN LEAST(GREATEST(ROUND(100*LR_LRZE/(LR_YYCB+LR_SJJFJ+LR_XSFY+LR_GLFY+LR_CWFY),2),-1100),100)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_ZZCBCL = (SELECT -- 总资产报酬率=100%*息税前利润/资产平均总额=200%*（净利润+所得税+利息支出）/（年初资产总额+年末资产总额）
           CASE WHEN (ZC_ZCZE_QC IS NOT NULL) AND (ZC_ZCZE_QM IS NOT NULL) AND (ZC_ZCZE_QC+ZC_ZCZE_QM<>0)
                THEN LEAST(GREATEST(ROUND(200*(LR_JLR+LR_SDS+LR_LXZC)/(ZC_ZCZE_QC+ZC_ZCZE_QM),2),-100),1000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_JZCSYL = (SELECT -- 净资产收益率=100%*净利润/净资产=100%*净利润/（所有者权益+少数股东权益）
           CASE WHEN (ZC_SYZQY_QM IS NOT NULL) AND (ZC_SSGDQY_QM IS NOT NULL) AND (ZC_SYZQY_QM+ZC_SSGDQY_QM<>0)
                THEN LEAST(GREATEST(ROUND(100*LR_JLR/(ZC_SYZQY_QM+ZC_SSGDQY_QM),2),-100),1000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_ZZCZZL = (SELECT -- 总资产增长率=100%*（年末资产总额-年初资产总额）/年初资产总额
           CASE WHEN (ZC_ZCZE_QC IS NOT NULL) AND (ZC_ZCZE_QC<>0)
                THEN LEAST(GREATEST(ROUND(100*(ZC_ZCZE_QM-ZC_ZCZE_QC)/ZC_ZCZE_QC,2),-100),1000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_LDBL = (SELECT -- 流动比率=100%*流动资产总额/流动负债总额
           CASE WHEN (ZC_LDFZZE_QM IS NOT NULL) AND (ZC_LDFZZE_QM<>0)
                THEN LEAST(GREATEST(ROUND(100*ZC_LDZC_QM/ZC_LDFZZE_QM,2),10),1000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_SDBL = (SELECT -- 速动比率=100%*速动资产总额/流动负债总额=100%*（流动资产-预付账款-存货）/流动负债总额
           CASE WHEN (ZC_LDFZZE_QM IS NOT NULL) AND (ZC_LDFZZE_QM<>0)
                THEN LEAST(GREATEST(ROUND(100*(ZC_LDZC_QM-ZC_YUFZK_QM-ZC_CH_QM)/ZC_LDFZZE_QM,2),10),1000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_ZCFZL = (SELECT -- 资产负债率=100%*负债总额/资产总额
           CASE WHEN (ZC_ZCZE_QM IS NOT NULL) AND (ZC_ZCZE_QM<>0)
                THEN LEAST(GREATEST(ROUND(100*ZC_FZZE_QM/ZC_ZCZE_QM,2),10),1000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_CHZZL = (SELECT -- 存货周转率=营业成本/平均存货=2*营业成本/(期末存货+期初存货)
           CASE WHEN (ZC_CH_QC IS NOT NULL) AND (ZC_CH_QM IS NOT NULL) AND (ZC_CH_QC+ZC_CH_QM<>0)
                THEN LEAST(GREATEST(ROUND(2*LR_YYCB/(ZC_CH_QC+ZC_CH_QM),2),0),360)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001),
    CW_YSZKZZL = (SELECT -- 应收账款周转率=2*当期销售净收入/（期初应收账款+期末应收账款
           CASE WHEN (ZC_YSZK_QC IS NOT NULL) AND (ZC_YSZK_QM IS NOT NULL) AND (ZC_YSZK_QC+ZC_YSZK_QM<>0)
                THEN LEAST(GREATEST(ROUND(200*LR_YYSR/(ZC_YSZK_QC+ZC_YSZK_QM),2),0),360)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001)
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;

    UPDATE JKGL_DATA_TJ_ZBU_KZ AS T
       SET CW_YYSRTBZZL = (SELECT -- 营业收入同比增长率=100%*（当期营业收入-上期营业收入）/上期营业收入
           CASE WHEN (B.LR_YYSR IS NOT NULL) AND (B.LR_YYSR<>0)
                THEN LEAST(GREATEST(ROUND(100*(A.LR_YYSR-B.LR_YYSR)/B.LR_YYSR,2),-6000),6000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU A, JKGL_DATA_TJ_ZBU B
     WHERE A.BGQID=BJTS_CUR_BGQ_BGQID_001 AND B.BGQID=V_NDJQID),
    CW_JLRTBZZL = (SELECT -- 净利润同比增长率=100%*（当期净利润-上期净利润）/上期净利润
           CASE WHEN (B.LR_JLR IS NOT NULL) AND (B.LR_JLR<>0)
                THEN LEAST(GREATEST(ROUND(100*(A.LR_JLR-B.LR_JLR)/B.LR_JLR,2),-6000),6000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU A, JKGL_DATA_TJ_ZBU B
     WHERE A.BGQID=BJTS_CUR_BGQ_BGQID_001 AND B.BGQID=V_NDJQID),
    CK_CKUSD_TB = (SELECT -- 美元出口额同比=100%*当期出口额USD/上期出口额USD
           CASE WHEN (B.CK_CKEUSD IS NOT NULL) AND (B.CK_CKEUSD>0)
                THEN LEAST(GREATEST(ROUND(100*A.CK_CKEUSD/B.CK_CKEUSD,2),0),6000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU A, JKGL_DATA_TJ_ZBU B
     WHERE A.BGQID=BJTS_CUR_BGQ_BGQID_001 AND B.BGQID=V_NDJQID),
    TS_TMSE_TB = (SELECT -- 申报退免税额同比=100%*当期申报退免税额/上期申报退免税额
           CASE WHEN (B.TS_MDE_SB IS NOT NULL) AND (B.TS_TSE_SB IS NOT NULL) AND (B.TS_MDE_SB+B.TS_TSE_SB>0)
                THEN LEAST(GREATEST(ROUND(100*(A.TS_MDE_SB+A.TS_TSE_SB)/(B.TS_MDE_SB+B.TS_TSE_SB),2),0),6000)
                ELSE NULL
           END
FROM JKGL_DATA_TJ_ZBU A, JKGL_DATA_TJ_ZBU B
     WHERE A.BGQID=BJTS_CUR_BGQ_BGQID_001 AND B.BGQID=V_NDJQID)
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;

    -- 计算 JKGL_DATA_TJ_ZBU_CKGB.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_CKGB AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, MYGDQSZ_DM AS GB_DM, SUM(MYLAJ) AS CKEUSD, SUM(RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT SUBSTR(HGGQKA_DM,1,2)) AS KASL, COUNT(DISTINCT SBDWDM) AS SBDWSL, COUNT(DISTINCT YSFS_DM) AS YSFSSL
                  FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM,T.HGGQKA_DM,T.YSFS_DM,T.CKSP_DM,T.CKSL
                          FROM CKTS_WBSJ_HG_BGD T
                         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND T.JGFS_DM<>'1039'
                         UNION ALL
                        SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM,S.HGGQKA_DM,S.YSFS_DM,S.CKSP_DM,S.CKSL
                          FROM CKTS_WBSJ_ZJ_DLCKHWZM S
                         WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND S.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND S.JGFS_DM<>'1039'
                       ) TT
                 GROUP BY MYGDQSZ_DM
) AS B
ON A.BGQID=B.BGQID AND A.GB_DM=B.GB_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, KASL = B.KASL, SBDWSL = B.SBDWSL, YSFSSL = B.YSFSSL;
INSERT INTO JKGL_DATA_TJ_ZBU_CKGB (ID,BGQID,GB_DM,CKEUSD,CKERMB,KASL,SBDWSL,YSFSSL)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_CKGB'),B.BGQID,B.GB_DM,B.CKEUSD,B.CKERMB,B.KASL,B.SBDWSL,B.YSFSSL
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, MYGDQSZ_DM AS GB_DM, SUM(MYLAJ) AS CKEUSD, SUM(RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT SUBSTR(HGGQKA_DM,1,2)) AS KASL, COUNT(DISTINCT SBDWDM) AS SBDWSL, COUNT(DISTINCT YSFS_DM) AS YSFSSL
                  FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM,T.HGGQKA_DM,T.YSFS_DM,T.CKSP_DM,T.CKSL
                          FROM CKTS_WBSJ_HG_BGD T
                         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND T.JGFS_DM<>'1039'
                         UNION ALL
                        SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM,S.HGGQKA_DM,S.YSFS_DM,S.CKSP_DM,S.CKSL
                          FROM CKTS_WBSJ_ZJ_DLCKHWZM S
                         WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND S.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND S.JGFS_DM<>'1039'
                       ) TT
                 GROUP BY MYGDQSZ_DM
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_CKGB AS A WHERE A.BGQID=B.BGQID AND A.GB_DM=B.GB_DM
);
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_CKKA.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_CKKA AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, HGGQKA_DM AS KA_DM, SUM(MYLAJ) AS CKEUSD, SUM(RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT SBDWDM) AS SBDWSL
                  FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM,T.HGGQKA_DM,T.YSFS_DM,T.CKSP_DM,T.CKSL
                          FROM CKTS_WBSJ_HG_BGD T
                         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND T.JGFS_DM<>'1039'
                         UNION ALL
                        SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM,S.HGGQKA_DM,S.YSFS_DM,S.CKSP_DM,S.CKSL
                          FROM CKTS_WBSJ_ZJ_DLCKHWZM S
                         WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND S.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND S.JGFS_DM<>'1039'
                       ) TT
                 GROUP BY HGGQKA_DM
) AS B
ON A.BGQID=B.BGQID AND A.KA_DM=B.KA_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, SBDWSL = B.SBDWSL;
INSERT INTO JKGL_DATA_TJ_ZBU_CKKA (ID,BGQID,KA_DM,CKEUSD,CKERMB,SBDWSL)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_CKKA'),B.BGQID,B.KA_DM,B.CKEUSD,B.CKERMB,B.SBDWSL
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, HGGQKA_DM AS KA_DM, SUM(MYLAJ) AS CKEUSD, SUM(RMBLAJ) AS CKERMB,
                       COUNT(DISTINCT SBDWDM) AS SBDWSL
                  FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM,T.HGGQKA_DM,T.YSFS_DM,T.CKSP_DM,T.CKSL
                          FROM CKTS_WBSJ_HG_BGD T
                         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND T.JGFS_DM<>'1039'
                         UNION ALL
                        SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM,S.HGGQKA_DM,S.YSFS_DM,S.CKSP_DM,S.CKSL
                          FROM CKTS_WBSJ_ZJ_DLCKHWZM S
                         WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND S.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND S.JGFS_DM<>'1039'
                       ) TT
                 GROUP BY HGGQKA_DM
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_CKKA AS A WHERE A.BGQID=B.BGQID AND A.KA_DM=B.KA_DM
);
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_CKSP.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_CKSP AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(CKSP_DM,1,8) AS SP8_DM, SUM(MYLAJ) AS CKEUSD, SUM(RMBLAJ) AS CKERMB,
                       SUM(CKSL) AS CKSL, CASE WHEN SUM(CKSL)=0 THEN NULL ELSE SUM(RMBLAJ)/SUM(CKSL) END AS CKDJ
                  FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM,T.HGGQKA_DM,T.YSFS_DM,T.CKSP_DM,T.CKSL
                          FROM CKTS_WBSJ_HG_BGD T
                         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND T.JGFS_DM<>'1039'
                         UNION ALL
                        SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM,S.HGGQKA_DM,S.YSFS_DM,S.CKSP_DM,S.CKSL
                          FROM CKTS_WBSJ_ZJ_DLCKHWZM S
                         WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND S.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND S.JGFS_DM<>'1039'
                       ) TT
                 GROUP BY SUBSTR(CKSP_DM,1,8)
) AS B
ON A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, CKSL = B.CKSL, CKDJ = B.CKDJ;
INSERT INTO JKGL_DATA_TJ_ZBU_CKSP (ID,BGQID,SP8_DM,CKEUSD,CKERMB,CKSL,CKDJ)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_CKSP'),B.BGQID,B.SP8_DM,B.CKEUSD,B.CKERMB,B.CKSL,B.CKDJ
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(CKSP_DM,1,8) AS SP8_DM, SUM(MYLAJ) AS CKEUSD, SUM(RMBLAJ) AS CKERMB,
                       SUM(CKSL) AS CKSL, CASE WHEN SUM(CKSL)=0 THEN NULL ELSE SUM(RMBLAJ)/SUM(CKSL) END AS CKDJ
                  FROM (SELECT T.CKBGDH,T.MYLAJ,T.RMBLAJ,T.SBDWDM,T.MYGDQSZ_DM,T.HGGQKA_DM,T.YSFS_DM,T.CKSP_DM,T.CKSL
                          FROM CKTS_WBSJ_HG_BGD T
                         WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND T.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND T.JGFS_DM<>'1039'
                         UNION ALL
                        SELECT S.CKBGDH,S.MYLAJ,S.RMBLAJ,S.SBDWDM,S.MYGDQSZ_DM,S.HGGQKA_DM,S.YSFS_DM,S.CKSP_DM,S.CKSL
                          FROM CKTS_WBSJ_ZJ_DLCKHWZM S
                         WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                           AND S.CKRQ_1>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.CKRQ_1<ORA_DATE_ADD(BJTS_CUR_BGQ_BGQ_Z_001, 1)
                           AND S.JGFS_DM<>'1039'
                       ) TT
                 GROUP BY SUBSTR(CKSP_DM,1,8)
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_CKSP AS A WHERE A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_CKSP AS A
       SET SPDL=SUBSTR(A.SP8_DM,1,2),
    SPMC=(SELECT B.CKSP_MC FROM JCFX_DM_CKSP B WHERE B.CKSP_DM=A.SP8_DM AND 1=1
LIMIT 1)
     WHERE A.BGQID=BJTS_CUR_BGQ_BGQID_001 AND A.SPDL IS NULL;
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_QYXX.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_QYXX AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.FDDBRMC  AS FR_XM, T.FRZJHM AS FR_ZJHM,
                       T.CWFZRXM AS CWR_XM, T.CWFZRSFZJHM AS CWR_ZJHM,
                       T.BSRXM AS BSR_XM, T.BSRSFZJHM AS BSR_ZJHM,
                       ROUND(TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.DJRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z)) AS JYYFSL,
                       CASE WHEN IFNULL(T.SCCKRQ, CAST('2100-12-31' AS DATE))>V_BGQ_Z THEN NULL
                            ELSE ROUND(TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.SCCKRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z)) END AS CKYFSL,
                       T.ZCDZ,T.SCJYDZ AS JYDZ,
                       S.SJJYR_XM AS SKR_XM, S.SJJYR_SFZH AS SKR_ZJHM, S.YJBGCS_MJ AS JYCDMJ
                  FROM GS_DJ_CKTMSDAB T
                  LEFT JOIN JKGL_ZLCJ_JGB S ON CAST(S.DJXH AS CHAR)=T.CPCODE
                 WHERE T.CPCODE=CAST(BJTS_CUR_BGQ_DJXH_001 AS CHAR)
) AS B
ON A.BGQID=B.BGQID
SET FR_XM = B.FR_XM, FR_ZJHM = B.FR_ZJHM, CWR_XM = B.CWR_XM, CWR_ZJHM = B.CWR_ZJHM, BSR_XM = B.BSR_XM, BSR_ZJHM = B.BSR_ZJHM, JYYFSL = B.JYYFSL, CKYFSL = B.CKYFSL, ZCDZ = B.ZCDZ, JYDZ = B.JYDZ, SKR_XM = B.SKR_XM, SKR_ZJHM = B.SKR_ZJHM, JYCDMJ = B.JYCDMJ;
INSERT INTO JKGL_DATA_TJ_ZBU_QYXX (BGQID,FR_XM,FR_ZJHM,CWR_XM,CWR_ZJHM,BSR_XM,BSR_ZJHM,JYYFSL,CKYFSL,ZCDZ,JYDZ,SKR_XM,SKR_ZJHM,JYCDMJ)
SELECT B.BGQID,B.FR_XM,B.FR_ZJHM,B.CWR_XM,B.CWR_ZJHM,B.BSR_XM,B.BSR_ZJHM,B.JYYFSL,B.CKYFSL,B.ZCDZ,B.JYDZ,B.SKR_XM,B.SKR_ZJHM,B.JYCDMJ
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, T.FDDBRMC  AS FR_XM, T.FRZJHM AS FR_ZJHM,
                       T.CWFZRXM AS CWR_XM, T.CWFZRSFZJHM AS CWR_ZJHM,
                       T.BSRXM AS BSR_XM, T.BSRSFZJHM AS BSR_ZJHM,
                       ROUND(TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.DJRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z)) AS JYYFSL,
                       CASE WHEN IFNULL(T.SCCKRQ, CAST('2100-12-31' AS DATE))>V_BGQ_Z THEN NULL
                            ELSE ROUND(TIMESTAMPDIFF(MONTH, CAST(DATE_FORMAT(T.SCCKRQ, '%Y-%m-01') AS DATETIME), V_BGQ_Z)) END AS CKYFSL,
                       T.ZCDZ,T.SCJYDZ AS JYDZ,
                       S.SJJYR_XM AS SKR_XM, S.SJJYR_SFZH AS SKR_ZJHM, S.YJBGCS_MJ AS JYCDMJ
                  FROM GS_DJ_CKTMSDAB T
                  LEFT JOIN JKGL_ZLCJ_JGB S ON CAST(S.DJXH AS CHAR)=T.CPCODE
                 WHERE T.CPCODE=CAST(BJTS_CUR_BGQ_DJXH_001 AS CHAR)
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_QYXX AS A WHERE A.BGQID=B.BGQID
);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_QYXX
       SET FLGLCD =
           (SELECT S.KZXX
              FROM GS_DJ_CKTMSDAB T, GS_DJ_CKTMSDAB_KZ S
             WHERE T.CPCODE=CAST(BJTS_CUR_BGQ_DJXH_001 AS CHAR)
               AND S.NSRDZDAH=T.NSRDZDAH
               AND S.KZLX='FLGLCD' AND (V_BGQ_Z BETWEEN S.ST_DATE AND S.END_DATE) AND S.FLAG='1'
               AND 1=1
LIMIT 1)
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_TSGH.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, S.GHFNSRSBH_1 AS GHFSH, SUM(S.JSJE) AS JHJE, SUM(S.TSE) AS TSE
                  FROM CKTS_SB_MTS_JHMX S
                 WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND S.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY S.GHFNSRSBH_1
) AS B
ON A.BGQID=B.BGQID AND A.GHFSH=B.GHFSH
SET JHJE = B.JHJE, TSE = B.TSE;
INSERT INTO JKGL_DATA_TJ_ZBU_TSGH (ID,BGQID,GHFSH,JHJE,TSE)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_TSGH'),B.BGQID,B.GHFSH,B.JHJE,B.TSE
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, S.GHFNSRSBH_1 AS GHFSH, SUM(S.JSJE) AS JHJE, SUM(S.TSE) AS TSE
                  FROM CKTS_SB_MTS_JHMX S
                 WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND S.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY S.GHFNSRSBH_1
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_TSGH AS A WHERE A.BGQID=B.BGQID AND A.GHFSH=B.GHFSH
);
    COMMIT;
    DELETE FROM JKGL_DATA_TJ_ZBU_TSGH AS T
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND NOT EXISTS (SELECT 1
                         FROM CKTS_SB_MTS_JHMX S
                        WHERE S.DJXH=BJTS_CUR_BGQ_DJXH_001 AND S.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND S.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                          AND S.GHFNSRSBH_1=T.GHFSH);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET FXQYBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_FXQY_SWJG S
                    WHERE S.QYSBH=T.GHFSH
                      AND IFNULL(S.YXQ_Z, CURRENT_TIMESTAMP)>BJTS_CUR_BGQ_BGQ_Q_001);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET FXDQBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_FXDQ_SWJG S
                    WHERE S.XZQH_DM= CASE WHEN LENGTH(T.GHFSH)=15
                                          THEN SUBSTR(T.GHFSH,1,LENGTH(S.XZQH_DM))
                                          ELSE SUBSTR(T.GHFSH,3,LENGTH(S.XZQH_DM)) END
                      AND IFNULL(S.YXQ_Z, CURRENT_TIMESTAMP)>BJTS_CUR_BGQ_BGQ_Q_001);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET SNWBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND '33' <> (CASE WHEN LENGTH(T.GHFSH)=15 THEN SUBSTR(T.GHFSH,1,2) ELSE SUBSTR(T.GHFSH,3,2) END);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSGH AS T
       SET FZCHBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_GHQYXX S
                    WHERE S.QYSBH=T.GHFSH AND IFNULL(S.NSRZT_DM, '03')='05');
    COMMIT;

    -- 计算 JKGL_DATA_TJ_ZBU_TSSP.BGQID
    UPDATE JKGL_DATA_TJ_ZBU_TSSP AS A
JOIN (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(T.CKSP_DM,1,8) AS SP8_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       SUM(S.RMBLAJ) AS CKERMB_STZC, SUM(T.CKSL) AS CKSL, SUM(T.TMSE) AS SBTMSE, SUM(T.JSJE) AS JHJE,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.MYLAJ) / SUM(T.CKSL), 2) END AS CKDJ,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.JSJE) / SUM(T.CKSL), 2) END AS JHDJ,
                       CASE WHEN SUM(T.MYLAJ)<=0 THEN 0 ELSE ROUND((SUM(T.RMBLAJ) - SUM(T.JSJE)) / SUM(T.MYLAJ),2) END AS MMYLR
                  FROM JCFX_DATA_TSSBMX T
                  LEFT JOIN CKTS_SB_MDT_CKMX S ON S.UUID=T.UUID AND S.CKTMSYWLXDMJH LIKE '%STZC%'
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY SUBSTR(T.CKSP_DM,1,8)
) AS B
ON A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
SET CKEUSD = B.CKEUSD, CKERMB = B.CKERMB, CKERMB_STZC = B.CKERMB_STZC, CKSL = B.CKSL, SBTMSE = B.SBTMSE, JHJE = B.JHJE, CKDJ = B.CKDJ, JHDJ = B.JHDJ, MMYLR = B.MMYLR;
INSERT INTO JKGL_DATA_TJ_ZBU_TSSP (ID,BGQID,SP8_DM,CKEUSD,CKERMB,CKERMB_STZC,CKSL,SBTMSE,JHJE,SP_DL,MMYLR,CKDJ,JHDJ)
SELECT SEQ_NEXTVAL('SEQ_JKGL_DATA_TJ_ZBU_TSSP'),B.BGQID,B.SP8_DM,B.CKEUSD,B.CKERMB,B.CKERMB_STZC,
                    B.CKSL,B.SBTMSE,B.JHJE,SUBSTR(B.SP8_DM,1,2),B.MMYLR,B.CKDJ,B.JHDJ
FROM (
SELECT BJTS_CUR_BGQ_BGQID_001 AS BGQID, SUBSTR(T.CKSP_DM,1,8) AS SP8_DM, SUM(T.MYLAJ) AS CKEUSD, SUM(T.RMBLAJ) AS CKERMB,
                       SUM(S.RMBLAJ) AS CKERMB_STZC, SUM(T.CKSL) AS CKSL, SUM(T.TMSE) AS SBTMSE, SUM(T.JSJE) AS JHJE,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.MYLAJ) / SUM(T.CKSL), 2) END AS CKDJ,
                       CASE WHEN SUM(T.CKSL)<=0 THEN 0 ELSE ROUND(SUM(T.JSJE) / SUM(T.CKSL), 2) END AS JHDJ,
                       CASE WHEN SUM(T.MYLAJ)<=0 THEN 0 ELSE ROUND((SUM(T.RMBLAJ) - SUM(T.JSJE)) / SUM(T.MYLAJ),2) END AS MMYLR
                  FROM JCFX_DATA_TSSBMX T
                  LEFT JOIN CKTS_SB_MDT_CKMX S ON S.UUID=T.UUID AND S.CKTMSYWLXDMJH LIKE '%STZC%'
                 WHERE T.DJXH=BJTS_CUR_BGQ_DJXH_001
                   AND T.SBRQ>=BJTS_CUR_BGQ_BGQ_Q_001 AND T.SBRQ<ORA_DATE_ADD(V_BGQ_Z, 1)
                 GROUP BY SUBSTR(T.CKSP_DM,1,8)
) AS B
WHERE NOT EXISTS (
  SELECT 1 FROM JKGL_DATA_TJ_ZBU_TSSP AS A WHERE A.BGQID=B.BGQID AND A.SP8_DM=B.SP8_DM
);
    COMMIT;
    UPDATE JKGL_DATA_TJ_ZBU_TSSP AS T
       SET MGBZ='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001
       AND EXISTS (SELECT 1
                     FROM JKGL_GY_MGSP_SWJG S
                    WHERE SUBSTR(T.SP8_DM,1,LENGTH(S.MGSP_DM)) = S.MGSP_DM
                      AND IFNULL(S.YXQ_Z, CURRENT_TIMESTAMP)>BJTS_CUR_BGQ_BGQ_Q_001);
    COMMIT;

    -- 解锁处理完成的报告期
    UPDATE JKGL_DATA_BGQ AS T
       SET TQBZ=NULL,
    WCSJ=CURRENT_TIMESTAMP,
    SXZT='2',
    ZZS_ZT='Y',
    DZSP_ZT='Y',
    DZDZ_ZT='Y',
    ZBU_DZGF_ZT='N',
    ZBU_DZXF_ZT='N',
    ZBU_DZSPJX_ZT='N',
    ZBU_DZSPXX_ZT='N'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_001;
    COMMIT;

    -- 后续需要通过ETL抽取的数据
    --  V_SDS_


  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_ZBU_ND.sql

-- ======================================================================
-- [134/146] BEGIN SOURCE: PRO_JKGL_COMPUTE_ZBU_QSPJ.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_COMPUTE_ZBU_QSPJ$$

CREATE PROCEDURE PRO_JKGL_COMPUTE_ZBU_QSPJ
/*
 * 全省平均数据刷新口径
 */
(
  IN P_ZBYEAR VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE V_SQL_SELECT      VARCHAR(1000);
  DECLARE V_QSPJZ           DECIMAL(18,2); --  全省平均值
  DECLARE V_ROWS            BIGINT;  -- 待更新表中是否存在目标记录

  BEGIN
  DECLARE BJTS_CURSOR_DONE_002 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_BGQ_BGQID_002 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_QYLX_002 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Q_002 LONGTEXT;
  DECLARE BJTS_CUR_BGQ_BGQ_Z_002 LONGTEXT;
  DECLARE BJTS_CURSOR_002 CURSOR FOR
SELECT T.BGQID, T.QYLX, T.BGQ_Q, T.BGQ_Z
                    FROM JKGL_DATA_BGQ_QSPJ T
                   WHERE P_ZBYEAR IS NULL
                      OR DATE_FORMAT(T.BGQ_Q, '%Y')=P_ZBYEAR;
  OPEN BJTS_CURSOR_002;
  BJTS_CURSOR_LOOP_002: LOOP
    SET BJTS_CURSOR_DONE_002 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_002 = TRUE;
      FETCH BJTS_CURSOR_002 INTO BJTS_CUR_BGQ_BGQID_002, BJTS_CUR_BGQ_QYLX_002, BJTS_CUR_BGQ_BGQ_Q_002, BJTS_CUR_BGQ_BGQ_Z_002;
    END;
    IF BJTS_CURSOR_DONE_002 THEN
      LEAVE BJTS_CURSOR_LOOP_002;
    END IF;
    -- 锁定正在处理的报告期
    UPDATE JKGL_DATA_BGQ_QSPJ AS T
       SET TQBZ=REPLACE(UUID(), '-', ''),
    TQSJ=CURRENT_TIMESTAMP,
    SXZT='1'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

    -- 确定 JKGL_QSPJ_JGB.BGQID 存在
    SELECT LEAST(COUNT(1), 1)
      INTO V_ROWS
      FROM JKGL_QSPJ_JGB T
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_002 AND 1=1;
    IF V_ROWS=0 THEN
      BEGIN
        INSERT INTO JKGL_QSPJ_JGB(ID,BGQID) VALUES (BJTS_CUR_BGQ_BGQID_002,BJTS_CUR_BGQ_BGQID_002);
        COMMIT;
      END;
    END IF;

    -- 更新全省平均数
    -- 毛利润
    SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('SELECT C.CW_MLL AS OBJ FROM GLXT_BB_SHXT_DJXX A', ' INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS'), ' INNER JOIN JKGL_DATA_TJ_ZBU_KZ C ON C.BGQID=B.BGQID'), (CASE BJTS_CUR_BGQ_QYLX_002 WHEN '1' THEN ' WHERE A.JSMODE=''1''' ELSE ' WHERE A.JSMODE=''2''' END)), ' AND B.BGQ_Q='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Q_002, '%Y-%m-%d')), ''''), ' AND B.BGQ_Z='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_002, '%Y-%m-%d')), ''''), ' AND C.CW_MLL IS NOT NULL')
      INTO V_SQL_SELECT
;

    CALL F_MY_STDAVG_TMPTB(V_SQL_SELECT, V_QSPJZ);

    UPDATE JKGL_QSPJ_JGB
       SET MLL = V_QSPJZ
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

    -- 还原税负率
    SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('SELECT C.CW_HYSFL AS OBJ FROM GLXT_BB_SHXT_DJXX A', ' INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS'), ' INNER JOIN JKGL_DATA_TJ_ZBU_KZ C ON C.BGQID=B.BGQID'), (CASE BJTS_CUR_BGQ_QYLX_002 WHEN '1' THEN ' WHERE A.JSMODE=''1''' ELSE ' WHERE A.JSMODE=''2''' END)), ' AND B.BGQ_Q='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Q_002, '%Y-%m-%d')), ''''), ' AND B.BGQ_Z='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_002, '%Y-%m-%d')), ''''), ' AND C.CW_HYSFL IS NOT NULL')
      INTO V_SQL_SELECT
;

    CALL F_MY_STDAVG_TMPTB(V_SQL_SELECT, V_QSPJZ);

    UPDATE JKGL_QSPJ_JGB
       SET HYSFL = V_QSPJZ
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

    -- 费用收入比
    SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('SELECT ROUND(100 * C.LR_XSFY / C.LR_YYSR, 2) AS OBJ FROM GLXT_BB_SHXT_DJXX A', ' INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS'), ' INNER JOIN JKGL_DATA_TJ_ZBU C ON C.BGQID=B.BGQID'), (CASE BJTS_CUR_BGQ_QYLX_002 WHEN '1' THEN ' WHERE A.JSMODE=''1''' ELSE ' WHERE A.JSMODE=''2''' END)), ' AND B.BGQ_Q='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Q_002, '%Y-%m-%d')), ''''), ' AND B.BGQ_Z='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_002, '%Y-%m-%d')), ''''), ' AND C.LR_YYSR>1')
      INTO V_SQL_SELECT
;

    CALL F_MY_STDAVG_TMPTB(V_SQL_SELECT, V_QSPJZ);

    UPDATE JKGL_QSPJ_JGB
       SET FYSRB = V_QSPJZ
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

    -- 单位固定资产销售额
    SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('SELECT ROUND(2*C.ZZS_XSE_QB/(C.ZC_GDZC_QC+C.ZC_GDZC_QM),2) AS OBJ', '  FROM GLXT_BB_SHXT_DJXX A'), ' INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS'), ' INNER JOIN JKGL_DATA_TJ_ZBU C ON C.BGQID=B.BGQID'), (CASE BJTS_CUR_BGQ_QYLX_002 WHEN '1' THEN ' WHERE A.JSMODE=''1''' ELSE ' WHERE A.JSMODE=''2''' END)), ' AND B.BGQ_Q='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Q_002, '%Y-%m-%d')), ''''), ' AND B.BGQ_Z='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_002, '%Y-%m-%d')), ''''), ' AND C.ZC_GDZC_QC + C.ZC_GDZC_QM<>0')
      INTO V_SQL_SELECT
;

    CALL F_MY_STDAVG_TMPTB(V_SQL_SELECT, V_QSPJZ);

    UPDATE JKGL_QSPJ_JGB
       SET DWGDZCXSE = V_QSPJZ
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

    -- 单位经营面积销售额
    SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('SELECT ROUND(C.ZZS_XSE_QB / D.YJBGCS_MJ, 2) AS OBJ', '  FROM GLXT_BB_SHXT_DJXX A'), ' INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS'), ' INNER JOIN JKGL_DATA_TJ_ZBU C ON C.BGQID=B.BGQID'), ' INNER JOIN JKGL_ZLCJ_JGB D ON D.DJXH=A.DJXH_JS'), (CASE BJTS_CUR_BGQ_QYLX_002 WHEN '1' THEN ' WHERE A.JSMODE=''1''' ELSE ' WHERE A.JSMODE=''2''' END)), ' AND B.BGQ_Q='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Q_002, '%Y-%m-%d')), ''''), ' AND B.BGQ_Z='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_002, '%Y-%m-%d')), ''''), ' AND D.YJBGCS_MJ<>0')
      INTO V_SQL_SELECT
;

    CALL F_MY_STDAVG_TMPTB(V_SQL_SELECT, V_QSPJZ);

    UPDATE JKGL_QSPJ_JGB
       SET DWJYMJXSE = V_QSPJZ
     WHERE BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

    -- 确定 JKGL_QSPJ_CKSP.BGQID 不存在
    DELETE FROM JKGL_QSPJ_CKSP AS T WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

    -- ID  N NUMBER(20)  N     序号
    -- BGQID N NUMBER(20)  Y     报告期ID 关联主表PK_JKGL_DATA_BGQ
    -- SP8_DM N VARCHAR2(8) Y     商品代码（8）
    -- CKEUSD  N NUMBER(18,2)  Y     出口额USD
    -- CKERMB N NUMBER(18,2)  Y     出口额
    -- CKSL  N NUMBER(18,2)  Y     出口数量
    -- QYHS  N INTEGER Y     企业户数
    INSERT INTO JKGL_QSPJ_CKSP (ID,BGQID,SP8_DM,CKEUSD,CKERMB,CKSL,QYHS)
         SELECT SEQ_NEXTVAL('SEQ_JKGL_QSPJ_CKSP'),BJTS_CUR_BGQ_BGQID_002,SP8_DM,CKEUSD,CKERMB,CKSL,QYHS
           FROM (SELECT C.SP8_DM,SUM(C.CKSL) AS CKSL,SUM(C.CKEUSD) AS CKEUSD,SUM(C.CKERMB) AS CKERMB,
                        COUNT(DISTINCT A.DJXH_JS) AS QYHS
                   FROM GLXT_BB_SHXT_DJXX A
                  INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS
                  INNER JOIN JKGL_DATA_TJ_ZBU_CKSP C ON C.BGQID=B.BGQID
                  WHERE (CASE A.JSMODE WHEN '1' THEN '1' ELSE '2' END)=BJTS_CUR_BGQ_QYLX_002
                    AND B.BGQ_Q=BJTS_CUR_BGQ_BGQ_Q_002
                    AND B.BGQ_Z=BJTS_CUR_BGQ_BGQ_Z_002
                  GROUP BY C.SP8_DM) TT;
    COMMIT;

    -- CKDJ  N NUMBER(18,2)  Y     出口单价
    -- MMYLR N NUMBER(18,2)  Y     每美元利润
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CKSP_ID_001 LONGTEXT;
  DECLARE BJTS_CUR_CKSP_SP8_DM_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT ID,SP8_DM FROM JKGL_QSPJ_CKSP WHERE BGQID=BJTS_CUR_BGQ_BGQID_002 ORDER BY ID;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_CKSP_ID_001, BJTS_CUR_CKSP_SP8_DM_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('SELECT C.CKDJ AS OBJ FROM GLXT_BB_SHXT_DJXX A', ' INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS'), ' INNER JOIN JKGL_DATA_TJ_ZBU_CKSP C ON C.BGQID=B.BGQID'), (CASE BJTS_CUR_BGQ_QYLX_002 WHEN '1' THEN ' WHERE A.JSMODE=''1''' ELSE ' WHERE A.JSMODE=''2''' END)), ' AND B.BGQ_Q='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Q_002, '%Y-%m-%d')), ''''), ' AND B.BGQ_Z='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_002, '%Y-%m-%d')), ''''), ' AND C.SP8_DM='''), BJTS_CUR_CKSP_SP8_DM_001), ''''), ' AND C.CKDJ IS NOT NULL')
        INTO V_SQL_SELECT
;

      CALL F_MY_STDAVG_TMPTB(V_SQL_SELECT, V_QSPJZ);

      UPDATE JKGL_QSPJ_CKSP
         SET CKDJ = V_QSPJZ
       WHERE ID=BJTS_CUR_CKSP_ID_001;
      COMMIT;

      IF BJTS_CUR_BGQ_QYLX_002 = '2' THEN
        SELECT ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('SELECT C.MMYLR AS OBJ FROM GLXT_BB_SHXT_DJXX A', ' INNER JOIN JKGL_DATA_BGQ B ON B.DJXH=A.DJXH_JS'), ' INNER JOIN JKGL_DATA_TJ_ZBU_TSSP C ON C.BGQID=B.BGQID'), ' WHERE A.JSMODE=''2'''), ' AND B.BGQ_Q='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Q_002, '%Y-%m-%d')), ''''), ' AND B.BGQ_Z='''), DATE_FORMAT(BJTS_CUR_BGQ_BGQ_Z_002, '%Y-%m-%d')), ''''), ' AND C.SP8_DM='''), BJTS_CUR_CKSP_SP8_DM_001), ''''), ' AND C.MMYLR IS NOT NULL')
          INTO V_SQL_SELECT
;

        CALL F_MY_STDAVG_TMPTB(V_SQL_SELECT, V_QSPJZ);

        UPDATE JKGL_QSPJ_CKSP
           SET MMYLR = V_QSPJZ
         WHERE ID=BJTS_CUR_CKSP_ID_001;
        COMMIT;
      END IF;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

    -- 解锁处理完成的报告期
    UPDATE JKGL_DATA_BGQ_QSPJ AS T
       SET TQBZ=NULL,
    WCSJ=CURRENT_TIMESTAMP,
    SXZT='2'
     WHERE T.BGQID=BJTS_CUR_BGQ_BGQID_002;
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_002;
  CLOSE BJTS_CURSOR_002;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_COMPUTE_ZBU_QSPJ.sql

-- ======================================================================
-- [135/146] BEGIN SOURCE: PRO_JKGL_JKM_COMPUTE.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_JKM_COMPUTE$$

CREATE procedure PRO_JKGL_JKM_COMPUTE(
  IN p_djxh VARCHAR(4000),
  IN p_tsjsfs VARCHAR(4000),
  IN p_swjg VARCHAR(4000)
)
routine_body: BEGIN
/*
 * 单户企业健康码结果计算
 */

  -- 定义变量

  -- 指标分转健康码分的折算比例
  DECLARE zsblv1 DECIMAL(18,2);
  DECLARE zsblv2 DECIMAL(18,2);
  DECLARE zsblv3 DECIMAL(18,2);
  DECLARE zsblv4 DECIMAL(18,2);
  DECLARE zsblv5 DECIMAL(18,2);
  DECLARE zsblv6 DECIMAL(18,2);

  -- 六个分类的红线
  DECLARE lineRed1 int;
  DECLARE lineRed2 int;
  DECLARE lineRed3 int;
  DECLARE lineRed4 int;
  DECLARE lineRed5 int;
  DECLARE lineRed6 int;
  -- 六个分类的黄线
  DECLARE lineYellow1 int;
  DECLARE lineYellow2 int;
  DECLARE lineYellow3 int;
  DECLARE lineYellow4 int;
  DECLARE lineYellow5 int;
  DECLARE lineYellow6 int;

  DECLARE lineRed_Zh integer;          -- 综合红线
  DECLARE lineYellow_Zh integer;       -- 综合黄线

  -- 实际指标赋分
  DECLARE zb_SCORE1 int;
  DECLARE zb_SCORE2 int;
  DECLARE zb_SCORE3 int;
  DECLARE zb_SCORE4 int;
  DECLARE zb_SCORE5 int;
  DECLARE zb_SCORE6 int;

  -- 折算后的分数
  DECLARE jk_SCORE1 int;
  DECLARE jk_SCORE2 int;
  DECLARE jk_SCORE3 int;
  DECLARE jk_SCORE4 int;
  DECLARE jk_SCORE5 int;
  DECLARE jk_SCORE6 int;
  DECLARE jk_SCORE_ZH integer;          -- -折算后健康码综合赋分

  -- 健康码结果  1绿  2黄 3红
  DECLARE V_level char(1);
  DECLARE V_note VARCHAR(200);


/*  -- 指标结果尚处于计算或赋分过程中，暂不能计算健康码结果
  select count1 into v_cnt
    from tl_tssh.JKGL_DATA_ZB_JGB t
    where djxh=p_djxh and t.js_status='0' and t.ff_status='0' and rownum=1;
  if v_cnt > 0 then
    return;
  end if;
*/
  SET V_note ='';

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

    -- 从健康码配置表，计算折算比率
    /*
    select
      sum(decode (ywfl_dm,'10',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'20',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'30',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'40',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'50',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'60',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'10',line_red,0)),
      sum(decode (ywfl_dm,'20',line_red,0)),
      sum(decode (ywfl_dm,'30',line_red,0)),
      sum(decode (ywfl_dm,'40',line_red,0)),
      sum(decode (ywfl_dm,'50',line_red,0)),
      sum(decode (ywfl_dm,'60',line_red,0)),
      sum(decode (ywfl_dm,'ZH',line_red,0)),
      sum(decode (ywfl_dm,'10',line_yellow,0)),
      sum(decode (ywfl_dm,'20',line_yellow,0)),
      sum(decode (ywfl_dm,'30',line_yellow,0)),
      sum(decode (ywfl_dm,'40',line_yellow,0)),
      sum(decode (ywfl_dm,'50',line_yellow,0)),
      sum(decode (ywfl_dm,'60',line_yellow,0)),
      sum(decode (ywfl_dm,'ZH',line_yellow,0))
    into zsblv1,zsblv2,zsblv3,zsblv4,zsblv5,zsblv6,
         lineRed1,lineRed2,lineRed3,lineRed4,lineRed5,lineRed6,lineRed_Zh,
         lineYellow1,lineYellow2,lineYellow3,lineYellow4,lineYellow5,lineYellow6,lineYellow_Zh
    from tl_tssh.JKGL_PZ_JKM t
    where t.tsjsfs=p_tsjsfs ;
    */


  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      DO ORA_CONCAT('【健康码】等级评定：', BJTS_SQLERRM_001);
      ROLLBACK;
      CALL ORA_RAISE_APPLICATION_ERROR(-20001,ORA_CONCAT('【健康码】等级评定：', P_djxh));

  END;
with TT as (
    select zb.ywfl_dm, sum(score) as zbScore
    from
      JKGL_PZ_ZB zb left join
      (
      select t.zb_id,max(IFNULL(s.score, t.score)) as score
      from
      JKGL_PZ_ZB_YCFF t
      left join JKGL_PZ_ZB_YCFF_SWJG s
           on s.swjg_dm =p_swjg
           and s.zb_id=t.zb_id and s.xh=t.xh and s.yxbz='Y'
      where t.yxbz='Y'
      group by t.zb_id
      ) pt on pt.zb_id=zb.zb_id
    where
      zb.yxbz='Y' and
      zb.apply_qy=p_tsjsfs
      group by zb.ywfl_dm
    )
    select
     sum((CASE jkm.ywfl_dm WHEN '10' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '20' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '30' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '40' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '50' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '60' THEN case when IFNULL(TT.zbScore, 0)=0 then 0 else JKM_TOTAL/IFNULL(TT.zbScore, 0) end ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '10' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '20' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '30' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '40' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '50' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '60' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN 'ZH' THEN line_red ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '10' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '20' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '30' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '40' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '50' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN '60' THEN line_yellow ELSE 0 END)),
      sum((CASE jkm.ywfl_dm WHEN 'ZH' THEN line_yellow ELSE 0 END))
    into zsblv1,zsblv2,zsblv3,zsblv4,zsblv5,zsblv6,
         lineRed1,lineRed2,lineRed3,lineRed4,lineRed5,lineRed6,lineRed_Zh,
         lineYellow1,lineYellow2,lineYellow3,lineYellow4,lineYellow5,lineYellow6,lineYellow_Zh
    from JKGL_PZ_JKM jkm
    left join TT on TT.ywfl_dm=jkm.ywfl_dm
    where jkm.tsjsfs=p_tsjsfs ;


    -- 获取该纳税人的指标赋分
    select
        IFNULL(sum((CASE ywfl_dm WHEN '10' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '20' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '30' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '40' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '50' THEN score ELSE 0 END)), 0),
        IFNULL(sum((CASE ywfl_dm WHEN '60' THEN score ELSE 0 END)), 0)
    into zb_SCORE1,zb_SCORE2,zb_SCORE3,zb_SCORE4,zb_SCORE5,zb_SCORE6
    from (
    select s.ywfl_dm,
      --   sum(t.score) as score
        sum(case when (k.fmyxq is null OR k.fmyxq>=DATE(CURRENT_TIMESTAMP)) and IFNULL(t.hcjg, '2')='1' then 0 else t.score end) as score
        from
        JKGL_DATA_QYJKM_JGB k
        inner join JKGL_DATA_ZB_JGB t on t.djxh=k.djxh
        inner join JKGL_PZ_ZB s on t.zb_id=s.zb_id and s.yxbz='Y'
        where t.djxh=p_djxh
        group by s.ywfl_dm
    ) AS BJTS_DERIVED_001;

    -- 计算健康码折算赋分
    SET jk_SCORE1 = zb_SCORE1 * zsblv1;
    SET jk_SCORE2 = zb_SCORE2 * zsblv2;
    SET jk_SCORE3 = zb_SCORE3 * zsblv3;
    SET jk_SCORE4 = zb_SCORE4 * zsblv4;
    SET jk_SCORE5 = zb_SCORE5 * zsblv5;
    SET jk_SCORE6 = zb_SCORE6 * zsblv6;
    SET jk_SCORE_ZH = jk_SCORE1+jk_SCORE2+jk_SCORE3+jk_SCORE4+jk_SCORE5+jk_SCORE6;

    if (lineRed_Zh<>0 and jk_SCORE_ZH >= lineRed_Zh)
      OR (lineRed1<>0 and jk_SCORE1 >= lineRed1)
      OR (lineRed2<>0 and jk_SCORE2 >= lineRed2)
      OR (lineRed3<>0 and jk_SCORE3 >= lineRed3)
      OR (lineRed4<>0 and jk_SCORE4 >= lineRed4)
      OR (lineRed5<>0 and jk_SCORE5 >= lineRed5)
      OR (lineRed6<>0 and jk_SCORE6 >= lineRed6)
    then
      SET V_level = '3';

      if (lineRed_Zh<>0 and jk_SCORE_ZH >= lineRed_Zh) then
        SET V_note =ORA_CONCAT(V_note, '综合,');
      end if;
      if (lineRed1<>0 and jk_SCORE1 >= lineRed1) then
        SET V_note =ORA_CONCAT(V_note, '信用,');
      end if;
      if (lineRed2<>0 and jk_SCORE2 >= lineRed2) then
        SET V_note =ORA_CONCAT(V_note, '退税,');
      end if;
      if (lineRed3<>0 and jk_SCORE3 >= lineRed3) then
        SET V_note =ORA_CONCAT(V_note, '出口,');
      end if;
      if (lineRed4<>0 and jk_SCORE4 >= lineRed4) then
        SET V_note =ORA_CONCAT(V_note, '发票,');
      end if;
      if (lineRed5<>0 and jk_SCORE5 >= lineRed5) then
        SET V_note =ORA_CONCAT(V_note, '财务,');
      end if;
      if (lineRed6<>0 and jk_SCORE6 >= lineRed6) then
        SET V_note =ORA_CONCAT(V_note, '其他,');
      end if;

    else
      if (lineYellow_Zh<>0 and jk_SCORE_ZH >= lineYellow_Zh)
        OR (lineYellow1<>0 and jk_SCORE1 >= lineYellow1)
        OR (lineYellow2<>0 and jk_SCORE2 >= lineYellow2)
        OR (lineYellow3<>0 and jk_SCORE3 >= lineYellow3)
        OR (lineYellow4<>0 and jk_SCORE4 >= lineYellow4)
        OR (lineYellow5<>0 and jk_SCORE5 >= lineYellow5)
        OR (lineYellow6<>0 and jk_SCORE6 >= lineYellow6)
      then
        SET V_level = '2';
        if (lineYellow_Zh<>0 and jk_SCORE_ZH >= lineYellow_Zh) then
          SET V_note =ORA_CONCAT(V_note, '综合,');
        end if;
        if (lineYellow1<>0 and jk_SCORE1 >= lineYellow1) then
          SET V_note =ORA_CONCAT(V_note, '信用,');
        end if;
        if (lineYellow2<>0 and jk_SCORE2 >= lineYellow2) then
          SET V_note =ORA_CONCAT(V_note, '退税,');
        end if;
        if (lineYellow3<>0 and jk_SCORE3 >= lineYellow3) then
          SET V_note =ORA_CONCAT(V_note, '出口,');
        end if;
        if (lineYellow4<>0 and jk_SCORE4 >= lineYellow4) then
          SET V_note =ORA_CONCAT(V_note, '发票,');
        end if;
        if (lineYellow5<>0 and jk_SCORE5 >= lineYellow5) then
          SET V_note =ORA_CONCAT(V_note, '财务,');
        end if;
        if (lineYellow6<>0 and jk_SCORE6 >= lineYellow6) then
          SET V_note =ORA_CONCAT(V_note, '其他,');
        end if;
      else
        SET V_level ='1';
      end if;
    end if;

    -- 保存健康码计算结果
    update JKGL_DATA_QYJKM_JGB
      set jkm_level=V_level,
    score_10 = jk_SCORE1,
    score_20 = jk_SCORE2,
    score_30 = jk_SCORE3,
    score_40 = jk_SCORE4,
    score_50 = jk_SCORE5,
    score_60 = jk_SCORE6,
    score_ZH = jk_SCORE_ZH,
    uptime = CURRENT_TIMESTAMP,
    note = V_note
      where djxh = p_djxh;
    COMMIT;
  END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_JKM_COMPUTE.sql

-- ======================================================================
-- [136/146] BEGIN SOURCE: PRO_JKGL_JKM_MAIN.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_JKM_MAIN$$

CREATE PROCEDURE PRO_JKGL_JKM_MAIN(
  IN P_DJXH VARCHAR(4000),
  IN P_SWJG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE V_COUNT BIGINT;
  DECLARE V_DJXH VARCHAR(20);
  DECLARE BJTS_RETURN_001 BOOLEAN DEFAULT FALSE;


  SET V_COUNT =0;
  DO ORA_CONCAT('【健康码】刷新开始，时间:', DATE_FORMAT(CURRENT_TIMESTAMP, '%Y%m%d %H:%i:%s'));

  -- 开始循环
  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      DO ORA_CONCAT(ORA_CONCAT('【健康码】刷新异常:', BJTS_SQLCODE_001), BJTS_SQLERRM_001);
      DO ORA_CONCAT(ORA_CONCAT(ORA_CONCAT('【异常企业】-', V_COUNT), '-'), V_DJXH);
      SET BJTS_RETURN_001 = TRUE;

  END;
BEGIN
  DECLARE BJTS_NAMED_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_CPCODE_001 LONGTEXT;
  DECLARE BJTS_CUR_TSJSFS_001 LONGTEXT;
  DECLARE BJTS_CUR_SWJGDM_001 LONGTEXT;
  DECLARE BJTS_NAMED_CURSOR_001 CURSOR FOR
SELECT DJ.CPCODE, (CASE DJ.JSMODE WHEN '1' THEN '1' ELSE '2' END) AS TSJSFS, DJ.SWJGDM
        FROM JKGL_DATA_QYJKM_JGB T
       INNER JOIN GLXT_BB_SHXT_DJXX DJ ON DJ.CPCODE=T.DJXH
       WHERE ((P_DJXH) IS NULL OR T.DJXH=(P_DJXH))
         AND ((P_SWJG) IS NULL OR DJ.SWJGDM=(P_SWJG))
         AND EXISTS (SELECT 1
                       FROM JKGL_DATA_ZB_JGB Z
                      WHERE T.DJXH=Z.DJXH AND Z.ZB_ID IN ('W10101','S10101'));
  OPEN BJTS_NAMED_CURSOR_001;
  BJTS_NAMED_CURSOR_LOOP_001: LOOP
    SET BJTS_NAMED_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_NAMED_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_NAMED_CURSOR_001 INTO BJTS_CUR_CPCODE_001, BJTS_CUR_TSJSFS_001, BJTS_CUR_SWJGDM_001;
    END;
    IF BJTS_NAMED_CURSOR_DONE_001 THEN
      LEAVE BJTS_NAMED_CURSOR_LOOP_001;
    END IF;
      SET V_COUNT =V_COUNT+1;
      SET V_DJXH = BJTS_CUR_CPCODE_001;

      -- 对指标进行异常判定和赋分
      CALL PRO_JKGL_JKM_ZB_YCFF(V_DJXH,BJTS_CUR_TSJSFS_001,BJTS_CUR_SWJGDM_001);

      -- 对指标进行异常判定和赋分
      CALL PRO_JKGL_JKM_COMPUTE(V_DJXH,BJTS_CUR_TSJSFS_001,BJTS_CUR_SWJGDM_001);



  END LOOP BJTS_NAMED_CURSOR_LOOP_001;
  CLOSE BJTS_NAMED_CURSOR_001;
END;
  END;

  IF BJTS_RETURN_001 THEN
    LEAVE routine_body;
  END IF;

  DO ORA_CONCAT('【健康码】刷新结束，时间:', DATE_FORMAT(CURRENT_TIMESTAMP, '%Y%m%d %H:%i:%s'));
  DO ORA_CONCAT('【健康码】刷新户数=', V_COUNT);

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_JKM_MAIN.sql

-- ======================================================================
-- [137/146] BEGIN SOURCE: PRO_JKGL_JKM_ZB_YCFF.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_JKGL_JKM_ZB_YCFF$$

CREATE PROCEDURE PRO_JKGL_JKM_ZB_YCFF
/*
 * 对单户企业健康码指标，做异常判定赋分处理
 */
(
  IN P_DJXH VARCHAR(4000),
  IN P_TSJSFS VARCHAR(4000),
  IN P_SWJG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE V_ZB_ID      VARCHAR(30);
  DECLARE V_ZB_VAL     DECIMAL(18,2);
  DECLARE V_BADPOINT   CHAR(1);
  DECLARE VAL1         DECIMAL(18,2);    -- 参数1
  DECLARE VAL2         DECIMAL(18,2);    -- 参数2
  DECLARE VAL3         DECIMAL(18,2);    -- 参数3
  DECLARE VALPJ        DECIMAL(18,2);    -- 参数平均值
--  VTYPE        VARCHAR2(10);  --参数类型，区分百分比
  DECLARE V_YC         INTEGER;         -- 异常判断规则XH
  DECLARE V_SCORE      INTEGER;         -- 赋分
  DECLARE V_SUCCESS    INTEGER;         -- 存储过程执行结果 1成功 0发生异常
-- 全省平均
  DECLARE V_MLL        DECIMAL(18,2);
  DECLARE V_HYSFL      DECIMAL(18,2);
  DECLARE V_FYSRB      DECIMAL(18,2);
  DECLARE V_DWGDZCXSE    DECIMAL(18,2);
  DECLARE V_DWJYMJXSE    DECIMAL(18,2);





  SET V_SUCCESS =1;

  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SELECT NULL,NULL,NULL,NULL,NULL
        INTO V_MLL,V_HYSFL,V_FYSRB,V_DWGDZCXSE,V_DWJYMJXSE
;

  END;
SELECT MLL,HYSFL,FYSRB,DWGDZCXSE,DWJYMJXSE
      INTO  V_MLL,V_HYSFL,V_FYSRB,V_DWGDZCXSE,V_DWJYMJXSE
      FROM (
      SELECT T.MLL,T.HYSFL,T.FYSRB,T.DWGDZCXSE,T.DWJYMJXSE
      FROM JKGL_QSPJ_JGB T
      INNER JOIN JKGL_DATA_BGQ_QSPJ S ON S.BGQID=T.BGQID AND S.QYBJ='Y'
      WHERE S.QYLX=P_TSJSFS
      ORDER BY S.BGQ_Z DESC
      ) AS BJTS_DERIVED_001 WHERE 1=1
LIMIT 1;
  END;

  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
        SET V_SUCCESS =0;
        DO ORA_CONCAT(ORA_CONCAT('Exception!', BJTS_SQLCODE_001), BJTS_SQLERRM_001);

  END;
BEGIN
  DECLARE BJTS_FETCH_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_FETCH_CURSOR_001 CURSOR FOR
SELECT T.ZB_ID,T.ZB_VAL,T.BADPOINT FROM JKGL_DATA_ZB_JGB T
        WHERE T.DJXH=(P_DJXH);
  OPEN BJTS_FETCH_CURSOR_001;
  BJTS_FETCH_LOOP_001: LOOP
      -- 取一条指标
      BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_FETCH_DONE_001 = TRUE;
      FETCH BJTS_FETCH_CURSOR_001 INTO V_ZB_ID, V_ZB_VAL, V_BADPOINT;
    END;
    IF BJTS_FETCH_DONE_001 THEN
      LEAVE BJTS_FETCH_LOOP_001;
    END IF;


      IF IFNULL(V_BADPOINT, 'Y')<>'N' OR V_ZB_VAL IS NULL THEN
        ITERATE BJTS_FETCH_LOOP_001;
      END IF;

      IF P_TSJSFS='1' THEN
        -- 生产L
      CASE V_ZB_ID
          WHEN 'S10101'  THEN    -- 企业经营稳定性
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10101_MONTHS_1';
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL2
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10101_MONTHS_3';
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL3
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10101_MONTHS_5';

            CASE
              WHEN VAL1 IS NULL OR VAL2 IS NULL OR VAL3 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL<VAL1 THEN SET V_YC =1;
              WHEN V_ZB_VAL>=VAL1 AND V_ZB_VAL<VAL2 THEN SET V_YC =2;
              WHEN V_ZB_VAL>=VAL2 AND V_ZB_VAL<VAL3 THEN SET V_YC =3;
              ELSE SET V_YC =0;
            END CASE;

          WHEN 'S10102'  THEN    -- 企业法人与实际经营人的一致性
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S10103'  THEN    -- 法定代表人是否来自敏感地区
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S10104'  THEN    -- 法定代表人年龄是否异常
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S10105'  THEN    -- 财务负责人或办税员是否兼职
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10105_CWJZQY_NUM';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;

          WHEN 'S10107'  THEN    -- 出口企业分类管理等级
            CASE V_ZB_VAL
              WHEN 1 THEN SET V_YC =1;
              WHEN 2 THEN SET V_YC =2;
              WHEN 3 THEN SET V_YC =3;
              WHEN 4 THEN SET V_YC =4;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S10201'  THEN    -- 平均固定资产销售额
            -- 取全省平均
            SET VALPJ =V_DWGDZCXSE;

            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10201_PJGDZCXS_1';
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL2
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10201_PJGDZCXS_2';

            CASE
              WHEN VAL1 IS NULL OR VAL2 IS NULL OR VALPJ IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL<VALPJ * VAL1 /100  THEN SET V_YC =1;
              WHEN V_ZB_VAL>=VALPJ * VAL1/100 AND V_ZB_VAL<VALPJ * VAL2/100 THEN SET V_YC =2;
              WHEN V_ZB_VAL>=VALPJ * VAL2/100 THEN SET V_YC =3;
              ELSE SET V_YC =0;
            END CASE;

          WHEN 'S10202'  THEN    -- 平均生产面积销售额
            -- 取全省平均
            SET VALPJ =V_DWJYMJXSE;

            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10202_PJJYMJXS_1';
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL2
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S10202_PJJYMJXS_2';

            CASE
              WHEN VAL1 IS NULL OR VAL2 IS NULL OR VALPJ IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL<VALPJ * VAL1 /100  THEN SET V_YC =1;
              WHEN V_ZB_VAL>=VALPJ * VAL1/100 AND V_ZB_VAL<VALPJ * VAL2/100 THEN SET V_YC =2;
              WHEN V_ZB_VAL>=VALPJ * VAL2/100 THEN SET V_YC =3;
              ELSE SET V_YC =0;
            END CASE;

          WHEN 'S10203'  THEN    -- 销售额与电费支出变动趋势
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S10204'  THEN    -- 销售额与电费支出合理关系
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S20101'  THEN    -- 应退税额占比
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S20102'  THEN    -- 退税额增长Ⅰ
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S20103'  THEN    -- 退税额增长Ⅱ
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

    --      WHEN 'S30101'  THEN    -- 出口额变动率异常
    /*        IF V_ZB_VAL=1 THEN
              V_YC:=1;
            ELSE
              V_YC:=0;
            END IF;
    */
          WHEN 'S30102'  THEN    -- 大额报关占比异常
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S30103'  THEN    -- 出口额增长异常Ⅰ
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S30104'  THEN    -- 出口额增长异常Ⅱ
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S30105'  THEN    -- 出口额增长异常Ⅲ
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S30201'  THEN    -- 商品出口额变动率
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30201_SP_CKEBDL_NUM';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30202'  THEN    -- 新增商品出口占比
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30202_NEWSP_CKE_ZB';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30203'  THEN    -- 出口商品单价变动率
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30203_SP_PJDJBDL_NUM';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30204'  THEN    -- 本地区商品单价差异率
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30204_SP_QSPJCYL_NUM';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30205'  THEN    -- 敏感商品
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30205_MGSP_NUM_1';
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL2
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30205_MGSP_NUM_2';

            CASE
              WHEN VAL1 IS NULL OR VAL2 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 AND V_ZB_VAL<VAL2 THEN SET V_YC =1;
              WHEN V_ZB_VAL>=VAL2 THEN SET V_YC =2;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30206'  THEN    -- 出口商品跨大类Ⅰ
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30206_CKSPKDL_NUM';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
    --      WHEN 'S30207'  THEN    -- 出口商品跨大类Ⅱ
    --        CONTINUE;
          WHEN 'S30301'  THEN    -- 口岸出口额变动率
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30301_KA_CKEBDL_NUM';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
    --      WHEN 'S30302'  THEN    -- 转关出口额占比
    --        CONTINUE;
          WHEN 'S30303'  THEN    -- 敏感口岸出口额占比
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30303_MGKA_NUM_1';
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL2
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30303_MGKA_NUM_2';

            CASE
              WHEN VAL1 IS NULL OR VAL2 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 AND V_ZB_VAL<VAL2 THEN SET V_YC =1;
              WHEN V_ZB_VAL>=VAL2 THEN SET V_YC =2;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30304'  THEN    -- 出口同一国别口岸数量
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30304_GB_KASL';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30401'  THEN    -- 出口目的国数量变动
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30401_MDGSLBDL';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30402'  THEN    -- 出口到香港商品占比
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30402_DXGCKZB';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30403'  THEN    -- 出口国别和增幅预警
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

    --      WHEN 'S30501'  THEN    -- 两高两不符
    --        CONTINUE;
          WHEN 'S30601'  THEN    -- 运费匹配度
            CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

          WHEN 'S30602'  THEN    -- 出口同一个国别货代数量
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30602_GB_SBDWSL';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S30603'  THEN    -- 二异出口
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S30603_EYBG_CKE';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
    --      WHEN 'S40101'  THEN    -- 货源地不一致占比
    --        CONTINUE;
          WHEN 'S40102'  THEN    -- 进项产成品异常
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S40102_JXCCPBLV';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
    --      WHEN 'S40103'  THEN    -- 视同自产出口额占比
    --        CONTINUE;
    --      WHEN 'S40201'  THEN    -- 上游供货企业涉及贵金属
    --        CONTINUE;
          WHEN 'S40202'  THEN    -- 农产品进项税额占比
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S40202_NCPJXZB';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S40203'  THEN    -- 农产品进项税额增幅
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S40203_NCPJXZF';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
    --      WHEN 'S40301'  THEN    -- 生产企业风险供货情况Ⅰ
    --        CONTINUE;
    --      WHEN 'S40302'  THEN    -- 生产企业风险供货情况Ⅱ
    --        CONTINUE;
    --      WHEN 'S50101'  THEN    -- 外销比重
    --        CONTINUE;
          WHEN 'S50201'  THEN    -- 期末存货占比变动率
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S50201_CW_CHBDL';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;
          WHEN 'S50301'  THEN    -- 还原税负率
            -- 取全省平均
            SET VALPJ =V_HYSFL;

            IF VALPJ IS NULL OR VALPJ=0 THEN
              SET V_YC =-1;
            ELSE
              SET VAL1 =(VALPJ - V_ZB_VAL)/VALPJ;
              CASE
                WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1<=0.2)  THEN SET V_YC =1;
                WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1>0.2 AND VAL1<=0.5)  THEN SET V_YC =2;
                WHEN V_ZB_VAL<VALPJ AND (V_ZB_VAL<VALPJ AND VAL1>0.5 AND VAL1<=1)  THEN SET V_YC =3;
                WHEN VAL1>1 THEN SET V_YC =4;
                ELSE SET V_YC =0;
              END CASE;
            END IF;

          WHEN 'S60101'  THEN    -- 同一业务员备案备案多家出口企业
            SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
              FROM JKGL_PZ_ZB_CS T
              LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
              WHERE T.CSBM='YC_S60101_YWY_JZ_NUM';

            CASE
              WHEN VAL1 IS NULL THEN SET V_YC =-1;
              WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
              ELSE SET V_YC =0;
            END CASE;

          ELSE
            ITERATE BJTS_FETCH_LOOP_001;
        END CASE;
      ELSE
        -- 外贸W类指标
        CASE V_ZB_ID
            WHEN 'W10101'  THEN    -- 企业存续时间是否较短
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W10101_MONTHS_1';
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL2
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W10101_MONTHS_3';
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL3
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W10101_MONTHS_5';

              CASE
                WHEN VAL1 IS NULL OR VAL2 IS NULL OR VAL3 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL<VAL1 THEN SET V_YC =1;
                WHEN V_ZB_VAL>=VAL1 AND V_ZB_VAL<VAL2 THEN SET V_YC =2;
                WHEN V_ZB_VAL>=VAL2 AND V_ZB_VAL<VAL3 THEN SET V_YC =3;
                ELSE SET V_YC =0;
              END CASE;

            WHEN 'W10201'  THEN    -- 多个企业共用一个经营地址
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W10201_QYHS';

              CASE
                WHEN VAL1 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
                ELSE SET V_YC =0;
              END CASE;

            WHEN 'W10202'  THEN    -- 注册地址与生产经营地址不一致
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W10301'  THEN    -- 法定代表人年龄是否异常
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W10302'  THEN    -- 法定代表人是否来自敏感地区
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W10303'  THEN    -- 法定代表人是否为企业实际控制人
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W10304'  THEN    -- 企业是否经常变更法定代表人
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W10304_FRBG_NUM';

              CASE
                WHEN VAL1 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
                ELSE SET V_YC =0;
              END CASE;

            WHEN 'W10401'  THEN    -- 企业四员是否来自敏感地区
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W10402'  THEN    -- 业务员是否缴纳社保
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W10403'  THEN    -- 法人、股东同时兼营多家企业
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W10403';

              CASE
                WHEN VAL1 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
                ELSE SET V_YC =0;
              END CASE;
            WHEN 'W10501'  THEN    -- 分类管理等级
              CASE V_ZB_VAL
                WHEN 1 THEN SET V_YC =1;
                WHEN 2 THEN SET V_YC =2;
                WHEN 3 THEN SET V_YC =3;
                WHEN 4 THEN SET V_YC =4;
                ELSE SET V_YC =0;
              END CASE;
            WHEN 'W20101'  THEN    -- 退税额增长Ⅱ
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

      --      WHEN 'W20102'  THEN    -- 超期申报的报关单异常
      --        CONTINUE;
            WHEN 'W20103'  THEN    -- 退税额增长Ⅰ
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

