              END CASE;

      --      WHEN 'W30403'  THEN    -- 单位重量的商品单价与同行业相比偏离较大
      --        CONTINUE;
            WHEN 'W30404'  THEN    -- 出口商品跨大类Ⅰ
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
