            WHEN 'W40102'  THEN    -- 省外供货占比
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W40102_SWGH_ZB';

              CASE
                WHEN VAL1 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
                ELSE SET V_YC =0;
              END CASE;

            WHEN 'W40103'  THEN    -- 供货企业数量预警
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W40104'  THEN    -- 风险供货Ⅰ
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W40105'  THEN    -- 风险供货Ⅱ
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W40201'  THEN    -- 超期开票Ⅰ
              SET V_YC = V_ZB_VAL;

      --      WHEN 'W40202'  THEN    -- 超期开票Ⅱ
      --        CONTINUE;

            WHEN 'W40203'  THEN    -- 顶格开票
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

      --      WHEN 'W40204'  THEN    -- 发票IP及MAC地址
      --        CONTINUE;
      --      WHEN 'W40301'  THEN    -- 上游供货企业涉及贵金属
      --        CONTINUE;
            WHEN 'W50101'  THEN    -- 同一商品每美元利润与全省平均相比偏离较大
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W50101_SPMLR_NUM';

              CASE
                WHEN VAL1 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
                ELSE SET V_YC =0;
              END CASE;

            WHEN 'W50102'  THEN    -- 总体毛利率与全省平均相比偏离较大
              -- 取全省平均
              SET VALPJ =V_MLL;

              IF VALPJ IS NULL OR VALPJ=0 THEN
                SET V_YC =-1;
              ELSE
                SET VAL1 =(VALPJ - V_ZB_VAL)/VALPJ;
                CASE
                  WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1<=0.2)  THEN SET V_YC =1;
                  WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1>0.2 AND VAL1<=0.5)  THEN SET V_YC =2;
                  WHEN V_ZB_VAL<VALPJ AND (V_ZB_VAL<VALPJ AND VAL1>0.5 AND VAL1<=1)  THEN SET V_YC =3;
                  WHEN VAL1>1 THEN SET V_YC =4;
                  ELSE SET V_YC =0;
                END CASE;
              END IF;

      --      WHEN 'W50201'  THEN    -- 出口企业税负率与全省平均值相比偏离是否较大
      --        CONTINUE;
            WHEN 'W50202'  THEN    -- 企业还原税负率异常
              -- 取全省平均
              SET VALPJ =V_HYSFL;

              IF VALPJ IS NULL OR VALPJ=0 THEN
                SET V_YC =-1;
              ELSE
                SET VAL1 =(VALPJ - V_ZB_VAL)/VALPJ;
                CASE
                  WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1<=0.2)  THEN SET V_YC =1;
                  WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1>0.2 AND VAL1<=0.5)  THEN SET V_YC =2;
                  WHEN V_ZB_VAL<VALPJ AND (V_ZB_VAL<VALPJ AND VAL1>0.5 AND VAL1<=1)  THEN SET V_YC =3;
                  WHEN VAL1>1 THEN SET V_YC =4;
                  ELSE SET V_YC =0;
                END CASE;
              END IF;

    --        WHEN 'W50301'  THEN    -- 应收账款周转率
    --          CONTINUE;
            WHEN 'W50302'  THEN    -- 应收账款占营业收入比重
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W50302_YSZK_YYSR_ZB';

              CASE
                WHEN VAL1 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
                ELSE SET V_YC =0;
              END CASE;

    --        WHEN 'W50303'  THEN    -- 应付账款周转率
    --          CONTINUE;
            WHEN 'W50304'  THEN    -- 应付账款占营业成本额比重
              SELECT IFNULL(S.VAL_DEF, T.VAL_DEF) INTO VAL1
                FROM JKGL_PZ_ZB_CS T
                LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJG AND S.YXBZ='Y'
                WHERE T.CSBM='YC_W50304_YFZK_YYCB_ZB';

              CASE
                WHEN VAL1 IS NULL THEN SET V_YC =-1;
                WHEN V_ZB_VAL>=VAL1 THEN SET V_YC =1;
                ELSE SET V_YC =0;
              END CASE;

      --      WHEN 'W50401'  THEN    -- 企业是否按规定缴纳社保
      --        CONTINUE;
            WHEN 'W50402'  THEN    -- 企业缴纳社保的人员与企业实际人员是否匹配
              CASE WHEN V_ZB_VAL=1 THEN SET V_YC =1; ELSE SET V_YC =0; END CASE;

            WHEN 'W50501'  THEN    -- 企业销售费用与企业营业收入的比值是否异常
              -- 取全省平均
              SET VALPJ =V_FYSRB;

              IF VALPJ IS NULL OR VALPJ=0 THEN
                SET V_YC =-1;
              ELSE
                SET VAL1 =(VALPJ - V_ZB_VAL)/VALPJ;
                CASE
                  WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1<=0.2)  THEN SET V_YC =1;
                  WHEN V_ZB_VAL>=VALPJ OR (V_ZB_VAL<VALPJ AND VAL1>0.2 AND VAL1<=0.5)  THEN SET V_YC =2;
                  WHEN V_ZB_VAL<VALPJ AND (V_ZB_VAL<VALPJ AND VAL1>0.5 AND VAL1<=1)  THEN SET V_YC =3;
                  WHEN VAL1>1 THEN SET V_YC =4;
                  ELSE SET V_YC =0;
                END CASE;
              END IF;

      --      WHEN 'W60101'  THEN    -- 业务员挂靠企业户数
      --        CONTINUE;
      --      WHEN 'W60102'  THEN    -- 业务员出口额变动率
      --        CONTINUE;
      --      WHEN 'W60103'  THEN    -- 业务员商品出口数量变动
      --        CONTINUE;
      --      WHEN 'W60104'  THEN    -- 业务员商品出口额变动率
      --        CONTINUE;
      --      WHEN 'W60105'  THEN    -- 业务员出口目的国数量
      --        CONTINUE;
      --      WHEN 'W60106'  THEN    -- 业务员出口目的国出口额变动率
      --        CONTINUE;
      --      WHEN 'W60107'  THEN    -- 业务员供货企业户数
      --        CONTINUE;
      --      WHEN 'W60108'  THEN    -- 业务员供货金额变动率
      --        CONTINUE;
      --      WHEN 'W60201'  THEN    -- 是否被公安、海关、外管、税务稽查等部门查处
      --        CONTINUE;
      --      WHEN 'W60202'  THEN    -- 存在各类企业异常信息
      --        CONTINUE;
      --      WHEN 'W60301'  THEN    -- 是否存在外管部门反馈的异常外汇数据
      --        CONTINUE;
              ELSE
                SET V_YC =-1;
--                CONTINUE;
          END CASE;
      END IF;

      -- 提取异常XH的赋分
      IF V_YC>0 THEN
        BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
             SET V_SCORE =0;

  END;
SELECT IFNULL(IFNULL(S.SCORE, T.SCORE), 0) INTO V_SCORE
            FROM JKGL_PZ_ZB_YCFF T
            LEFT JOIN JKGL_PZ_ZB_YCFF_SWJG S
              ON S.ZB_ID = T.ZB_ID
             AND S.XH = T.XH
             AND S.SWJG_DM = P_SWJG
             AND S.YXBZ = 'Y'
           WHERE T.ZB_ID = V_ZB_ID AND T.XH=V_YC
             AND T.YXBZ = 'Y';
         END;
       ELSE
         SET V_SCORE =0;
       END IF;

       -- 更新健康码指标赋分表
       UPDATE JKGL_DATA_ZB_JGB AS T SET YC_RESULT=V_YC,
    SCORE=V_SCORE,
    FF_STATUS='1',
    UPTIME=CURRENT_TIMESTAMP
         WHERE T.DJXH=P_DJXH AND T.ZB_ID=V_ZB_ID;


  END LOOP BJTS_FETCH_LOOP_001;
  CLOSE BJTS_FETCH_CURSOR_001;
END;
  END;

  IF V_SUCCESS=1 THEN
     COMMIT;
  ELSE
     ROLLBACK;
     CALL ORA_RAISE_APPLICATION_ERROR(-20001,ORA_CONCAT('【健康码】指标判定：', P_DJXH));
  END IF;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_JKGL_JKM_ZB_YCFF.sql

