DELIMITER $$

DROP PROCEDURE IF EXISTS TEMP_PRO_DEAL_AFTER_ETL$$

CREATE PROCEDURE TEMP_PRO_DEAL_AFTER_ETL
(
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LC_SBYY          VARCHAR(2000);
  DECLARE LD_DEALDATA      DATETIME;          -- 用于基础数据处理的提前量
  DECLARE LN_LOG           BIGINT;
  DECLARE LC_BBNY          VARCHAR(6);   -- 本期制表年月
  DECLARE LD_BBNY_KSNF     DATETIME;          -- 本期制表年月年初
  DECLARE LD_BBNY_KSRQ     DATETIME;          -- 本期制表年月开始日期，一般为制表年月的月初
  DECLARE LD_BBNY_JZRQ     DATETIME;          -- 本期制表年月结束日期，一般为制表年月的下一个月初
  DECLARE LC_DJZCLX        VARCHAR(6);   -- 本期制表年月
  DECLARE GLH_JSJE         DECIMAL(18,2);
  DECLARE GLH_TSL          DECIMAL(18,2);
  DECLARE GLH_TMSE         DECIMAL(18,2);
  DECLARE LN_ALLCK         DECIMAL(18,2);
  DECLARE LN_SNCK          DECIMAL(18,2);
  DECLARE LN_MYLAJ         DECIMAL(18,2);
  DECLARE LN_RMBLAJ        DECIMAL(18,2);
  DECLARE LN_MDTSE         DECIMAL(18,2);
  DECLARE LN_ZH_MDTSE      DECIMAL(18,2);
  DECLARE LN_BYTS_MDTSE    DECIMAL(18,2);
  DECLARE LN_BYBL_MDTSE    DECIMAL(18,2);
  DECLARE LN_ZZS           DECIMAL(18,2);
  DECLARE LN_XFS           DECIMAL(18,2);
  DECLARE LN_MDSE          DECIMAL(18,2);
  DECLARE SN_ZZS           DECIMAL(18,2);
  DECLARE SN_XFS           DECIMAL(18,2);
  DECLARE SN_MDSE          DECIMAL(18,2);
  DECLARE SY_ZZS           DECIMAL(18,2);
  DECLARE SY_XFS           DECIMAL(18,2);
  DECLARE SY_MDSE          DECIMAL(18,2);
  DECLARE ALL_SB_MDTSE     DECIMAL(18,2);
  DECLARE LD_LASTRQ        DATETIME;
  DECLARE V_ZLC_FS         DECIMAL(18,2);
  DECLARE V_ZLC_TS_AMT     DECIMAL(18,2);
  DECLARE V_ZLC_MD_AMT     DECIMAL(18,2);
  DECLARE V_ZLC_ZK_AMT     DECIMAL(18,2);
  DECLARE V_FF_DATE        DATETIME;
  DECLARE V_SL_DATE        DATETIME;
  DECLARE V_FH_DATE        DATETIME;
  DECLARE V_FH_USER        VARCHAR(20);
  DECLARE V_YWHZ_DATE      DATETIME;
  DECLARE V_YWHZ_USER      VARCHAR(20);
  DECLARE V_SEHZ_DATE      DATETIME;
  DECLARE V_SEHZ_USER      VARCHAR(20);
  DECLARE V_TSKP_DATE      DATETIME;
  DECLARE V_TSTK_DATE      DATETIME;
  DECLARE LN_I             BIGINT;
  DECLARE LN_J             BIGINT;
  DECLARE V_ZFBZ           CHAR(1);
  DECLARE V_ZFR_DM         VARCHAR(100);
  DECLARE V_ZFRQ           DATETIME;
  DECLARE V_CKSPTSSPLX_DM  CHAR(1);
  DECLARE V_TSL            DECIMAL(18,2);
  DECLARE V_JGFSTSLX_DM    CHAR(1);
  DECLARE V_HYDXZQH_DM     CHAR(4);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  SET LD_DEALDATA =ORA_DATE_ADD(DATE(CURRENT_TIMESTAMP), -(3));
  SET LN_LOG =2;

    -- ZBBLBZ：需要根据CKTS_LC_SHYDDCL重新设置
    -- 20260730从CKTS_LC_SHYDDCL设置暂不办理，从CKTS_LC_JCZBBL解除暂不办理
    SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_002 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTS_DJXH_002 LONGTEXT;
  DECLARE BJTS_CUR_MTS_GLH_002 LONGTEXT;
  DECLARE BJTS_CUR_MTS_LCSLID_002 LONGTEXT;
  DECLARE BJTS_CURSOR_002 CURSOR FOR
SELECT DISTINCT T.DJXH, T.GLH, T.LCSLID
                      FROM (SELECT * FROM CKTS_LC_SHYDDCL WHERE SBYWB_DM='A0301001'
                             UNION ALL
                            SELECT * FROM CKTS_LC_SHYDDCL_SHXT WHERE SBYWB_DM='A0301001') T;
  OPEN BJTS_CURSOR_002;
  BJTS_CURSOR_LOOP_002: LOOP
    SET BJTS_CURSOR_DONE_002 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_002 = TRUE;
      FETCH BJTS_CURSOR_002 INTO BJTS_CUR_MTS_DJXH_002, BJTS_CUR_MTS_GLH_002, BJTS_CUR_MTS_LCSLID_002;
    END;
    IF BJTS_CURSOR_DONE_002 THEN
      LEAVE BJTS_CURSOR_LOOP_002;
    END IF;
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX AS R
           SET SJTB_SJ=CURRENT_TIMESTAMP,
    ZBBLBZ='Y'
         WHERE R.DJXH=BJTS_CUR_MTS_DJXH_002 AND R.GLH=BJTS_CUR_MTS_GLH_002 AND R.LCSLID=BJTS_CUR_MTS_LCSLID_002 AND R.ZBBLBZ='N';
        UPDATE CKTS_SB_MTS_CKMX AS R
           SET SJTB_SJ=CURRENT_TIMESTAMP,
    ZBBLBZ='Y'
         WHERE R.DJXH=BJTS_CUR_MTS_DJXH_002 AND R.GLH=BJTS_CUR_MTS_GLH_002 AND R.LCSLID=BJTS_CUR_MTS_LCSLID_002 AND R.ZBBLBZ='N';
        COMMIT;
        SET LN_I =LN_I+1;
      END;

  END LOOP BJTS_CURSOR_LOOP_002;
  CLOSE BJTS_CURSOR_002;
END;

    SET LN_I =0;
    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_MTS_DJXH_001 LONGTEXT;
  DECLARE BJTS_CUR_MTS_GLH_001 LONGTEXT;
  DECLARE BJTS_CUR_MTS_LCSLID_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT DISTINCT T.DJXH, T.GLH, T.LCSLID
                      FROM CKTS_LC_JCZBBL T
                     WHERE T.SBYWB_DM='A0301001';
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_MTS_DJXH_001, BJTS_CUR_MTS_GLH_001, BJTS_CUR_MTS_LCSLID_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX AS R
           SET SJTB_SJ=CURRENT_TIMESTAMP,
    ZBBLBZ='N'
         WHERE R.DJXH=BJTS_CUR_MTS_DJXH_001 AND R.GLH=BJTS_CUR_MTS_GLH_001 AND R.LCSLID=BJTS_CUR_MTS_LCSLID_001 AND R.ZBBLBZ='Y';
        UPDATE CKTS_SB_MTS_CKMX AS R
           SET SJTB_SJ=CURRENT_TIMESTAMP,
    ZBBLBZ='N'
         WHERE R.DJXH=BJTS_CUR_MTS_DJXH_001 AND R.GLH=BJTS_CUR_MTS_GLH_001 AND R.LCSLID=BJTS_CUR_MTS_LCSLID_001 AND R.ZBBLBZ='Y';
        COMMIT;
        SET LN_I =LN_I+1;
      END;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: TEMP_PRO_DEAL_AFTER_ETL.sql

