                           WHERE A.LCTJJC IN ('21','22','23') AND A.LCJSRQ>=CAST('2026-01-01' AS DATE)
                            GROUP BY A.DJXH HAVING COUNT(DISTINCT A.LCTJJC)>1);
  OPEN BJTS_CURSOR_002;
  BJTS_CURSOR_LOOP_002: LOOP
