         SET LCTJJC='51'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'51' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
      COMMIT;
      -- 其他服务贸易
