       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'42' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      -- 内资生产企业
      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='41'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'41' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      -- 外贸服务贸易
      -- 研发设计业务
      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='50'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'50' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
      COMMIT;
      -- 其他服务贸易
      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='40'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'40' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      -- 周边业务
      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='30'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'30' AND T.SBYWB_DM IN ('A0302001','A0303001','A0304001');
      COMMIT;
      -- 外商投资企业
      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='23'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'23' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      -- 委托出口企业
      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='22'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'22' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
