      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='21'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'21' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' ';
      COMMIT;
      -- 外贸企业
      UPDATE CKTS_LC_SHXX AS T
         SET LCTJJC='10'
       WHERE T.UUID=BJTS_CUR_SHXX_UUID_002 AND T.LCTJJC<'10' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' ';
      COMMIT;

      BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_HZXX_YWHZBUUID_001 LONGTEXT;
