  DECLARE BJTS_CUR_HZXX_LCTJJC_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT T.YWHZBUUID,T.CKTMSHWYSFWLX_DM,MAX(S.LCTJJC) AS LCTJJC
                         FROM CKTS_LC_YWHZXX T
                        INNER JOIN CKTS_LC_SHXX S ON S.LCSLID_FS=T.LCSLID_FS
                        WHERE T.LCSLID_FS=BJTS_CUR_SHXX_LCSLID_FS_002
                        GROUP BY T.YWHZBUUID,T.CKTMSHWYSFWLX_DM;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
