    END IF;
        UPDATE CKTS_LC_YWHZXX AS A
           SET LCTJJC=(CASE WHEN (BJTS_CUR_HZXX_LCTJJC_001 IN ('72','71','70','30','23','22','21','10')) OR (BJTS_CUR_HZXX_CKTMSHWYSFWLX_DM_001='2') THEN BJTS_CUR_HZXX_LCTJJC_001
                              ELSE (CASE WHEN BJTS_CUR_HZXX_LCTJJC_001 IN ('63','53','43') THEN '23'
                                         WHEN BJTS_CUR_HZXX_LCTJJC_001 IN ('62','52','42') THEN '22'
                                         WHEN BJTS_CUR_HZXX_LCTJJC_001 IN ('61','51','41') THEN '21'
                                         WHEN BJTS_CUR_HZXX_LCTJJC_001 IN ('50','40') THEN '10'
                                         ELSE '00'
