         WHERE A.YWHZBUUID=BJTS_CUR_HZXX_YWHZBUUID_001;
        COMMIT;
        UPDATE CKTS_LC_SEHZXX AS B
           SET LCTJJC =(SELECT A.LCTJJC FROM CKTS_LC_YWHZXX A WHERE A.YWHZBUUID=B.YWHZBUUID AND 1=1
LIMIT 1)
         WHERE B.YWHZBUUID=BJTS_CUR_HZXX_YWHZBUUID_001;
        COMMIT;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
