-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS TEMP_PRO_DEAL_SBLCSLID$$

CREATE PROCEDURE TEMP_PRO_DEAL_SBLCSLID()
routine_body: BEGIN
  DECLARE LS_LCSLID      VARCHAR(32);


  BEGIN
  DECLARE BJTS_CURSOR_DONE_009 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SHXX_DJXH_009 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SSQ_009 LONGTEXT;
  DECLARE BJTS_CURSOR_009 CURSOR FOR
SELECT T.DJXH,T.SSQ FROM CKTS_LC_SHXX T
     WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL
     GROUP BY T.DJXH,T.SSQ
    HAVING COUNT(DISTINCT T.LCSLID_SB)>1;
  OPEN BJTS_CURSOR_009;
  BJTS_CURSOR_LOOP_009: LOOP
    SET BJTS_CURSOR_DONE_009 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_009 = TRUE;
      FETCH BJTS_CURSOR_009 INTO BJTS_CUR_SHXX_DJXH_009, BJTS_CUR_SHXX_SSQ_009;
    END;
    IF BJTS_CURSOR_DONE_009 THEN
      LEAVE BJTS_CURSOR_LOOP_009;
    END IF;
    BEGIN
  DECLARE BJTS_SQLCODE_009 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_009 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_009 = MYSQL_ERRNO, BJTS_SQLERRM_009 = MESSAGE_TEXT;
      SET LS_LCSLID =' ';

  END;
SELECT IFNULL(LCSLID_SB, ' ')
        INTO LS_LCSLID
        FROM (SELECT A.LCSLID_SB
                FROM CKTS_LC_SBXX A
               WHERE A.SBYWB_DM='A0305001'
                 AND A.DJXH=BJTS_CUR_SHXX_DJXH_009 AND A.SSQ=BJTS_CUR_SHXX_SSQ_009
                 AND A.ZFBZ IS NULL
               ORDER BY IFNULL(A.HTBZ_1, 'N')) TT
       WHERE 1=1
LIMIT 1;
    END;
    UPDATE CKTS_LC_SHXX AS S
       SET LCSLID_SB=LS_LCSLID
     WHERE S.SBYWB_DM='A0305001'
       AND S.DJXH=BJTS_CUR_SHXX_DJXH_009 AND S.SSQ=BJTS_CUR_SHXX_SSQ_009
       AND S.ZFBZ IS NULL;
    COMMIT;
    UPDATE CKTS_SB_MDT_CKMX AS S
       SET LCSLID_SB=LS_LCSLID
     WHERE S.DJXH=BJTS_CUR_SHXX_DJXH_009 AND S.SSQ=BJTS_CUR_SHXX_SSQ_009;
    COMMIT;
    UPDATE CKTS_SB_MDT_GJYS AS S
       SET LCSLID_SB=LS_LCSLID
     WHERE S.DJXH=BJTS_CUR_SHXX_DJXH_009 AND S.SSQ=BJTS_CUR_SHXX_SSQ_009;
    COMMIT;
    UPDATE CKTS_SB_MDT_YFSJ AS S
       SET LCSLID_SB=LS_LCSLID
     WHERE S.DJXH=BJTS_CUR_SHXX_DJXH_009 AND S.SSQ=BJTS_CUR_SHXX_SSQ_009;
    COMMIT;
    DELETE FROM GLXT_BB_SHXT_LCXX AS S
     WHERE S.DJXH=BJTS_CUR_SHXX_DJXH_009 AND S.SB_YM=BJTS_CUR_SHXX_SSQ_009
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SBXX A WHERE A.UUID=S.UUID AND IFNULL(A.ZFBZ, 'N')='N');
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_009;
  CLOSE BJTS_CURSOR_009;
END;

  BEGIN
  DECLARE BJTS_CURSOR_DONE_008 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_CUR_SHXX_DJXH_008 LONGTEXT;
  DECLARE BJTS_CUR_SHXX_SSQ_008 LONGTEXT;
  DECLARE BJTS_CURSOR_008 CURSOR FOR
SELECT T.DJXH,T.SSQ FROM CKTS_LC_SHXX T
     WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SBXX S WHERE S.LCSLID_SB=T.LCSLID_SB AND S.ZFBZ IS NULL);
  OPEN BJTS_CURSOR_008;
  BJTS_CURSOR_LOOP_008: LOOP
    SET BJTS_CURSOR_DONE_008 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_008 = TRUE;
      FETCH BJTS_CURSOR_008 INTO BJTS_CUR_SHXX_DJXH_008, BJTS_CUR_SHXX_SSQ_008;
    END;
    IF BJTS_CURSOR_DONE_008 THEN
      LEAVE BJTS_CURSOR_LOOP_008;
    END IF;
    BEGIN
  DECLARE BJTS_SQLCODE_008 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_008 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_008 = MYSQL_ERRNO, BJTS_SQLERRM_008 = MESSAGE_TEXT;
      SET LS_LCSLID =' ';

  END;
SELECT IFNULL(LCSLID_SB, ' ')
        INTO LS_LCSLID
        FROM (SELECT A.LCSLID_SB
