    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_CUR_SHXX_DJXH_001, BJTS_CUR_SHXX_SSQ_001, BJTS_CUR_SHXX_SBPC_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
    BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET LS_LCSLID =' ';

  END;
SELECT IFNULL(LCSLID_SB, ' ')
        INTO LS_LCSLID
        FROM (SELECT A.LCSLID_SB
                FROM CKTS_LC_SBXX A
               WHERE A.SBYWB_DM='A0310001'
                 AND A.DJXH=BJTS_CUR_SHXX_DJXH_001 AND A.SSQ=BJTS_CUR_SHXX_SSQ_001 AND A.SBPC=BJTS_CUR_SHXX_SBPC_001
                 AND A.ZFBZ IS NULL
               ORDER BY IFNULL(A.HTBZ_1, 'N')) TT
       WHERE 1=1
LIMIT 1;
    END;
    UPDATE CKTS_LC_SHXX AS S
       SET LCSLID_SB=LS_LCSLID
     WHERE S.SBYWB_DM='A0310001'
       AND S.DJXH=BJTS_CUR_SHXX_DJXH_001 AND S.SSQ=BJTS_CUR_SHXX_SSQ_001 AND S.SBPC=BJTS_CUR_SHXX_SBPC_001
       AND S.ZFBZ IS NULL;
    COMMIT;
    UPDATE CKTS_SB_WZF_CKMX AS S
       SET LCSLID_SB=LS_LCSLID
     WHERE S.DJXH=BJTS_CUR_SHXX_DJXH_001 AND S.SSQ=BJTS_CUR_SHXX_SSQ_001 AND S.SBPC=BJTS_CUR_SHXX_SBPC_001;
    COMMIT;
    DELETE FROM GLXT_BB_SHXT_LCXX AS S
     WHERE S.DJXH=BJTS_CUR_SHXX_DJXH_001 AND S.SB_YM=BJTS_CUR_SHXX_SSQ_001 AND S.SB_PC=BJTS_CUR_SHXX_SBPC_001
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SBXX A WHERE A.UUID=S.UUID AND IFNULL(A.ZFBZ, 'N')='N');
    COMMIT;

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

  LEAVE routine_body;
END$$

DELIMITER ;

